/**
 * FilterChip Component
 *
 * Reusable filter chip/badge showing active filter with remove option.
 * Implements Single Responsibility Principle - displays single filter state.
 */

import React, { useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { X } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';

export interface FilterChipProps {
  readonly label: string;
  readonly value: string;
  readonly onRemove: () => void;
  readonly variant?: 'default' | 'secondary' | 'outline' | 'destructive';
  readonly disabled?: boolean;
  readonly namespace?: string;
}

/**
 * Display active filter as a removable chip/badge
 *
 * @example
 * ```tsx
 * <FilterChip
 *   label="Type"
 *   value="Idrettshall"
 *   onRemove={() => clearFilter('type')}
 * />
 * ```
 */
export const FilterChip = ({
  label,
  value,
  onRemove,
  variant = 'secondary',
  disabled = false,
  namespace = 'common'
}: FilterChipProps): JSX.Element => {
  const { t } = useTranslation(namespace as any);

  const handleRemove = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    onRemove();
  }, [onRemove]);

  return (
    <Badge
      variant={variant}
      className="flex items-center gap-2 px-3 py-1.5 text-sm font-medium"
    >
      <span className="text-gray-600 font-normal">{label}:</span>
      <span className="font-medium">{value}</span>
      <Button
        type="button"
        variant="ghost"
        size="sm"
        onClick={handleRemove}
        disabled={disabled}
        className="h-4 w-4 p-0 ml-1 hover:bg-transparent"
        aria-label={t('aria.remove_filter', { label })}
      >
        <X className="h-3 w-3" />
      </Button>
    </Badge>
  );
};

/**
 * FilterPanel Component
 *
 * Reusable panel container for filters with collapsible support.
 * Implements Open/Closed Principle - extensible through children.
 */

import React, { useState, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { Filter, ChevronDown, ChevronUp, X } from 'lucide-react';
import { Card, CardContent, CardHeader } from '@/components/ui/card';
import { Button } from '@/components/ui/button';

export interface FilterPanelProps {
  readonly children: React.ReactNode;
  readonly title?: string;
  readonly isCollapsible?: boolean;
  readonly defaultExpanded?: boolean;
  readonly onClearFilters?: () => void;
  readonly activeFiltersCount?: number;
  readonly showClearButton?: boolean;
  readonly className?: string;
  readonly namespace?: string;
}

/**
 * Container component for filter controls
 *
 * @example
 * ```tsx
 * <FilterPanel
 *   title="Filtre"
 *   onClearFilters={clearAllFilters}
 *   activeFiltersCount={3}
 *   isCollapsible
 * >
 *   <SearchInput value={query} onChange={setQuery} />
 *   <Select>...</Select>
 * </FilterPanel>
 * ```
 */
export const FilterPanel = ({
  children,
  title,
  isCollapsible = false,
  defaultExpanded = true,
  onClearFilters,
  activeFiltersCount = 0,
  showClearButton = true,
  className = '',
  namespace = 'common'
}: FilterPanelProps): JSX.Element => {
  const { t } = useTranslation(namespace as any);
  const [isExpanded, setIsExpanded] = useState<boolean>(defaultExpanded);

  const toggleExpanded = useCallback(() => {
    setIsExpanded(prev => !prev);
  }, []);

  const handleClear = useCallback(() => {
    onClearFilters?.();
  }, [onClearFilters]);

  const defaultTitle = t('filters.title', 'Filtre');

  return (
    <Card className={className}>
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Filter className="h-5 w-5 text-gray-500" aria-hidden="true" />
            <h3 className="text-lg font-semibold text-gray-900">
              {title || defaultTitle}
            </h3>
            {activeFiltersCount > 0 && (
              <span className="ml-2 px-2 py-0.5 text-xs font-medium bg-blue-100 text-blue-800 rounded-full">
                {activeFiltersCount}
              </span>
            )}
          </div>

          <div className="flex items-center gap-2">
            {showClearButton && activeFiltersCount > 0 && onClearFilters && (
              <Button
                variant="ghost"
                size="sm"
                onClick={handleClear}
                className="text-sm text-blue-600 hover:text-blue-700 hover:bg-blue-50"
                aria-label={t('filters.clear', 'Tøm filtre')}
              >
                <X className="h-4 w-4 mr-1" />
                {t('filters.clear', 'Tøm filtre')}
              </Button>
            )}

            {isCollapsible && (
              <Button
                variant="ghost"
                size="sm"
                onClick={toggleExpanded}
                className="h-8 w-8 p-0"
                aria-label={isExpanded ? t('actions.collapse', 'Kollaps') : t('actions.expand', 'Utvid')}
              >
                {isExpanded ? (
                  <ChevronUp className="h-4 w-4" />
                ) : (
                  <ChevronDown className="h-4 w-4" />
                )}
              </Button>
            )}
          </div>
        </div>
      </CardHeader>

      {isExpanded && (
        <CardContent className="pt-0">
          <div className="space-y-4">
            {children}
          </div>
        </CardContent>
      )}
    </Card>
  );
};

/**
 * ResultsCount Component
 *
 * Display count of filtered/search results with i18n support.
 * Implements Single Responsibility Principle - shows only results count.
 */

import React from 'react';
import { useTranslation } from 'react-i18next';

export interface ResultsCountProps {
  readonly count: number;
  readonly total?: number;
  readonly isFiltered?: boolean;
  readonly namespace?: string;
  readonly className?: string;
}

/**
 * Display results count with optional total and filtering indicator
 *
 * @example
 * ```tsx
 * <ResultsCount
 *   count={filteredItems.length}
 *   total={allItems.length}
 *   isFiltered={hasActiveFilters}
 * />
 * ```
 */
export const ResultsCount = ({
  count,
  total,
  isFiltered = false,
  namespace = 'common',
  className = ''
}: ResultsCountProps): JSX.Element => {
  const { t } = useTranslation(namespace as any);

  const getText = (): string => {
    if (count === 0) {
      return t('search.no_results', 'Ingen resultater funnet');
    }

    if (total !== undefined && isFiltered) {
      return t('filters.results_filtered', {
        count,
        total,
        defaultValue: '{{count}} av {{total}} resultater'
      });
    }

    return t('filters.results_count', {
      count,
      defaultValue: '{{count}} resultater'
    });
  };

  return (
    <div className={`text-sm text-gray-600 ${className}`}>
      <span>{getText()}</span>
    </div>
  );
};

/**
 * SearchInput Component
 *
 * Reusable search input with icon, clear button, and i18n support.
 * Implements Single Responsibility Principle - handles only search input UI.
 */

import React, { useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { Search, X } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';

export interface SearchInputProps {
  readonly value: string;
  readonly onChange: (value: string) => void;
  readonly placeholder?: string;
  readonly ariaLabel?: string;
  readonly showClearButton?: boolean;
  readonly disabled?: boolean;
  readonly className?: string;
  readonly namespace?: string;
}

/**
 * Reusable search input component with clear functionality
 *
 * @example
 * ```tsx
 * <SearchInput
 *   value={searchQuery}
 *   onChange={setSearchQuery}
 *   placeholder="Search facilities..."
 *   showClearButton
 * />
 * ```
 */
export const SearchInput = ({
  value,
  onChange,
  placeholder,
  ariaLabel,
  showClearButton = true,
  disabled = false,
  className = '',
  namespace = 'common'
}: SearchInputProps): JSX.Element => {
  const { t } = useTranslation(namespace as any);

  const handleClear = useCallback(() => {
    onChange('');
  }, [onChange]);

  const handleChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    onChange(e.target.value);
  }, [onChange]);

  const defaultPlaceholder = t('search.placeholder', 'Søk...');
  const defaultAriaLabel = t('aria.search_input', 'Søkefelt');

  return (
    <div className={`relative ${className}`}>
      <Search
        className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-4 w-4"
        aria-hidden="true"
      />
      <Input
        type="text"
        value={value}
        onChange={handleChange}
        placeholder={placeholder || defaultPlaceholder}
        disabled={disabled}
        className="pl-10 pr-10 h-12"
        aria-label={ariaLabel || defaultAriaLabel}
      />
      {showClearButton && value && (
        <Button
          type="button"
          variant="ghost"
          size="sm"
          onClick={handleClear}
          disabled={disabled}
          className="absolute right-1 top-1/2 transform -translate-y-1/2 h-8 w-8 p-0 hover:bg-gray-100"
          aria-label={t('search.clear_search', 'Tøm søk')}
        >
          <X className="h-4 w-4 text-gray-400" />
        </Button>
      )}
    </div>
  );
};

/**
 * SortDropdown Component
 *
 * Reusable dropdown for sorting options with i18n support.
 * Implements Single Responsibility Principle - handles only sort selection UI.
 */

import React from 'react';
import { useTranslation } from 'react-i18next';
import { ArrowUpDown } from 'lucide-react';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue
} from '@/components/ui/select';

export interface SortOption {
  readonly value: string;
  readonly label: string;
  readonly translationKey?: string;
}

export interface SortDropdownProps {
  readonly value: string;
  readonly options: readonly SortOption[];
  readonly onChange: (value: string) => void;
  readonly placeholder?: string;
  readonly ariaLabel?: string;
  readonly disabled?: boolean;
  readonly className?: string;
  readonly namespace?: string;
}

/**
 * Reusable dropdown for sorting selection
 *
 * @example
 * ```tsx
 * <SortDropdown
 *   value={sortBy}
 *   options={[
 *     { value: 'name-asc', label: 'Name (A-Z)', translationKey: 'sort.name_asc' },
 *     { value: 'price-asc', label: 'Price (Low to High)', translationKey: 'sort.price_asc' }
 *   ]}
 *   onChange={setSortBy}
 * />
 * ```
 */
export const SortDropdown = ({
  value,
  options,
  onChange,
  placeholder,
  ariaLabel,
  disabled = false,
  className = '',
  namespace = 'common'
}: SortDropdownProps): JSX.Element => {
  const { t } = useTranslation(namespace as any);

  const defaultPlaceholder = t('filters.sort_by', 'Sorter etter');
  const defaultAriaLabel = t('aria.sort_dropdown', 'Sorteringsvalg');

  return (
    <Select
      value={value}
      onValueChange={onChange}
      disabled={disabled}
    >
      <SelectTrigger
        className={`h-12 ${className}`}
        aria-label={ariaLabel || defaultAriaLabel}
      >
        <div className="flex items-center gap-2">
          <ArrowUpDown className="h-4 w-4 text-gray-500" />
          <SelectValue placeholder={placeholder || defaultPlaceholder} />
        </div>
      </SelectTrigger>
      <SelectContent>
        {options.map((option) => (
          <SelectItem key={option.value} value={option.value}>
            {option.translationKey ? t(option.translationKey, option.label) : option.label}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
};

/**
 * KPICard - Reusable Key Performance Indicator Card
 *
 * A flexible, accessible component for displaying metrics with trends.
 * Supports multiple formats, colors, and optional navigation.
 *
 * @example
 * ```tsx
 * <KPICard
 *   title="Total Bookings"
 *   value={1234}
 *   format="number"
 *   trend={{ value: 12, direction: "up" }}
 *   icon={<Calendar />}
 *   color="blue"
 *   onClick={() => navigate('/bookings')}
 * />
 * ```
 */

import React from "react";
import { useTranslation } from "react-i18next";
import { TrendingUp, TrendingDown, Minus } from "lucide-react";

/**
 * Trend direction
 */
export type TrendDirection = "up" | "down" | "neutral";

/**
 * Value format type
 */
export type ValueFormat = "number" | "currency" | "percentage";

/**
 * Color variant
 */
export type KPIColor = "blue" | "green" | "yellow" | "red" | "purple" | "gray";

/**
 * Trend data
 */
export interface KPITrend {
  /** Percentage change */
  value: number;
  /** Trend direction */
  direction: TrendDirection;
  /** Period description (e.g., "vs last month") */
  period?: string;
}

/**
 * KPICard Props
 */
export interface KPICardProps {
  /** Card title/label */
  title: string;
  /** Main value to display */
  value: number;
  /** Value format */
  format?: ValueFormat;
  /** Description/subtitle */
  description?: string;
  /** Trend data */
  trend?: KPITrend;
  /** Icon component */
  icon?: React.ReactNode;
  /** Color scheme */
  color?: KPIColor;
  /** Click handler */
  onClick?: () => void;
  /** Additional className */
  className?: string;
  /** Size variant */
  size?: "sm" | "md" | "lg";
  /** Loading state */
  loading?: boolean;
}

/**
 * Format value based on type
 */
const formatValue = (
  value: number,
  format: ValueFormat,
  locale: string
): string => {
  switch (format) {
    case "currency":
      return new Intl.NumberFormat(locale, {
        style: "currency",
        currency: "NOK",
        minimumFractionDigits: 0,
        maximumFractionDigits: 0,
      }).format(value);
    case "percentage":
      return `${value}%`;
    case "number":
    default:
      return new Intl.NumberFormat(locale).format(value);
  }
};

/**
 * KPICard Component
 */
export const KPICard: React.FC<KPICardProps> = ({
  title,
  value,
  format = "number",
  description,
  trend,
  icon,
  color = "gray",
  onClick,
  className = "",
  size = "md",
  loading = false,
}) => {
  const { t, i18n } = useTranslation("common");

  // Size configurations
  const sizeConfig = {
    sm: {
      padding: "p-4",
      iconSize: "w-5 h-5",
      iconPadding: "p-1.5",
      titleSize: "text-xs",
      valueSize: "text-2xl",
      descriptionSize: "text-xs",
      trendSize: "text-xs",
    },
    md: {
      padding: "p-6",
      iconSize: "w-6 h-6",
      iconPadding: "p-2",
      titleSize: "text-sm",
      valueSize: "text-4xl",
      descriptionSize: "text-sm",
      trendSize: "text-sm",
    },
    lg: {
      padding: "p-8",
      iconSize: "w-7 h-7",
      iconPadding: "p-2.5",
      titleSize: "text-base",
      valueSize: "text-5xl",
      descriptionSize: "text-base",
      trendSize: "text-base",
    },
  };

  const config = sizeConfig[size];

  // Color configurations
  const colorConfig: Record<
    KPIColor,
    { border: string; iconBg: string; icon: string }
  > = {
    blue: {
      border:
        "border-gray-200 dark:border-gray-700 hover:border-blue-300 dark:hover:border-blue-600",
      iconBg: "bg-blue-100 dark:bg-blue-800",
      icon: "text-blue-600 dark:text-blue-400",
    },
    green: {
      border:
        "border-gray-200 dark:border-gray-700 hover:border-green-300 dark:hover:border-green-600",
      iconBg: "bg-green-100 dark:bg-green-800",
      icon: "text-green-600 dark:text-green-400",
    },
    yellow: {
      border:
        "border-gray-200 dark:border-gray-700 hover:border-yellow-300 dark:hover:border-yellow-600",
      iconBg: "bg-yellow-100 dark:bg-yellow-800",
      icon: "text-yellow-600 dark:text-yellow-400",
    },
    red: {
      border:
        "border-gray-200 dark:border-gray-700 hover:border-red-300 dark:hover:border-red-600",
      iconBg: "bg-red-100 dark:bg-red-800",
      icon: "text-red-600 dark:text-red-400",
    },
    purple: {
      border:
        "border-gray-200 dark:border-gray-700 hover:border-purple-300 dark:hover:border-purple-600",
      iconBg: "bg-purple-100 dark:bg-purple-800",
      icon: "text-purple-600 dark:text-purple-400",
    },
    gray: {
      border:
        "border-gray-200 dark:border-gray-700 hover:border-gray-300 dark:hover:border-gray-600",
      iconBg: "bg-gray-100 dark:bg-gray-700",
      icon: "text-gray-600 dark:text-gray-400",
    },
  };

  const colors = colorConfig[color];

  // Trend helpers
  const getTrendIcon = (direction: TrendDirection): React.ReactNode => {
    const iconClass = "w-4 h-4";
    switch (direction) {
      case "up":
        return (
          <TrendingUp
            className={`${iconClass} text-green-500`}
            aria-hidden="true"
          />
        );
      case "down":
        return (
          <TrendingDown
            className={`${iconClass} text-red-500`}
            aria-hidden="true"
          />
        );
      default:
        return (
          <Minus className={`${iconClass} text-gray-500`} aria-hidden="true" />
        );
    }
  };

  const getTrendColor = (direction: TrendDirection): string => {
    switch (direction) {
      case "up":
        return "text-green-600 dark:text-green-400";
      case "down":
        return "text-red-600 dark:text-red-400";
      default:
        return "text-gray-600 dark:text-gray-400";
    }
  };

  const handleClick = (): void => {
    onClick?.();
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>): void => {
    if (onClick && (e.key === "Enter" || e.key === " ")) {
      e.preventDefault();
      handleClick();
    }
  };

  const formattedValue = formatValue(value, format, i18n.language);

  // Loading skeleton
  if (loading) {
    return (
      <div
        className={`${config.padding} rounded-xl border-2 ${colors.border} bg-white dark:bg-gray-800 ${className}`}
      >
        <div className="animate-pulse">
          <div className="flex items-center gap-3 mb-3">
            <div
              className={`${config.iconPadding} rounded-lg ${colors.iconBg}`}
            >
              <div
                className={`${config.iconSize} bg-gray-300 dark:bg-gray-600 rounded`}
              />
            </div>
            <div className="h-4 bg-gray-300 dark:bg-gray-600 rounded w-24" />
          </div>
          <div className="h-10 bg-gray-300 dark:bg-gray-600 rounded w-32 mb-3" />
          {description && (
            <div className="h-4 bg-gray-300 dark:bg-gray-600 rounded w-full mb-3" />
          )}
        </div>
      </div>
    );
  }

  return (
    <div
      onClick={onClick ? handleClick : undefined}
      onKeyDown={onClick ? handleKeyDown : undefined}
      className={`
        ${config.padding} 
        rounded-xl 
        border-2 
        ${colors.border}
        bg-white 
        dark:bg-gray-800 
        ${onClick ? "cursor-pointer hover:shadow-lg hover:scale-105" : ""}
        transition-all 
        duration-200
        ${className}
      `}
      role={onClick ? "button" : undefined}
      tabIndex={onClick ? 0 : undefined}
      aria-label={onClick ? `Navigate to ${title}` : undefined}
    >
      <div className="flex items-start justify-between">
        <div className="flex-1">
          {/* Icon & Title */}
          <div className="flex items-center gap-3 mb-3">
            {icon && (
              <div
                className={`${config.iconPadding} rounded-lg ${colors.iconBg}`}
              >
                <div className={`${config.iconSize} ${colors.icon}`}>
                  {icon}
                </div>
              </div>
            )}
            <h3
              className={`${config.titleSize} font-semibold text-gray-700 dark:text-gray-300`}
            >
              {title}
            </h3>
          </div>

          {/* Value */}
          <div className="mb-3">
            <p
              className={`${config.valueSize} font-bold text-gray-900 dark:text-white`}
            >
              {formattedValue}
            </p>
          </div>

          {/* Description */}
          {description && (
            <p
              className={`${config.descriptionSize} text-gray-600 dark:text-gray-400 mb-3`}
            >
              {description}
            </p>
          )}

          {/* Trend */}
          {trend && (
            <div className="flex items-center gap-2">
              {getTrendIcon(trend.direction)}
              <span
                className={`${config.trendSize} font-medium ${getTrendColor(
                  trend.direction
                )}`}
              >
                {Math.abs(trend.value)}%
              </span>
              {trend.period && (
                <span className="text-xs text-gray-400 dark:text-gray-500">
                  {trend.period}
                </span>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

"use client";

import React from "react";
import { X } from "lucide-react";
import { useTranslation } from "react-i18next";

import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from "@/components/ui/dialog";
import { cn } from "@/lib/utils/cn";

/**
 * Modal size variants
 */
type ModalSize = 'sm' | 'md' | 'lg' | 'xl' | '2xl' | '4xl';

/**
 * Base modal props interface
 */
interface BaseModalProps {
  readonly isOpen: boolean;
  readonly onClose: () => void;
  readonly title: string;
  readonly description?: string;
  readonly children: React.ReactNode;
  readonly actions?: React.ReactNode;
  readonly size?: ModalSize;
  readonly showCloseButton?: boolean;
  readonly closeOnOverlayClick?: boolean;
  readonly className?: string;
  readonly titleIcon?: React.ReactNode;
}

/**
 * Size class mappings for modal widths
 */
const sizeClasses: Record<ModalSize, string> = {
  sm: "max-w-sm",
  md: "max-w-md",
  lg: "max-w-lg",
  xl: "max-w-xl",
  "2xl": "max-w-2xl",
  "4xl": "max-w-4xl"
};

/**
 * BaseModal component
 *
 * A reusable modal component that follows the Open/Closed Principle (OCP)
 * by providing a consistent base structure that can be extended without modification.
 *
 * Features:
 * - Configurable sizing (sm, md, lg, xl, 2xl, 4xl)
 * - Optional header icon
 * - Optional description
 * - Customizable action buttons in footer
 * - Accessibility compliant with ARIA labels
 * - Keyboard navigation support (ESC to close)
 * - Internationalization support via react-i18next
 *
 * @example
 * <BaseModal
 *   isOpen={isOpen}
 *   onClose={onClose}
 *   title="Confirm Action"
 *   size="md"
 *   actions={
 *     <>
 *       <Button variant="outline" onClick={onClose}>Cancel</Button>
 *       <Button onClick={onConfirm}>Confirm</Button>
 *     </>
 *   }
 * >
 *   <p>Are you sure you want to proceed?</p>
 * </BaseModal>
 */
export const BaseModal: React.FC<BaseModalProps> = ({
  isOpen,
  onClose,
  title,
  description,
  children,
  actions,
  size = 'md',
  showCloseButton = true,
  closeOnOverlayClick = true,
  className,
  titleIcon
}): JSX.Element => {
  const { t } = useTranslation('common');

  const handleOpenChange = (open: boolean): void => {
    if (!open && closeOnOverlayClick) {
      onClose();
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={handleOpenChange}>
      <DialogContent
        className={cn(
          sizeClasses[size],
          "max-h-[90vh] overflow-y-auto",
          className
        )}
        aria-describedby={description ? "modal-description" : undefined}
      >
        <DialogHeader>
          <div className="flex items-center justify-between">
            <DialogTitle className="flex items-center space-x-2">
              {titleIcon && <span className="flex-shrink-0">{titleIcon}</span>}
              <span>{title}</span>
            </DialogTitle>
          </div>
          {description && (
            <DialogDescription id="modal-description">
              {description}
            </DialogDescription>
          )}
        </DialogHeader>

        <div className="py-4">
          {children}
        </div>

        {actions && (
          <DialogFooter className="flex justify-end space-x-2">
            {actions}
          </DialogFooter>
        )}
      </DialogContent>
    </Dialog>
  );
};

/**
