              <p className="text-sm text-gray-600 dark:text-gray-400">{translatedLabels.completed}</p>
            </div>
          </div>

          {/* Next Booking */}
          {group.nextBooking && (
            <div className="p-4 bg-purple-50 dark:bg-purple-900/20 rounded-lg border border-purple-200 dark:border-purple-800">
              <h4 className="font-medium text-gray-900 dark:text-white mb-2">{translatedLabels.nextOccurrence}</h4>
              <div className="flex items-center gap-2 text-sm">
                <Calendar className="w-4 h-4 text-purple-600 dark:text-purple-400" />
                <span className="text-gray-900 dark:text-white">{formatDate(group.nextBooking.starts_at)}</span>
                <Clock className="w-4 h-4 text-purple-600 dark:text-purple-400 ml-2" />
                <span className="text-gray-900 dark:text-white">
                  {formatTime(group.nextBooking.starts_at)} - {formatTime(group.nextBooking.ends_at)}
                </span>
              </div>
            </div>
          )}

          {/* Purpose */}
          {group.bookings[0]?.notes && (
            <div>
              <h4 className="font-medium text-gray-900 dark:text-white mb-1">{translatedLabels.purpose}</h4>
              <p className="text-sm text-gray-600 dark:text-gray-400">{group.bookings[0].notes}</p>
            </div>
          )}

          {/* Occurrences List */}
          <div>
            <div className="flex items-center justify-between mb-3">
              <h4 className="font-medium text-gray-900 dark:text-white">
                {translatedLabels.occurrences}
              </h4>
              {group.bookings.length > 5 && (
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => setShowAllOccurrences(!showAllOccurrences)}
                  className="dark:text-gray-300 dark:hover:bg-gray-700"
                >
                  {showAllOccurrences 
                    ? translatedLabels.showLess 
                    : translatedLabels.showAll}
                </Button>
              )}
            </div>

            <div className="space-y-2 max-h-60 overflow-y-auto">
              {occurrencesToShow.map((booking) => {
                const isPast = new Date(booking.starts_at) < new Date();
                return (
                  <div 
                    key={booking.id} 
                    className={`flex items-center justify-between p-3 rounded-lg border ${
                      isPast ? "bg-gray-50 border-gray-200 dark:bg-gray-700 dark:border-gray-600" : "bg-white border-gray-200 dark:bg-gray-800 dark:border-gray-700"
                    }`}
                  >
                    <div className="flex items-center gap-3">
                      {getStatusIcon(booking.status)}
                      <div>
                        <div className="flex items-center gap-2">
                          <span className="font-medium text-gray-900 dark:text-white">
                            {formatDate(booking.starts_at)}
                          </span>
                          <Badge className={getStatusBadgeColor(booking.status)} variant="secondary">
                            {getStatusLabel(booking.status)}
                          </Badge>
                        </div>
                        <div className="flex items-center gap-2 text-sm text-gray-600 dark:text-gray-400">
                          <Clock className="w-3 h-3" />
                          <span>
                            {formatTime(booking.starts_at)} - {formatTime(booking.ends_at)}
                          </span>
                        </div>
                      </div>
                    </div>

                    {booking.total_cents > 0 && (
                      <span className="text-sm font-medium text-gray-900 dark:text-white">
                        {Math.round(booking.total_cents / 100)} kr
                      </span>
                    )}
                  </div>
                );
              })}
            </div>
          </div>

          {/* Actions */}
          <Separator className="dark:bg-gray-700" />
          <div className="flex justify-end gap-3">
            <Button variant="outline" onClick={onClose} className="dark:border-gray-600 dark:text-gray-300 dark:hover:bg-gray-700">
              {translatedLabels.close}
            </Button>
            {onCancelGroup && (
              <Button variant="destructive" onClick={handleCancelGroup}>
                {translatedLabels.cancelSeries}
              </Button>
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

/**
 * BookingCard Component
 *
 * Displays a single booking with all relevant information.
 * Supports selection, actions, and click handlers.
 *
 * SOLID Principles Applied:
 * - Single Responsibility: Displays booking information only
 * - Open/Closed: Extensible through props without modification
 * - Dependency Inversion: Uses i18n translations and utility functions
 */

import React, { useCallback } from "react";
import { useTranslation } from "react-i18next";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Calendar, Clock, MapPin, Eye, Trash2 } from "lucide-react";
import type { BookingWithDetails } from "@/services/supabase/bookings.service";
import type { Database } from "@/types/database";
import {
  formatDate,
  formatTime,
  formatPrice,
  getStatusColor,
  getStatusBadgeColor,
} from "@/components/features/facilities/utils/formatters";

type BookingStatus = Database["public"]["Enums"]["booking_status"];

export interface BookingCardProps {
  readonly booking: BookingWithDetails;
  readonly selected?: boolean;
  readonly onSelect?: (bookingId: string) => void;
  readonly onViewDetails?: (booking: BookingWithDetails) => void;
  readonly onDelete?: (bookingId: string) => void;
  readonly showCheckbox?: boolean;
}

/**
 * Get translated status label
 */
const useStatusLabel = (status: BookingStatus): string => {
  const { t } = useTranslation("booking");

  const statusMap: Record<BookingStatus, string> = {
    paid: t("status.paid"),
    completed: t("status.completed"),
    pending: t("status.pending"),
    awaiting_payment: t("status.pending_payment"),
    cancelled: t("status.cancelled"),
    expired: t("status.paid"),
    refunded: t("status.refunded"),
  };

  return statusMap[status] || status;
};

/**
 * BookingCard component displays a single booking
 *
 * @example
 * ```tsx
 * <BookingCard
 *   booking={booking}
 *   selected={selectedIds.includes(booking.id)}
 *   onSelect={handleSelect}
 *   onViewDetails={handleViewDetails}
 *   onDelete={handleDelete}
 *   showCheckbox
 * />
 * ```
 */
export const BookingCard = ({
  booking,
  selected = false,
  onSelect,
  onViewDetails,
  onDelete,
  showCheckbox = true,
}: BookingCardProps): JSX.Element => {
  const { t, i18n } = useTranslation("booking");
  const statusLabel = useStatusLabel(booking.status);

  const durationTranslations = {
    hour: t("time.hour"),
    hours: t("time.hours"),
  };

  const handleCardClick = useCallback(() => {
    if (onViewDetails) {
      onViewDetails(booking);
    }
  }, [onViewDetails, booking]);

  const handleSelectClick = useCallback(
    (e: React.MouseEvent) => {
      e.stopPropagation();
      if (onSelect) {
        onSelect(booking.id);
      }
    },
    [onSelect, booking.id]
  );

  const handleViewClick = useCallback(
    (e: React.MouseEvent) => {
      e.stopPropagation();
      if (onViewDetails) {
        onViewDetails(booking);
      }
    },
    [onViewDetails, booking]
  );

  const handleDeleteClick = useCallback(
    (e: React.MouseEvent) => {
      e.stopPropagation();
      if (onDelete) {
        onDelete(booking.id);
      }
    },
    [onDelete, booking.id]
  );

  const handleCheckboxChange = useCallback(() => {
    if (onSelect) {
      onSelect(booking.id);
    }
  }, [onSelect, booking.id]);

  // Determine the appropriate delete action based on booking status
  const getDeleteButtonProps = () => {
    if (booking.status === 'cancelled') {
      // If already cancelled, the action is to permanently delete
      return {
        ariaLabel: t("actions.delete_permanently", "Delete Permanently"),
        title: t("actions.delete_permanently", "Delete Permanently"),
        variant: "outline" as const,
        iconColor: "text-red-600 border-red-600 hover:text-red-700 hover:border-red-700 hover:bg-red-50"
      };
    } else {
      // If not cancelled, the action is to cancel the booking
      return {
        ariaLabel: t("actions.cancel", "Cancel Booking"),
        title: t("actions.cancel", "Cancel Booking"),
        variant: "outline" as const,
        iconColor: "text-red-600 hover:text-red-700 hover:bg-red-50"
      };
    }
  };

  const deleteButtonProps = getDeleteButtonProps();

  return (
    <div className="flex items-start gap-4">
      {showCheckbox && (
        <div onClick={handleSelectClick}>
          <Checkbox
            checked={selected}
            onCheckedChange={handleCheckboxChange}
            className="mt-1"
            aria-label={`Select booking for ${booking.facility?.name || t("details.unknownVenue")}`}
          />
        </div>
      )}

      <Card
        className="relative cursor-pointer flex-1 hover:shadow-md transition-shadow"
        onClick={handleCardClick}
      >
        <div
          className={`absolute left-0 top-0 bottom-0 w-1 rounded-l-lg ${getStatusColor(
            booking.status
          )}`}
        />

        <CardContent className="p-4">
          <div className="flex items-start justify-between">
            <div className="flex-1 ml-2">
              {/* Header */}
              <div className="flex items-center justify-between mb-2">
                <h3 className="font-semibold text-gray-900 dark:text-white text-lg">
                  {booking.facility?.name || t("details.unknownVenue")}
                </h3>
                <Badge className={getStatusBadgeColor(booking.status)}>
                  {statusLabel}
                </Badge>
              </div>

              {/* Details */}
              <div className="text-sm text-gray-600 dark:text-gray-400 space-y-1">
                <div className="flex flex-wrap gap-4">
                  <span className="flex items-center gap-1">
                    <Calendar className="w-3 h-3" />
                    {formatDate(booking.starts_at)}
                  </span>
                  <span className="flex items-center gap-1">
                    <Clock className="w-3 h-3" />
                    {formatTime(booking.starts_at)} -{" "}
                    {formatTime(booking.ends_at)}
                  </span>
                  <span className="text-gray-500 dark:text-gray-500">
                    (
                    {(() => {
                      const start = new Date(booking.starts_at);
                      const end = new Date(booking.ends_at);
                      const hours = (end.getTime() - start.getTime()) / (1000 * 60 * 60);
                      // Use proper language-specific formatting
                      if (i18n.language === 'no') {
                        return hours === 1 ? `1 time` : `${hours} timer`;
                      } else {
                        return hours === 1 ? `1 hour` : `${hours} hours`;
                      }
                    })()}
                    )
                  </span>
                </div>

                {booking.zone?.name && (
                  <div className="flex items-center gap-1">
                    <MapPin className="w-3 h-3" />
                    <span>{booking.zone.name}</span>
                  </div>
                )}

                <div className="flex items-center justify-between mt-2">
                  <span className="font-medium text-gray-900 dark:text-white text-base">
                    {formatPrice(booking.total_cents)}
                  </span>
                  {booking.notes && (
                    <span className="text-xs text-gray-500 dark:text-gray-500 italic">
                      {t("details.notesLabel")}
                    </span>
                  )}
                </div>
              </div>
            </div>

            {/* Actions */}
            <div className="flex items-center gap-2 ml-4">
              <Button
                variant="default"
                size="sm"
                onClick={handleViewClick}
                className="h-9 w-9 p-0"
                aria-label={t("actions.view_details", "View Details")}
                title={t("actions.view_details", "View Details")}
              >
                <Eye className="w-4 h-4" />
              </Button>
              {onDelete && (
                <Button
                  variant={deleteButtonProps.variant}
                  size="sm"
                  onClick={handleDeleteClick}
                  className={`h-9 w-9 p-0 ${deleteButtonProps.iconColor}`}
                  aria-label={deleteButtonProps.ariaLabel}
                  title={deleteButtonProps.title}
                >
                  <Trash2 className="w-4 h-4" />
                </Button>
              )}
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

"use client";

// External libraries
import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { format } from 'date-fns';

// Internal libraries/utilities
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { recurrenceEngine } from '@/components/features/bookings/utils/recurrence';

// Types
import type { RecurrencePattern } from '@/components/features/bookings/utils/recurrence';

interface RecurrencePatternSelectorProps {
  readonly pattern: RecurrencePattern | null;
  readonly onPatternChange: (pattern: RecurrencePattern | null) => void;
  readonly disabled?: boolean;
}

/**
 * RecurrencePatternSelector Component
 * 
 * Allows users to configure recurring booking patterns with various options:
 * - Weekly patterns with specific weekdays
 * - Biweekly patterns
 * - Monthly patterns with specific occurrences
 * - Custom intervals
 * 
 * Features:
 * - Visual weekday selection
 * - Monthly pattern configuration
 * - Custom interval support
 * - Date range selection
 * - Pattern validation
 * - Human-readable descriptions
 * 
 * Usage:
 * - Use pattern to control the current pattern
 * - Use onPatternChange to handle pattern changes
 * - Use disabled to prevent interaction when needed
 */
export function RecurrencePatternSelector({ 
  pattern, 
  onPatternChange, 
  disabled = false 
}: RecurrencePatternSelectorProps): JSX.Element {
  const { t } = useTranslation(['common','booking']);
  const [localPattern, setLocalPattern] = useState<RecurrencePattern>(() => 
    pattern || {
      type: 'weekly',
      weekdays: [], // No default selection - user must choose
      timeSlots: ['09:00-11:00'],
      interval: 1,
      maxOccurrences: 1
    }
  );

  const weekdays = [
    { id: 1, name: t('common:time.weekdays.monday'), short: t('common:time.weekdays.monday').substring(0, 3) },
    { id: 2, name: t('common:time.weekdays.tuesday'), short: t('common:time.weekdays.tuesday').substring(0, 3) },
    { id: 3, name: t('common:time.weekdays.wednesday'), short: t('common:time.weekdays.wednesday').substring(0, 3) },
    { id: 4, name: t('common:time.weekdays.thursday'), short: t('common:time.weekdays.thursday').substring(0, 3) },
    { id: 5, name: t('common:time.weekdays.friday'), short: t('common:time.weekdays.friday').substring(0, 3) },
    { id: 6, name: t('common:time.weekdays.saturday'), short: t('common:time.weekdays.saturday').substring(0, 3) },
    { id: 0, name: t('common:time.weekdays.sunday'), short: t('common:time.weekdays.sunday').substring(0, 3) }
  ];

  const monthlyPatterns = [
    { id: 'first', label: t('booking:recurrence.first', 'First') },
    { id: 'second', label: t('booking:recurrence.second', 'Second') },
    { id: 'third', label: t('booking:recurrence.third', 'Third') },
    { id: 'fourth', label: t('booking:recurrence.fourth', 'Fourth') },
    { id: 'last', label: t('booking:recurrence.last', 'Last') }
  ];



  const handleTypeChange = React.useCallback((type: RecurrencePattern['type']) => {
    setLocalPattern(prevPattern => {
      const newPattern: RecurrencePattern = {
        type,
        weekdays: type === 'single' ? [] : prevPattern.weekdays,
        timeSlots: prevPattern.timeSlots,
        interval: prevPattern.interval,
        startDate: prevPattern.startDate,
        endDate: prevPattern.endDate,
        monthlyPattern: type === 'monthly' ? (prevPattern.monthlyPattern || 'first') : undefined,
        monthlyWeekday: type === 'monthly' ? (prevPattern.monthlyWeekday || 1) : undefined,
        maxOccurrences: prevPattern.maxOccurrences
      };

      return newPattern;
    });
  }, []);

  const handleWeekdayToggle = React.useCallback((weekday: number) => {
    setLocalPattern(prevPattern => {
      const newWeekdays = prevPattern.weekdays.includes(weekday)
        ? prevPattern.weekdays.filter(d => d !== weekday)
        : [...prevPattern.weekdays, weekday];

      const newPattern = {
        ...prevPattern,
        weekdays: newWeekdays
      };

      return newPattern;
    });
  }, []);

  const handleIntervalChange = React.useCallback((interval: number) => {
    setLocalPattern(prevPattern => {
      const newPattern = {
        ...prevPattern,
        interval: Math.max(1, interval)
      };
      return newPattern;
    });
  }, []);

  const handleMonthlyPatternChange = React.useCallback((monthlyPattern: RecurrencePattern['monthlyPattern']) => {
    setLocalPattern(prevPattern => {
      const newPattern = {
        ...prevPattern,
        monthlyPattern
      };
      return newPattern;
    });
  }, []);

  const handleMonthlyWeekdayChange = React.useCallback((monthlyWeekday: number) => {
    setLocalPattern(prevPattern => {
      const newPattern = {
        ...prevPattern,
        monthlyWeekday
      };
      return newPattern;
    });
  }, []);

  const handleEndDateChange = React.useCallback((endDate: Date | undefined) => {
    setLocalPattern(prevPattern => {
      const newPattern = {
        ...prevPattern,
        endDate
      };
      return newPattern;
    });
  }, []);

  const handleMaxOccurrencesChange = React.useCallback((maxOccurrences: number) => {
    setLocalPattern(prevPattern => {
      const newPattern = {
        ...prevPattern,
        maxOccurrences: Math.max(1, maxOccurrences)
      };
      return newPattern;
    });
  }, []);

  // Call onPatternChange when localPattern changes
  React.useEffect(() => {
    onPatternChange(localPattern);
  }, [localPattern]); // Remove onPatternChange from dependencies to prevent infinite loop

  const validation = recurrenceEngine.validatePattern(localPattern, t);

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-lg font-semibold text-gray-900">
          {t('booking:recurrence.title', 'Recurrence pattern')}
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-6">
        {/* Pattern Type Selection */}
        <div>
          <Label className="text-sm font-medium text-gray-700 mb-3 block">
            {t('booking:recurrence.select_pattern', 'Choose pattern')}
          </Label>
          <div className="grid grid-cols-2 gap-3">
              {[
              { id: 'weekly', label: t('booking:recurrence.weekly', 'Weekly'), description: t('booking:recurrence.weekly_desc', 'Every week') },
              { id: 'biweekly', label: t('booking:recurrence.biweekly', 'Every other week'), description: t('booking:recurrence.biweekly_desc', 'Every 2nd week') },
              { id: 'monthly', label: t('booking:recurrence.monthly', 'Monthly'), description: t('booking:recurrence.monthly_desc', 'Every month') },
              { id: 'custom', label: t('booking:recurrence.custom', 'Custom'), description: t('booking:recurrence.custom_desc', 'Custom interval') }
            ].map((type) => (
              <Button
                key={type.id}
                variant={localPattern?.type === type.id ? 'default' : 'outline'}
                onClick={() => !disabled && handleTypeChange(type.id as RecurrencePattern['type'])}
                disabled={disabled}
                className="h-auto p-3 flex flex-col items-center space-y-1"
              >
                <span className="font-medium">{type.label}</span>
                <span className={`text-xs ${localPattern?.type === type.id ? 'text-white' : 'text-gray-600'}`}>
                  {type.description}
                </span>
              </Button>
            ))}
          </div>
        </div>

        {/* Weekday Selection (for weekly, biweekly, custom) */}
        {localPattern && (localPattern.type === 'weekly' || localPattern.type === 'biweekly' || localPattern.type === 'custom') && (
          <div>
            <Label className="text-sm font-medium text-gray-700 mb-3 block">
              {t('booking:recurrence.select_days', 'Select days')}
            </Label>
            <div className="grid grid-cols-7 gap-2">
              {weekdays.map((weekday) => (
                <div key={weekday.id} className="flex flex-col items-center space-y-2">
                  <Checkbox
                    id={`weekday-${weekday.id}`}
                    checked={localPattern.weekdays.includes(weekday.id)}
                    onCheckedChange={() => !disabled && handleWeekdayToggle(weekday.id)}
                    disabled={disabled}
                  />
                  <Label 
                    htmlFor={`weekday-${weekday.id}`}
                    className="text-xs text-center cursor-pointer"
                  >
                    {weekday.short}
                  </Label>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Monthly Pattern Selection */}
        {localPattern && localPattern.type === 'monthly' && (
          <div className="space-y-4">
            <div>
              <Label className="text-sm font-medium text-gray-700 mb-2 block">
                {t('booking:recurrence.which_week', 'Which week of the month')}
              </Label>
              <Select
                value={localPattern.monthlyPattern || 'first'}
                onValueChange={(value) => !disabled && handleMonthlyPatternChange(value as RecurrencePattern['monthlyPattern'])}
                disabled={disabled}
              >
                <SelectTrigger>
                  <SelectValue placeholder={t('common:placeholders.selectWeek', 'Select week')} />
                </SelectTrigger>
                <SelectContent>
                  {monthlyPatterns.map((pattern) => (
                    <SelectItem key={pattern.id} value={pattern.id}>
                      {pattern.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div>
              <Label className="text-sm font-medium text-gray-700 mb-2 block">
                {t('booking:recurrence.which_day', 'Which day')}
              </Label>
              <Select
                value={localPattern.monthlyWeekday?.toString() || '1'}
                onValueChange={(value) => !disabled && handleMonthlyWeekdayChange(parseInt(value))}
                disabled={disabled}
              >
                <SelectTrigger>
                  <SelectValue placeholder={t('common:placeholders.selectDay', 'Select day')} />
                </SelectTrigger>
                <SelectContent>
                  {weekdays.map((weekday) => (
                    <SelectItem key={weekday.id} value={weekday.id.toString()}>
                      {weekday.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
        )}

        {/* Custom Interval */}
        {localPattern && localPattern.type === 'custom' && (
          <div>
            <Label className="text-sm font-medium text-gray-700 mb-2 block">
              {t('booking:recurrence.interval_days', 'Interval (days)')}
            </Label>
            <Input
              type="number"
              min="1"
              value={localPattern.interval || 1}
              onChange={(e) => !disabled && handleIntervalChange(parseInt(e.target.value) || 1)}
              disabled={disabled}
              className="w-32"
            />
          </div>
        )}

        {/* End Date Selection */}
        <div>
          <Label className="text-sm font-medium text-gray-700 mb-2 block">
            {t('common:placeholders.selectEndDate', 'End date (optional)')}
          </Label>
          <Input
            type="date"
            value={localPattern?.endDate ? format(localPattern.endDate, 'yyyy-MM-dd') : ''}
            onChange={(e) => {
              if (e.target.value) {
                const date = new Date(e.target.value);
                handleEndDateChange(date);
              } else {
                handleEndDateChange(undefined);
              }
            }}
            disabled={disabled}
            className="w-full"
            min={format(new Date(), 'yyyy-MM-dd')}
            placeholder={t('common:placeholders.selectEndDate', 'Select end date')}
          />
        </div>

        {/* Max Occurrences */}
        <div>
          <Label className="text-sm font-medium text-gray-700 mb-2 block">
            {t('booking:recurrence.max_occurrences', 'Max occurrences (optional)')}
          </Label>
            <Input
            type="number"
            min="1"
            max="52"
              value={localPattern.maxOccurrences || ''}
            onChange={(e) => !disabled && handleMaxOccurrencesChange(parseInt(e.target.value) || 52)}
            disabled={disabled}
              className="w-32"
              placeholder="1"
          />
        </div>

        {/* Pattern Description */}
        {localPattern && (
          <div className="p-3 bg-gray-100 rounded-lg">
            <p className="text-sm text-gray-900">
              <strong>{t('booking:recurrence.pattern', 'Pattern')}:</strong> {recurrenceEngine.getPatternDescription(localPattern, t)}
            </p>
          </div>
        )}

        {/* Validation Errors */}
        {!validation.isValid && (
          <div className="p-3 bg-red-50 rounded-lg">
            <p className="text-sm text-red-800 font-medium mb-2">{t('booking:recurrence.errors_title', 'Pattern error:')}</p>
            <ul className="text-sm text-red-700 space-y-1">
              {validation.errors.map((error, index) => (
                <li key={index}>• {error}</li>
              ))}
            </ul>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

// External libraries
import React, { useState, useMemo, useCallback, useEffect } from "react";
import { useTranslation } from "react-i18next";
import {
  addDays,
  startOfWeek,
  isToday,
  isWeekend,
  isPast,
} from "date-fns";

// Internal hooks
import { useSlotSelection } from "@/components/features/bookings/hooks";
import {
  useHolidayCalculation,
  useCalendarPricing,
  useRecurrenceHandler,
  useBookingCoordination,
} from "@/hooks/features/calendar";

// Sub-components
import { StepByStepBooking } from "@/components/features/bookings/components/StepByStepBooking";
import { CalendarRenderer } from "./components/CalendarRenderer";
import { BookingFormPanel } from "./components/BookingFormPanel";

// Types
import {
  ISelectedTimeSlot,
  IZone,
  IBookingFormData,
  BookingType,
} from "@/components/features/bookings/types";
import type { RecurrencePattern } from "@/components/features/bookings/utils/recurrence";

/**
 * Facility calendar component
 *
 * Main calendar component that combines time slot selection
 * with booking functionality. Provides a complete booking
 * experience with calendar view and booking form.
 *
 * Features:
 * - Week-based calendar view
 * - Time slot selection
 * - Real-time booking form
 * - Price calculation
 * - Cart integration
 * - Responsive design
 * - Loading states
 *
 * Refactored to use custom hooks and sub-components for
 * better separation of concerns and maintainability.
 */
export interface IFacilityCalendarProps {
  readonly facilityId: string;
  readonly facilityName: string;
  readonly zones: readonly IZone[];
  readonly isLoading?: boolean;
  readonly error?: string;
  readonly selectedSlots?: readonly ISelectedTimeSlot[];
  readonly onSlotClick?: (
    zoneId: string,
    date: Date,
    timeSlot: string,
    status: string
  ) => void;
  readonly onBulkSlotSelection?: (slots: readonly ISelectedTimeSlot[]) => void;
  readonly getAvailabilityStatus?: (
    zoneId: string,
    date: Date,
    timeSlot: string
  ) => {
    status: string;
    conflict?: { readonly id: string; readonly title: string };
  };
  readonly isSlotSelected?: (
    zoneId: string,
    date: Date,
    timeSlot: string
  ) => boolean;
  readonly onAddToCart?: (bookingData: IBookingFormData) => void;
  readonly onCompleteBooking?: (bookingData: IBookingFormData) => void;
  readonly openingHoursStart?: string;
  readonly openingHoursEnd?: string;
  readonly useStepByStepBooking?: boolean;
}

export const FacilityCalendar: React.FC<IFacilityCalendarProps> = ({
  facilityId,
  facilityName,
  zones,
  isLoading = false,
  error,
  selectedSlots: externalSelectedSlots,
  onSlotClick: externalOnSlotClick,
  onBulkSlotSelection: externalOnBulkSlotSelection,
  getAvailabilityStatus: externalGetAvailabilityStatus,
  isSlotSelected: externalIsSlotSelected,
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  onAddToCart: _externalOnAddToCart,
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  onCompleteBooking: _externalOnCompleteBooking,
  openingHoursStart = "08:00",
  openingHoursEnd = "22:00",
  useStepByStepBooking = false,
}) => {
  const { t } = useTranslation("calendar");

  // State for current week
  const [currentWeekStart, setCurrentWeekStart] = useState(() =>
    startOfWeek(new Date(), { weekStartsOn: 1 })
  );

  // State for selected zone
  const [selectedZoneId, setSelectedZoneId] = useState(zones?.[0]?.id || "");

  // Custom hooks
  const { checkIfHoliday, getHolidayName } = useHolidayCalculation();
  const { calculatePricing, 
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    formatPrice: _formatPrice } = useCalendarPricing();
  const {
    pattern: recurrencePattern,
    setPattern: setRecurrencePattern,
    generateRecurringSlots,
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    clearPattern: _clearRecurrencePattern,
  } = useRecurrenceHandler();

  // Slot selection hook
  const {
    selectedSlots: internalSelectedSlots,
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    recurringSlots: _recurringSlots,
    handleSlotClick: internalHandleSlotClick,
    handleBulkSlotSelection: internalHandleBulkSlotSelection,
    clearSelection: internalClearSelection,
    setSelectedSlots,
    clearRecurringSlots,
  } = useSlotSelection();

  // Get selected zone
  const selectedZone = zones?.find((zone) => zone.id === selectedZoneId);

  // Booking coordination hook
  const {
    handleAddToCart: coordinatedAddToCart,
    handleCompleteBooking: coordinatedCompleteBooking,
    handleSlotClickCoordination,
    handleBulkSelectCoordination,
  } = useBookingCoordination({
    facilityId,
    facilityName,
    selectedZone,
    recurrencePattern,
    t: t as unknown as (key: string) => string,
  });

  // Use external props if available, otherwise use internal state
  const selectedSlots = externalSelectedSlots || internalSelectedSlots;
  const handleSlotClick = externalOnSlotClick || internalHandleSlotClick;
  const handleBulkSlotSelection =
    externalOnBulkSlotSelection || internalHandleBulkSlotSelection;
  const clearSelection = internalClearSelection;

  // Set default zone when zones are loaded
  useEffect(() => {
    if (zones && zones.length > 0 && !selectedZoneId) {
      setSelectedZoneId(zones[0].id);
    }
  }, [zones, selectedZoneId]);

  /**
   * Handle slots change from BookingForm
   */
  const handleSlotsChange = useCallback(
    (slots: readonly ISelectedTimeSlot[]): void => {
      setSelectedSlots(slots);
    },
    [setSelectedSlots]
  );

  /**
   * Generate calendar week data with holiday information
   */
  const calendarWeek = useMemo(() => {
    const days = Array.from({ length: 7 }, (_, i) => {
      const date = addDays(currentWeekStart, i);
      return {
        date,
        isToday: isToday(date),
        isWeekend: isWeekend(date),
        isHoliday: checkIfHoliday(date),
        holidayName: getHolidayName(date),
        isPast: isPast(date),
        timeSlots: [],
      };
    });

    return {
      startDate: currentWeekStart,
      endDate: addDays(currentWeekStart, 6),
      days,
    };
  }, [currentWeekStart, checkIfHoliday, getHolidayName]);

  /**
   * Get all selected slots with facility context
   */
  const allSelectedSlots = useMemo(() => {
    if (!selectedZone) return [];

    const enrichedSlots = selectedSlots.map((slot) => ({
      ...slot,
      facilityName,
      zoneName: selectedZone.name,
    }));

    return enrichedSlots;
  }, [selectedSlots, facilityName, selectedZone?.id, selectedZone?.name]);

  // For step-by-step booking
  const stepByStepSelectedSlots = useStepByStepBooking
    ? selectedSlots
    : allSelectedSlots;

  /**
   * Handle time slot click with zone context
   */
  const handleSlotClickWithZone = useCallback(
    (zoneId: string, date: Date, timeSlot: string, status: string): void => {
      handleSlotClickCoordination(
        zoneId,
        date,
        timeSlot,
        status,
        handleSlotClick,
        stepByStepSelectedSlots,
        handleSlotsChange,
        useStepByStepBooking,
        selectedZone?.pricePerHour || 0
      );
    },
    [
      handleSlotClickCoordination,
      handleSlotClick,
      stepByStepSelectedSlots,
      handleSlotsChange,
      useStepByStepBooking,
      selectedZone?.pricePerHour,
    ]
  );

  /**
   * Handle bulk slot selection with zone context
   */
  const handleBulkSelectWithZone = useCallback(
    (slots: readonly ISelectedTimeSlot[]): void => {
      handleBulkSelectCoordination(
        slots,
        handleBulkSlotSelection,
        stepByStepSelectedSlots,
        handleSlotsChange,
        useStepByStepBooking,
        selectedZone?.pricePerHour || 0
      );
    },
    [
      handleBulkSelectCoordination,
      handleBulkSlotSelection,
      stepByStepSelectedSlots,
      handleSlotsChange,
      useStepByStepBooking,
      selectedZone?.pricePerHour,
    ]
  );

  /**
   * Week navigation handlers
   */
  const handlePreviousWeek = useCallback((): void => {
    setCurrentWeekStart((prev) => addDays(prev, -7));
  }, []);

  const handleNextWeek = useCallback((): void => {
    setCurrentWeekStart((prev) => addDays(prev, 7));
  }, []);

  /**
   * Handle add to cart
   */
  const handleAddToCart = useCallback(
    (bookingData: IBookingFormData): void => {
      const slotsToUse =
        bookingData.recurringSlots && bookingData.recurringSlots.length > 0
          ? bookingData.recurringSlots
          : allSelectedSlots;

      const pricing = calculatePricing(
        slotsToUse,
        bookingData.actorType,
        bookingData.activityType
      );

      coordinatedAddToCart(
        {
          purpose: bookingData.purpose,
          attendees: bookingData.attendees,
          activityType: bookingData.activityType,
          additionalInfo: bookingData.additionalInfo || "",
          actorType: bookingData.actorType,
          bookingType: bookingData.bookingType,
          recurrencePattern: bookingData.recurrencePattern,
          recurringSlots: bookingData.recurringSlots,
        },
        allSelectedSlots,
        pricing,
        clearSelection,
        clearRecurringSlots
      );
    },
    [
      allSelectedSlots,
      calculatePricing,
      coordinatedAddToCart,
      clearSelection,
      clearRecurringSlots,
    ]
  );

  /**
   * Handle add to cart for BookingFormPanel (without termsAccepted)
   */
  const handleAddToCartForPanel = useCallback(
    (bookingData: {
      readonly purpose: string;
      readonly attendees: number;
      readonly activityType: string;
      readonly additionalInfo: string;
      readonly actorType: string;
      readonly bookingType: BookingType;
      readonly recurrencePattern?: RecurrencePattern | null;
      readonly recurringSlots?: readonly ISelectedTimeSlot[];
    }): void => {
      handleAddToCart({
        ...bookingData,
        termsAccepted: false,
      } as IBookingFormData);
    },
    [handleAddToCart]
  );

  /**
   * Handle complete booking
   */
  const handleCompleteBooking = useCallback(
    (bookingData: IBookingFormData): void => {
      const slotsToUse =
        bookingData.recurringSlots && bookingData.recurringSlots.length > 0
          ? bookingData.recurringSlots
          : allSelectedSlots;

      const pricing = calculatePricing(
        slotsToUse,
        bookingData.actorType,
        bookingData.activityType
      );

      coordinatedCompleteBooking(
        {
          purpose: bookingData.purpose,
          attendees: bookingData.attendees,
          activityType: bookingData.activityType,
          additionalInfo: bookingData.additionalInfo || "",
          actorType: bookingData.actorType,
          bookingType: bookingData.bookingType,
          recurrencePattern: bookingData.recurrencePattern,
          recurringSlots: bookingData.recurringSlots,
        },
        allSelectedSlots,
        pricing,
        clearSelection,
        clearRecurringSlots
      );
    },
    [
      allSelectedSlots,
      calculatePricing,
      coordinatedCompleteBooking,
      clearSelection,
      clearRecurringSlots,
    ]
  );

  /**
   * Handle complete booking for BookingFormPanel (without termsAccepted)
   */
  const handleCompleteBookingForPanel = useCallback(
    (bookingData: {
      readonly purpose: string;
      readonly attendees: number;
      readonly activityType: string;
      readonly additionalInfo: string;
      readonly actorType: string;
      readonly bookingType: BookingType;
      readonly recurrencePattern?: RecurrencePattern | null;
      readonly recurringSlots?: readonly ISelectedTimeSlot[];
    }): void => {
      handleCompleteBooking({
        ...bookingData,
        termsAccepted: false,
      } as IBookingFormData);
    },
    [handleCompleteBooking]
  );

  /**
   * Handle booking type change
   */
  const handleBookingTypeChange = useCallback(
    (type: BookingType): void => {
      if (type === "one-time") {
        clearRecurringSlots();
      }
    },
    [clearRecurringSlots]
  );

  /**
   * Handle recurrence pattern change
   */
  const handleRecurrencePatternChange = useCallback(
    (pattern: RecurrencePattern | null): void => {
      if (pattern && selectedZone) {
        setRecurrencePattern(pattern);
        generateRecurringSlots(
          pattern,
          new Date(),
          selectedZone.id,
          facilityId,
          selectedZone.pricePerHour,
          pattern.maxOccurrences || 52
        );
      } else {
        clearRecurringSlots();
      }
    },
    [
      selectedZone,
      generateRecurringSlots,
      clearRecurringSlots,
      facilityId,
      setRecurrencePattern,
    ]
  );

  // Loading state
  if (isLoading) {
    return (
      <div className="bg-gray-50 py-8">
        <div className="max-w-7xl mx-auto px-4">
          <div className="text-center py-12">
            <p className="text-gray-500">{t("loading.calendar")}</p>
          </div>
        </div>
      </div>
    );
  }

  // Error state
  if (error) {
    return (
      <div className="bg-gray-50 py-8">
        <div className="max-w-7xl mx-auto px-4">
          <div className="text-center py-12">
            <p className="text-red-500">
              {t("messages.error_prefix")}: {error}
            </p>
          </div>
        </div>
      </div>
    );
  }

  // No zones state
  if (!zones || zones.length === 0) {
    return (
      <div className="bg-gray-50 py-8">
        <div className="max-w-7xl mx-auto px-4">
          <div className="text-center py-12">
            <p className="text-gray-500">{t("messages.no_zones_available")}</p>
          </div>
        </div>
      </div>
    );
  }

  // No selected zone state
  if (!selectedZone) {
    return (
      <div className="bg-gray-50 py-8">
        <div className="max-w-7xl mx-auto px-4">
          <div className="text-center py-12">
            <p className="text-gray-500">{t("loading.zones")}</p>
          </div>
        </div>
      </div>
    );
  }

  // Step-by-step booking mode
  if (useStepByStepBooking) {
    return (
      <div className="bg-gray-50 py-8">
        <div className="w-full px-4">
          <StepByStepBooking
            facilityId={facilityId}
            facilityName={facilityName}
            zones={zones}
            selectedZoneId={selectedZoneId}
            onZoneChange={setSelectedZoneId}
            selectedSlots={stepByStepSelectedSlots}
            onSlotsChange={handleSlotsChange}
            onAddToCart={handleAddToCart}
            onCompleteBooking={handleCompleteBooking}
            isLoading={isLoading}
            error={error}
            openingHoursStart={openingHoursStart}
            openingHoursEnd={openingHoursEnd}
            calendarWeek={{
              start: calendarWeek.startDate,
              end: calendarWeek.endDate
            }}
            onSlotClick={handleSlotClickWithZone}
            onBulkSlotSelection={handleBulkSelectWithZone}
            getAvailabilityStatus={externalGetAvailabilityStatus}
            isSlotSelected={externalIsSlotSelected}
          />
        </div>
      </div>
    );
  }

  // Standard calendar view
  return (
    <div className="bg-gray-50 py-8">
      <div className="w-full px-4">
        <div className="space-y-6">
          {/* 60/40 Layout for Calendar and Booking Form */}
          <div className="grid grid-cols-1 lg:grid-cols-5 gap-6">
            {/* Left Column - Calendar (60%) */}
            <div className="lg:col-span-3">
              <CalendarRenderer
                facilityId={facilityId}
                zones={zones}
                selectedZoneId={selectedZoneId}
                onZoneChange={setSelectedZoneId}
                calendarWeek={calendarWeek}
                currentWeekStart={currentWeekStart}
                onPreviousWeek={handlePreviousWeek}
                onNextWeek={handleNextWeek}
                selectedSlots={selectedSlots}
                onSlotClick={handleSlotClickWithZone}
                onBulkSelect={handleBulkSelectWithZone}
                pricePerHour={selectedZone?.pricePerHour || 0}
                isLoading={isLoading}
                error={error}
                getAvailabilityStatus={externalGetAvailabilityStatus}
                isSlotSelected={externalIsSlotSelected}
                openingHoursStart={openingHoursStart}
                openingHoursEnd={openingHoursEnd}
              />
            </div>

            {/* Right Column - Booking Form (40%) */}
            <div className="lg:col-span-2">
              <BookingFormPanel
                facilityId={facilityId}
                facilityName={facilityName}
                zoneId={selectedZone.id}
                selectedSlots={allSelectedSlots}
                onSlotsChange={handleSlotsChange}
                onAddToCart={handleAddToCartForPanel}
                onCompleteBooking={handleCompleteBookingForPanel}
                isLoading={isLoading}
                error={error}
                bookingType="one-time"
                onBookingTypeChange={handleBookingTypeChange}
                recurrencePattern={recurrencePattern}
                onRecurrencePatternChange={handleRecurrencePatternChange}
                showRecurrenceSelector={false}
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default FacilityCalendar;

