"use client";

import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { MapPin, Users, Heart, Share2 } from "lucide-react";

import { useTranslation } from "react-i18next";
import type { Database } from "@/types/database";
import { useFieldConfigStore } from "@/stores/fieldConfigStore";

import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import {
  getFieldUnit,
  generateShareUrl,
  copyToClipboard,
} from "@/components/features/facilities/utils/formatters";
import { useAmenityTranslation } from "@/hooks/shared";
import { useFacilityTypeTranslation } from "@/hooks/shared/useFacilityTypeTranslation";
import { useAuth } from "@/contexts/hooks/useAuth";

// Import the favorites store
import { useFavoritesStore } from "@/stores/favoritesStore";

type Facility = Database['public']['Tables']['facilities']['Row'];

interface FacilityCardProps {
  readonly facility: Facility;
  readonly onAddressClick: (e: React.MouseEvent, facility: Facility) => void;
  readonly viewMode?: "grid" | "list";
}

/**
 * FacilityCard Component
 *
 * SOLID Principles Applied:
 * - Single Responsibility: Displays facility information only
 * - Open/Closed: Extensible through props without modification
 * - Dependency Inversion: Uses i18n translations for text content
 */
export const FacilityCard = ({
  facility,
  onAddressClick,
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  viewMode: _viewMode = "grid",
}: FacilityCardProps): JSX.Element => {
  const { t } = useTranslation(["facility", "common"]);
  const { user } = useAuth();
  const translateAmenity = useAmenityTranslation();
  const translateFacilityType = useFacilityTypeTranslation();
  const navigate = useNavigate();
  const [isHovered, setIsHovered] = useState(false);

  // Use the favorites store instead of local state
  const { isFavorite, toggleFavorite } = useFavoritesStore();
  const isFavorited = isFavorite(facility.id);

  const { getFieldConfigsForFacility } = useFieldConfigStore();
  const fieldConfigs = getFieldConfigsForFacility(facility.id);

  const handleCardClick = (): void => {
    // Use slug for SEO-friendly URLs, fallback to id for backward compatibility
    const facilityPath = facility.slug || facility.id;
    navigate(`/facilities/${facilityPath}`);
  };

  const handleShare = async (e: React.MouseEvent): Promise<void> => {
    e.stopPropagation();
    try {
      const facilityPath = facility.slug || facility.id;
      const shareUrl = generateShareUrl(`/facilities/${facilityPath}`);

      if (navigator.share) {
        await navigator.share({
          title: facility.name,
          url: shareUrl,
        });
      } else {
        await copyToClipboard(shareUrl);
      }
    } catch (error) {
      if (error instanceof Error && error.name !== "AbortError") {
        try {
          const facilityPath = facility.slug || facility.id;
          const shareUrl = generateShareUrl(`/facilities/${facilityPath}`);
          await copyToClipboard(shareUrl);
        } catch (clipboardError) {
          console.error("Failed to share or copy:", clipboardError);
        }
      }
    }
  };

  const handleFavorite = async (e: React.MouseEvent): Promise<void> => {
    e.stopPropagation();
    if (user) {
      await toggleFavorite(facility.id);
    }
  };

  const getFieldValue = (fieldKey: string): string | number => {
    const valueMap: Record<string, string | number> = {
      capacity: facility.capacity || 0,
      rating: facility.rating || 0,
      reviewCount: facility.review_count || 0,
    };
    return valueMap[fieldKey] || "";
  };

  const getFieldIcon = (fieldKey: string): JSX.Element => {
    const iconMap: Record<string, JSX.Element> = {
      capacity: <Users className="h-5 w-5" />,
      area: <MapPin className="h-5 w-5" />,
      pricePerHour: <span className="text-gray-400">💰</span>,
      rating: <span className="text-yellow-500">★</span>,
      reviewCount: <span className="text-gray-400">📝</span>,
    };
    return iconMap[fieldKey] || <span className="text-gray-400">📋</span>;
  };

  const translationKeys = {
    people: t("facility:card.people"),
    squareMeters: t("facility:card.squareMeters"),
    pricePerHour: t("facility:card.pricePerHour"),
    outOf5: t("facility:card.outOf5"),
    reviewCount: t("facility:card.reviewCount"),
    yes: t("facility:card.yes"),
    no: t("facility:card.no"),
  };

  return (
    <Card
      className="group overflow-hidden hover:shadow-2xl transition-all duration-500 hover:translate-y-[-8px] border-0 shadow-lg bg-white relative cursor-pointer focus:outline-none focus:ring-4 focus:ring-blue-500 focus:ring-opacity-50 h-full flex flex-col"
      onClick={handleCardClick}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      role="button"
      tabIndex={0}
      aria-label={t("facility:card.viewDetailsFor", {
        name: facility.name,
        address: facility.address,
      })}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          handleCardClick();
        }
      }}
    >
      {/* Image Section */}
      <div className="relative h-48 sm:h-56 md:h-64 overflow-hidden">
        <img
          src={(facility.images && Array.isArray(facility.images) && facility.images.length > 0 ? facility.images[0] as string : "/placeholder.svg")}
          alt={facility.name}
          className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700"
        />

        {/* Overlay buttons - only show favorite button when user is logged in */}
        <div className="absolute top-2 sm:top-3 md:top-4 right-2 sm:right-3 md:right-4 flex gap-1 sm:gap-2">
          {user && (
            <button
              onClick={handleFavorite}
              className="p-1.5 sm:p-2 rounded-full bg-white/90 backdrop-blur-sm shadow-lg hover:bg-white transition-colors"
              aria-label={t("facility:card.addToFavorites")}
            >
              <Heart
                className={`h-3 w-3 sm:h-4 sm:w-4 ${
                  isFavorited ? "fill-red-500 text-red-500" : "text-gray-600"
                }`}
              />
            </button>
          )}
          <button
            onClick={handleShare}
            className="p-1.5 sm:p-2 rounded-full bg-white/90 backdrop-blur-sm shadow-lg hover:bg-white transition-colors"
            aria-label={t("facility:card.shareFacility")}
          >
            <Share2 className="h-3 w-3 sm:h-4 sm:w-4 text-gray-600" />
          </button>
        </div>

        {/* Type badge */}
        <div className="absolute top-2 sm:top-3 md:top-4 left-2 sm:left-3 md:left-4">
          <Badge className="bg-blue-600 text-white font-medium px-2 py-1 text-xs sm:text-sm">
            {translateFacilityType(facility.facility_type || '')}
          </Badge>
        </div>
      </div>

      {/* Content Section */}
      <div className="flex-1 flex flex-col p-4 sm:p-5 md:p-6">
        {/* Facility Name */}
        <h3 className="text-lg sm:text-xl md:text-2xl font-bold text-gray-900 mb-3 sm:mb-4 line-clamp-2">
          {facility.name}
        </h3>

        {/* Location */}
        <div className="flex items-center gap-2 sm:gap-3 mb-4 sm:mb-5 text-gray-600 hover:text-blue-600 transition-colors group/location">
          <MapPin className="h-4 w-4 sm:h-5 sm:w-5 text-gray-400 group-hover/location:text-blue-500 flex-shrink-0" />
          <span
            className="text-sm sm:text-base font-medium line-clamp-1 cursor-pointer"
            onClick={(e) => onAddressClick(e, facility)}
          >
            {facility.address}
          </span>
        </div>

        {/* Description */}
        <p className="text-gray-700 text-sm sm:text-base leading-relaxed mb-3 sm:mb-4 line-clamp-2">
          {facility.description}
        </p>

        {/* Amenities Tags */}
        {facility.amenities && Array.isArray(facility.amenities) && facility.amenities.length > 0 && (
          <div className="flex flex-wrap gap-1.5 sm:gap-2 mb-4 sm:mb-5">
            {facility.amenities.slice(0, 3).map((amenity, index) => (
              <Badge
                key={index}
                className="bg-blue-50 text-blue-700 border-blue-200 font-medium px-2 py-1 text-xs sm:text-sm hover:bg-blue-100 transition-colors"
              >
                {translateAmenity(amenity as string)}
              </Badge>
            ))}
            {facility.amenities.length > 3 && (
              <Badge
                variant="outline"
                className="bg-gray-50 text-gray-600 border-gray-300 font-medium px-2 py-1 text-xs sm:text-sm"
              >
                +{facility.amenities.length - 3}{" "}
                {t("facility:card.moreAmenities")}
              </Badge>
            )}
          </div>
        )}

        {/* Dynamic fields based on configuration */}
        <div className="space-y-2 mt-auto">
          {fieldConfigs
            .filter((field) => field.visible)
            .map((field) => {
              const value = getFieldValue(field.key);
              const unit = getFieldUnit(field.key, translationKeys);
              const booleanValue =
                typeof field.value === "boolean"
                  ? field.value
                    ? translationKeys.yes
                    : translationKeys.no
                  : "";

              return (
                <div
                  key={field.id}
                  className="flex items-center gap-2 sm:gap-3 text-gray-600"
                >
                  {getFieldIcon(field.key)}
                  <span className="text-sm sm:text-base font-medium">
                    {t(field.label as any)}: {value || booleanValue}
                    {unit && ` ${unit}`}
                  </span>
                </div>
              );
            })}
        </div>
      </div>

      {/* Hover Effect Border */}
      <div
        className={`absolute inset-0 rounded-xl border-2 border-blue-400 transition-opacity duration-300 pointer-events-none ${
          isHovered ? "opacity-100" : "opacity-0"
        }`}
      />
    </Card>
  );
};

"use client";

import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import { MapPin, Users, Edit, Trash2, Eye, Plus, AlertTriangle, Copy, Save, Image as ImageIcon } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { toast } from "react-toastify";
import { FacilityMiniMap } from "@/components/features/facilities/components/FacilityMap/FacilityMiniMap";

import type { Database } from '@/types/database';
import { useAmenityTranslation } from '@/hooks/shared/useAmenityTranslation';

type Facility = Database['public']['Tables']['facilities']['Row'];

interface IAdminFacilityListItemProps {
  readonly facility: Facility;
  readonly onDelete?: (facilityId: string) => void;
  readonly onToggleStatus?: (facilityId: string, newStatus: "published" | "draft" | "archived") => void;
  readonly onDuplicate?: (facilityId: string) => void;
}

const AdminFacilityListItem = ({ facility, onDelete, 
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  onToggleStatus: _onToggleStatus, onDuplicate }: IAdminFacilityListItemProps): JSX.Element => {
  const { t } = useTranslation(['admin', 'facility', 'common']);
  const translateAmenity = useAmenityTranslation();

  // Create a flexible translation function that ensures string return
  const translate = (key: string, options?: Record<string, unknown>): string => {
    // Handle facility namespace keys separately
    if (key.startsWith('facility:')) {
      return t(key as any, options);
    }
    // For admin namespace keys, use the admin namespace
    return t(key as any, options);
  };

  // Simple amenities translation map - DEPRECATED: Using useAmenityTranslation hook instead
  /*
  const translateAmenityOld = (amenity: string): string => {
    const amenityMap: Record<string, string> = {
      // Norwegian to English translations
      'innendørs': 'indoor',
      'profesjonell-underlag': 'professional-underlay',
      'garderober': 'lockers',
      'wifi': 'wifi',
      'parking': 'parking',
      'projector': 'projector',
      'whiteboard': 'whiteboard',
      'kitchen': 'kitchen',
      'bathroom': 'bathroom',
      'air-conditioning': 'air-conditioning',
      'heating': 'heating',
      'sound-system': 'sound-system',
      'outdoor': 'outdoor',
      'indoor': 'indoor'
    };

    // Return English translation if available, otherwise return original
    return amenityMap[amenity.toLowerCase()] || amenity;
  };
  */

  const navigate = useNavigate();
  const [isEditing, setIsEditing] = useState<boolean>(false);
  const [editValue, setEditValue] = useState<string>("");
  const [editField, setEditField] = useState<string>("");
  const [showDeleteConfirm, setShowDeleteConfirm] = useState<boolean>(false);
  const [showEditModal, setShowEditModal] = useState<boolean>(false);
  const [showImageModal, setShowImageModal] = useState<boolean>(false);
  const [showAmenitiesModal, setShowAmenitiesModal] = useState<boolean>(false);
  const [editFormData, setEditFormData] = useState<{
    name: string;
    address: string | null;
    description: string | null;
    capacity: number;
    facility_type: string;
    amenities: string[] | null;
  }>({
    name: facility.name,
    address: facility.address,
    description: facility.description,
    capacity: facility.capacity,
    facility_type: facility.facility_type,
    amenities: facility.amenities ? (Array.isArray(facility.amenities) ? facility.amenities : JSON.parse(facility.amenities as string)) : null
  });

  const handleCardClick = (): void => {
    // Use slug if available, otherwise use ID
    const urlId = facility.slug || facility.id;
    navigate(`/admin/facilities/${urlId}/edit`);
  };


  const handleDelete = (e: React.MouseEvent): void => {
    e.stopPropagation();
    setShowDeleteConfirm(true);
  };

  const confirmDelete = (): void => {
    onDelete?.(facility.id);
    setShowDeleteConfirm(false);
  };

  const handleView = (e: React.MouseEvent): void => {
    e.stopPropagation();
    // Use slug if available, otherwise use ID
    const urlId = facility.slug || facility.id;
    navigate(`/facilities/${urlId}`);
  };

  const handleDuplicate = (e: React.MouseEvent): void => {
    e.stopPropagation();
    if (onDuplicate) {
      onDuplicate(facility.id);
    }
  };

  const handleInlineEdit = (e: React.MouseEvent, field: string): void => {
    e.stopPropagation();
    setIsEditing(true);
    setEditField(field);
    setEditValue((field === "name" ? facility.name : field === "address" ? facility.address : facility.description) || "");
  };

  const handleSaveEdit = (): void => {
    try {
      // Simulate saving to backend/localStorage
      const updatedFacility = {
        ...facility,
        [editField]: editValue
      };

      // Save to localStorage (simulating backend)
      const facilities = JSON.parse(localStorage.getItem('adminFacilities') || '[]');
      const updatedFacilities = facilities.map((f: Facility) => 
        f.id === facility.id ? updatedFacility : f
      );
      localStorage.setItem('adminFacilities', JSON.stringify(updatedFacilities));

      // Show success message
      toast.success(translate('facility:messages.success.facility_updated'));
      setIsEditing(false);
      setEditField("");
    } catch (error) {
      console.error('Failed to save facility:', error);
      toast.error(translate('facility:messages.error.save_error'));
    }
  };

  const handleCancelEdit = (): void => {
    setIsEditing(false);
    setEditValue("");
    setEditField("");
  };

  const handleTagClick = (tag: string, e: React.MouseEvent): void => {
    e.stopPropagation();
    setShowEditModal(true);
  };

  const handleEditModal = (e: React.MouseEvent): void => {
    e.stopPropagation();
    setShowEditModal(true);
  };

  const handleSaveModalEdit = (): void => {
    try {
      const updatedFacility = {
        ...facility,
        ...editFormData
      };

      // Save to localStorage (simulating backend)
      const facilities = JSON.parse(localStorage.getItem('adminFacilities') || '[]');
      const updatedFacilities = facilities.map((f: Facility) => 
        f.id === facility.id ? updatedFacility : f
      );
      localStorage.setItem('adminFacilities', JSON.stringify(updatedFacilities));

      toast.success(translate('facility:messages.success.facility_updated'));
      setShowEditModal(false);
    } catch (error) {
      console.error('Failed to save facility:', error);
      toast.error(translate('facility:messages.error.save_error'));
    }
  };

  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const _handleImageUpload = (
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    _e: React.MouseEvent
  ): void => {
    setShowImageModal(true);
  };

  const handleImageUploadSubmit = (files: FileList | null): void => {
    if (!files || files.length === 0) return;

    try {
      // Simulate image upload
      const imageUrls = Array.from(files).map(file => URL.createObjectURL(file));
      const updatedFacility = {
        ...facility,
        images: facility.images ? [...(Array.isArray(facility.images) ? facility.images : []), ...imageUrls] : imageUrls
      };

      // Save to localStorage (simulating backend)
      const facilities = JSON.parse(localStorage.getItem('adminFacilities') || '[]');
      const updatedFacilities = facilities.map((f: Facility) => 
        f.id === facility.id ? updatedFacility : f
      );
      localStorage.setItem('adminFacilities', JSON.stringify(updatedFacilities));

      toast.success(translate('facility:messages.success.images_uploaded'));
      setShowImageModal(false);
    } catch (error) {
      console.error('Failed to upload images:', error);
      toast.error(translate('facility:messages.error.image_upload_error'));
    }
  };

  const handleShowAllAmenities = (): void => {
    setShowAmenitiesModal(true);
  };

  return (
    <>
    <div className="border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden hover:shadow-md transition-shadow">
      <div className="flex min-h-[128px]" onClick={handleCardClick}>
        {/* Image Section */}
        <div className="relative w-48 min-h-[128px] bg-gray-200 dark:bg-gray-700 flex-shrink-0 flex items-center justify-center">
          {facility.images && (Array.isArray(facility.images) ? facility.images[0] : JSON.parse(facility.images as string)[0]) ? (
            <img 
              src={Array.isArray(facility.images) ? facility.images[0] : JSON.parse(facility.images as string)[0]} 
              alt={facility.name} 
              className="w-full h-full object-cover"
            />
          ) : (
            <div className="w-full h-full bg-gray-200 dark:bg-gray-700 rounded-lg flex items-center justify-center">
              <ImageIcon className="w-8 h-8 text-gray-400" />
            </div>
          )}

          {/* Type badge */}
          <div className="absolute top-2 left-2">
            <Badge className="bg-blue-600 text-white text-xs">
              {facility.facility_type}
            </Badge>
          </div>

          {/* Admin Action Buttons */}
          <div className="absolute top-2 right-2 flex gap-2">
            <Button
              onClick={handleView}
              size="sm"
              variant="secondary"
              className="h-7 w-7 p-0 bg-white/90 backdrop-blur-sm shadow-lg hover:bg-white"
              aria-label={translate('pages.facilities.card.view_main_app')}
            >
              <Eye className="h-3 w-3" />
            </Button>
            <Button
              onClick={handleDuplicate}
              size="sm"
              variant="outline"
              className="h-7 w-7 p-0 bg-blue-500/90 backdrop-blur-sm shadow-lg hover:bg-blue-600 text-white border-blue-600"
              aria-label={translate('pages.facilities.card.duplicate')}
            >
              <Copy className="h-3 w-3" />
            </Button>
            <Button
              onClick={handleDelete}
              size="sm"
              variant="destructive"
              className="h-7 w-7 p-0 bg-red-500/90 backdrop-blur-sm shadow-lg hover:bg-red-600"
              aria-label={translate('pages.facilities.card.delete')}
            >
              <Trash2 className="h-3 w-3" />
            </Button>
          </div>
        </div>

        {/* Content Section */}
        <div className="flex-1 p-4 flex flex-col min-w-0">
          <div className="flex items-start justify-between mb-2 flex-shrink-0">
            <div className="flex-1 min-w-0">
              {/* Facility Name - Clickable for inline editing */}
              <div className="mb-1">
                {isEditing ? (
                  <div className="flex items-center gap-2">
                    <input
                      type="text"
                      value={editValue}
                      onChange={(e) => setEditValue(e.target.value)}
                      className="flex-1 px-2 py-1 border border-gray-300 dark:border-gray-600 rounded text-lg font-semibold text-gray-900 dark:text-white bg-white dark:bg-gray-800"
                      autoFocus
                      onBlur={handleSaveEdit}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter') handleSaveEdit();
                        if (e.key === 'Escape') handleCancelEdit();
                      }}
                    />
                  </div>
                ) : (
                  <h3 
                    className="text-lg font-semibold text-gray-900 dark:text-white mb-1 hover:bg-gray-50 dark:hover:bg-gray-700 px-1 py-1 rounded cursor-pointer transition-colors truncate"
                    onClick={(e) => handleInlineEdit(e, "name")}
                  >
                    {facility.name}
                  </h3>
                )}
              </div>

              {/* Location - Clickable for inline editing */}
              <div className="flex items-center gap-2 mb-2 text-gray-600 dark:text-gray-400 hover:text-blue-600 dark:hover:text-blue-400 transition-colors group/location">
                <MapPin className="h-4 w-4 text-gray-400 dark:text-gray-500 group-hover/location:text-blue-500 flex-shrink-0" />
                <span 
                  className="text-sm font-medium cursor-pointer hover:bg-gray-50 dark:hover:bg-gray-700 px-1 py-1 rounded transition-colors truncate"
                  onClick={(e) => handleInlineEdit(e, "address")}
                >
                  {facility.address}
                </span>
              </div>
            </div>
          </div>

          {/* Description - Clickable for inline editing */}
          <p 
            className="text-sm text-gray-600 dark:text-gray-400 mb-3 line-clamp-2 hover:bg-gray-50 dark:hover:bg-gray-700 px-1 py-1 rounded cursor-pointer transition-colors"
            onClick={(e) => handleInlineEdit(e, "description")}
          >
            {facility.description}
          </p>

          <div className="flex items-center justify-between mt-auto">
            <div className="flex items-center space-x-4 flex-shrink-0">
              {/* Capacity */}
              <div className="flex items-center gap-1 text-gray-600 dark:text-gray-400">
                <Users className="h-4 w-4" />
                <span className="font-medium text-sm">{translate('pages.facilities.card.capacity', { capacity: facility.capacity } as any)}</span>
              </div>

              {/* Amenities Tags - Clickable for facility editing */}
              {facility.amenities && (Array.isArray(facility.amenities) ? facility.amenities : JSON.parse(facility.amenities as string)).length > 0 && (
                <div className="flex flex-wrap gap-1">
                  {(Array.isArray(facility.amenities) ? facility.amenities : JSON.parse(facility.amenities as string)).slice(0, 3).map((amenity: string, index: number) => (
                    <button
                      key={index}
                      onClick={(e) => handleTagClick(amenity, e)}
                      className="bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-300 border-blue-200 dark:border-blue-800 font-medium px-2 py-1 text-xs rounded-md hover:bg-blue-100 dark:hover:bg-blue-900/30 transition-colors"
                    >
                      {translateAmenity(amenity)}
                    </button>
                  ))}
                  {(Array.isArray(facility.amenities) ? facility.amenities : JSON.parse(facility.amenities as string)).length > 3 && (
                    <button
                      onClick={handleShowAllAmenities}
                      className="bg-gray-50 dark:bg-gray-800 text-gray-600 dark:text-gray-400 border-gray-300 dark:border-gray-600 font-medium px-2 py-1 text-xs rounded-md hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors"
                    >
                      {translate('pages.facilities.card.show_more_amenities', { count: (Array.isArray(facility.amenities) ? facility.amenities : JSON.parse(facility.amenities as string)).length - 3 } as any)}
                    </button>
                  )}
                </div>
              )}
            </div>

            {/* Bottom section */}
            <div className="flex gap-2 flex-shrink-0">
              <Button
                onClick={(e) => {
                  e.stopPropagation();
                  handleEditModal(e);
                }}
                size="sm"
                variant="outline"
                className="h-8 px-3"
              >
                <Edit className="h-3 w-3 mr-1" />
                {translate('pages.facilities.card.edit')}
              </Button>
            </div>
          </div>
        </div>

        {/* Map Section */}
        <div className="w-32 min-h-[128px] flex-shrink-0 border-l border-gray-200 dark:border-gray-700 flex items-center justify-center">
          {facility.location ? (
            <FacilityMiniMap
              address={facility.address || undefined}
              // Note: lat/lng are not directly available on the facility object
              // The FacilityMiniMap component will handle geocoding if needed
            />
          ) : (
            <div className="h-full flex items-center justify-center text-gray-500 dark:text-gray-400">
              <div className="text-center">
                <MapPin className="w-6 h-6 mx-auto mb-1" />
                <p className="text-xs">{translate('common:messages.no_coordinates')}</p>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>

    {/* Delete Confirmation Dialog - Identical to gridview */}
    {showDeleteConfirm && (
      <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
        <div className="bg-white dark:bg-gray-800 rounded-lg p-6 max-w-md w-full mx-4">
          <div className="flex items-center gap-3 mb-4">
            <div className="p-2 bg-red-100 dark:bg-red-900/20 rounded-full">
              <AlertTriangle className="h-6 w-6 text-red-600 dark:text-red-400" />
            </div>
            <div>
              <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
                {translate('pages.facilities.card.delete_dialog.title')}
              </h3>
              <p className="text-sm text-gray-500 dark:text-gray-400">
                {translate('pages.facilities.card.delete_dialog.warning')}
              </p>
            </div>
          </div>

          <p className="text-gray-700 dark:text-gray-300 mb-6" 
             dangerouslySetInnerHTML={{ 
               __html: translate('pages.facilities.card.delete_dialog.confirm_text', { name: facility.name } as any)
             }}>
          </p>

          <div className="flex gap-3 justify-end">
            <Button
              onClick={(): void => setShowDeleteConfirm(false)}
              variant="outline"
              size="sm"
            >
              {translate('pages.facilities.card.delete_dialog.cancel')}
            </Button>
            <Button
              onClick={confirmDelete}
              variant="destructive"
              size="sm"
            >
              <Trash2 className="h-4 w-4 mr-2" />
              {translate('pages.facilities.card.delete_dialog.confirm')} 
            </Button>
          </div>
        </div>
      </div>
    )}

    {/* Edit Modal */}
    <Dialog open={showEditModal} onOpenChange={setShowEditModal}>
      <DialogContent className="sm:max-w-[600px]">
        <DialogHeader>
          <DialogTitle>{translate('pages.facilities.card.edit_modal.title')}</DialogTitle>
        </DialogHeader>
        <div className="grid gap-4 py-4">
          <div className="grid grid-cols-4 items-center gap-4">
            <Label htmlFor="edit-name" className="text-right">
              {translate('pages.facilities.card.edit_modal.name')}
            </Label>
            <Input
              id="edit-name"
              value={editFormData.name}
              onChange={(e) => setEditFormData(prev => ({ ...prev, name: e.target.value }))}
              className="col-span-3"
            />
          </div>
          <div className="grid grid-cols-4 items-center gap-4">
            <Label htmlFor="edit-address" className="text-right">
              {translate('pages.facilities.card.edit_modal.address')}
            </Label>
            <Input
              id="edit-address"
              value={editFormData.address || ""}
              onChange={(e) => setEditFormData(prev => ({ ...prev, address: e.target.value }))}
              className="col-span-3"
            />
          </div>
          <div className="grid grid-cols-4 items-center gap-4">
            <Label htmlFor="edit-type" className="text-right">
              {translate('pages.facilities.card.edit_modal.type')}
            </Label>
            <Input
              id="edit-type"
              value={editFormData.facility_type}
              onChange={(e) => setEditFormData(prev => ({ ...prev, facility_type: e.target.value }))}
              className="col-span-3"
            />
