"use client";

import React, { useState } from 'react';
import { X, Plus, Eye, EyeOff, Trash2, GripVertical } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';

interface FieldConfig {
  readonly id: string;
  readonly label: string;
  readonly key: string;
  readonly type: 'text' | 'number' | 'boolean';
  readonly visible: boolean;
  readonly value: string | number | boolean;
}

interface FieldConfigModalProps {
  readonly isOpen: boolean;
  readonly onClose: () => void;
  readonly onSave: (fields: readonly FieldConfig[]) => void;
  readonly initialFields: readonly FieldConfig[];
  readonly facilityId: string;
  readonly onToggleVisibility: (fieldId: string) => void;
  readonly onUpdateValue: (fieldId: string, value: string | number | boolean) => void;
  readonly onAddField: (field: Omit<FieldConfig, 'id'>) => void;
  readonly onRemoveField: (fieldId: string) => void;
}

export const FieldConfigModal = ({ 
  isOpen, 
  onClose, 
  onSave, 
  initialFields,
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  facilityId: _facilityId,
  onToggleVisibility,
  onUpdateValue,
  onAddField,
  onRemoveField
}: FieldConfigModalProps): JSX.Element => {
  const [fields, setFields] = useState<readonly FieldConfig[]>(initialFields);
  const [isAddingField, setIsAddingField] = useState(false);
  const [newField, setNewField] = useState<{
    label: string;
    key: string;
    type: 'text' | 'number' | 'boolean';
    value: string | number | boolean;
  }>({
    label: '',
    key: '',
    type: 'text',
    value: ''
  });

  const handleToggleVisibility = (fieldId: string): void => {
    onToggleVisibility(fieldId);
    setFields(prev => prev.map(field => 
      field.id === fieldId 
        ? { ...field, visible: !field.visible }
        : field
    ));
  };

  const handleFieldValueChange = (fieldId: string, value: string | number | boolean): void => {
    onUpdateValue(fieldId, value);
    setFields(prev => prev.map(field => 
      field.id === fieldId 
        ? { ...field, value: value as any }
        : field
    ));
  };

  const handleAddField = (): void => {
    if (newField.label && newField.key) {
      const field: Omit<FieldConfig, 'id'> = {
        label: newField.label,
        key: newField.key,
        type: newField.type,
        visible: true,
        value: newField.type === 'number' ? 0 : newField.type === 'boolean' ? false : ''
      };

      onAddField(field);
      setNewField({ label: '', key: '', type: 'text', value: '' });
      setIsAddingField(false);
    }
  };

  const handleRemoveField = (fieldId: string): void => {
    onRemoveField(fieldId);
    setFields(prev => prev.filter(field => field.id !== fieldId));
  };

  const handleSave = (): void => {
    onSave(fields);
    onClose();
  };

  if (!isOpen) return <></>;

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
      <Card className="w-full max-w-4xl max-h-[90vh] overflow-hidden">
        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-4">
          <CardTitle>Konfigurer informasjonsfelt</CardTitle>
          <Button variant="ghost" size="sm" onClick={onClose}>
            <X className="h-4 w-4" />
          </Button>
        </CardHeader>

        <CardContent className="overflow-y-auto max-h-[70vh] space-y-6">
          {/* Existing Fields */}
          <div className="space-y-4">
            <h3 className="text-lg font-semibold">Eksisterende felt</h3>
            {fields.map((field) => (
              <Card key={field.id} className="p-4">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-4 flex-1">
                    <GripVertical className="h-4 w-4 text-gray-400 cursor-move" />

                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-2">
                        <span className="font-medium">{field.label}</span>
                        <Badge variant="outline" className="text-xs">
                          {field.key}
                        </Badge>
                        <Badge variant="secondary" className="text-xs">
                          {field.type}
                        </Badge>
                      </div>

                      <div className="space-y-2">
                        <Label className="text-sm text-gray-600">Verdi:</Label>
                        {field.type === 'text' && (
                          <Input
                            value={String(field.value)}
                            onChange={(e) => handleFieldValueChange(field.id, e.target.value)}
                            className="text-sm"
                          />
                        )}
                        {field.type === 'number' && (
                          <Input
                            type="number"
                            value={Number(field.value)}
                            onChange={(e) => handleFieldValueChange(field.id, parseInt(e.target.value) || 0)}
                            className="text-sm"
                          />
                        )}
                        {field.type === 'boolean' && (
                          <div className="flex items-center space-x-2">
                            <Switch
                              checked={Boolean(field.value)}
                              onCheckedChange={(checked) => handleFieldValueChange(field.id, checked)}
                            />
                            <Label className="text-sm">
                              {field.value ? 'Ja' : 'Nei'}
                            </Label>
                          </div>
                        )}
                      </div>
                    </div>
                  </div>

                  <div className="flex items-center gap-2">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => handleToggleVisibility(field.id)}
                      className={field.visible ? 'text-green-600' : 'text-gray-400'}
                    >
                      {field.visible ? <Eye className="h-4 w-4" /> : <EyeOff className="h-4 w-4" />}
                    </Button>

                    {field.key.startsWith('custom-') && (
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => handleRemoveField(field.id)}
                        className="text-red-600"
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    )}
                  </div>
                </div>
              </Card>
            ))}
          </div>

          {/* Add New Field */}
          {isAddingField ? (
            <Card className="border-2 border-dashed border-blue-200">
              <CardContent className="p-4">
                <div className="space-y-4">
                  <h4 className="font-semibold">Legg til nytt felt</h4>

                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <Label htmlFor="field-label">Feltnavn</Label>
                      <Input
                        id="field-label"
                        value={newField.label}
                        onChange={(e) => setNewField(prev => ({ ...prev, label: e.target.value }))}
                        placeholder="F.eks. 'Etasje nummer'"
                      />
                    </div>
                    <div>
                      <Label htmlFor="field-key">Nøkkel</Label>
                      <Input
                        id="field-key"
                        value={newField.key}
                        onChange={(e) => setNewField(prev => ({ ...prev, key: e.target.value }))}
                        placeholder="F.eks. 'floorNumber'"
                      />
                    </div>
                  </div>

                  <div>
                    <Label htmlFor="field-type">Type</Label>
                    <Select
                      value={newField.type}
                      onValueChange={(value: 'text' | 'number' | 'boolean') => 
                        setNewField(prev => ({ 
                          ...prev, 
                          type: value,
                          value: value === 'number' ? 0 : value === 'boolean' ? false : ''
                        }))
                      }
                    >
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="text">Tekst</SelectItem>
                        <SelectItem value="number">Nummer</SelectItem>
                        <SelectItem value="boolean">Ja/Nei</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="flex gap-2">
                    <Button onClick={handleAddField} size="sm">
                      <Plus className="h-4 w-4 mr-2" />
                      Legg til
                    </Button>
                    <Button 
                      onClick={() => setIsAddingField(false)} 
                      variant="outline" 
                      size="sm"
                    >
                      Avbryt
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          ) : (
            <Button 
              onClick={() => setIsAddingField(true)}
              variant="outline"
              className="w-full"
            >
              <Plus className="h-4 w-4 mr-2" />
              Legg til nytt informasjonsfelt
            </Button>
          )}
        </CardContent>

        <div className="flex justify-end gap-2 p-6 border-t">
          <Button variant="outline" onClick={onClose}>
            Avbryt
          </Button>
          <Button onClick={handleSave}>
            Lagre endringer
          </Button>
        </div>
      </Card>
    </div>
  );
};

"use client";

// External imports
import React, { useRef, useEffect } from 'react';
import mapboxgl from 'mapbox-gl';
import 'mapbox-gl/dist/mapbox-gl.css';
import { useMapErrorHandling } from '@/hooks/features/facilities';

interface MapContainerProps {
  readonly onMapLoad: (map: mapboxgl.Map) => void;
  readonly onMapError: (error: string) => void;
  readonly onLoadingChange: (loading: boolean) => void;
  readonly mapboxToken?: string; // Make token optional
}

export const MapContainer: React.FC<MapContainerProps> = ({
  onMapLoad,
  onMapError,
  onLoadingChange,
  mapboxToken = '' // Default to empty string
}): JSX.Element => {
  const mapContainer = useRef<HTMLDivElement>(null);
  const map = useRef<mapboxgl.Map | null>(null);

  // Use map error handling hook
  const { parseMapError, validateToken } = useMapErrorHandling();

  const initializeMap = async (): Promise<void> => {

    // Wait for next tick to ensure DOM is ready
    await new Promise(resolve => setTimeout(resolve, 100));

    if (!mapContainer.current) {
      onMapError('Map container not ready. Please try again.');
      onLoadingChange(false);
      return;
    }

    onLoadingChange(true);
    onMapError('');

    try {
      // Set the access token
      mapboxgl.accessToken = mapboxToken;

      // Validate the access token format using hook (with error handling)
      // Only validate if token is provided
      if (mapboxToken) {
        try {
          validateToken(mapboxToken);
        } catch (validationError) {
          console.warn('Token validation failed:', validationError);
          // Continue anyway as the map might still work
        }
      }

      // Clear any existing map
      if (map.current) {
        map.current.remove();
        map.current = null;
      }

      // Create new map with error handling
      map.current = new mapboxgl.Map({
        container: mapContainer.current,
        style: 'mapbox://styles/mapbox/streets-v12',
        center: [10.2045, 59.7464], // Center on Drammen
        zoom: 12,
        attributionControl: true
      });

      // Add navigation controls
      map.current.addControl(new mapboxgl.NavigationControl(), 'top-right');

      // Handle successful map load
      map.current.on('load', (): void => {
        if (map.current) {
          onMapLoad(map.current);
        }
        onLoadingChange(false);
      });

      // Handle map errors using hook
      map.current.on('error', (e): void => {
        const errorMessage = parseMapError(e);
        // Only log errors that are likely to affect functionality
        // Suppress less critical errors to reduce console noise
        if (errorMessage.includes('Invalid Mapbox access token') || 
            errorMessage.includes('Network error') || 
            errorMessage.includes('error occurred')) {
          console.error('Mapbox error:', e);
        } else {
          // Log non-critical errors as warnings instead
          console.warn('Mapbox warning:', e);
        }
        onMapError(errorMessage);
        onLoadingChange(false);
      });

    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error occurred while initializing map.';
      console.error('Map initialization error:', error);
      onMapError(errorMessage);
      onLoadingChange(false);
    }
  };

  useEffect((): (() => void) => {
    initializeMap();

    // Cleanup function
    return (): void => {
      if (map.current) {
        map.current.remove();
        map.current = null;
      }
    };
  }, []); // Only run once on mount

  return (
    <div className="relative w-full h-full">
      <div 
        ref={mapContainer} 
        className="w-full h-full rounded-lg overflow-hidden" 
        style={{ minHeight: '400px' }}
      />
    </div>
  );
};

"use client";

// External imports
import React, { useEffect, useRef } from 'react';
import mapboxgl from 'mapbox-gl';

// Internal imports
import type { FacilityWithCoords } from '@/types/facility';
import { geocodeAddress } from '@/lib/geocode';

interface MapMarkersProps {
  readonly map: mapboxgl.Map | null;
  readonly facilities: readonly FacilityWithCoords[];
  readonly onMarkerClick?: (facility: FacilityWithCoords) => void;
}

// Helper function to extract coordinates from location data
const extractCoordinates = (location: unknown): { lat: number | null; lng: number | null } => {
  let lat: number | null = null;
  let lng: number | null = null;

  try {
    // If location is an object with lat/lng properties
    if (location && typeof location === 'object' && !Array.isArray(location)) {
      const locObj = location as Record<string, unknown>;
      if ('lat' in locObj && 'lng' in locObj) {
        lat = typeof locObj.lat === 'number' ? locObj.lat : null;
        lng = typeof locObj.lng === 'number' ? locObj.lng : null;
      }
    }
    // If location is a string in POINT format (POINT(lng lat))
    else if (typeof location === 'string' && location.startsWith('POINT(') && location.endsWith(')')) {
      const coords = location.slice(6, -1).split(' ');
      if (coords.length === 2) {
        lng = parseFloat(coords[0]);
        lat = parseFloat(coords[1]);
      }
    }
    // If location is a binary PostGIS object, we can't parse it directly
    // In this case, we need to rely on the database to convert it to text format
    else if (location && typeof location === 'object' && Array.isArray(location)) {
      // This might be a binary array, we can't parse it directly
      console.warn('Cannot parse binary PostGIS location data directly');
    }
  } catch (error) {
    console.warn('Error parsing location data:', error);
  }

  return { lat, lng };
};

// Normalize facility with coordinates, but don't save to database automatically
const normalizeFacility = async (facility: FacilityWithCoords): Promise<FacilityWithCoords> => {
  // If we already have coordinates, use them
  if (Number.isFinite(facility.lat) && Number.isFinite(facility.lng)) {
    return facility;
  }

  // Try to extract from location_geog field if it exists
  if (facility.location_geog) {
    const { lat, lng } = extractCoordinates(facility.location_geog);
    if (Number.isFinite(lat) && Number.isFinite(lng)) {
      return { ...facility, lat, lng };
    }
  }

  // Fallback to geocoding if we have an address
  if (facility.address) {
    const result = await geocodeAddress(facility.address);
    if (result) {
      // Return facility with geocoded coordinates but don't save to database
      // This prevents performance issues and database timeouts
      return { 
        ...facility, 
        lat: result.lat, 
        lng: result.lng 
      };
    }
  }

  // Return facility as is if we can't geocode
  return facility;
}

export const MapMarkers: React.FC<MapMarkersProps> = ({
  map,
  facilities,
  onMarkerClick
}): JSX.Element => {
  const markersRef = useRef<readonly mapboxgl.Marker[]>([]);

  const createMarkerElement = (facility: FacilityWithCoords): HTMLDivElement => {
    const markerElement = document.createElement('div');
    markerElement.className = 'custom-marker';
    // Create a location icon marker with black color, no white border, matching exactly the style used in list view (Mapbox pin)
    markerElement.innerHTML = `
      <div class="text-gray-800 cursor-pointer hover:text-black transition-colors" style="filter: drop-shadow(0 2px 4px rgba(0,0,0,0.2));">
        <svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24" fill="#000000">
          <path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7z"/>
          <circle cx="12" cy="9" r="2" fill="white"/>
        </svg>
      </div>
    `;

    // Add click handler - only open popup, don't navigate directly
    markerElement.addEventListener('click', (e): void => {
      // Prevent default to avoid immediate navigation
      e.preventDefault();
      // Let Mapbox handle the popup opening automatically
      if (onMarkerClick) {
        onMarkerClick(facility);
      }
    });

    return markerElement;
  };

  const createPopupContent = (facility: FacilityWithCoords): string => {
    // Get the first image or use a placeholder
    const images = facility.images as string[] | null;
    const imageUrl = images && images.length > 0 
      ? images[0] 
      : '/placeholder.svg';

    // Simplified popup content with only name and image, entire popup is clickable
    return `
      <div style="min-width: 200px; padding: 12px;" onclick="window.location.href='/facilities/${facility.id}'" style="cursor: pointer;">
        <div style="margin-bottom: 8px;">
          <img src="${imageUrl}" alt="${facility.name}" style="width: 100%; height: 128px; object-fit: cover; border-radius: 4px;" onerror="this.src='/placeholder.svg'">
        </div>
        <h3 style="font-weight: bold; font-size: 16px; margin: 0;">${facility.name}</h3>
        ${facility.address ? `<p style="margin: 4px 0 0 0; font-size: 14px; color: #666;">${facility.address}</p>` : ''}
      </div>
    `;
  };

  const addMarkersToMap = async (): Promise<void> => {
    if (!map) return;

    // Clear existing markers
    markersRef.current.forEach((marker): void => {
      marker.remove();
    });

    // Normalize all facilities with geocoding fallback
    const enrichedFacilities = await Promise.all(
      facilities.map(normalizeFacility)
    );

    // Filter facilities to only include those with valid coordinates or address for geocoding
    const facilitiesWithCoordinates = enrichedFacilities.filter(facility => {
      return (Number.isFinite(facility.lat) && Number.isFinite(facility.lng)) || facility.address;
    });

    // Process each facility to ensure it has coordinates
    const markerData = await Promise.all(
      facilitiesWithCoordinates.map(async (facility) => {
        let lat = facility.lat;
        let lng = facility.lng;

        // If we don't have valid coordinates but have an address, try to geocode it
        if ((!Number.isFinite(lat) || !Number.isFinite(lng)) && facility.address) {
          const geocoded = await geocodeAddress(facility.address);
          if (geocoded) {
            lat = geocoded.lat;
            lng = geocoded.lng;
          }
        }

        // Return facility with coordinates if available
        if (Number.isFinite(lat) && Number.isFinite(lng)) {
          return {
            facility: {...facility, lat, lng},
            lat,
            lng
          };
        }
        // Return null for facilities that can't be geocoded
        return null;
      })
    );

    // Filter out null values and create markers
    const validMarkerData = markerData.filter(Boolean) as Array<{
      facility: FacilityWithCoords;
      lat: number;
      lng: number;
    }>;

    // Create new markers
    const newMarkers = validMarkerData.map(({facility, lat, lng}): mapboxgl.Marker => {
      const markerElement = createMarkerElement(facility);
      const popupContent = createPopupContent(facility);

      const popup = new mapboxgl.Popup({
        offset: 25,
        closeButton: true,
        closeOnClick: true
      }).setHTML(popupContent);

      const marker = new mapboxgl.Marker({
        element: markerElement,
        anchor: 'bottom'
      })
        .setLngLat([lng, lat])
        .setPopup(popup)
        .addTo(map);

      return marker;
    });

    markersRef.current = newMarkers;
  };

  useEffect((): void => {
    addMarkersToMap();
  }, [map, facilities]);

  // Cleanup markers when component unmounts
  useEffect((): (() => void) => {
    return (): void => {
      markersRef.current.forEach((marker): void => {
        marker.remove();
      });
    };
  }, []);

  return <></>; // This component doesn't render anything directly
};

