  readonly toggleLogSelection: (id: string) => void;
  readonly selectAllLogs: () => void;
  readonly clearSelection: () => void;
  readonly openDetails: (logId: string) => void;
  readonly closeDetails: () => void;
  readonly resetFilters: () => void;

  // Pagination Actions
  readonly setCurrentPage: (page: number) => void;
  readonly setItemsPerPage: (itemsPerPage: number) => void;
  readonly nextPage: () => void;
  readonly previousPage: () => void;
  readonly goToFirstPage: () => void;
  readonly goToLastPage: () => void;

  // Export Operations
  readonly exportToCSV: () => void;
  readonly downloadCSV: (filename: string, content: string) => void;
}

/**
 * Query key for audit logs
 */
const auditKeys = {
  all: ['auditLogs'] as const,
  orgLogs: (orgId: string) => [...auditKeys.all, 'org', orgId] as const,
};

/**
 * Fetch audit logs for organization from Supabase
 */
const fetchOrgAuditLogs = async (orgId: string): Promise<AuditEvent[]> => {
  const { data, error } = await supabase
    .from('audit_events')
    .select('*')
    .eq('org_id', orgId)
    .order('created_at', { ascending: false })
    .limit(1000); // Limit to last 1000 events for performance

  if (error) {
    console.error('Error fetching audit logs:', error);
    throw error;
  }

  return data || [];
};

/**
 * Hook for managing audit logs with business logic separation
 *
 * Provides comprehensive audit log management functionality including:
 * - Data fetching and caching via React Query
 * - UI state management via Zustand store
 * - Business logic filtering and formatting
 * - Timeline and grouped views
 * - Statistics and analytics
 * - CSV export functionality
 * - Pagination support
 *
 * @returns Complete audit management interface
 *
 * @example
 * ```tsx
 * function AuditLogPage() {
 *   const {
 *     groupedLogs,
 *     isLoading,
 *     stats,
 *     searchTerm,
 *     setSearchTerm,
 *     exportToCSV,
 *   } = useAuditManagement();
 *
 *   return (
 *     <div>
 *       <SearchBar value={searchTerm} onChange={setSearchTerm} />
 *       <AuditStats stats={stats} />
 *       <AuditTimeline groups={groupedLogs} />
 *       <Button onClick={exportToCSV}>Export to CSV</Button>
 *     </div>
 *   );
 * }
 * ```
 */
export const useAuditManagement = (): IUseAuditManagementReturn => {
  // Data layer - fetch audit logs from Supabase
  const orgId = useOrganizationId();
  const {
    data: auditLogs = [],
    isLoading,
    error,
  }: UseQueryResult<AuditEvent[], Error> = useQuery({
    queryKey: auditKeys.orgLogs(orgId),
    queryFn: () => fetchOrgAuditLogs(orgId),
    enabled: !!orgId,
    staleTime: 30000, // 30 seconds
  });

  // UI state layer - appUIStore audit section
  const appUIStore = useAppUIStore();
  const {
    view,
    showFilters,
    searchTerm,
    filters,
    dateRange,
    sortBy,
    sortOrder,
    selectedLogIds,
    selectedLogId,
    isDetailsPanelOpen,
    isExporting,
    currentPage,
    itemsPerPage,
  } = appUIStore.audit;

  // Actions from appUIStore with audit prefix
  const setView = appUIStore.setAuditView;
  const toggleFilters = appUIStore.toggleAuditFilters;
  const setSearchTerm = appUIStore.setAuditSearchTerm;
  const toggleUserFilter = appUIStore.toggleAuditUserFilter;
  const toggleActionFilter = appUIStore.toggleAuditActionFilter;
  const toggleEntityFilter = appUIStore.toggleAuditEntityFilter;
  const toggleSeverityFilter = appUIStore.toggleAuditSeverityFilter;
  const clearFilters = appUIStore.clearAuditFilters;
  const setDateRange = appUIStore.setAuditDateRange;
  const clearDateRange = appUIStore.clearAuditDateRange;
  const setToday = appUIStore.setAuditToday;
  const setYesterday = appUIStore.setAuditYesterday;
  const setLast7Days = appUIStore.setAuditLast7Days;
  const setLast30Days = appUIStore.setAuditLast30Days;
  const setThisWeek = appUIStore.setAuditThisWeek;
  const setThisMonth = appUIStore.setAuditThisMonth;
  const toggleSort = appUIStore.toggleAuditSort;
  const toggleLogSelection = appUIStore.toggleAuditLogSelection;
  const selectAll = (ids: readonly string[]) => appUIStore.selectAllAuditLogs(ids);
  const clearSelection = appUIStore.clearAuditSelection;
  const openDetails = appUIStore.openAuditDetails;
  const closeDetails = appUIStore.closeAuditDetails;
  const resetFilters = appUIStore.resetAuditFilters;
  const setCurrentPage = appUIStore.setAuditPage;
  const setItemsPerPage = appUIStore.setAuditItemsPerPage;
  const startExport = () => appUIStore.setAuditIsExporting(true);
  const finishExport = () => appUIStore.setAuditIsExporting(false);

  // Pagination actions (derived from current page state)
  const nextPage = () => setCurrentPage(currentPage + 1);
  const previousPage = () => setCurrentPage(Math.max(1, currentPage - 1));
  const goToFirstPage = () => setCurrentPage(1);
  const goToLast = (totalPages: number) => setCurrentPage(totalPages);

  // Business logic layer - filtering and sorting
  const filteredAndSorted = useMemo(() => {
    // Apply business logic filters
    const businessFilters: IAuditFilters = {
      searchTerm,
      userIds: filters.userIds,
      actions: filters.actions,
      entities: filters.entities,
      dateRange: dateRange.startDate && dateRange.endDate
        ? {
            startDate: dateRange.startDate,
            endDate: dateRange.endDate,
          }
        : undefined,
    };

    const filtered = filterAuditLogs(auditLogs, businessFilters);

    // Apply severity filter (UI-specific)
    const severityFiltered = filters.severityFilter.length > 0
      ? filtered.filter((log) => {
          const formatted = formatAuditEntry(log);
          return filters.severityFilter.includes(formatted.severity);
        })
      : filtered;

    // Apply business logic sorting
    const sortConfig: IAuditSortConfig = {
      sortBy: sortBy as IAuditSortConfig['sortBy'],
      sortOrder: sortOrder as IAuditSortConfig['sortOrder'],
    };

    return sortAuditLogs(severityFiltered, sortConfig);
  }, [auditLogs, searchTerm, filters, dateRange, sortBy, sortOrder]);

  // Format logs for display
  const formattedLogs = useMemo(
    () => filteredAndSorted.map(formatAuditEntry),
    [filteredAndSorted]
  );

  // Group logs by date for timeline view
  const groupedLogs = useMemo(
    () => groupAuditLogsByDate(formattedLogs),
    [formattedLogs]
  );

  // Pagination
  const totalItems = formattedLogs.length;
  const totalPages = Math.ceil(totalItems / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const endIndex = startIndex + itemsPerPage;
  const paginatedLogs = formattedLogs.slice(startIndex, endIndex);
  const hasNextPage = currentPage < totalPages;
  const hasPreviousPage = currentPage > 1;

  // Statistics - calculate from current audit logs
  const stats = useMemo(() => calculateAuditStats(auditLogs), [auditLogs]);

  // Unique values for filters
  const uniqueActions = useMemo(() => getUniqueActions(auditLogs), [auditLogs]);
  const uniqueEntities = useMemo(() => getUniqueEntities(auditLogs), [auditLogs]);
  const uniqueUsers = useMemo(() => getUniqueUsers(auditLogs), [auditLogs]);

  // Export operations
  const exportToCSV = useCallback(() => {
    startExport();

    try {
      const exportData = exportAuditLogsToCSV(formattedLogs);
      const csvContent = generateAuditCSVContent(exportData);

      // Create blob and download
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      const url = URL.createObjectURL(blob);

      link.setAttribute('href', url);
      link.setAttribute('download', `${exportData.filename}.csv`);
      link.style.visibility = 'hidden';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
    } catch (error) {
      console.error('Error exporting to CSV:', error);
    } finally {
      finishExport();
    }
  }, [formattedLogs, startExport, finishExport]);

  const downloadCSV = useCallback((filename: string, content: string) => {
    const blob = new Blob([content], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);

    link.setAttribute('href', url);
    link.setAttribute('download', filename);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  }, []);

  const selectAllLogs = useCallback(() => {
    selectAll(formattedLogs.map((log) => log.id));
  }, [formattedLogs, selectAll]);

  const goToLastPage = useCallback(() => {
    goToLast(totalPages);
  }, [totalPages, goToLast]);

  return {
    // Data
    auditLogs,
    filteredLogs: formattedLogs,
    groupedLogs,
    paginatedLogs,
    isLoading,
    error,

    // Statistics
    stats,
    uniqueActions,
    uniqueEntities,
    uniqueUsers,

    // Pagination
    totalItems,
    totalPages,
    currentPage,
    itemsPerPage,
    hasNextPage,
    hasPreviousPage,

    // UI State
    view,
    showFilters,
    searchTerm,
    filters,
    dateRange,
    sortBy,
    sortOrder,
    selectedLogIds,
    selectedLogId,
    isDetailsPanelOpen,
    isExporting,

    // UI Actions
    setView,
    toggleFilters,
    setSearchTerm,
    toggleUserFilter,
    toggleActionFilter,
    toggleEntityFilter,
    toggleSeverityFilter,
    clearFilters,
    setDateRange,
    clearDateRange,
    setToday,
    setYesterday,
    setLast7Days,
    setLast30Days,
    setThisWeek,
    setThisMonth,
    toggleSort,
    toggleLogSelection,
    selectAllLogs,
    clearSelection,
    openDetails,
    closeDetails,
    resetFilters,

    // Pagination Actions
    setCurrentPage,
    setItemsPerPage,
    nextPage,
    previousPage,
    goToFirstPage,
    goToLastPage,

    // Export Operations
    exportToCSV,
    downloadCSV,
  };
};

"use client";

import { useMemo, useCallback } from "react";
import { useTranslation } from "react-i18next";
import type { ISelectedTimeSlot, BookingType } from "@/components/features/bookings/types";
import type { IPriceCalculationResult } from "@/components/features/bookings/components/StepByStepBooking/hooks/usePriceCalculation";

/**
 * Booking sidebar display hook props
 */
interface IUseBookingSidebarDisplayProps {
  readonly selectedSlots: readonly ISelectedTimeSlot[];
  readonly recurringSlots: readonly ISelectedTimeSlot[];
  readonly bookingType: BookingType;
  readonly priceCalculation?: IPriceCalculationResult;
}

/**
 * Booking sidebar display hook return type
 */
interface IUseBookingSidebarDisplayReturn {
  readonly title: string;
  readonly hasSlots: boolean;
  readonly isRecurring: boolean;
  readonly currentLocale: string;
  readonly shouldShowTemplate: boolean;
  readonly shouldShowRecurringPreview: boolean;
  readonly visibleRecurringSlots: readonly ISelectedTimeSlot[];
  readonly remainingRecurringSlotsCount: number;
  readonly shouldShowClearButton: boolean;
  readonly formatSlotDate: (date: Date | string) => string;
  readonly formatPrice: (amount: number) => string;
}

/**
 * Custom hook for booking sidebar display logic
 *
 * Provides computed display values and formatting for the BookingSidebar component:
 * - Dynamic title based on booking state
 * - Locale-aware formatting
 * - Slot visibility calculations
 * - Conditional rendering flags
 *
 * This hook encapsulates all display logic, separating it from
 * the rendering concerns of the BookingSidebar component.
 *
 * @param props - Hook configuration
 * @returns Display values and formatting utilities
 */
export const useBookingSidebarDisplay = ({
  selectedSlots,
  recurringSlots,
  bookingType,
  _priceCalculation,
}: IUseBookingSidebarDisplayProps): IUseBookingSidebarDisplayReturn => {
  const { t, i18n } = useTranslation("booking");

  /**
   * Current locale for date formatting
   */
  const currentLocale = useMemo(
    () => (i18n.language === "en" ? "en-US" : "nb-NO"),
    [i18n.language]
  );

  /**
   * Check if there are any selected slots
   */
  const hasSlots = useMemo(
    () => selectedSlots.length > 0 || recurringSlots.length > 0,
    [selectedSlots.length, recurringSlots.length]
  );

  /**
   * Check if booking type is recurring
   */
  const isRecurring = useMemo(
    () => bookingType === "recurring",
    [bookingType]
  );

  /**
   * Determine if template view should be shown
   */
  const shouldShowTemplate = useMemo(
    () => isRecurring && recurringSlots.length > 0,
    [isRecurring, recurringSlots.length]
  );

  /**
   * Determine if recurring preview should be shown
   */
  const shouldShowRecurringPreview = useMemo(
    () => isRecurring && recurringSlots.length > 0,
    [isRecurring, recurringSlots.length]
  );

  /**
   * Get visible recurring slots (first 5)
   */
  const visibleRecurringSlots = useMemo(
    () => recurringSlots.slice(0, 5),
    [recurringSlots]
  );

  /**
   * Calculate remaining recurring slots count
   */
  const remainingRecurringSlotsCount = useMemo(
    () => Math.max(0, recurringSlots.length - 5),
    [recurringSlots.length]
  );

  /**
   * Determine if clear all button should be shown
   */
  const shouldShowClearButton = useMemo(
    () => selectedSlots.length > 1 || recurringSlots.length > 0,
    [selectedSlots.length, recurringSlots.length]
  );

  /**
   * Get appropriate title based on current state
   */
  const title = useMemo((): string => {
    if (!hasSlots) {
      return t(
        "details.select_slots_pricing",
        "Velg tidspunkter og få en prisberegning"
      );
    }

    if (isRecurring) {
      return recurringSlots.length > 0
        ? t(
            "details.recurring_slots_pricing",
            "Gjentakende tidspunkter og prisberegning"
          )
        : t(
            "details.select_pattern",
            "Tidspunkter og prisberegning (velg gjentakelsesmønster)"
          );
    }

    return t(
      "details.selected_slots_pricing",
      "Valgte tidspunkter og prisberegning"
    );
  }, [hasSlots, isRecurring, recurringSlots.length, t]);

  /**
   * Format slot date for display
   *
   * @param date - Date to format (Date object or string)
   * @returns Formatted date string
   */
  const formatSlotDate = useCallback(
    (date: Date | string): string => {
      const dateObj = date instanceof Date ? date : new Date(date);
      return dateObj.toLocaleDateString(currentLocale);
    },
    [currentLocale]
  );

  /**
   * Format price for display
   *
   * @param amount - Amount to format
   * @returns Formatted price string (e.g., "kr 1,234.56")
   */
  const formatPrice = useCallback((amount: number): string => {
    return `kr ${Math.abs(amount).toFixed(2)}`;
  }, []);

  return {
    title,
    hasSlots,
    isRecurring,
    currentLocale,
    shouldShowTemplate,
    shouldShowRecurringPreview,
    visibleRecurringSlots,
    remainingRecurringSlotsCount,
    shouldShowClearButton,
    formatSlotDate,
    formatPrice,
  };
};

import { useState, useMemo, useCallback } from 'react';
import { format, addDays, startOfWeek, addWeeks, subWeeks, isToday, isWeekend, isPast } from 'date-fns';

export interface CalendarDay {
  readonly date: Date;
  readonly isToday: boolean;
  readonly isWeekend: boolean;
  readonly isPast: boolean;
}

export interface CalendarWeek {
  readonly startDate: Date;
  readonly endDate: Date;
  readonly days: readonly CalendarDay[];
}

export interface CalendarGridState {
  readonly currentWeekStart: Date;
  readonly calendarWeek: CalendarWeek;
  readonly timeSlots: readonly string[];
}

export interface CalendarGridActions {
  readonly handlePreviousWeek: () => void;
  readonly handleNextWeek: () => void;
  readonly setCurrentWeekStart: (date: Date) => void;
}

export interface UseCalendarGridProps {
  readonly openingHoursStart?: string;
  readonly openingHoursEnd?: string;
  readonly initialDate?: Date;
}

export interface UseCalendarGridReturn {
  readonly state: CalendarGridState;
  readonly actions: CalendarGridActions;
}

/**
 * Custom hook for managing calendar grid data
 * Handles week navigation, calendar generation, and time slot calculation
 */
export const useCalendarGrid = ({
  openingHoursStart = "08:00",
  openingHoursEnd = "22:00",
  initialDate
}: UseCalendarGridProps = {}): UseCalendarGridReturn => {
  const [currentWeekStart, setCurrentWeekStart] = useState<Date>(() =>
    startOfWeek(initialDate || new Date(), { weekStartsOn: 1 })
  );

  // Generate time slots based on opening hours
  const timeSlots = useMemo((): readonly string[] => {
    const startHour = parseInt(openingHoursStart.split(':')[0]);
    const endHour = parseInt(openingHoursEnd.split(':')[0]);
    const totalHours = endHour - startHour;

    return Array.from({ length: totalHours }, (_, i) => {
      const hour = startHour + i;
      const nextHour = hour + 1;
      return `${hour.toString().padStart(2, '0')}:00-${nextHour.toString().padStart(2, '0')}:00`;
    });
  }, [openingHoursStart, openingHoursEnd]);

  // Generate calendar week data with day metadata
  const calendarWeek = useMemo((): CalendarWeek => {
    const days = Array.from({ length: 7 }, (_, i): CalendarDay => {
      const date = addDays(currentWeekStart, i);
      return {
        date,
        isToday: isToday(date),
        isWeekend: isWeekend(date),
        isPast: isPast(date),
      };
    });

    return {
      startDate: currentWeekStart,
      endDate: addDays(currentWeekStart, 6),
      days,
    };
  }, [currentWeekStart]);

  // Navigate to previous week
  const handlePreviousWeek = useCallback((): void => {
    setCurrentWeekStart(prev => subWeeks(prev, 1));
  }, []);

  // Navigate to next week
  const handleNextWeek = useCallback((): void => {
    setCurrentWeekStart(prev => addWeeks(prev, 1));
  }, []);

  return {
    state: {
      currentWeekStart,
      calendarWeek,
      timeSlots
    },
    actions: {
      handlePreviousWeek,
      handleNextWeek,
      setCurrentWeekStart
    }
  };
};

"use client";

import { useCallback } from "react";
import { format } from "date-fns";
import type {
  Zone,
  SelectedTimeSlot,
  AvailabilityStatus,
} from "@/types/booking";
import { useDragSelection } from "@/components/features/calendar/hooks";

/**
 * Calendar grid drag selection hook props
 */
interface IUseCalendarGridDragSelectionProps {
  readonly zone: Zone;
  readonly timeSlots: readonly string[];
  readonly weekDays: readonly Date[];
  readonly getAvailabilityStatus: (
    zoneId: string,
    date: Date,
    timeSlot: string
  ) => AvailabilityStatus;
  readonly onBulkSlotSelection?: (slots: readonly SelectedTimeSlot[]) => void;
  readonly onSlotClick: (
    zoneId: string,
    date: Date,
    timeSlot: string,
    availability: string
  ) => void;
}

/**
 * Calendar grid drag selection return type
 */
interface IUseCalendarGridDragSelectionReturn {
  readonly dragState: {
    readonly isDragging: boolean;
    readonly startSlot: {
      readonly zoneId: string;
      readonly date: Date;
      readonly timeSlot: string;
    } | null;
    readonly currentSlot: {
      readonly zoneId: string;
      readonly date: Date;
      readonly timeSlot: string;
    } | null;
    readonly previewSlots: readonly SelectedTimeSlot[];
  };
  readonly handleMouseDown: (
    day: Date,
    timeSlot: string,
    event: React.MouseEvent
  ) => void;
  readonly handleMouseEnter: (day: Date, timeSlot: string) => void;
  readonly handleMouseUp: () => void;
  readonly handleClick: (day: Date, timeSlot: string) => void;
  readonly cancelDrag: () => void;
  readonly isSlotInPreview: (
    zoneId: string,
    date: Date,
    timeSlot: string
  ) => boolean;
  readonly getStatusStyle: (
    status: string,
    isSelected: boolean,
    isInPreview: boolean
  ) => string;
}

/**
 * Custom hook for calendar grid drag selection functionality
 *
 * Provides comprehensive drag selection capabilities for the calendar grid:
 * - Multi-slot selection via drag
 * - Single slot click selection
 * - Visual feedback during drag
 * - Status-based styling
 * - Touch and mouse event handling
 *
 * This hook encapsulates all drag selection logic, event handlers,
 * and styling utilities for the CalendarGrid component.
 *
 * @param props - Hook configuration
 * @returns Drag selection state and handlers
 */
export const useCalendarGridDragSelection = ({
  zone,
  timeSlots,
  weekDays,
  getAvailabilityStatus,
  onBulkSlotSelection,
  onSlotClick,
}: IUseCalendarGridDragSelectionProps): IUseCalendarGridDragSelectionReturn => {
  const {
    dragState,
    startDrag,
    updateDrag,
    endDrag,
    cancelDrag,
    isSlotInPreview,
  } = useDragSelection();

  /**
   * Get status-based style classes for slot rendering
   *
   * @param status - Slot availability status
   * @param isSelected - Whether slot is selected
   * @param isInPreview - Whether slot is in drag preview
   * @returns Tailwind CSS classes
   */
  const getStatusStyle = useCallback(
    (status: string, isSelected: boolean, isInPreview: boolean): string => {
      if (isSelected) {
        return "bg-blue-600 hover:bg-blue-700 text-white font-semibold border border-blue-700";
      }

      if (isInPreview) {
        return "bg-blue-200 hover:bg-blue-300 border border-blue-400 text-blue-800 font-medium cursor-pointer";
      }

      switch (status) {
        case "available":
          return "bg-green-100 hover:bg-green-200 border border-green-300 text-gray-800 hover:shadow-sm cursor-pointer";
        case "busy":
          return "bg-red-50 border border-red-200 text-gray-500 line-through cursor-not-allowed";
        case "unavailable":
        default:
          return "bg-gray-100 border border-gray-200 text-gray-400 line-through cursor-not-allowed";
      }
    },
    []
  );

  /**
   * Handle mouse down event to initiate drag selection
   *
   * @param day - Selected day
   * @param timeSlot - Selected time slot
   * @param event - Mouse event
   */
  const handleMouseDown = useCallback(
    (day: Date, timeSlot: string, event: React.MouseEvent): void => {
      const { status } = getAvailabilityStatus(zone.id, day, timeSlot);

      if (status === "available" && onBulkSlotSelection) {
        event.preventDefault();
        startDrag(zone.id, day, timeSlot, event);
      }
    },
    [zone.id, getAvailabilityStatus, onBulkSlotSelection, startDrag]
  );

  /**
   * Handle mouse enter event during drag
   *
   * @param day - Current day
   * @param timeSlot - Current time slot
   */
  const handleMouseEnter = useCallback(
    (day: Date, timeSlot: string): void => {
      if (dragState.isDragging && onBulkSlotSelection) {
        updateDrag(
          zone.id,
          day,
          timeSlot,
          timeSlots,
          weekDays,
          getAvailabilityStatus
        );
      }
    },
    [
      dragState.isDragging,
      zone.id,
      timeSlots,
      weekDays,
      getAvailabilityStatus,
      onBulkSlotSelection,
      updateDrag,
    ]
  );

  /**
   * Handle mouse up event to complete drag selection
   */
  const handleMouseUp = useCallback((): void => {
    if (dragState.isDragging && onBulkSlotSelection) {
      const previewSlots = endDrag();

      if (previewSlots.length > 0) {
        // Fill in the missing data for the slots
        const completeSlots = previewSlots.map((slot) => ({
          ...slot,
          facilityId: zone.facilityId,
          facilityName: "", // This should be filled by the parent component
          zoneName: zone.name,
          pricePerHour: zone.pricePerHour,
        }));

        onBulkSlotSelection(completeSlots);
      }
    }
  }, [
    dragState.isDragging,
    zone.facilityId,
    zone.name,
    zone.pricePerHour,
    onBulkSlotSelection,
    endDrag,
  ]);

  /**
   * Handle single click on slot
   *
   * @param day - Selected day
   * @param timeSlot - Selected time slot
   */
  const handleClick = useCallback(
    (day: Date, timeSlot: string): void => {
      // Prevent click if we just finished dragging
      if (dragState.isDragging) {
        return;
      }

      const { status } = getAvailabilityStatus(zone.id, day, timeSlot);

      // Only proceed with click if available
      if (status === "available") {
        onSlotClick(zone.id, day, timeSlot, status);
      }
    },
    [dragState.isDragging, zone.id, getAvailabilityStatus, onSlotClick]
  );

  return {
    dragState,
    handleMouseDown,
    handleMouseEnter,
    handleMouseUp,
    handleClick,
    cancelDrag,
    isSlotInPreview,
    getStatusStyle,
  };
};

import { useState, useCallback, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import type { SupportedLanguage } from '@/i18n/config';

export type CalendarView = 'month' | 'week' | 'day';

export interface DateRange {
  readonly start: Date;
  readonly end: Date;
}

export interface UseDateNavigationOptions {
  readonly initialDate?: Date;
  readonly view?: CalendarView;
  readonly onDateChange?: (date: Date) => void;
}

export interface UseDateNavigationReturn {
  readonly currentDate: Date;
  readonly view: CalendarView;
  readonly setCurrentDate: (date: Date) => void;
  readonly goToPrevious: () => void;
  readonly goToNext: () => void;
  readonly goToToday: () => void;
  readonly getDisplayText: () => string;
  readonly dateRange: DateRange;
  readonly weekStartDate: Date;
  readonly weekEndDate: Date;
  readonly firstDayOfMonth: Date;
  readonly lastDayOfMonth: Date;
}

/**
 * Custom hook for handling calendar date navigation and date range calculations
 * Supports month, week, and day views with bidirectional date synchronization
 */
export const useDateNavigation = (
  externalCurrentDate?: Date,
  onDateChange?: (date: Date) => void,
  view: CalendarView = 'month'
): UseDateNavigationReturn => {
  const { i18n } = useTranslation();
  const [internalCurrentDate, setInternalCurrentDate] = useState<Date>(new Date());

  // Use external date if provided, otherwise use internal state
  const currentDate = externalCurrentDate || internalCurrentDate;
  const setCurrentDate = onDateChange || setInternalCurrentDate;

  // Get the current locale based on i18n language
  const getCurrentLocale = (): string => {
    return i18n.language === 'no' ? 'nb-NO' : 'en-US';
  };

  // Calculate month boundaries
  const firstDayOfMonth = useMemo(() => {
    return new Date(currentDate.getFullYear(), currentDate.getMonth(), 1);
  }, [currentDate]);

  const lastDayOfMonth = useMemo(() => {
    return new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 0);
  }, [currentDate]);

  // Calculate week boundaries (Monday start)
  const weekStartDate = useMemo(() => {
    const startOfWeek = new Date(currentDate);
    const day = startOfWeek.getDay();
    // Adjust for Monday start: Sunday (0) becomes 6, Monday (1) becomes 0
    const adjustedDay = (day + 6) % 7;
    const diff = startOfWeek.getDate() - adjustedDay;
    startOfWeek.setDate(diff);
    return startOfWeek;
  }, [currentDate]);

  const weekEndDate = useMemo(() => {
    const endOfWeek = new Date(weekStartDate);
    endOfWeek.setDate(weekStartDate.getDate() + 6);
    return endOfWeek;
  }, [weekStartDate]);

  // Calculate date range based on current view
  const dateRange = useMemo((): DateRange => {
    if (view === 'month') {
      return {
        start: firstDayOfMonth,
        end: lastDayOfMonth
      };
    } else if (view === 'week') {
      return {
        start: weekStartDate,
        end: weekEndDate
      };
    } else {
      // Day view
      const dayStart = new Date(currentDate);
      dayStart.setHours(0, 0, 0, 0);
      const dayEnd = new Date(currentDate);
      dayEnd.setHours(23, 59, 59, 999);
      return {
        start: dayStart,
        end: dayEnd
      };
    }
  }, [view, firstDayOfMonth, lastDayOfMonth, weekStartDate, weekEndDate, currentDate]);

  // Navigation functions
  const goToPrevious = useCallback(() => {
    const newDate = new Date(currentDate);
    if (view === 'month') {
      newDate.setMonth(newDate.getMonth() - 1);
    } else if (view === 'week') {
      newDate.setDate(newDate.getDate() - 7);
    } else if (view === 'day') {
      newDate.setDate(newDate.getDate() - 1);
    }
    setCurrentDate(newDate);
  }, [currentDate, view, setCurrentDate]);

  const goToNext = useCallback(() => {
    const newDate = new Date(currentDate);
    if (view === 'month') {
      newDate.setMonth(newDate.getMonth() + 1);
    } else if (view === 'week') {
      newDate.setDate(newDate.getDate() + 7);
    } else if (view === 'day') {
      newDate.setDate(newDate.getDate() + 1);
    }
    setCurrentDate(newDate);
  }, [currentDate, view, setCurrentDate]);

  const goToToday = useCallback(() => {
    setCurrentDate(new Date());
  }, [setCurrentDate]);

  // Format display text based on view
  const getDisplayText = useCallback((): string => {
    const locale = getCurrentLocale();

    if (view === 'month') {
      return firstDayOfMonth.toLocaleDateString(locale, {
        month: 'long',
        year: 'numeric'
      });
    } else if (view === 'week') {
      return `${weekStartDate.toLocaleDateString(locale, {
        day: 'numeric',
        month: 'short'
      })} - ${weekEndDate.toLocaleDateString(locale, {
        day: 'numeric',
        month: 'short',
        year: 'numeric'
      })}`;
    } else if (view === 'day') {
      return currentDate.toLocaleDateString(locale, {
        weekday: 'long',
        day: 'numeric',
        month: 'long',
        year: 'numeric'
      });
    }
    return '';
  }, [view, firstDayOfMonth, weekStartDate, weekEndDate, currentDate, getCurrentLocale]);

  return {
    currentDate,
    view,
    setCurrentDate,
    goToPrevious,
    goToNext,
    goToToday,
    getDisplayText,
    dateRange,
    weekStartDate,
    weekEndDate,
    firstDayOfMonth,
    lastDayOfMonth
  };
};

"use client";

import { useCallback } from "react";
import { ISelectedTimeSlot } from "@/components/features/bookings/types";
import { TimeSlotStatus } from "@/components/features/calendar/types";

/**
 * Hook for drag slot selection in calendar grid
 *
 * Provides drag and drop functionality for selecting multiple
 * time slots in the calendar grid. Supports both single clicks
 * and drag selection for bulk operations with mobile touch support.
 *
 * Features:
 * - Mouse down/move/up event handlers
 * - Touch event handlers for mobile devices
 * - Drag preview with visual feedback
 * - Rectangle selection logic across days and times
 * - Conflict detection during drag
 * - Availability checking integration
 * - Cleanup and cancellation support
 *
 * @example
 * const {
 *   handleMouseDown,
 *   handleMouseEnter,
 *   handleMouseUp,
 *   handleSlotClick,
 *   cancelDrag
 * } = useDragSlotSelection({
 *   zoneId: "zone-1",
 *   facilityId: "facility-1",
 *   pricePerHour: 100,
 *   timeSlots,
 *   weekDays: week.days,
 *   dragState,
 *   startDrag,
 *   updateDrag,
 *   endDrag,
 *   cancelDrag: cancelDragHandler,
 *   isSlotInPreview,
 *   getAvailabilityStatus,
 *   isSlotSelected,
 *   onSlotClick,
 *   onBulkSelect
 * });
 */

/**
 * Props for useDragSlotSelection hook
 */
export interface IUseDragSlotSelectionProps {
  readonly zoneId: string;
  readonly facilityId: string;
  readonly pricePerHour: number;
  readonly timeSlots: readonly string[];
  readonly weekDays: readonly { readonly date: Date }[];
  readonly dragState: {
    readonly isDragging: boolean;
  };
  readonly startDrag: (
    zoneId: string,
    date: Date,
    timeSlot: string,
    event: React.MouseEvent | React.TouchEvent
  ) => void;
  readonly updateDrag: (
    zoneId: string,
    date: Date,
    timeSlot: string,
    timeSlots: readonly string[],
    weekDays: readonly { readonly date: Date }[],
    getAvailabilityStatus: (
      zoneId: string,
      date: Date,
      timeSlot: string
    ) => { readonly status: string; readonly conflict?: { readonly id: string; readonly title: string } },
    facilityId: string,
    pricePerHour: number
  ) => void;
  readonly endDrag: () => readonly ISelectedTimeSlot[];
  readonly cancelDrag: () => void;
  readonly isSlotInPreview: (
    zoneId: string,
    date: Date,
    timeSlot: string
  ) => boolean;
  readonly getAvailabilityStatus: (
    zoneId: string,
    date: Date,
    timeSlot: string
  ) => { readonly status: string; readonly conflict?: { readonly id: string; readonly title: string } };
  readonly isSlotSelected: (
    zoneId: string,
    date: Date,
    timeSlot: string
  ) => boolean;
  readonly onSlotClick: (
    zoneId: string,
    date: Date,
    timeSlot: string,
    status: TimeSlotStatus
  ) => void;
  readonly onBulkSelect?: (slots: readonly ISelectedTimeSlot[]) => void;
}

/**
 * Return type for useDragSlotSelection hook
 */
export interface IUseDragSlotSelectionReturn {
  readonly handleMouseDown: (
    day: Date,
    timeSlot: string,
    event: React.MouseEvent
  ) => void;
  readonly handleMouseEnter: (day: Date, timeSlot: string) => void;
  readonly handleMouseUp: (event: React.MouseEvent) => void;
  readonly handleSlotClick: (
    day: Date,
    timeSlot: string,
    event: React.MouseEvent
  ) => void;
  readonly handleTouchStart: (
    day: Date,
    timeSlot: string,
    event: React.TouchEvent
  ) => void;
  readonly handleTouchMove: (event: React.TouchEvent) => void;
  readonly handleTouchEnd: (event: React.TouchEvent) => void;
}

/**
 * Custom hook for drag slot selection functionality
 *
 * Encapsulates all drag selection logic including mouse and touch event
 * handlers, providing a clean interface for the TimeSlotGrid component.
 *
 * @param props - Hook configuration props
 * @returns Event handlers and state for drag selection
 */
export const useDragSlotSelection = ({
  zoneId,
  facilityId,
  pricePerHour,
  timeSlots,
  weekDays,
  dragState,
  startDrag,
  updateDrag,
  endDrag,
  cancelDrag,
  isSlotInPreview,
  getAvailabilityStatus,
  isSlotSelected,
  onSlotClick,
  onBulkSelect,
}: IUseDragSlotSelectionProps): IUseDragSlotSelectionReturn => {
  /**
   * Handle mouse down for drag selection
   *
   * Initiates drag selection when user clicks on an available or selected slot.
   * Only triggers if bulk selection callback is provided.
   *
   * @param day - Calendar day
   * @param timeSlot - Time slot string
   * @param event - Mouse event
   */
  const handleMouseDown = useCallback(
    (day: Date, timeSlot: string, event: React.MouseEvent): void => {
      const { status } = getAvailabilityStatus(zoneId, day, timeSlot);

      if ((status === "available" || status === "selected") && !!onBulkSelect) {
        event.preventDefault();
        startDrag(zoneId, day, timeSlot, event);
      }
    },
    [zoneId, getAvailabilityStatus, onBulkSelect, startDrag]
  );

  /**
   * Handle mouse enter for drag selection
   *
   * Updates drag selection preview as user moves mouse over slots.
   * Only updates if drag is currently active and bulk selection is enabled.
   *
   * @param day - Calendar day
   * @param timeSlot - Time slot string
   */
  const handleMouseEnter = useCallback(
    (day: Date, timeSlot: string): void => {
      if (dragState.isDragging && !!onBulkSelect) {
        updateDrag(
          zoneId,
          day,
          timeSlot,
          timeSlots,
          weekDays,
          getAvailabilityStatus,
          facilityId,
          pricePerHour
        );
      }
    },
    [
      dragState.isDragging,
      onBulkSelect,
      updateDrag,
      zoneId,
      timeSlots,
      weekDays,
      getAvailabilityStatus,
      facilityId,
      pricePerHour,
    ]
  );

  /**
   * Handle mouse up for drag selection
   *
   * Completes drag selection and triggers bulk select callback
   * with all slots in the selection rectangle.
   *
   * @param event - Mouse event
   */
  const handleMouseUp = useCallback(
    (event: React.MouseEvent): void => {
      if (dragState.isDragging && !!onBulkSelect) {
        event.preventDefault();
        event.stopPropagation();

        const previewSlots = endDrag();

        if (previewSlots.length > 0) {
          // Pass the full slot objects to bulk select handler
          onBulkSelect(previewSlots);
        }
      }
    },
    [dragState.isDragging, onBulkSelect, endDrag]
  );

  /**
   * Handle time slot click
   *
   * Handles single slot selection when user clicks without dragging.
   * Checks availability status and triggers appropriate callback.
   *
   * @param day - Calendar day
   * @param timeSlot - Time slot string
   * @param event - Mouse event
   */
  const handleSlotClick = useCallback(
    (day: Date, timeSlot: string, event: React.MouseEvent): void => {
      // Prevent click if we just finished dragging
      if (dragState.isDragging) {
        event.preventDefault();
        event.stopPropagation();
        return;
      }

      const { status } = getAvailabilityStatus(zoneId, day, timeSlot);

      // Check if slot is already selected
      const isSelected = isSlotSelected(zoneId, day, timeSlot);
      const actualStatus = isSelected ? "selected" : (status as TimeSlotStatus);

      if (status === "available" || isSelected) {
        // Pass the actual Date object and parameters directly
        onSlotClick(zoneId, day, timeSlot, actualStatus);
      }
    },
    [
      dragState.isDragging,
      getAvailabilityStatus,
      zoneId,
      isSlotSelected,
      onSlotClick,
    ]
  );

  /**
   * Handle touch start for mobile drag selection
   *
   * Initiates drag selection on mobile devices when user touches
   * an available or selected slot.
   *
   * @param day - Calendar day
   * @param timeSlot - Time slot string
   * @param event - Touch event
   */
  const handleTouchStart = useCallback(
    (day: Date, timeSlot: string, event: React.TouchEvent): void => {
      const { status } = getAvailabilityStatus(zoneId, day, timeSlot);

      if ((status === "available" || status === "selected") && !!onBulkSelect) {
        event.preventDefault();
        startDrag(zoneId, day, timeSlot, event);
      }
    },
    [zoneId, getAvailabilityStatus, onBulkSelect, startDrag]
  );

  /**
   * Handle touch move for mobile drag selection
   *
   * Updates drag selection as user moves finger across slots.
   * Uses document.elementFromPoint to detect slot under touch.
   *
   * @param event - Touch event
   */
  const handleTouchMove = useCallback(
    (event: React.TouchEvent): void => {
      if (dragState.isDragging && !!onBulkSelect) {
        event.preventDefault();

        const touch = event.touches[0];
        const element = document.elementFromPoint(
          touch.clientX,
          touch.clientY
        );

        if (element && element.hasAttribute("data-slot")) {
          const slotData = element.getAttribute("data-slot");
          if (slotData) {
            try {
              const { day, timeSlot } = JSON.parse(slotData);
              const date = new Date(day);

              updateDrag(
                zoneId,
                date,
                timeSlot,
                timeSlots,
                weekDays,
                getAvailabilityStatus,
                facilityId,
                pricePerHour
              );
            } catch (error) {
              console.error("Error parsing slot data:", error);
            }
          }
        }
      }
    },
    [
      dragState.isDragging,
      onBulkSelect,
      updateDrag,
      zoneId,
      timeSlots,
      weekDays,
      getAvailabilityStatus,
      facilityId,
      pricePerHour,
    ]
  );

  /**
   * Handle touch end for mobile drag selection
   *
   * Completes drag selection on mobile and triggers bulk select
   * callback with all slots in the selection.
   *
   * @param event - Touch event
   */
  const handleTouchEnd = useCallback(
    (event: React.TouchEvent): void => {
      if (dragState.isDragging && !!onBulkSelect) {
        event.preventDefault();

        const previewSlots = endDrag();

        if (previewSlots.length > 0) {
          onBulkSelect(previewSlots);
        }
      }
    },
    [dragState.isDragging, onBulkSelect, endDrag]
  );

  return {
    handleMouseDown,
    handleMouseEnter,
    handleMouseUp,
    handleSlotClick,
    handleTouchStart,
    handleTouchMove,
    handleTouchEnd,
  };
};

/**
 * Dashboard Management Hook
 *
 * Clean architecture hook that handles all dashboard business logic:
 * - User data loading from Supabase
 * - Booking statistics and filtering
 * - Recommended facilities mapping
 * - System messages management
 * - Weather data simulation
 *
 * This hook extracts all business logic from the UserDashboard component,
 * making the component a pure presentation layer.
 *
 * @example
 * ```tsx
 * function UserDashboard() {
 *   const dashboard = useDashboardManagement(orgId);
 *
 *   return (
 *     <div>
 *       <h1>Welcome {dashboard.user.name}</h1>
 *       <BookingList bookings={dashboard.filteredBookings} />
 *     </div>
 *   );
 * }
 * ```
 */

import { useState, useEffect, useMemo, useCallback } from "react";
import { useTranslation } from "react-i18next";
import { usePublishedFacilities } from "@/services/supabase/facilities.service";
import { useUserBookings } from "@/services/supabase/bookings.service";
import { useAuth } from "@/contexts/hooks";

// ============================================================================
// Types & Interfaces
// ============================================================================

interface IUserData {
  readonly name: string;
  readonly totalBookings: number;
  readonly monthlyBookingLimit: number;
  readonly nextBooking: {
    readonly facility: string;
    readonly date: string;
    readonly time: string;
  } | null;
}

interface IWeatherData {
  readonly temperature: number;
  readonly condition: "sunny" | "cloudy" | "rainy" | "snowy";
  readonly description: string;
}

interface IUserFacility {
  readonly id: string;
  readonly name: string;
  readonly description: string;
  readonly type: string;
  readonly location: string;
  readonly address: string;
  readonly capacity: number;
  readonly amenities: readonly string[];
  readonly image: string;
  readonly rating: number;
  readonly price: string;
  readonly availability: "available" | "busy" | "full";
  readonly recommendationReason?: string;
  readonly isFrequentlyBooked?: boolean;
  readonly isNewInArea?: boolean;
  readonly matchesPreferredTimes?: boolean;
  readonly slug?: string;
}

interface IUserBooking {
  readonly id: string;
  readonly facility: string;
  readonly date: string;
  readonly time: string;
  readonly duration: string;
  readonly status: "confirmed" | "pending" | "cancelled";
  readonly location: string;
  readonly price: string;
  readonly purpose: string;
  readonly participants?: readonly string[];
  readonly qrCode?: string;
  readonly cancellationPolicy?: string;
  readonly contactInfo?: {
    readonly phone: string;
    readonly email: string;
  };
}

interface ISystemMessage {
  readonly id: string;
  readonly title: string;
  readonly message: string;
  readonly type: "info" | "warning" | "maintenance" | "success";
  readonly date: string;
  readonly isRead?: boolean;
  readonly category?: "system" | "booking" | "news";
}

export interface IUseDashboardManagementReturn {
  readonly user: IUserData;
  readonly weather: IWeatherData | null;
  readonly recommendedFacilities: readonly IUserFacility[];
  readonly userBookings: readonly IUserBooking[];
  readonly systemMessages: readonly ISystemMessage[];
  readonly filteredBookings: readonly IUserBooking[];
  readonly filteredMessages: readonly ISystemMessage[];
  readonly unreadMessagesCount: number;
  readonly facilitiesLoading: boolean;
  readonly bookingsLoading: boolean;
  readonly bookingFilter: string;
  readonly messageFilter: string;
  readonly expandedBookings: Set<string>;
  readonly setBookingFilter: (filter: string) => void;
  readonly setMessageFilter: (filter: string) => void;
  readonly toggleBookingExpansion: (id: string) => void;
  readonly markMessageAsRead: (id: string) => void;
}

// ============================================================================
// Hook Implementation
// ============================================================================

/**
 * Dashboard management hook
 *
 * @param orgId - Organization ID for fetching facilities
 * @returns Complete dashboard state and handlers
 */
export const useDashboardManagement = (
  orgId: string
): IUseDashboardManagementReturn => {
  const { t } = useTranslation(["common", "user", "booking"]);
  const { user: authUser } = useAuth();

  // State management
  const [bookingFilter, setBookingFilter] = useState<string>("all");
  const [messageFilter, setMessageFilter] = useState<string>("all");
  const [expandedBookings, setExpandedBookings] = useState<Set<string>>(
    new Set()
  );
  const [weather, setWeather] = useState<IWeatherData | null>(null);

  // Fetch data from Supabase
  const { data: facilities = [], isLoading: facilitiesLoading } =
    usePublishedFacilities(orgId);

  const { data: bookingsData = [], isLoading: bookingsLoading } =
    useUserBookings(authUser?.id || "", !!authUser?.id);

  // ============================================================================
  // User Data Loading
  // ============================================================================

  /**
   * Calculate user data from Supabase bookings
   * Includes total bookings count and next upcoming booking
   */
  const user: IUserData = useMemo(() => {
    try {
      // Find next upcoming paid/confirmed booking
      const now = new Date();
      const upcomingBookings = bookingsData
        .filter((booking) => {
          const bookingDate = new Date(booking.starts_at);
          return bookingDate >= now &&
                 (booking.status === "paid" || booking.status === "completed");
        })
        .sort((a, b) =>
          new Date(a.starts_at).getTime() - new Date(b.starts_at).getTime()
        );

      const nextBooking = upcomingBookings[0];

      return {
        name: t("user:dashboard.default_username"),
        totalBookings: bookingsData.length,
        monthlyBookingLimit: 5,
        nextBooking: nextBooking
          ? {
              facility:
                nextBooking.facility?.name ||
                t("user:dashboard.unknown_facility"),
              date: new Date(nextBooking.starts_at).toLocaleDateString(
                "nb-NO",
                { day: "2-digit", month: "2-digit" }
              ),
              time: new Date(nextBooking.starts_at).toLocaleTimeString(
                "nb-NO",
                { hour: "2-digit", minute: "2-digit" }
              ),
            }
          : null,
      };
    } catch (error) {
      console.error("Error calculating user data:", error);
      return {
        name: t("user:dashboard.default_username"),
        totalBookings: 0,
        monthlyBookingLimit: 5,
        nextBooking: null,
      };
    }
  }, [bookingsData, t]);

  // ============================================================================
  // Bookings Loading
  // ============================================================================

  /**
   * Load recent bookings from Supabase
   * Converts Supabase data to dashboard format
   */
  const userBookings: readonly IUserBooking[] = useMemo(() => {
    try {
      // Get recent bookings (last 3)
      const recentBookings = [...bookingsData]
        .sort(
          (a, b) =>
            new Date(b.starts_at).getTime() - new Date(a.starts_at).getTime()
        )
        .slice(0, 3);

      return recentBookings.map((booking) => {
        // Calculate duration
        const startTime = new Date(booking.starts_at);
        const endTime = new Date(booking.ends_at);
        const durationHours = Math.round(
          (endTime.getTime() - startTime.getTime()) / (1000 * 60 * 60)
        );

        // Map Supabase status to dashboard status
        let status: "confirmed" | "pending" | "cancelled";
        if (booking.status === "paid" || booking.status === "completed") {
          status = "confirmed";
        } else if (booking.status === "cancelled" || booking.status === "expired" || booking.status === "refunded") {
          status = "cancelled";
        } else {
          status = "pending";
        }

        return {
          id: booking.id,
          facility:
            booking.facility?.name || t("user:dashboard.unknown_facility"),
          date: booking.starts_at.split("T")[0],
          time: startTime.toLocaleTimeString("nb-NO", {
            hour: "2-digit",
            minute: "2-digit",
          }),
          duration: `${durationHours} ${durationHours === 1 ? "time" : "timer"}`,
          status,
          location:
            booking.facility?.name || t("user:dashboard.unknown_facility"),
          price: `${(booking.total_cents || 0) / 100} ${booking.currency || "kr"}`,
          purpose: booking.notes || t("user:bookings.not_specified"),
          participants: [t("user:dashboard.default_username")],
          qrCode: `QR${booking.id.slice(-6)}`,
          cancellationPolicy: t("user:bookings.cancellation_policy"),
          contactInfo: {
            phone: "+47 123 45 678",
            email: "admin@drammen.no",
          },
        };
      });
    } catch (error) {
      console.error("Error loading recent bookings:", error);
      return [];
    }
  }, [bookingsData, t]);

  // ============================================================================
  // Recommended Facilities
  // ============================================================================

  /**
   * Map published facilities to dashboard format
   * First 3 facilities with recommendation reasons
   */
  const recommendedFacilities: readonly IUserFacility[] = useMemo(() => {
    return facilities.slice(0, 3).map((facility, index) => ({
      id: facility.id,
      name: facility.name,
      description: facility.description || "",
      type: facility.facility_type || "",
      location: facility.area || "",
      address: facility.address || "",
      capacity: facility.capacity || 0,
      amenities: facility.amenities || [],
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      image: (facility.images as any)?.[0] || "/placeholder.svg",
      rating: facility.rating || 0,
      price: `${(facility.price_per_hour_cents || 0) / 100} kr/time`,
      availability: "available" as const,
      recommendationReason:
        index === 0
          ? t("user:recommendations.frequent_bookings")
          : index === 1
          ? t("user:recommendations.preferred_times")
          : t("user:recommendations.new_in_area"),
      isFrequentlyBooked: index === 0,
      matchesPreferredTimes: index === 1,
      isNewInArea: index === 2,
      slug: facility.slug,
    }));
  }, [facilities, t]);

  // ============================================================================
  // System Messages
  // ============================================================================

  /**
   * Static system messages
   * In production, this would come from an API
   */
  const systemMessages: readonly ISystemMessage[] = useMemo(
    () => [
      {
        id: "1",
        title: t("user:dashboard.system_messages.booking_updated"),
