const mapDbNotificationToNotification = (dbNotification: DbNotification): Notification => {
  return {
    id: dbNotification.id,
    userId: dbNotification.user_id,
    type: dbNotification.type as Notification['type'],
    title: dbNotification.title,
    content: dbNotification.content,
    priority: dbNotification.priority as Notification['priority'],
    read: dbNotification.read,
    actionUrl: dbNotification.action_url || undefined,
    metadata: dbNotification.metadata as Record<string, unknown> | undefined,
    createdAt: dbNotification.created_at,
    readAt: dbNotification.read_at || undefined,
  };
};

/**
 * Hook for managing notifications with business logic separation
 *
 * Provides comprehensive notification management functionality including:
 * - Data fetching and caching via React Query
 * - UI state management
 * - Business logic validation and operations
 * - Filtering, sorting, grouping, and search
 * - CRUD operations with optimistic updates
 * - Batch operations for multiple notifications
 *
 * @returns Complete notification management interface
 *
 * @example
 * ```tsx
 * function NotificationCenter() {
 *   const {
 *     filteredNotifications,
 *     isLoading,
 *     stats,
 *     searchTerm,
 *     setSearchTerm,
 *     markAsRead,
 *     markAllAsRead,
 *   } = useNotificationManagement();
 *
 *   const handleMarkAsRead = async (notificationId: string) => {
 *     await markAsRead(notificationId);
 *     toast.success('Notification marked as read');
 *   };
 *
 *   return (
 *     <div>
 *       <SearchBar value={searchTerm} onChange={setSearchTerm} />
 *       <NotificationStats stats={stats} />
 *       <NotificationList
 *         notifications={filteredNotifications}
 *         onMarkAsRead={handleMarkAsRead}
 *       />
 *     </div>
 *   );
 * }
 * ```
 */
export const useNotificationManagement = (): IUseNotificationManagementReturn => {
  // Auth context
  const { user } = useAuth();
  const userId = user?.id || '';

  // Data layer - fetch notifications from Supabase
  const {
    data: dbNotifications = [],
    isLoading,
    error,
  } = useNotifications(userId);

  // Convert database notifications to application notifications
  const notifications = useMemo(
    () => dbNotifications.map(mapDbNotificationToNotification),
    [dbNotifications]
  );

  const markAsReadMutation = useMarkNotificationAsRead();
  const markAllAsReadMutation = useMarkAllNotificationsAsRead();
  const deleteNotificationMutation = useDeleteNotification();
  const deleteAllReadMutation = useDeleteAllReadNotifications();

  // UI state layer
  const [uiState, setUiState] = useState<INotificationUIState>({
    searchTerm: '',
    typeFilter: [],
    priorityFilter: [],
    readFilter: undefined,
    dateRange: undefined,
    sortBy: 'created_at',
    sortOrder: 'desc',
    groupBy: 'date',
    selectedNotificationIds: [],
  });

  // Business logic layer - filtering and sorting
  const filteredNotifications = useMemo(() => {
    const filters: INotificationFilters = {
      searchTerm: uiState.searchTerm,
      type: uiState.typeFilter,
      priority: uiState.priorityFilter,
      read: uiState.readFilter,
      dateRange: uiState.dateRange,
    };

    const filtered = filterNotifications(notifications, filters);

    const sortConfig: INotificationSortConfig = {
      sortBy: uiState.sortBy,
      sortOrder: uiState.sortOrder,
    };

    return sortNotifications(filtered, sortConfig);
  }, [notifications, uiState]);

  // Group notifications based on groupBy setting
  const groupedNotifications = useMemo((): readonly INotificationGroup[] => {
    if (uiState.groupBy === 'none') {
      return [{ label: 'All', notifications: filteredNotifications }];
    }

    if (uiState.groupBy === 'type') {
      const groups = new Map<string, Notification[]>();
      filteredNotifications.forEach((notification) => {
        const key = notification.type;
        if (!groups.has(key)) {
          groups.set(key, []);
        }
        groups.get(key)!.push(notification);
      });

      return Array.from(groups.entries()).map(([type, notifications]) => ({
        label: type.charAt(0).toUpperCase() + type.slice(1),
        notifications,
      }));
    }

    if (uiState.groupBy === 'priority') {
      const priorityOrder = ['high', 'medium', 'low'];
      const groups = new Map<string, Notification[]>();

      filteredNotifications.forEach((notification) => {
        const key = notification.priority;
        if (!groups.has(key)) {
          groups.set(key, []);
        }
        groups.get(key)!.push(notification);
      });

      return priorityOrder
        .filter((priority) => groups.has(priority))
        .map((priority) => ({
          label: priority.charAt(0).toUpperCase() + priority.slice(1) + ' Priority',
          notifications: groups.get(priority)!,
        }));
    }

    // Group by date (default)
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const yesterday = new Date(today);
    yesterday.setDate(yesterday.getDate() - 1);
    const thisWeek = new Date(today);
    thisWeek.setDate(thisWeek.getDate() - 7);

    const groups = {
      today: [] as Notification[],
      yesterday: [] as Notification[],
      thisWeek: [] as Notification[],
      older: [] as Notification[],
    };

    filteredNotifications.forEach((notification) => {
      const notificationDate = new Date(notification.createdAt);
      const notificationDay = new Date(
        notificationDate.getFullYear(),
        notificationDate.getMonth(),
        notificationDate.getDate()
      );

      if (notificationDay.getTime() === today.getTime()) {
        groups.today.push(notification);
      } else if (notificationDay.getTime() === yesterday.getTime()) {
        groups.yesterday.push(notification);
      } else if (notificationDay >= thisWeek) {
        groups.thisWeek.push(notification);
      } else {
        groups.older.push(notification);
      }
    });

    const result: INotificationGroup[] = [];
    if (groups.today.length > 0) {
      result.push({ label: 'Today', notifications: groups.today });
    }
    if (groups.yesterday.length > 0) {
      result.push({ label: 'Yesterday', notifications: groups.yesterday });
    }
    if (groups.thisWeek.length > 0) {
      result.push({ label: 'This Week', notifications: groups.thisWeek });
    }
    if (groups.older.length > 0) {
      result.push({ label: 'Older', notifications: groups.older });
    }

    return result;
  }, [filteredNotifications, uiState.groupBy]);

  // Statistics
  const stats = useMemo(() => calculateNotificationStats(notifications, userId), [notifications, userId]);
  const unreadCount = useMemo(() => calculateUnreadCount(notifications, userId), [notifications, userId]);
  const unreadByType = useMemo(
    () => calculateUnreadCountByType(notifications, userId),
    [notifications, userId]
  );
  const unreadByPriority = useMemo(
    () => calculateUnreadCountByPriority(notifications, userId),
    [notifications, userId]
  );
  const highPriorityUnread = useMemo(
    () => getHighPriorityUnread(notifications, userId),
    [notifications, userId]
  );
  const urgentNotifications = useMemo(
    () => getUrgentNotifications(notifications, userId),
    [notifications, userId]
  );

  // UI Actions
  const setSearchTerm = useCallback((term: string) => {
    setUiState((prev) => ({ ...prev, searchTerm: term }));
  }, []);

  const toggleTypeFilter = useCallback((type: Notification['type']) => {
    setUiState((prev) => {
      const typeFilter = prev.typeFilter.includes(type)
        ? prev.typeFilter.filter((t) => t !== type)
        : [...prev.typeFilter, type];
      return { ...prev, typeFilter };
    });
  }, []);

  const clearTypeFilters = useCallback(() => {
    setUiState((prev) => ({ ...prev, typeFilter: [] }));
  }, []);

  const togglePriorityFilter = useCallback((priority: Notification['priority']) => {
    setUiState((prev) => {
      const priorityFilter = prev.priorityFilter.includes(priority)
        ? prev.priorityFilter.filter((p) => p !== priority)
        : [...prev.priorityFilter, priority];
      return { ...prev, priorityFilter };
    });
  }, []);

  const clearPriorityFilters = useCallback(() => {
    setUiState((prev) => ({ ...prev, priorityFilter: [] }));
  }, []);

  const setReadFilter = useCallback((read?: boolean) => {
    setUiState((prev) => ({ ...prev, readFilter: read }));
  }, []);

  const setDateRange = useCallback((range?: { from: Date; to: Date }) => {
    setUiState((prev) => ({ ...prev, dateRange: range }));
  }, []);

  const setSortBy = useCallback((sortBy: 'created_at' | 'priority' | 'type') => {
    setUiState((prev) => ({ ...prev, sortBy }));
  }, []);

  const setSortOrder = useCallback((sortOrder: 'asc' | 'desc') => {
    setUiState((prev) => ({ ...prev, sortOrder }));
  }, []);

  const setGroupBy = useCallback((groupBy: 'date' | 'type' | 'priority' | 'none') => {
    setUiState((prev) => ({ ...prev, groupBy }));
  }, []);

  const toggleNotificationSelection = useCallback((id: string) => {
    setUiState((prev) => {
      const selectedNotificationIds = prev.selectedNotificationIds.includes(id)
        ? prev.selectedNotificationIds.filter((nId) => nId !== id)
        : [...prev.selectedNotificationIds, id];
      return { ...prev, selectedNotificationIds };
    });
  }, []);

  const selectAllNotifications = useCallback(() => {
    setUiState((prev) => ({
      ...prev,
      selectedNotificationIds: filteredNotifications.map((n) => n.id),
    }));
  }, [filteredNotifications]);

  const clearSelection = useCallback(() => {
    setUiState((prev) => ({ ...prev, selectedNotificationIds: [] }));
  }, []);

  const resetFilters = useCallback(() => {
    setUiState((prev) => ({
      ...prev,
      searchTerm: '',
      typeFilter: [],
      priorityFilter: [],
      readFilter: undefined,
      dateRange: undefined,
    }));
  }, []);

  // Business Operations
  const markAsRead = useCallback(
    async (id: string): Promise<void> => {
      await markAsReadMutation.mutateAsync(id);
    },
    [markAsReadMutation]
  );

  const markAllAsRead = useCallback(async (): Promise<void> => {
    if (!userId) return;
    await markAllAsReadMutation.mutateAsync(userId);
  }, [userId, markAllAsReadMutation]);

  const deleteNotification = useCallback(
    async (id: string): Promise<void> => {
      await deleteNotificationMutation.mutateAsync(id);
      // Remove from selection if selected
      setUiState((prev) => ({
        ...prev,
        selectedNotificationIds: prev.selectedNotificationIds.filter((nId) => nId !== id),
      }));
    },
    [deleteNotificationMutation]
  );

  const deleteAllRead = useCallback(async (): Promise<void> => {
    if (!userId) return;
    await deleteAllReadMutation.mutateAsync(userId);
    clearSelection();
  }, [userId, deleteAllReadMutation, clearSelection]);

  const batchMarkAsRead = useCallback(
    async (ids: readonly string[]): Promise<void> => {
      await Promise.all(ids.map((id) => markAsReadMutation.mutateAsync(id)));
      clearSelection();
    },
    [markAsReadMutation, clearSelection]
  );

  const batchDelete = useCallback(
    async (ids: readonly string[]): Promise<void> => {
      await Promise.all(ids.map((id) => deleteNotificationMutation.mutateAsync(id)));
      clearSelection();
    },
    [deleteNotificationMutation, clearSelection]
  );

  return {
    // Data
    notifications,
    filteredNotifications,
    groupedNotifications,
    isLoading,
    error,

    // Statistics
    stats,
    unreadCount,
    unreadByType,
    unreadByPriority,
    highPriorityUnread,
    urgentNotifications,

    // UI State
    uiState,
    setSearchTerm,
    toggleTypeFilter,
    clearTypeFilters,
    togglePriorityFilter,
    clearPriorityFilters,
    setReadFilter,
    setDateRange,
    setSortBy,
    setSortOrder,
    setGroupBy,
    toggleNotificationSelection,
    selectAllNotifications,
    clearSelection,
    resetFilters,

    // Business Operations
    markAsRead,
    markAllAsRead,
    deleteNotification,
    deleteAllRead,
    batchMarkAsRead,
    batchDelete,
  };
};

/**
 * Admin Profile Management Hook
 *
 * Connects UI components to business logic and data services.
 * Provides a clean interface for admin profile management operations.
 */

import { useState, useRef, useCallback, useEffect } from 'react';
import { useAuth } from "@/contexts/hooks";
import { useTranslation } from 'react-i18next';
import { avatarService } from '@/services/supabase/avatar.service';
import { usersService } from '@/services/supabase/users.service';

interface AdminProfileForm {
  readonly firstName: string;
  readonly lastName: string;
  readonly email: string;
  readonly phone: string;
  readonly address: string;
}

interface ToastState {
  readonly show: boolean;
  readonly message: string;
}

interface UseAdminProfileManagementReturn {
  readonly profileForm: AdminProfileForm;
  readonly isEditingPersonalInfo: boolean;
  readonly isEditingSecurity: boolean;
  readonly avatarPreview: string | null;
  readonly toast: ToastState;
  readonly fileInputRef: React.RefObject<HTMLInputElement | null>;
  readonly setIsEditingPersonalInfo: (value: boolean) => void;
  readonly setIsEditingSecurity: (value: boolean) => void;
  readonly handleInputChange: (field: string, value: string) => void;
  readonly handleAvatarUpload: (event: React.ChangeEvent<HTMLInputElement>) => void;
  readonly handleSavePersonalInfo: () => Promise<void>;
  readonly handleSaveSecurity: () => Promise<void>;
  readonly handleCancelPersonalInfo: () => void;
  readonly handleCancelSecurity: () => void;
  readonly showToastMessage: (message: string) => void;
}

export const useAdminProfileManagement = (): UseAdminProfileManagementReturn => {
  const { t } = useTranslation('admin');
  const { user, profile, refreshProfile } = useAuth();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const hasSyncedRef = useRef<boolean>(false);

  // State management
  const [isEditingPersonalInfo, setIsEditingPersonalInfo] = useState<boolean>(false);
  const [isEditingSecurity, setIsEditingSecurity] = useState<boolean>(false);
  const [avatarPreview, setAvatarPreview] = useState<string | null>(null);
  const [toast, setToast] = useState<ToastState>({ show: false, message: "" });

  // Load avatar from localStorage on initialization
  useEffect(() => {
    if (user?.id) {
      const storedAvatar = localStorage.getItem(`avatar_${user.id}`);
      if (storedAvatar) {
        setAvatarPreview(storedAvatar);
      }
    }
  }, [user?.id]);

  // Local editing state
  const [profileForm, setProfileForm] = useState<AdminProfileForm>({
    firstName: profile?.display_name?.split(' ')[0] || user?.email?.split('@')[0] || "",
    lastName: profile?.display_name?.split(' ').slice(1).join(' ') || "",
    email: user?.email || "",
    phone: profile?.phone || "",
    address: ""
  });

  // Sync profileForm with profile when profile changes
  useEffect(() => {
    if (profile?.display_name || profile?.phone || user?.email) {
      // Get first and last name from display_name
      let firstName = "";
      let lastName = "";
      if (profile?.display_name) {
        const nameParts = profile.display_name.split(' ');
        firstName = nameParts[0] || "";
        lastName = nameParts.slice(1).join(' ') || "";
      } else if (user?.email) {
        // Fallback to email prefix
        firstName = user.email.split('@')[0] || "";
      }

      // Get address from localStorage if it exists
      let address = "";
      if (user?.id) {
        const addressKey = `address_${user.id}`;
        address = localStorage.getItem(addressKey) || "";
      }

      setProfileForm({
        firstName,
        lastName,
        email: user?.email || "",
        phone: profile?.phone || "",
        address
      });
      hasSyncedRef.current = true;
    }
  }, [profile?.display_name, profile?.phone, user?.email, user?.id]);

  // Toast management
  const showToastMessage = useCallback((message: string): void => {
    setToast({ show: true, message });
    setTimeout(() => setToast({ show: false, message: "" }), 3000);
  }, []);

  // Handle input changes
  const handleInputChange = useCallback((field: string, value: string): void => {
    setProfileForm(prev => ({
      ...prev,
      [field]: value
    }));
  }, []);

  // Handle avatar upload
  const handleAvatarUpload = useCallback((event: React.ChangeEvent<HTMLInputElement>): void => {
    const file = event.target.files?.[0];
    if (file && user?.id) {
      // Convert file to data URL and update profile
      const reader = new FileReader();
      reader.onload = (e) => {
        const dataUrl = e.target?.result as string;
        if (dataUrl) {
          setAvatarPreview(dataUrl);
          // Save to localStorage
          const storageKey = `avatar_${user.id}`;
          localStorage.setItem(storageKey, dataUrl);
          showToastMessage(t('pages.settings.changes_saved'));
        }
      };
      reader.readAsDataURL(file);
    }
  }, [user?.id, showToastMessage, t]);

  // Handle save profile for personal info
  const handleSavePersonalInfo = useCallback(async (): Promise<void> => {
    if (!user?.id) return;

    try {
      // Update profile in Supabase
      const updateData: any = {
        display_name: profileForm.firstName && profileForm.lastName 
          ? `${profileForm.firstName} ${profileForm.lastName}` 
          : (profileForm.firstName || profileForm.lastName || undefined),
        phone: profileForm.phone,
        email: profileForm.email
      };

      // Save address to localStorage (since it's not in the database)
      if (profileForm.address) {
        const addressKey = `address_${user.id}`;
        localStorage.setItem(addressKey, profileForm.address);
      }

      await usersService.update(user.id, updateData);

      // Refresh profile data
      await refreshProfile();

      setIsEditingPersonalInfo(false);
      showToastMessage(t('pages.settings.changes_saved'));
    } catch (error) {
      console.error('Failed to save profile:', error);
      showToastMessage(t('pages.settings.save_failed'));
    }
  }, [profileForm, user?.id, refreshProfile, showToastMessage, t]);

  // Handle save for security (placeholder for now)
  const handleSaveSecurity = useCallback(async (): Promise<void> => {
    // For now, just close the editing mode
    setIsEditingSecurity(false);
    showToastMessage(t('pages.settings.changes_saved'));
  }, [showToastMessage, t]);

  // Handle cancel editing for personal info
  const handleCancelPersonalInfo = useCallback((): void => {
    // Reset to original profile data
    setProfileForm({
      firstName: profile?.display_name?.split(' ')[0] || user?.email?.split('@')[0] || "",
      lastName: profile?.display_name?.split(' ').slice(1).join(' ') || "",
      email: user?.email || "",
      phone: profile?.phone || "",
      address: ""
    });
    setIsEditingPersonalInfo(false);

    // Restore avatar preview to original state
    if (user?.id) {
      const storedAvatar = localStorage.getItem(`avatar_${user.id}`);
      setAvatarPreview(storedAvatar);
    }

    hasSyncedRef.current = false; // Allow sync again
  }, [profile?.display_name, profile?.phone, user?.email, user?.id]);

  // Handle cancel editing for security
  const handleCancelSecurity = useCallback((): void => {
    setIsEditingSecurity(false);
  }, []);

  return {
    profileForm,
    isEditingPersonalInfo,
    isEditingSecurity,
    avatarPreview,
    toast,
    fileInputRef,
    setIsEditingPersonalInfo,
    setIsEditingSecurity,
    handleInputChange,
    handleAvatarUpload,
    handleSavePersonalInfo,
    handleSaveSecurity,
    handleCancelPersonalInfo,
    handleCancelSecurity,
    showToastMessage
  };
};

/**
 * User Preferences Hook
 *
 * Manages user preferences including language, theme, and notification settings.
 *
 * @module hooks/features/profile/useUserPreferences
 */

import { useState, useEffect, useCallback } from 'react';
import { preferencesService } from '@/services/supabase/preferences.service';
import type { Theme } from '@/services/supabase/preferences.service';
import { changeLanguage as changeI18nLanguage } from '@/i18n/config';
import type { Language as I18nLanguage } from '@/i18n/types';

export interface UserPreferences {
  readonly language: I18nLanguage;
  readonly theme: Theme;
  readonly emailBookingConfirmation: boolean;
  readonly emailBookingReminder: boolean;
  readonly smsBookingConfirmation: boolean;
  readonly smsBookingReminder: boolean;
  readonly browserBookingReminder: boolean;
  readonly browserEnabled: boolean;
}

export interface UseUserPreferencesReturn {
  readonly preferences: UserPreferences | null;
  readonly isLoading: boolean;
  readonly error: Error | null;
  readonly updateLanguage: (language: I18nLanguage) => Promise<void>;
  readonly updateTheme: (theme: Theme) => Promise<void>;
  readonly updateNotifications: (notifications: {
    readonly emailBookingConfirmation?: boolean;
    readonly emailBookingReminder?: boolean;
    readonly smsBookingConfirmation?: boolean;
    readonly smsBookingReminder?: boolean;
    readonly browserBookingReminder?: boolean;
    readonly browserEnabled?: boolean;
  }) => Promise<void>;
  readonly refresh: () => Promise<void>;
}

const defaultPreferences: UserPreferences = {
  language: 'NO',
  theme: 'system',
  emailBookingConfirmation: true,
  emailBookingReminder: true,
  smsBookingConfirmation: false,
  smsBookingReminder: false,
  browserBookingReminder: true,
  browserEnabled: true,
};

export const useUserPreferences = (userId: string | undefined): UseUserPreferencesReturn => {
  const [preferences, setPreferences] = useState<UserPreferences | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [error, setError] = useState<Error | null>(null);

  // Load preferences from Supabase and localStorage
  const loadPreferences = useCallback(async () => {
    if (!userId) {
      setIsLoading(false);
      return;
    }

    try {
      setIsLoading(true);
      setError(null);

      // Get notification preferences from Supabase
      const data = await preferencesService.getByUserId(userId);

      // Get language and theme from database (with localStorage fallback)
      let language: I18nLanguage = 'NO';
      let theme: Theme = 'system';

      // Try to get language from database
      const dbLanguage = await preferencesService.getLanguagePreference(userId);
      if (dbLanguage) {
        language = dbLanguage === 'en-US' ? 'EN' : 'NO';
      } else {
        // Fallback to localStorage
        const savedLanguage = localStorage.getItem('booknor-language');
        if (savedLanguage === 'EN') {
          language = 'EN';
        } else if (savedLanguage === 'NO') {
          language = 'NO';
        }
      }

      // Try to get theme from database
      const dbTheme = await preferencesService.getThemePreference(userId);
      if (dbTheme) {
        theme = dbTheme;
      } else {
        // Fallback to localStorage
        const savedTheme = localStorage.getItem('theme') as Theme | null;
        if (savedTheme && (savedTheme === 'light' || savedTheme === 'dark' || savedTheme === 'system')) {
          theme = savedTheme;
        }
      }

      if (data) {
        setPreferences({
          language,
          theme,
          emailBookingConfirmation: data.email_booking_confirmation,
          emailBookingReminder: data.email_booking_reminder,
          smsBookingConfirmation: data.sms_booking_confirmation,
          smsBookingReminder: data.sms_booking_reminder,
          browserBookingReminder: data.browser_booking_reminder,
          browserEnabled: data.browser_enabled,
        });
      } else {
        // If no preferences exist, use defaults with localStorage values
        setPreferences({
          ...defaultPreferences,
          language,
          theme
        });
      }
    } catch (err) {
      const error = err instanceof Error ? err : new Error(String(err));
      setError(error);
      setPreferences(defaultPreferences);
    } finally {
      setIsLoading(false);
    }
  }, [userId]);

  // Update language preference
  const updateLanguage = useCallback(async (language: I18nLanguage) => {
    if (!userId) return;

    try {
      // Update in database (with localStorage fallback)
      const serviceLanguage = language === 'EN' ? 'en-US' : 'nb-NO';
      await preferencesService.updateLanguagePreference(userId, serviceLanguage);

      // Update i18n
      const i18nLang = language === 'EN' ? 'en' : 'no';
      await changeI18nLanguage(i18nLang as 'no' | 'en');

      // Update local state
      setPreferences(prev => prev ? { ...prev, language } : {
        ...defaultPreferences,
        language
      });
    } catch (err) {
      const error = err instanceof Error ? err : new Error(String(err));
      setError(error);
    }
  }, [userId]);

  // Update theme preference - disabled (dark mode removed)
  const updateTheme = useCallback(async (theme: Theme) => {
    if (!userId) return;

    try {
      // Dark mode has been removed - always use light theme
      const lightTheme: Theme = 'light';

      // Update in localStorage (existing system)
      localStorage.setItem('theme', lightTheme);

      // Also save in user-specific storage
      localStorage.setItem(`theme_${userId}`, lightTheme);

      // Ensure dark class is never added
      document.documentElement.classList.remove('dark');

      // Update local state
      setPreferences(prev => prev ? { ...prev, theme: lightTheme } : {
        ...defaultPreferences,
        theme: lightTheme
      });
    } catch (err) {
      const error = err instanceof Error ? err : new Error(String(err));
      setError(error);
    }
  }, [userId]);

  // Update notification preferences
  const updateNotifications = useCallback(async (notifications: {
    readonly emailBookingConfirmation?: boolean;
    readonly emailBookingReminder?: boolean;
    readonly smsBookingConfirmation?: boolean;
    readonly smsBookingReminder?: boolean;
    readonly browserBookingReminder?: boolean;
    readonly browserEnabled?: boolean;
  }) => {
    if (!userId) return;

    try {
      // Prepare the update data for the notification preferences
      const updateData: any = {};
      if (notifications.emailBookingConfirmation !== undefined) {
        updateData.email_booking_confirmation = notifications.emailBookingConfirmation;
      }
      if (notifications.emailBookingReminder !== undefined) {
        updateData.email_booking_reminder = notifications.emailBookingReminder;
      }
      if (notifications.smsBookingConfirmation !== undefined) {
        updateData.sms_booking_confirmation = notifications.smsBookingConfirmation;
      }
      if (notifications.smsBookingReminder !== undefined) {
        updateData.sms_booking_reminder = notifications.smsBookingReminder;
      }
      if (notifications.browserBookingReminder !== undefined) {
        updateData.browser_booking_reminder = notifications.browserBookingReminder;
      }
      if (notifications.browserEnabled !== undefined) {
        updateData.browser_enabled = notifications.browserEnabled;
      }

      // Only update notification preferences in Supabase if there are fields to update
      if (Object.keys(updateData).length > 0) {
        await preferencesService.upsertNotificationPreferences(userId, updateData);
      }

      // Update local state
      setPreferences(prev => {
        if (!prev) return defaultPreferences;

        return {
          ...prev,
          emailBookingConfirmation: notifications.emailBookingConfirmation ?? prev.emailBookingConfirmation,
          emailBookingReminder: notifications.emailBookingReminder ?? prev.emailBookingReminder,
          smsBookingConfirmation: notifications.smsBookingConfirmation ?? prev.smsBookingConfirmation,
          smsBookingReminder: notifications.smsBookingReminder ?? prev.smsBookingReminder,
          browserBookingReminder: notifications.browserBookingReminder ?? prev.browserBookingReminder,
          browserEnabled: notifications.browserEnabled ?? prev.browserEnabled,
        };
      });
    } catch (err) {
      const error = err instanceof Error ? err : new Error(String(err));
      setError(error);
    }
  }, [userId]);

  // Refresh preferences
  const refresh = useCallback(async () => {
    await loadPreferences();
  }, [loadPreferences]);

  // Load preferences when userId changes
  useEffect(() => {
    loadPreferences();
  }, [loadPreferences]);

  return {
    preferences,
    isLoading,
    error,
    updateLanguage,
    updateTheme,
    updateNotifications,
    refresh,
  };
};

import { useState, useRef, useCallback, useEffect } from 'react';
import { useUserProfile } from "@/contexts/hooks";
import { useTranslation } from 'react-i18next';
import { avatarService } from '@/services/supabase/avatar.service';
import { usersService } from '@/services/supabase/users.service';
import { preferencesService } from '@/services/supabase/preferences.service';

interface PasswordForm {
  readonly currentPassword: string;
  readonly newPassword: string;
  readonly confirmPassword: string;
}

interface SecuritySettings {
  readonly twoFactorEnabled: boolean;
  readonly loginNotifications: boolean;
  readonly sessionTimeout: string;
}

interface NotificationPreferences {
  readonly email: boolean;
  readonly sms: boolean;
  readonly push: boolean;
  readonly bookingReminders: boolean;
  readonly newBookings: boolean;
}

interface Preferences {
  readonly language: string;
  readonly theme: string;
  readonly notifications: NotificationPreferences;
  readonly dashboardView: string;
}

interface LoginHistory {
  readonly date: string;
  readonly ip: string;
  readonly location: string;
  readonly device: string;
}

interface EditingProfile {
  readonly firstName: string;
  readonly lastName: string;
  readonly email: string;
  readonly phone: string;
  readonly address: string;
  readonly dateOfBirth: string;
}

interface ToastState {
  readonly show: boolean;
  readonly message: string;
}

interface UseUserProfileManagementReturn {
  readonly editingProfile: EditingProfile;
  readonly passwordForm: PasswordForm;
  readonly securitySettings: SecuritySettings;
  readonly preferences: Preferences;
  readonly loginHistory: readonly LoginHistory[];
  readonly isEditing: boolean;
  readonly showPassword: { readonly [key: string]: boolean };
  readonly avatarPreview: string | null;
  readonly deleteConfirmation: string;
  readonly showDeleteModal: boolean;
  readonly toast: ToastState;
  readonly fileInputRef: React.RefObject<HTMLInputElement | null>;
  readonly setIsEditing: (value: boolean) => void;
  readonly setDeleteConfirmation: (value: string) => void;
  readonly setShowDeleteModal: (value: boolean) => void;
  readonly setSecuritySettings: React.Dispatch<React.SetStateAction<SecuritySettings>>;
  readonly setPreferences: React.Dispatch<React.SetStateAction<Preferences>>;
  readonly handleInputChange: (field: string, value: string) => void;
  readonly handlePasswordChange: (field: string, value: string) => void;
  readonly handlePasswordSave: () => void;
  readonly handleAvatarUpload: (event: React.ChangeEvent<HTMLInputElement>) => void;
  readonly handleSave: () => void;
  readonly handleCancel: () => void;
  readonly handleDeleteAccount: () => void;
  readonly togglePasswordVisibility: (field: string) => void;
  readonly formatDate: (dateString: string) => string;
  readonly showToastMessage: (message: string) => void;
}

export const useUserProfileManagement = (): UseUserProfileManagementReturn => {
  const { t } = useTranslation('user');
  const { profile, updateProfile } = useUserProfile();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const hasSyncedRef = useRef<boolean>(false);

  // State management
  const [isEditing, setIsEditing] = useState<boolean>(false);
  const [showPassword, setShowPassword] = useState<{ [key: string]: boolean }>({});
  const [showDeleteModal, setShowDeleteModal] = useState<boolean>(false);
  const [deleteConfirmation, setDeleteConfirmation] = useState<string>("");
  const [avatarPreview, setAvatarPreview] = useState<string | null>(null);
  const [toast, setToast] = useState<ToastState>({ show: false, message: "" });

  // Local editing state - only update context when saving
  const [editingProfile, setEditingProfile] = useState<EditingProfile>({
    firstName: profile.firstName,
    lastName: profile.lastName,
    email: profile.email,
    phone: profile.phone,
    address: profile.address,
    dateOfBirth: profile.dateOfBirth
  });

  // Password form state
  const [passwordForm, setPasswordForm] = useState<PasswordForm>({
    currentPassword: "",
    newPassword: "",
    confirmPassword: ""
  });

  // Security settings state
  const [securitySettings, setSecuritySettings] = useState<SecuritySettings>({
    twoFactorEnabled: false,
    loginNotifications: true,
    sessionTimeout: "24"
  });

  // Preferences state
  const [preferences, setPreferences] = useState<Preferences>({
    language: "nb",
    theme: "system",
    notifications: {
      email: true,
      sms: false,
      push: true,
      bookingReminders: true,
      newBookings: true
    },
    dashboardView: "extended"
  });

  // Login history mock data
  const [loginHistory] = useState<readonly LoginHistory[]>([
    {
      date: "2024-01-20T14:30:00Z",
      ip: "192.168.1.1",
      location: "Drammen, Norge",
      device: "Chrome på Windows"
    },
    {
      date: "2024-01-19T09:15:00Z",
      ip: "192.168.1.1",
      location: "Drammen, Norge",
      device: "Safari på iPhone"
    },
    {
      date: "2024-01-18T16:45:00Z",
      ip: "10.0.0.5",
      location: "Oslo, Norge",
      device: "Chrome på Mac"
    }
  ]);

  // Load theme preference from database when component mounts
  useEffect(() => {
    const loadPreferences = async () => {
      if (profile.accountId) {
        try {
          // Try to get theme from database using the preferences service
          // This will fallback to localStorage if the database columns don't exist
          const theme = await preferencesService.getThemePreference(profile.accountId);
          if (theme && (theme === 'light' || theme === 'dark' || theme === 'system')) {
            setPreferences(prev => ({
              ...prev,
              theme
            }));
          } else {
            // Fallback to localStorage
            const savedTheme = localStorage.getItem('theme');
            if (savedTheme && (savedTheme === 'light' || savedTheme === 'dark' || savedTheme === 'system')) {
              setPreferences(prev => ({
                ...prev,
                theme: savedTheme
              }));
            }

            // Also check user-specific storage
            const userSpecificTheme = localStorage.getItem(`theme_${profile.accountId}`);
            if (userSpecificTheme && (userSpecificTheme === 'light' || userSpecificTheme === 'dark' || userSpecificTheme === 'system')) {
              setPreferences(prev => ({
                ...prev,
                theme: userSpecificTheme
              }));
            }
          }
        } catch (error) {
          // Fallback to localStorage if there's any error
          const savedTheme = localStorage.getItem('theme');
          if (savedTheme && (savedTheme === 'light' || savedTheme === 'dark' || savedTheme === 'system')) {
            setPreferences(prev => ({
              ...prev,
              theme: savedTheme
            }));
          }

          // Also check user-specific storage
          const userSpecificTheme = localStorage.getItem(`theme_${profile.accountId}`);
          if (userSpecificTheme && (userSpecificTheme === 'light' || userSpecificTheme === 'dark' || userSpecificTheme === 'system')) {
            setPreferences(prev => ({
              ...prev,
              theme: userSpecificTheme
            }));
          }
        }
      }
    };

    loadPreferences();
  }, [profile.accountId]);

  // Sync editingProfile with profile when profile changes
  useEffect(() => {
    if (profile.firstName || profile.lastName || profile.email) {
      setEditingProfile({
        firstName: profile.firstName,
        lastName: profile.lastName,
        email: profile.email,
        phone: profile.phone,
        address: profile.address,
        dateOfBirth: profile.dateOfBirth
      });

      // Load avatar from Supabase Storage
      if (profile.accountId) {
        avatarService.getAvatarUrl(profile.accountId).then(avatarUrl => {
          setAvatarPreview(avatarUrl);
        }).catch(error => {
          console.error('Error loading avatar:', error);
        });
      }

      hasSyncedRef.current = true;
    }
  }, [profile.firstName, profile.lastName, profile.email, profile.phone, profile.address, profile.dateOfBirth, profile.accountId, profile.avatar]);

  // Toast management
  const showToastMessage = useCallback((message: string): void => {
    setToast({ show: true, message });
    setTimeout(() => setToast({ show: false, message: "" }), 3000);
  }, []);

  // Handle input changes
  const handleInputChange = useCallback((field: string, value: string): void => {
    setEditingProfile(prev => ({
      ...prev,
      [field]: value
    }));
  }, []);

  // Handle password changes
  const handlePasswordChange = useCallback((field: string, value: string): void => {
    setPasswordForm(prev => ({ ...prev, [field]: value }));
  }, []);

  // Handle save profile
  const handleSave = useCallback((): void => {
    // Update context with all changes
    const updates: Record<string, string> = { ...editingProfile };
    if (avatarPreview) {
      updates.avatar = avatarPreview;
    }

    updateProfile(updates);
    setIsEditing(false);
    showToastMessage(t('pages.profile.personal_info.changes_saved'));
  }, [editingProfile, avatarPreview, updateProfile, showToastMessage, t]);

  // Handle cancel editing
  const handleCancel = useCallback((): void => {
    // Reset to original profile data
    setEditingProfile({
      firstName: profile.firstName,
      lastName: profile.lastName,
      email: profile.email,
      phone: profile.phone,
      address: profile.address,
      dateOfBirth: profile.dateOfBirth
    });
    setIsEditing(false);

    // Restore avatar preview to original state
    if (profile.accountId) {
      avatarService.getAvatarUrl(profile.accountId).then(avatarUrl => {
        setAvatarPreview(avatarUrl);
      }).catch(error => {
        console.error('Error loading avatar:', error);
      });
    }

    hasSyncedRef.current = false; // Allow sync again
  }, [profile]);

  // Handle password save with validation
  const handlePasswordSave = useCallback((): void => {
    if (passwordForm.newPassword !== passwordForm.confirmPassword) {
      showToastMessage(t('pages.profile.security.password.mismatch'));
      return;
    }

    // In a real app, this would call an API to update the password
    setPasswordForm({ currentPassword: "", newPassword: "", confirmPassword: "" });
    showToastMessage(t('pages.profile.security.password.updated'));
  }, [passwordForm, showToastMessage, t]);

  // Handle avatar upload
  const handleAvatarUpload = useCallback((event: React.ChangeEvent<HTMLInputElement>): void => {
    const file = event.target.files?.[0];
    if (file && profile.accountId) {
      // Upload file to Supabase Storage
      avatarService.uploadAvatar(profile.accountId, file).then(result => {
        setAvatarPreview(result.url);
        updateProfile({ avatar: result.url });
        showToastMessage(t('pages.profile.personal_info.changes_saved'));
      }).catch(error => {
        console.error('Error uploading avatar:', error);
        showToastMessage(t('pages.profile.personal_info.changes_saved'));
      });
    }
  }, [profile.accountId, updateProfile, showToastMessage, t]);

  // Handle delete account with GDPR logic
  const handleDeleteAccount = useCallback((): void => {
    if (deleteConfirmation !== profile.email) {
      showToastMessage(t('pages.profile.privacy.delete_account.email_mismatch'));
      return;
    }

    // GDPR-compliant account deletion
    if (window.confirm(t('pages.profile.privacy.delete_account.confirm_final'))) {
      // In a real app, this would call an API to:
      // 1. Anonymize all personal data
      // 2. Delete all bookings and associated data
      // 3. Remove user from all systems
      // 4. Send confirmation email
      // 5. Log the deletion for audit purposes

      // Simulate API call
      setTimeout(() => {
        showToastMessage(t('pages.profile.privacy.delete_account.success'));
        setShowDeleteModal(false);
        setDeleteConfirmation("");

        // In a real app, redirect to logout or landing page
        // navigate('/logout');
      }, 1000);
    }
  }, [deleteConfirmation, profile.email, showToastMessage, t]);

  // Toggle password visibility
  const togglePasswordVisibility = useCallback((field: string): void => {
    setShowPassword(prev => ({ ...prev, [field]: !prev[field] }));
  }, []);

  // Format date helper
  const formatDate = useCallback((dateString: string): string => {
    const date = new Date(dateString);
    const now = new Date();
    const diffTime = Math.abs(now.getTime() - date.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays === 1) return t('pages.profile.time.yesterday');
    if (diffDays < 7) return t('pages.profile.time.days_ago', { count: diffDays });
    if (diffDays < 30) return t('pages.profile.time.weeks_ago', { count: Math.ceil(diffDays / 7) });

    return date.toLocaleDateString('nb-NO', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  }, [t]);

  return {
    editingProfile,
    passwordForm,
    securitySettings,
    preferences,
    loginHistory,
    isEditing,
    showPassword,
    avatarPreview,
    deleteConfirmation,
    showDeleteModal,
    toast,
    fileInputRef,
    setIsEditing,
    setDeleteConfirmation,
    setShowDeleteModal,
    setSecuritySettings,
    setPreferences,
    handleInputChange,
    handlePasswordChange,
    handlePasswordSave,
    handleAvatarUpload,
    handleSave,
    handleCancel,
    handleDeleteAccount,
    togglePasswordVisibility,
    formatDate,
    showToastMessage
  };
};

import { useCallback } from "react";
import type { IReceipt } from "./useReceiptData";

interface UseReceiptActionsProps {
  readonly receipts: ReadonlyArray<IReceipt>;
}

interface UseReceiptActionsReturn {
  readonly handleDownloadReceipt: (receiptId: string) => void;
  readonly handleViewInvoice: (receiptId: string) => void;
  readonly handleCopyInvoiceNumber: (invoiceNumber: string) => void;
  readonly handleSendReceiptEmail: (receiptId: string) => void;
  readonly handleCompletePayment: (receiptId: string) => void;
  readonly handleExportCSV: (receipts: ReadonlyArray<IReceipt>) => void;
}

const formatDate = (dateString: string): string => {
  return new Date(dateString).toLocaleDateString("nb-NO", {
    year: "numeric",
    month: "long",
    day: "numeric",
  });
};

const formatAmount = (amount: number): string => {
  return new Intl.NumberFormat("nb-NO", {
    style: "currency",
    currency: "NOK",
  }).format(amount);
};

const createReceiptContent = (receipt: IReceipt): string => {
  const statusLabels = {
    paid: "Betalt",
    pending: "Venter på betaling",
    cancelled: "Avbrutt",
    refunded: "Refundert",
  };

  return `
KVITTERING - ${receipt.facility}
Fakturanummer: ${receipt.invoiceNumber}
Booking-ID: ${receipt.bookingId}

Dato: ${formatDate(receipt.date)}
Lokasjon: ${receipt.location}
Formål: ${receipt.purpose}
Varighet: ${receipt.duration}

Beløp: ${formatAmount(receipt.amount)}
${receipt.mvaAmount ? `MVA (25%): ${formatAmount(receipt.mvaAmount)}` : ""}
Betalt med: ${receipt.paymentMethod}
Status: ${statusLabels[receipt.status]}

${
  receipt.paidAt
    ? `Betalt: ${new Date(receipt.paidAt).toLocaleDateString("nb-NO")}`
    : ""
}
${receipt.refundReason ? `Refunderingsinfo: ${receipt.refundReason}` : ""}

---
Booknor - Drammen kommune
  `.trim();
};

const downloadTextFile = (content: string, filename: string): void => {
  const blob = new Blob([content], { type: "text/plain" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  link.click();
  URL.revokeObjectURL(url);
};

const createEmailBody = (receipt: IReceipt): string => {
  return `
Hei,

Vedlagt finner du kvittering for din booking:

Fasilitet: ${receipt.facility}
Dato: ${formatDate(receipt.date)}
Beløp: ${formatAmount(receipt.amount)}
Fakturanummer: ${receipt.invoiceNumber}
Booking-ID: ${receipt.bookingId}

Med vennlig hilsen
Booknor - Drammen kommune
  `.trim();
};

const createCSVContent = (receipts: ReadonlyArray<IReceipt>): string => {
  const headers = [
    "Fakturanummer",
    "Booking-ID",
    "Fasilitet",
    "Dato",
    "Beløp",
    "Status",
    "Betaling",
    "Lokasjon",
    "Formål",
    "Varighet",
    "Kategori",
    "MVA",
    "Betalt dato",
  ];

  const data = receipts.map((receipt) => [
    receipt.invoiceNumber,
    receipt.bookingId,
    receipt.facility,
    receipt.date,
    receipt.amount.toString(),
    receipt.status,
    receipt.paymentMethod,
    receipt.location,
    receipt.purpose,
    receipt.duration,
    receipt.category || "",
    receipt.mvaAmount?.toString() || "0",
    receipt.paidAt ? new Date(receipt.paidAt).toLocaleDateString("nb-NO") : "",
  ]);

  return [headers, ...data]
    .map((row) => row.map((field) => `"${field}"`).join(","))
    .join("\n");
};

export const useReceiptActions = ({
  receipts,
}: UseReceiptActionsProps): UseReceiptActionsReturn => {
  const handleDownloadReceipt = useCallback(
    (receiptId: string): void => {
      const receipt = receipts.find((r) => r.id === receiptId);
      if (!receipt) return;

      const content = createReceiptContent(receipt);
      downloadTextFile(content, `kvittering-${receipt.invoiceNumber}.txt`);

      // Show success message
      alert("Kvittering lastet ned!");
    },
    [receipts]
  );

  const handleViewInvoice = useCallback((receiptId: string): void => {
    // This is handled by state in the component
    // Kept here for consistency with the action interface
  }, []);

  const handleCopyInvoiceNumber = useCallback((invoiceNumber: string): void => {
    navigator.clipboard
      .writeText(invoiceNumber)
      .then(() => {
        alert("Fakturanummer kopiert til utklippstavle!");
      })
      .catch((error) => {
        console.error("Failed to copy invoice number:", error);
        alert("Kunne ikke kopiere fakturanummer");
      });
  }, []);

  const handleSendReceiptEmail = useCallback(
    (receiptId: string): void => {
      const receipt = receipts.find((r) => r.id === receiptId);
      if (!receipt) return;

      const subject = `Kvittering for ${receipt.facility} - ${receipt.invoiceNumber}`;
      const body = createEmailBody(receipt);

      const mailtoLink = `mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(
        body
      )}`;
      window.open(mailtoLink);

      // Show success message
      alert("E-post klargjort!");
    },
    [receipts]
  );

  const handleCompletePayment = useCallback(
    (receiptId: string): void => {
      const receipt = receipts.find((r) => r.id === receiptId);
      if (!receipt) return;

      // In a real app, this would redirect to the payment provider
      alert(`Omdirigerer til betalingsportal for ${receipt.facility}...`);

      // Simulate navigation
      setTimeout(() => {
        window.location.href = `/payment/${receipt.bookingId}`;
      }, 1000);
    },
    [receipts]
  );

  const handleExportCSV = useCallback((receipts: ReadonlyArray<IReceipt>): void => {
    const csvContent = createCSVContent(receipts);
    const filename = `kvitteringer-${new Date().toISOString().split("T")[0]}.csv`;

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = filename;
    link.click();
    URL.revokeObjectURL(url);

    // Show success message
    alert("CSV-fil lastet ned!");
  }, []);

  return {
    handleDownloadReceipt,
    handleViewInvoice,
    handleCopyInvoiceNumber,
    handleSendReceiptEmail,
    handleCompletePayment,
    handleExportCSV,
  };
};

