/**
 * Hook return interface
 */
export interface IUseUserManagementReturn {
  // Data
  readonly users: readonly IUserWithRole[];
  readonly filteredUsers: readonly IUserWithRole[];
  readonly isLoading: boolean;
  readonly error: Error | null;

  // Statistics
