  readonly uniqueRoles: readonly OrgRole[];

  // UI State
  readonly view: string;
  readonly showFilters: boolean;
  readonly searchTerm: string;
  readonly roleFilter: readonly OrgRole[];
  readonly statusFilter: readonly string[];
