/**
 * Hook for managing users with business logic separation
 *
 * Provides comprehensive user management including:
 * - User list with filtering and sorting
 * - Role-based operations validation
 * - Batch operations support
 * - User statistics and analytics
 * - Permission-based access control
 *
 * @returns Complete user management interface
 *
 * @example
 * ```tsx
 * function UserManagementPage() {
 *   const {
 *     filteredUsers,
 *     isLoading,
 *     stats,
 *     searchTerm,
 *     setSearchTerm,
 *     updateUserRole,
 *     deleteUser,
 *     canDeleteUser,
 *     canChangeRole,
 *   } = useUserManagement();
 *
 *   const handleRoleChange = async (userId: string, newRole: OrgRole) => {
 *     const user = filteredUsers.find(u => u.id === userId);
 *     if (!user) return;
 *
 *     const validation = canChangeRole(user, newRole);
 *     if (!validation.canChange) {
 *       toast.error(validation.reason);
 *       return;
 *     }
 *
 *     await updateUserRole(userId, newRole);
 *     toast.success('Role updated successfully');
 *   };
 *
 *   return (
 *     <div>
 *       <UserStats stats={stats} />
 *       <SearchBar value={searchTerm} onChange={setSearchTerm} />
 *       <UserTable
 *         users={filteredUsers}
 *         onRoleChange={handleRoleChange}
 *         onDelete={deleteUser}
 *         canDeleteUser={canDeleteUser}
 *       />
 *     </div>
 *   );
 * }
 * ```
 */
export const useUserManagement = (): IUseUserManagementReturn => {
  // Data layer - TODO: Connect to actual Supabase hooks when available
  const { user: currentUser } = useAuth();

  // Placeholder data layer - replace with actual hooks
  const users: readonly IUserWithRole[] = []; // TODO: useUsers(orgId)
  const isLoading = false; // TODO: from useUsers
  const error = null; // TODO: from useUsers

  // Placeholder mutations - replace with actual hooks
  const deleteUserMutation = {
    mutateAsync: async (id: string): Promise<void> => {
      // TODO: Connect to actual delete mutation
      console.log('Delete user:', id);
    },
  };

  const updateUserMutation = {
    mutateAsync: async (params: { id: string; data: Record<string, unknown> }): Promise<void> => {
      // TODO: Connect to actual update mutation
      console.log('Update user:', params);
    },
  };

  // UI state layer - appUIStore users section
  const appUIStore = useAppUIStore();
  const {
    view,
    showFilters,
    searchTerm,
    roleFilter,
    statusFilter,
    selectedUserIds,
  } = appUIStore.users;

  // Actions from appUIStore with users prefix
  const setView = appUIStore.setUsersView;
  const toggleFilters = appUIStore.toggleUsersFilters;
  const setSearchTerm = appUIStore.setUsersSearchTerm;
  const toggleRoleFilter = appUIStore.toggleUsersRoleFilter;
  const toggleStatusFilter = appUIStore.toggleUsersStatusFilter;
  const resetFilters = appUIStore.resetUsersFilters;

  // Business logic layer - filtering and sorting
  const filteredUsers = useMemo(() => {
    const filters: IUserFilters = {
      searchTerm,
      roleFilter,
      statusFilter: statusFilter as readonly ('active' | 'inactive' | 'suspended')[],
    };

    const filtered = filterUsers(users, filters);

    const sortConfig: IUserSortConfig = {
      sortBy: sortBy as IUserSortConfig['sortBy'],
      sortOrder: sortOrder as IUserSortConfig['sortOrder'],
    };

    return sortUsers(filtered, sortConfig);
  }, [users, searchTerm, roleFilter, statusFilter, sortBy, sortOrder]);

  // Statistics
  const stats = useMemo(() => calculateUserStats(users), [users]);
  const uniqueRoles = useMemo(() => getUniqueUserRoles(users), [users]);

  // Validation helpers
  const canDeleteUserFn = useCallback(
    (user: IUserWithRole): IUserDeletionValidationResult => {
      if (!currentUser?.id || !user.role) {
        return {
          canDelete: false,
          reason: 'Insufficient information to validate deletion',
        };
      }

      // Check if user is the last owner
      const isLastOwner = user.role === 'owner' && stats.byRole.owner === 1;

      // TODO: Check for active bookings and owned facilities from data layer
      const hasActiveBookings = false;
      const ownsFacilities = false;

      return canDeleteUser(
        user.id,
        currentUser.id,
        user.role,
        isLastOwner,
        hasActiveBookings,
        ownsFacilities
      );
    },
    [currentUser, stats]
  );

  const canSuspendUserFn = useCallback(
    (user: IUserWithRole): IRoleChangeValidationResult => {
      if (!currentUser?.id || !user.role) {
        return {
          canChange: false,
          reason: 'Insufficient information to validate suspension',
        };
      }

      const isLastOwner = user.role === 'owner' && stats.byRole.owner === 1;

      return canSuspendUser(user.id, currentUser.id, user.role, isLastOwner);
    },
    [currentUser, stats]
  );

  const canChangeRoleFn = useCallback(
    (targetUser: IUserWithRole, newRole: OrgRole): IRoleChangeValidationResult => {
      if (!currentUser?.id || !currentUser.role || !targetUser.role) {
        return {
          canChange: false,
          reason: 'Insufficient information to validate role change',
        };
      }

      return validateRoleChange(
        currentUser.role as OrgRole,
        targetUser.id,
        currentUser.id,
        newRole
      );
    },
    [currentUser]
  );

  // Business operations
  const deleteUserFn = useCallback(
    async (id: string): Promise<void> => {
      const user = users.find((u) => u.id === id);
      if (!user) {
        throw new Error('User not found');
      }

      const validation = canDeleteUserFn(user);
      if (!validation.canDelete) {
        throw new Error(validation.reason || 'Cannot delete user');
      }

      if (validation.warnings && validation.warnings.length > 0) {
        const confirmed = window.confirm(
          `${validation.warnings.join('\n')}\n\nAre you sure you want to delete this user?`
        );
        if (!confirmed) return;
      }

      await deleteUserMutation.mutateAsync(id);
    },
    [users, canDeleteUserFn, deleteUserMutation]
  );

  const batchDeleteUsers = useCallback(
    async (ids: readonly string[]): Promise<void> => {
      const usersToDelete = users.filter((u) => ids.includes(u.id));

      // Validate each user
      for (const user of usersToDelete) {
        const validation = canDeleteUserFn(user);
        if (!validation.canDelete) {
          throw new Error(
            `Cannot delete user ${user.display_name || user.email}: ${validation.reason}`
          );
        }
      }

      const confirmed = window.confirm(
        `Are you sure you want to delete ${ids.length} user(s)?`
      );
      if (!confirmed) return;

      await Promise.all(ids.map((id) => deleteUserMutation.mutateAsync(id)));
      clearSelection();
    },
    [users, canDeleteUserFn, deleteUserMutation, clearSelection]
  );

  const updateUserRoleFn = useCallback(
    async (id: string, role: OrgRole): Promise<void> => {
      const user = users.find((u) => u.id === id);
      if (!user) {
        throw new Error('User not found');
      }

      const validation = canChangeRoleFn(user, role);
      if (!validation.canChange) {
        throw new Error(validation.reason || 'Cannot change user role');
      }

      await updateUserMutation.mutateAsync({
        id,
        data: { role },
      });
    },
    [users, canChangeRoleFn, updateUserMutation]
  );

  const batchUpdateRole = useCallback(
    async (ids: readonly string[], role: OrgRole): Promise<void> => {
      const usersToUpdate = users.filter((u) => ids.includes(u.id));

      // Validate each user
      for (const user of usersToUpdate) {
        const validation = canChangeRoleFn(user, role);
        if (!validation.canChange) {
          throw new Error(
            `Cannot change role for ${user.display_name || user.email}: ${validation.reason}`
          );
        }
      }

      await Promise.all(
        ids.map((id) =>
          updateUserMutation.mutateAsync({
            id,
            data: { role },
          })
        )
      );
      clearSelection();
    },
    [users, canChangeRoleFn, updateUserMutation, clearSelection]
  );

  const suspendUserFn = useCallback(
    async (id: string): Promise<void> => {
      const user = users.find((u) => u.id === id);
      if (!user) {
        throw new Error('User not found');
      }

      const validation = canSuspendUserFn(user);
      if (!validation.canChange) {
        throw new Error(validation.reason || 'Cannot suspend user');
      }

      await updateUserMutation.mutateAsync({
        id,
        data: { status: 'suspended' },
      });
    },
    [users, canSuspendUserFn, updateUserMutation]
  );

  const activateUserFn = useCallback(
    async (id: string): Promise<void> => {
      await updateUserMutation.mutateAsync({
        id,
        data: { status: 'active' },
      });
    },
    [updateUserMutation]
  );

  const selectAllUsersFn = useCallback(() => {
    selectAll(filteredUsers.map((u) => u.id));
  }, [filteredUsers, selectAll]);

  return {
    // Data
    users,
    filteredUsers,
    isLoading,
    error,

    // Statistics
    stats,
    uniqueRoles,

    // UI State
    view,
    showFilters,
    searchTerm,
    roleFilter,
    statusFilter: statusFilter as readonly string[],
    sortBy,
    sortOrder,
    selectedUserIds,

    // UI Actions
    setView,
    toggleFilters,
    setSearchTerm,
    toggleRoleFilter,
    toggleStatusFilter: toggleStatusFilter as (status: string) => void,
    toggleSort,
    toggleUserSelection,
    selectAllUsers: selectAllUsersFn,
    clearSelection,
    resetFilters,

    // Business Operations
    deleteUser: deleteUserFn,
    batchDeleteUsers,
    updateUserRole: updateUserRoleFn,
    batchUpdateRole,
    suspendUser: suspendUserFn,
    activateUser: activateUserFn,

    // Validation
    canDeleteUser: canDeleteUserFn,
    canSuspendUser: canSuspendUserFn,
    canChangeRole: canChangeRoleFn,
  };
};

/**
 * User Permissions Hook
 *
 * Manages user permissions and access control based on roles.
 * Provides permission checking utilities for routes, actions, and resources.
 * Follows clean architecture principles with business logic separation.
 *
 * @module hooks/features/users/useUserPermissions
 */

import { useMemo, useCallback } from 'react';
import { useAuth } from "@/contexts/hooks";
import { getUserPermissions, type IUserPermissions } from '@/services/business/user.business.service';
import {
  canAccessAdminRoute,
  canAccessUserRoute,
  hasRolePriority,
  type RouteAccessResult,
} from '@/services/business/auth.business.service';
import {
  hasMinimumRole,
  canManageBookings,
  canEditFacilities,
  canManageUsers,
  canViewReports,
  canExportData,
  canManageMedia,
  hasFullAccess,
  hasReadOnlyAccess,
  isOperationalRole,
  isEditorialRole,
  type OrgRole,
  type SystemRole,
} from '@/constants/roles';

/**
 * Resource types for permission checking
 */
export type TResource =
  | 'users'
  | 'facilities'
  | 'bookings'
  | 'reports'
  | 'organizations'
  | 'media'
  | 'roles'
  | 'billing'
  | 'settings';

/**
 * Action types for permission checking
 */
export type TAction = 'create' | 'read' | 'update' | 'delete' | 'export' | 'manage';

/**
 * Route types for permission checking
 */
export type TRouteType = 'admin' | 'user' | 'public';

/**
 * Hook return interface
 */
export interface IUseUserPermissionsReturn {
  // Current user info
  readonly currentUserId: string | null;
  readonly currentUserRole: OrgRole | null;
  readonly isPlatformAdmin: boolean;

  // Permission object
  readonly permissions: IUserPermissions;

  // General permission checks
  readonly hasPermission: (resource: TResource, action: TAction) => boolean;
  readonly canAccessRoute: (routeType: TRouteType, path?: string) => RouteAccessResult;
  readonly hasMinimumRole: (minRole: OrgRole) => boolean;
  readonly hasRolePriority: (requiredRole: OrgRole) => boolean;

  // Specific capability checks
  readonly canManageUsers: boolean;
  readonly canManageFacilities: boolean;
  readonly canManageBookings: boolean;
  readonly canViewReports: boolean;
  readonly canExportData: boolean;
  readonly canManageOrganization: boolean;
  readonly canManageRoles: boolean;
  readonly canManageBilling: boolean;
  readonly canViewAuditLogs: boolean;
  readonly isReadOnly: boolean;

  // Role type checks
  readonly hasFullAccess: boolean;
  readonly isOperational: boolean;
  readonly isEditorial: boolean;

  // Resource-specific permission helpers
  readonly canCreateUser: boolean;
  readonly canUpdateUser: (targetUserId: string) => boolean;
  readonly canDeleteUser: (targetUserId: string) => boolean;
  readonly canChangeUserRole: (targetUserId: string, newRole: OrgRole) => boolean;

  readonly canCreateFacility: boolean;
  readonly canUpdateFacility: boolean;
  readonly canDeleteFacility: boolean;

  readonly canCreateBooking: boolean;
  readonly canUpdateBooking: boolean;
  readonly canDeleteBooking: boolean;
  readonly canApproveBooking: boolean;

  readonly canUploadMedia: boolean;
  readonly canDeleteMedia: boolean;
}

/**
 * Hook for managing user permissions with business logic
 *
 * Provides comprehensive permission management including:
 * - Role-based access control (RBAC)
 * - Resource and action permission checks
 * - Route access validation
 * - Hierarchy-based permissions
 * - Specific capability checks for UI components
 *
 * @returns Complete user permissions interface
 *
 * @example
 * ```tsx
 * function UserManagementPage() {
 *   const {
 *     canManageUsers,
 *     canCreateUser,
 *     canDeleteUser,
 *     hasPermission,
 *     canAccessRoute,
 *   } = useUserPermissions();
 *
 *   // Check if user can access this page
 *   useEffect(() => {
 *     const access = canAccessRoute('admin', '/users');
 *     if (!access.canAccess) {
 *       toast.error(access.reason);
 *       navigate(access.redirectTo || '/dashboard');
 *     }
 *   }, [canAccessRoute, navigate]);
 *
 *   if (!canManageUsers) {
 *     return <AccessDenied />;
 *   }
 *
 *   return (
 *     <div>
 *       {canCreateUser && (
 *         <button onClick={handleCreateUser}>Create User</button>
 *       )}
 *       <UserTable
 *         users={users}
 *         canDelete={(user) => canDeleteUser(user.id)}
 *       />
 *     </div>
 *   );
 * }
 * ```
 *
 * @example
 * ```tsx
 * function FacilityEditor() {
 *   const {
 *     canManageFacilities,
 *     canUpdateFacility,
 *     canUploadMedia,
 *   } = useUserPermissions();
 *
 *   if (!canManageFacilities) {
 *     return <AccessDenied />;
 *   }
 *
 *   return (
 *     <form>
 *       <FacilityDetailsSection disabled={!canUpdateFacility} />
 *       {canUploadMedia && <MediaUploadSection />}
 *     </form>
 *   );
 * }
 * ```
 */
export const useUserPermissions = (): IUseUserPermissionsReturn => {
  const { user } = useAuth();

  // Extract user info
  const currentUserId = user?.id || null;
  const currentUserRole = (user?.role as OrgRole) || null;
  const isPlatformAdmin = user?.role === 'platform_admin';

  // Get permissions from business logic
  const permissions = useMemo(
    () => getUserPermissions(currentUserRole),
    [currentUserRole]
  );

  // General permission checks
  const hasPermissionFn = useCallback(
    (resource: TResource, action: TAction): boolean => {
      // Platform admin has all permissions
      if (isPlatformAdmin) return true;

      // Map resource and action to specific permissions
      switch (resource) {
        case 'users':
          return action === 'read' ? true : permissions.canManageUsers;
        case 'facilities':
          return action === 'read' ? true : permissions.canManageFacilities;
        case 'bookings':
          return action === 'read' ? true : permissions.canManageBookings;
        case 'reports':
          return permissions.canViewReports;
        case 'organizations':
          return action === 'read' ? true : permissions.canManageOrganization;
        case 'media':
          return action === 'read' ? true : permissions.canManageFacilities; // Media tied to facilities
        case 'roles':
          return permissions.canManageRoles;
        case 'billing':
          return permissions.canManageBilling;
        case 'settings':
          return permissions.canManageOrganization;
        default:
          return false;
      }
    },
    [isPlatformAdmin, permissions]
  );

  const canAccessRouteFn = useCallback(
    (routeType: TRouteType, path?: string): RouteAccessResult => {
      // Public routes are always accessible
      if (routeType === 'public') {
        return { canAccess: true };
      }

      // Admin routes
      if (routeType === 'admin') {
        return canAccessAdminRoute(currentUserRole as SystemRole, isPlatformAdmin);
      }

      // User routes
      if (routeType === 'user') {
        return canAccessUserRoute(currentUserRole as SystemRole, isPlatformAdmin);
      }

      return {
        canAccess: false,
        reason: 'Unknown route type',
      };
    },
    [currentUserRole, isPlatformAdmin]
  );

  const hasMinimumRoleFn = useCallback(
    (minRole: OrgRole): boolean => {
      return hasMinimumRole(currentUserRole, minRole);
    },
    [currentUserRole]
  );

  const hasRolePriorityFn = useCallback(
    (requiredRole: OrgRole): boolean => {
      return hasRolePriority(currentUserRole, requiredRole, isPlatformAdmin);
    },
    [currentUserRole, isPlatformAdmin]
  );

  // Specific capability checks (from constants/roles.ts)
  const canManageUsersFn = useMemo(
    () => canManageUsers(currentUserRole),
    [currentUserRole]
  );

  const canManageFacilitiesFn = useMemo(
    () => canEditFacilities(currentUserRole),
    [currentUserRole]
  );

  const canManageBookingsFn = useMemo(
    () => canManageBookings(currentUserRole),
    [currentUserRole]
  );

  const canViewReportsFn = useMemo(
    () => canViewReports(currentUserRole),
    [currentUserRole]
  );

  const canExportDataFn = useMemo(
    () => canExportData(currentUserRole),
    [currentUserRole]
  );

  const canManageMediaFn = useMemo(
    () => canManageMedia(currentUserRole),
    [currentUserRole]
  );

  const hasFullAccessFn = useMemo(
    () => hasFullAccess(currentUserRole),
    [currentUserRole]
  );

  const hasReadOnlyAccessFn = useMemo(
    () => hasReadOnlyAccess(currentUserRole),
    [currentUserRole]
  );

  const isOperationalFn = useMemo(
    () => isOperationalRole(currentUserRole),
    [currentUserRole]
  );

  const isEditorialFn = useMemo(
    () => isEditorialRole(currentUserRole),
    [currentUserRole]
  );

  // Resource-specific permission helpers
  const canCreateUserFn = useMemo(
    () => permissions.canManageUsers,
    [permissions]
  );

  const canUpdateUserFn = useCallback(
    (targetUserId: string): boolean => {
      // Can update if can manage users, or updating own profile
      return permissions.canManageUsers || targetUserId === currentUserId;
    },
    [permissions, currentUserId]
  );

  const canDeleteUserFn = useCallback(
    (targetUserId: string): boolean => {
      // Cannot delete yourself
      if (targetUserId === currentUserId) return false;
      // Must have user management permission
      return permissions.canManageUsers;
    },
    [permissions, currentUserId]
  );

  const canChangeUserRoleFn = useCallback(
    (targetUserId: string, newRole: OrgRole): boolean => {
      // Cannot change your own role
      if (targetUserId === currentUserId) return false;
      // Must have role management permission
      if (!permissions.canManageRoles) return false;
      // Must have higher or equal priority than target role
      return hasRolePriorityFn(newRole);
    },
    [permissions, currentUserId, hasRolePriorityFn]
  );

  // Facility permissions
  const canCreateFacilityFn = useMemo(
    () => permissions.canManageFacilities,
    [permissions]
  );

  const canUpdateFacilityFn = useMemo(
    () => permissions.canManageFacilities,
    [permissions]
  );

  const canDeleteFacilityFn = useMemo(
    () => permissions.canManageFacilities && !permissions.isReadOnly,
    [permissions]
  );

  // Booking permissions
  const canCreateBookingFn = useMemo(
    () => permissions.canManageBookings || currentUserRole === 'customer',
    [permissions, currentUserRole]
  );

  const canUpdateBookingFn = useMemo(
    () => permissions.canManageBookings,
    [permissions]
  );

  const canDeleteBookingFn = useMemo(
    () => permissions.canManageBookings && !permissions.isReadOnly,
    [permissions]
  );

  const canApproveBookingFn = useMemo(
    () => permissions.canManageBookings,
    [permissions]
  );

  // Media permissions
  const canUploadMediaFn = useMemo(
    () => canManageMediaFn,
    [canManageMediaFn]
  );

  const canDeleteMediaFn = useMemo(
    () => canManageMediaFn && !permissions.isReadOnly,
    [canManageMediaFn, permissions]
  );

  return {
    // Current user info
    currentUserId,
    currentUserRole,
    isPlatformAdmin,

    // Permission object
    permissions,

    // General permission checks
    hasPermission: hasPermissionFn,
    canAccessRoute: canAccessRouteFn,
    hasMinimumRole: hasMinimumRoleFn,
    hasRolePriority: hasRolePriorityFn,

    // Specific capability checks
    canManageUsers: canManageUsersFn,
    canManageFacilities: canManageFacilitiesFn,
    canManageBookings: canManageBookingsFn,
    canViewReports: canViewReportsFn,
    canExportData: canExportDataFn,
    canManageOrganization: permissions.canManageOrganization,
    canManageRoles: permissions.canManageRoles,
    canManageBilling: permissions.canManageBilling,
    canViewAuditLogs: permissions.canViewAuditLogs,
    isReadOnly: permissions.isReadOnly,

    // Role type checks
    hasFullAccess: hasFullAccessFn,
    isOperational: isOperationalFn,
    isEditorial: isEditorialFn,

    // Resource-specific permission helpers
    canCreateUser: canCreateUserFn,
    canUpdateUser: canUpdateUserFn,
    canDeleteUser: canDeleteUserFn,
    canChangeUserRole: canChangeUserRoleFn,

    canCreateFacility: canCreateFacilityFn,
    canUpdateFacility: canUpdateFacilityFn,
    canDeleteFacility: canDeleteFacilityFn,

    canCreateBooking: canCreateBookingFn,
    canUpdateBooking: canUpdateBookingFn,
    canDeleteBooking: canDeleteBookingFn,
    canApproveBooking: canApproveBookingFn,

    canUploadMedia: canUploadMediaFn,
    canDeleteMedia: canDeleteMediaFn,
  };
};

/**
 * Zone Management Hook
 *
 * Connects UI components to zone business logic and data services.
 * Provides a clean interface for zone management operations including
 * filtering, sorting, CRUD operations, and availability checking.
 * Follows clean architecture principles with clear separation of concerns.
 */

import { useMemo, useCallback } from 'react';
import { useZoneUIStore, type TZoneView, type TZoneSortBy } from '@/stores/zoneUIStore';
import {
  filterZones,
  sortZones,
  validateZoneData,
  canDeleteZone,
  calculateZoneUtilization,
  findAvailableZones,
  groupZonesByFacility,
  getAveragePricePerHour,
  getZoneCapacityBounds,
  getUniqueAmenities,
  calculateTotalCapacity,
  hasAmenity,
  hasAllAmenities,
  calculateBookingCost,
  getZonesAvailableForDateTimeRange,
  type IZoneFilters,
  type IZoneSortConfig,
  type ZoneValidationResult,
  type ZoneDeleteCheckResult,
  type ZoneUtilizationStats,
  type ZonesByFacility,
} from '@/services/business/zone.business.service';
import type { Zone } from '@/types/booking';

export interface IUseZoneManagementReturn {
  // Data (would be fetched from API in real implementation)
  readonly zones: readonly Zone[];
  readonly filteredZones: readonly Zone[];
  readonly isLoading: boolean;
  readonly error: Error | null;

  // Statistics
  readonly totalCapacity: number;
  readonly averagePrice: number;
  readonly capacityBounds: ReturnType<typeof getZoneCapacityBounds>;
  readonly uniqueAmenities: readonly string[];
  readonly zonesByFacility: readonly ZonesByFacility[];

  // UI State
  readonly view: TZoneView;
  readonly showFilters: boolean;
  readonly searchTerm: string;
  readonly facilityFilter: readonly string[];
  readonly capacityRange: { readonly min: number; readonly max: number };
  readonly amenityFilter: readonly string[];
  readonly sortBy: TZoneSortBy;
  readonly sortOrder: string;
  readonly selectedZoneIds: readonly string[];
  readonly modals: {
    readonly create: boolean;
    readonly edit: boolean;
    readonly delete: boolean;
    readonly availability: boolean;
  };
  readonly activeZoneId: string | null;

  // UI Actions
  readonly setView: (view: TZoneView) => void;
  readonly toggleFilters: () => void;
  readonly setSearchTerm: (term: string) => void;
  readonly toggleFacilityFilter: (facility: string) => void;
  readonly setCapacityRange: (range: { min: number; max: number }) => void;
  readonly toggleAmenityFilter: (amenity: string) => void;
  readonly toggleSort: (sortBy: TZoneSortBy) => void;
  readonly toggleZoneSelection: (id: string) => void;
  readonly selectAllZones: () => void;
  readonly clearSelection: () => void;
  readonly resetFilters: () => void;
  readonly openModal: (modal: 'create' | 'edit' | 'delete' | 'availability', zoneId?: string) => void;
  readonly closeModal: (modal: 'create' | 'edit' | 'delete' | 'availability') => void;
  readonly closeAllModals: () => void;
  readonly setActiveZoneId: (id: string | null) => void;

  // Business Operations
  readonly validateZoneData: (zone: Partial<Zone>) => ZoneValidationResult;
  readonly canDeleteZone: (zone: Zone, activeBookingCount: number) => ZoneDeleteCheckResult;
  readonly calculateZoneUtilization: (zone: Zone, currentOccupancy: number) => number;
  readonly findAvailableZones: (
    dayOfWeek: number,
    timeSlot: string,
    facilityId?: string,
    minimumCapacity?: number
  ) => readonly Zone[];
  readonly hasAmenity: (zone: Zone, amenity: string) => boolean;
  readonly hasAllAmenities: (zone: Zone, amenities: readonly string[]) => boolean;
  readonly calculateBookingCost: (zone: Zone, hours: number) => number;
  readonly getZonesAvailableForDateTimeRange: (
    date: Date,
    startTime: string,
    endTime: string,
    facilityId?: string
  ) => readonly Zone[];
}

/**
 * Hook for managing zones with business logic separation
 *
 * Provides comprehensive zone management functionality including:
 * - Data fetching and caching (would use React Query in real implementation)
 * - UI state management via Zustand store
 * - Business logic validation and operations
 * - Filtering by facility, capacity, amenities
 * - Sorting by multiple criteria
 * - CRUD operations validation
 * - Availability checking
 * - Cost calculations
 *
 * @returns Complete zone management interface
 *
 * @example
 * ```tsx
 * function ZoneManagementPage() {
 *   const {
 *     filteredZones,
 *     searchTerm,
 *     setSearchTerm,
 *     validateZoneData,
 *     canDeleteZone,
 *     openModal,
 *   } = useZoneManagement();
 *
 *   const handleDelete = (zone: Zone) => {
 *     const validation = canDeleteZone(zone, activeBookingCount);
 *     if (!validation.canDelete) {
 *       toast.error(validation.reason);
 *       return;
 *     }
 *     openModal('delete', zone.id);
 *   };
 *
 *   return (
 *     <div>
 *       <SearchBar value={searchTerm} onChange={setSearchTerm} />
 *       <ZoneGrid zones={filteredZones} onDelete={handleDelete} />
 *     </div>
 *   );
 * }
 * ```
 */
export const useZoneManagement = (zones: readonly Zone[] = []): IUseZoneManagementReturn => {
  // In a real implementation, data would be fetched here
  // const { data: zones = [], isLoading, error } = useZones(orgId);
  const isLoading = false;
  const error = null;

  // UI state layer - Zustand store for UI-specific state
  const {
    view,
    showFilters,
    searchTerm,
    facilityFilter,
    capacityRange,
    amenityFilter,
    sortBy,
    sortOrder,
    selectedZoneIds,
    modals,
    activeZoneId,
    setView,
    toggleFilters,
    setSearchTerm,
    toggleFacilityFilter,
    setCapacityRange,
    toggleAmenityFilter,
    toggleSort,
    toggleZoneSelection,
    selectAllZones: selectAll,
    clearSelection,
    resetFilters,
    openModal,
    closeModal,
    closeAllModals,
    setActiveZoneId,
  } = useZoneUIStore();

  // Business logic layer - filtering and sorting
  const filteredZones = useMemo(() => {
    const filters: IZoneFilters = {
      searchTerm,
      facilityId: facilityFilter.length > 0 ? facilityFilter[0] : undefined,
      capacityRange,
    };

    const filtered = filterZones(zones, filters);

    const sortConfig: IZoneSortConfig = {
      sortBy: sortBy === 'facility' || sortBy === 'updated_at' || sortBy === 'created_at'
        ? 'name' // Map unsupported sort fields to 'name'
        : sortBy,
      sortOrder: sortOrder as 'asc' | 'desc',
    };

    return sortZones(filtered, sortConfig);
  }, [zones, searchTerm, facilityFilter, capacityRange, sortBy, sortOrder]);

  // Statistics
  const totalCapacity = useMemo(() => calculateTotalCapacity(zones), [zones]);
  const averagePrice = useMemo(() => getAveragePricePerHour(zones), [zones]);
  const capacityBounds = useMemo(() => getZoneCapacityBounds(zones), [zones]);
  const uniqueAmenities = useMemo(() => getUniqueAmenities(zones), [zones]);
  const zonesByFacility = useMemo(() => groupZonesByFacility(zones), [zones]);

  // Business operations - wrapped with useCallback for stability
  const findAvailableZonesCallback = useCallback(
    (
      dayOfWeek: number,
      timeSlot: string,
      facilityId?: string,
      minimumCapacity?: number
    ): readonly Zone[] => {
      return findAvailableZones(zones, dayOfWeek, timeSlot, facilityId, minimumCapacity);
    },
    [zones]
  );

  const getZonesAvailableForDateTimeRangeCallback = useCallback(
    (
      date: Date,
      startTime: string,
      endTime: string,
      facilityId?: string
    ): readonly Zone[] => {
      return getZonesAvailableForDateTimeRange(zones, date, startTime, endTime, facilityId);
    },
    [zones]
  );

  const hasAmenityCallback = useCallback(
    (zone: Zone, amenity: string): boolean => {
      return hasAmenity(zone, amenity);
    },
    []
  );

  const hasAllAmenitiesCallback = useCallback(
    (zone: Zone, amenities: readonly string[]): boolean => {
      return hasAllAmenities(zone, amenities);
    },
    []
  );

  const calculateBookingCostCallback = useCallback(
    (zone: Zone, hours: number): number => {
      return calculateBookingCost(zone, hours);
    },
    []
  );

  const selectAllZones = useCallback(() => {
    selectAll(filteredZones.map((z) => z.id));
  }, [filteredZones, selectAll]);

  return {
    // Data
    zones,
    filteredZones,
    isLoading,
    error,

    // Statistics
    totalCapacity,
    averagePrice,
    capacityBounds,
    uniqueAmenities,
    zonesByFacility,

    // UI State
    view,
    showFilters,
    searchTerm,
    facilityFilter,
    capacityRange,
    amenityFilter,
    sortBy,
    sortOrder,
    selectedZoneIds,
    modals,
    activeZoneId,

    // UI Actions
    setView,
    toggleFilters,
    setSearchTerm,
    toggleFacilityFilter,
    setCapacityRange,
    toggleAmenityFilter,
    toggleSort,
    toggleZoneSelection,
    selectAllZones,
    clearSelection,
    resetFilters,
    openModal,
    closeModal,
    closeAllModals,
    setActiveZoneId,

    // Business Operations
    validateZoneData,
    canDeleteZone,
    calculateZoneUtilization,
    findAvailableZones: findAvailableZonesCallback,
    hasAmenity: hasAmenityCallback,
    hasAllAmenities: hasAllAmenitiesCallback,
    calculateBookingCost: calculateBookingCostCallback,
    getZonesAvailableForDateTimeRange: getZonesAvailableForDateTimeRangeCallback,
  };
};

/**
 * useBookings Hook
 *
 * Provides a unified interface for booking operations with automatic
 * storage layer abstraction. Handles gradual migration from localStorage
 * to Supabase with three phases:
 *
 * Phase 1 (fallback): Read from Supabase with localStorage fallback
 * Phase 2 (dual-write): Write to both, read from Supabase with fallback
 * Phase 3 (supabase-only): All operations go to Supabase
 */

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '@/lib/clients/supabase';
import type { IStoredBooking } from '@/utils/localStorageTypes';
import {
  getStoredBookings,
  setStoredBookings,
} from '@/utils/localStorageTypes';
import {
  getMigrationPhase,
  type MigrationPhase,
  MigrationError,
} from '@/utils/storageMigration';

/**
 * Return type for useBookings hook
 */
interface UseBookingsReturn {
  readonly bookings: readonly IStoredBooking[];
  readonly isLoading: boolean;
  readonly error: Error | null;
  readonly addBooking: (booking: IStoredBooking) => Promise<void>;
  readonly updateBooking: (id: string, updates: Partial<IStoredBooking>) => Promise<void>;
  readonly deleteBooking: (id: string) => Promise<void>;
  readonly syncWithLocalStorage: () => Promise<void>;
  readonly refetch: () => Promise<void>;
}

/**
 * Convert Supabase booking row to IStoredBooking format
 */
const mapSupabaseToStoredBooking = (row: Record<string, unknown>): IStoredBooking => {
  return {
    id: String(row.id),
    facilityId: row.facility_id ? String(row.facility_id) : undefined,
    facilityName: row.facility_name ? String(row.facility_name) : undefined,
    facility: row.facility_name ? String(row.facility_name) : undefined,
    startDate: row.start_date ? String(row.start_date) : '',
    date: row.start_date ? String(row.start_date) : undefined,
    startTime: row.start_time ? String(row.start_time) : undefined,
    time: row.start_time ? String(row.start_time) : undefined,
    endTime: row.end_time ? String(row.end_time) : undefined,
    duration: row.duration ? Number(row.duration) : undefined,
    status: row.status as 'approved' | 'rejected' | 'pending' | 'cancelled' | undefined,
    price: row.price_cents ? Number(row.price_cents) / 100 : undefined,
    purpose: row.purpose ? String(row.purpose) : undefined,
    description: row.description ? String(row.description) : undefined,
    contactPerson: row.contact_person ? String(row.contact_person) : undefined,
    bookerName: row.booker_name ? String(row.booker_name) : undefined,
    bookerEmail: row.booker_email ? String(row.booker_email) : undefined,
    submittedAt: row.submitted_at ? String(row.submitted_at) : undefined,
    requestedAt: row.submitted_at ? String(row.submitted_at) : undefined,
    processedBy: row.processed_by ? String(row.processed_by) : undefined,
    processedAt: row.processed_at ? String(row.processed_at) : undefined,
    isRecurring: row.is_recurring ? Boolean(row.is_recurring) : undefined,
    parentBookingId: row.parent_booking_id ? String(row.parent_booking_id) : undefined,
  };
};

/**
 * Convert IStoredBooking to Supabase insert format
 */
const mapStoredBookingToSupabase = (
  booking: IStoredBooking,
  userId: string
): Record<string, unknown> => {
  return {
    id: booking.id,
    user_id: userId,
    facility_id: booking.facilityId,
    facility_name: booking.facilityName || booking.facility,
    start_date: booking.startDate || booking.date,
    start_time: booking.startTime || booking.time,
    end_time: booking.endTime,
    duration: typeof booking.duration === 'number'
      ? booking.duration
      : parseFloat(String(booking.duration || '0')),
    status: booking.status || 'pending',
    price_cents: typeof booking.price === 'number'
      ? Math.round(booking.price * 100)
      : Math.round(parseFloat(String(booking.price || '0')) * 100),
    purpose: booking.purpose,
    description: booking.description,
    contact_person: booking.contactPerson,
    booker_name: booking.bookerName,
    booker_email: booking.bookerEmail,
    submitted_at: booking.submittedAt || booking.requestedAt,
    processed_by: booking.processedBy,
    processed_at: booking.processedAt,
    is_recurring: booking.isRecurring || false,
    parent_booking_id: booking.parentBookingId,
  };
};

/**
 * Hook to manage bookings with storage migration support
 *
 * @param userId - The current user ID
 * @param bookingType - Type of bookings to fetch ('pending' or 'processed')
 * @param autoFetch - Whether to automatically fetch on mount
 *
 * @example
 * ```typescript
 * const {
 *   bookings,
 *   isLoading,
 *   addBooking,
 *   updateBooking,
 *   deleteBooking
 * } = useBookings(userId, 'pending', true);
 *
 * // Add a new booking
 * const handleAddBooking = async (booking: IStoredBooking) => {
 *   await addBooking(booking);
 * };
 *
 * // Update existing booking
 * const handleUpdateBooking = async (id: string, status: string) => {
 *   await updateBooking(id, { status });
 * };
 * ```
 */
export const useBookings = (
  userId: string | null,
  bookingType: 'pending' | 'processed' | 'all' = 'all',
  autoFetch: boolean = true
): UseBookingsReturn => {
  const [bookings, setBookings] = useState<readonly IStoredBooking[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<Error | null>(null);
  const phase = getMigrationPhase();

  /**
   * Fetch bookings based on current migration phase
   */
  const fetchBookings = useCallback(async (): Promise<void> => {
    if (!userId) {
      setBookings([]);
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      let fetchedBookings: IStoredBooking[] = [];

      // Phase 1: Try Supabase first, fallback to localStorage
      if (phase === 'fallback') {
        try {
          const query = supabase
            .from('bookings')
            .select('*')
            .eq('user_id', userId);

          // Filter by status if not 'all'
          if (bookingType === 'pending') {
            query.eq('status', 'pending');
          } else if (bookingType === 'processed') {
            query.in('status', ['approved', 'rejected', 'cancelled']);
          }

          const { data, error: supabaseError } = await query;

          if (supabaseError) {
            throw supabaseError;
          }

          if (data && data.length > 0) {
            fetchedBookings = data.map(mapSupabaseToStoredBooking);
          } else {
            // Fallback to localStorage
            const localKey = bookingType === 'all' ? null :
              bookingType === 'pending' ? 'pendingBookings' : 'processedBookings';

            if (localKey) {
              fetchedBookings = getStoredBookings(localKey);
            } else {
              const pending = getStoredBookings('pendingBookings');
              const processed = getStoredBookings('processedBookings');
              fetchedBookings = [...pending, ...processed];
            }
          }
        } catch (supabaseError) {
          console.error('Supabase fetch failed, using localStorage:', supabaseError);
          // Fallback to localStorage
          const localKey = bookingType === 'all' ? null :
            bookingType === 'pending' ? 'pendingBookings' : 'processedBookings';

          if (localKey) {
            fetchedBookings = getStoredBookings(localKey);
          } else {
            const pending = getStoredBookings('pendingBookings');
            const processed = getStoredBookings('processedBookings');
            fetchedBookings = [...pending, ...processed];
          }
        }
      }

      // Phase 2 & 3: Read from Supabase (with fallback in phase 2)
      if (phase === 'dual-write' || phase === 'supabase-only') {
        try {
          const query = supabase
            .from('bookings')
            .select('*')
            .eq('user_id', userId);

          // Filter by status if not 'all'
          if (bookingType === 'pending') {
            query.eq('status', 'pending');
          } else if (bookingType === 'processed') {
            query.in('status', ['approved', 'rejected', 'cancelled']);
          }

          const { data, error: supabaseError } = await query;

          if (supabaseError) {
            throw supabaseError;
          }

          fetchedBookings = data ? data.map(mapSupabaseToStoredBooking) : [];
        } catch (supabaseError) {
          // Only fallback in phase 2
          if (phase === 'dual-write') {
            console.error('Supabase fetch failed, using localStorage:', supabaseError);
            const localKey = bookingType === 'all' ? null :
              bookingType === 'pending' ? 'pendingBookings' : 'processedBookings';

            if (localKey) {
              fetchedBookings = getStoredBookings(localKey);
            } else {
              const pending = getStoredBookings('pendingBookings');
              const processed = getStoredBookings('processedBookings');
              fetchedBookings = [...pending, ...processed];
            }
          } else {
            throw supabaseError;
          }
        }
      }

      setBookings(fetchedBookings);
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Unknown error';
      setError(new Error(`Failed to fetch bookings: ${errorMessage}`));
      console.error('Error fetching bookings:', err);
    } finally {
      setIsLoading(false);
    }
  }, [userId, bookingType, phase]);

  /**
   * Add a new booking with phase-aware storage
   */
  const addBooking = useCallback(
    async (booking: IStoredBooking): Promise<void> => {
      if (!userId) {
        throw new Error('User ID is required to add booking');
      }

      setError(null);

      try {
        // Phase 1: Write to localStorage only
        if (phase === 'fallback') {
          const key = booking.status === 'pending' ? 'pendingBookings' : 'processedBookings';
          const existing = getStoredBookings(key);
          setStoredBookings(key, [...existing, booking]);
        }

        // Phase 2: Write to both
        if (phase === 'dual-write') {
          // Write to localStorage
          const localKey = booking.status === 'pending' ? 'pendingBookings' : 'processedBookings';
          const existing = getStoredBookings(localKey);
          setStoredBookings(localKey, [...existing, booking]);

          // Write to Supabase
          const supabaseData = mapStoredBookingToSupabase(booking, userId);
          const { error: supabaseError } = await supabase
            .from('bookings')
            .insert(supabaseData);

          if (supabaseError) {
            throw new MigrationError(
              'Failed to write to Supabase',
              phase,
              'add_booking',
              supabaseError
            );
          }
        }

        // Phase 3: Write to Supabase only
        if (phase === 'supabase-only') {
          const supabaseData = mapStoredBookingToSupabase(booking, userId);
          const { error: supabaseError } = await supabase
            .from('bookings')
            .insert(supabaseData);

          if (supabaseError) {
            throw new MigrationError(
              'Failed to write to Supabase',
              phase,
              'add_booking',
              supabaseError
            );
          }
        }

        // Refetch to update local state
        await fetchBookings();
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : 'Unknown error';
        setError(new Error(`Failed to add booking: ${errorMessage}`));
        throw err;
      }
    },
    [userId, phase, fetchBookings]
  );

  /**
   * Update an existing booking
   */
  const updateBooking = useCallback(
    async (id: string, updates: Partial<IStoredBooking>): Promise<void> => {
      if (!userId) {
        throw new Error('User ID is required to update booking');
      }

      setError(null);

      try {
        // Phase 1: Update localStorage only
        if (phase === 'fallback') {
          ['pendingBookings', 'processedBookings'].forEach((key) => {
            const existing = getStoredBookings(key as 'pendingBookings' | 'processedBookings');
            const updated = existing.map((b) =>
              b.id === id ? { ...b, ...updates } : b
            );
            if (existing.length !== updated.length || existing.some((b, i) => b !== updated[i])) {
              setStoredBookings(key as 'pendingBookings' | 'processedBookings', updated);
            }
          });
        }

        // Phase 2: Update both
        if (phase === 'dual-write') {
          // Update localStorage
          ['pendingBookings', 'processedBookings'].forEach((key) => {
            const existing = getStoredBookings(key as 'pendingBookings' | 'processedBookings');
            const updated = existing.map((b) =>
              b.id === id ? { ...b, ...updates } : b
            );
            if (existing.some((b, i) => b !== updated[i])) {
              setStoredBookings(key as 'pendingBookings' | 'processedBookings', updated);
            }
          });

          // Update Supabase
          const supabaseUpdates: Record<string, unknown> = {};
          if (updates.status) supabaseUpdates.status = updates.status;
          if (updates.processedBy) supabaseUpdates.processed_by = updates.processedBy;
          if (updates.processedAt) supabaseUpdates.processed_at = updates.processedAt;
          if (updates.description) supabaseUpdates.description = updates.description;

          const { error: supabaseError } = await supabase
            .from('bookings')
            .update(supabaseUpdates)
            .eq('id', id)
            .eq('user_id', userId);

          if (supabaseError) {
            throw new MigrationError(
              'Failed to update in Supabase',
              phase,
              'update_booking',
              supabaseError
            );
          }
        }

        // Phase 3: Update Supabase only
        if (phase === 'supabase-only') {
          const supabaseUpdates: Record<string, unknown> = {};
          if (updates.status) supabaseUpdates.status = updates.status;
          if (updates.processedBy) supabaseUpdates.processed_by = updates.processedBy;
          if (updates.processedAt) supabaseUpdates.processed_at = updates.processedAt;
          if (updates.description) supabaseUpdates.description = updates.description;

          const { error: supabaseError } = await supabase
            .from('bookings')
            .update(supabaseUpdates)
            .eq('id', id)
            .eq('user_id', userId);

          if (supabaseError) {
            throw new MigrationError(
              'Failed to update in Supabase',
              phase,
              'update_booking',
              supabaseError
            );
          }
        }

        // Refetch to update local state
        await fetchBookings();
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : 'Unknown error';
        setError(new Error(`Failed to update booking: ${errorMessage}`));
        throw err;
      }
    },
    [userId, phase, fetchBookings]
  );

  /**
   * Delete a booking
   */
  const deleteBooking = useCallback(
    async (id: string): Promise<void> => {
      if (!userId) {
        throw new Error('User ID is required to delete booking');
      }

      setError(null);

      try {
        // Phase 1: Delete from localStorage only
        if (phase === 'fallback') {
          ['pendingBookings', 'processedBookings'].forEach((key) => {
            const existing = getStoredBookings(key as 'pendingBookings' | 'processedBookings');
            const filtered = existing.filter((b) => b.id !== id);
            if (existing.length !== filtered.length) {
              setStoredBookings(key as 'pendingBookings' | 'processedBookings', filtered);
            }
          });
        }

        // Phase 2: Delete from both
        if (phase === 'dual-write') {
          // Delete from localStorage
          ['pendingBookings', 'processedBookings'].forEach((key) => {
            const existing = getStoredBookings(key as 'pendingBookings' | 'processedBookings');
            const filtered = existing.filter((b) => b.id !== id);
            if (existing.length !== filtered.length) {
              setStoredBookings(key as 'pendingBookings' | 'processedBookings', filtered);
            }
          });

          // Delete from Supabase
          const { error: supabaseError } = await supabase
            .from('bookings')
            .delete()
            .eq('id', id)
            .eq('user_id', userId);

          if (supabaseError) {
            throw new MigrationError(
              'Failed to delete from Supabase',
              phase,
              'delete_booking',
              supabaseError
            );
          }
        }

        // Phase 3: Delete from Supabase only
        if (phase === 'supabase-only') {
          const { error: supabaseError } = await supabase
            .from('bookings')
            .delete()
            .eq('id', id)
            .eq('user_id', userId);

          if (supabaseError) {
            throw new MigrationError(
              'Failed to delete from Supabase',
              phase,
              'delete_booking',
              supabaseError
            );
          }
        }

        // Refetch to update local state
        await fetchBookings();
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : 'Unknown error';
        setError(new Error(`Failed to delete booking: ${errorMessage}`));
        throw err;
      }
    },
    [userId, phase, fetchBookings]
  );

  /**
   * Sync localStorage with Supabase (useful during migration)
   */
  const syncWithLocalStorage = useCallback(async (): Promise<void> => {
    if (!userId || phase === 'supabase-only') {
      return;
    }

    setError(null);

    try {
      const pending = getStoredBookings('pendingBookings');
      const processed = getStoredBookings('processedBookings');
      const allLocal = [...pending, ...processed];

      for (const booking of allLocal) {
        const supabaseData = mapStoredBookingToSupabase(booking, userId);
        await supabase.from('bookings').upsert(supabaseData);
      }

      await fetchBookings();
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Unknown error';
      setError(new Error(`Failed to sync with localStorage: ${errorMessage}`));
    }
  }, [userId, phase, fetchBookings]);

  /**
   * Auto-fetch on mount if enabled
   */
  useEffect(() => {
    if (autoFetch && userId) {
      fetchBookings();
    }
  }, [autoFetch, userId, fetchBookings]);

  return {
    bookings,
    isLoading,
    error,
    addBooking,
    updateBooking,
    deleteBooking,
    syncWithLocalStorage,
    refetch: fetchBookings,
  };
};

/**
 * Export type for external use
 */
export type { UseBookingsReturn };

/**
 * useDraftBooking Hook
 *
 * Manages draft booking state with auto-save functionality and
 * storage migration support. Useful for multi-step booking forms
 * where users might leave and come back.
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { supabase } from '@/lib/clients/supabase';
import type { IStoredBooking } from '@/utils/localStorageTypes';
import {
  getMigrationPhase,
  type MigrationPhase,
  MigrationError,
} from '@/utils/storageMigration';

/**
 * Draft booking with metadata
 */
interface DraftBookingData {
  readonly draft: Partial<IStoredBooking>;
  readonly sessionId: string;
  readonly lastSaved: string;
  readonly expiresAt: string;
}

/**
 * Return type for useDraftBooking hook
 */
interface UseDraftBookingReturn {
  readonly draft: Partial<IStoredBooking> | null;
  readonly isLoading: boolean;
  readonly isSaving: boolean;
  readonly error: Error | null;
  readonly hasDraft: boolean;
  readonly lastSaved: Date | null;
  readonly saveDraft: (data: Partial<IStoredBooking>) => Promise<void>;
  readonly clearDraft: () => Promise<void>;
  readonly refetch: () => Promise<void>;
}

/**
 * Default draft expiration (7 days)
 */
const DRAFT_EXPIRATION_DAYS = 7;

/**
 * Auto-save debounce delay (3 seconds)
 */
const AUTO_SAVE_DELAY_MS = 3000;

/**
 * Get draft key for localStorage
 */
const getDraftKey = (userId: string, bookingId?: string): string => {
  return bookingId
    ? `draft_booking_${userId}_${bookingId}`
    : `draft_booking_${userId}`;
};

/**
 * Load draft from localStorage
 */
const loadFromLocalStorage = (
  userId: string,
  bookingId?: string
): DraftBookingData | null => {
  try {
    const key = getDraftKey(userId, bookingId);
    const stored = localStorage.getItem(key);
    if (!stored) return null;

    const parsed = JSON.parse(stored) as DraftBookingData;

    // Check if draft has expired
    const expiresAt = new Date(parsed.expiresAt);
    if (expiresAt < new Date()) {
      localStorage.removeItem(key);
      return null;
    }

    return parsed;
  } catch (error) {
    console.error('Failed to load draft from localStorage:', error);
    return null;
  }
};

/**
 * Save draft to localStorage
 */
const saveToLocalStorage = (
  userId: string,
  draft: Partial<IStoredBooking>,
  sessionId: string,
  bookingId?: string
): void => {
  try {
    const key = getDraftKey(userId, bookingId);
    const expiresAt = new Date();
    expiresAt.setDate(expiresAt.getDate() + DRAFT_EXPIRATION_DAYS);

    const data: DraftBookingData = {
      draft,
      sessionId,
      lastSaved: new Date().toISOString(),
      expiresAt: expiresAt.toISOString(),
    };

    localStorage.setItem(key, JSON.stringify(data));
  } catch (error) {
    console.error('Failed to save draft to localStorage:', error);
  }
};

/**
 * Clear draft from localStorage
 */
const clearFromLocalStorage = (userId: string, bookingId?: string): void => {
  try {
    const key = getDraftKey(userId, bookingId);
    localStorage.removeItem(key);
  } catch (error) {
    console.error('Failed to clear draft from localStorage:', error);
  }
};

/**
 * Hook to manage draft bookings with auto-save
 *
 * @param userId - The current user ID
 * @param bookingId - Optional booking ID for editing existing bookings
 * @param autoSave - Whether to enable auto-save (default: true)
 * @param autoSaveDelay - Auto-save debounce delay in ms (default: 3000)
 *
 * @example
 * ```typescript
 * const {
 *   draft,
 *   hasDraft,
 *   saveDraft,
 *   clearDraft
 * } = useDraftBooking(userId, undefined, true);
 *
 * // Save draft manually
 * const handleSave = async (formData: Partial<IStoredBooking>) => {
 *   await saveDraft(formData);
 * };
 *
 * // Clear draft on submission
 * const handleSubmit = async () => {
 *   // ... submit booking
 *   await clearDraft();
 * };
 *
 * // Auto-save is handled automatically
 * ```
 */
export const useDraftBooking = (
  userId: string | null,
  bookingId?: string,
  autoSave: boolean = true,
  autoSaveDelay: number = AUTO_SAVE_DELAY_MS
): UseDraftBookingReturn => {
  const [draft, setDraft] = useState<Partial<IStoredBooking> | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isSaving, setIsSaving] = useState<boolean>(false);
  const [error, setError] = useState<Error | null>(null);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);
  const [sessionId] = useState<string>(() => `session_${Date.now()}_${Math.random()}`);
  const phase = getMigrationPhase();

  // Auto-save timer ref
  const autoSaveTimerRef = useRef<NodeJS.Timeout | null>(null);
  const pendingDraftRef = useRef<Partial<IStoredBooking> | null>(null);

  /**
   * Fetch draft based on current migration phase
   */
  const fetchDraft = useCallback(async (): Promise<void> => {
    if (!userId) {
      setDraft(null);
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      let fetchedDraft: DraftBookingData | null = null;

      // Phase 1: Try Supabase first, fallback to localStorage
      if (phase === 'fallback') {
        try {
          const query = supabase
            .from('draft_bookings')
            .select('*')
            .eq('user_id', userId);

          if (bookingId) {
            query.eq('booking_id', bookingId);
          } else {
            query.is('booking_id', null);
          }

          const { data, error: supabaseError } = await query
            .order('last_saved', { ascending: false })
            .limit(1)
            .single();

          if (!supabaseError && data) {
            fetchedDraft = {
              draft: data.draft_data as Partial<IStoredBooking>,
              sessionId: data.session_id,
              lastSaved: data.last_saved,
              expiresAt: data.expires_at,
            };
          } else {
            // Fallback to localStorage
            fetchedDraft = loadFromLocalStorage(userId, bookingId);
          }
        } catch (supabaseError) {
          console.error('Supabase fetch failed, using localStorage:', supabaseError);
          fetchedDraft = loadFromLocalStorage(userId, bookingId);
        }
      }

      // Phase 2 & 3: Read from Supabase (with fallback in phase 2)
      if (phase === 'dual-write' || phase === 'supabase-only') {
        try {
          const query = supabase
            .from('draft_bookings')
            .select('*')
            .eq('user_id', userId);

          if (bookingId) {
            query.eq('booking_id', bookingId);
          } else {
            query.is('booking_id', null);
          }

          const { data, error: supabaseError } = await query
            .order('last_saved', { ascending: false })
            .limit(1)
            .single();

          if (supabaseError && supabaseError.code !== 'PGRST116') {
            // PGRST116 is "no rows returned", which is fine
            throw supabaseError;
          }

          if (data) {
            fetchedDraft = {
              draft: data.draft_data as Partial<IStoredBooking>,
              sessionId: data.session_id,
              lastSaved: data.last_saved,
              expiresAt: data.expires_at,
            };
          }
        } catch (supabaseError) {
          // Only fallback in phase 2
          if (phase === 'dual-write') {
            console.error('Supabase fetch failed, using localStorage:', supabaseError);
            fetchedDraft = loadFromLocalStorage(userId, bookingId);
          } else if (phase === 'supabase-only') {
            // In supabase-only mode, no draft is okay
            fetchedDraft = null;
          } else {
            throw supabaseError;
          }
        }
      }

      if (fetchedDraft) {
        setDraft(fetchedDraft.draft);
        setLastSaved(new Date(fetchedDraft.lastSaved));
      } else {
        setDraft(null);
        setLastSaved(null);
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Unknown error';
      setError(new Error(`Failed to fetch draft: ${errorMessage}`));
      console.error('Error fetching draft:', err);
      setDraft(null);
    } finally {
      setIsLoading(false);
    }
  }, [userId, bookingId, phase]);

  /**
   * Save draft with phase-aware storage
   */
  const saveDraft = useCallback(
    async (data: Partial<IStoredBooking>): Promise<void> => {
      if (!userId) {
        throw new Error('User ID is required to save draft');
      }

      setError(null);
      setIsSaving(true);

      try {
        const expiresAt = new Date();
        expiresAt.setDate(expiresAt.getDate() + DRAFT_EXPIRATION_DAYS);

        // Phase 1: Write to localStorage only
        if (phase === 'fallback') {
          saveToLocalStorage(userId, data, sessionId, bookingId);
          setDraft(data);
          setLastSaved(new Date());
        }

        // Phase 2: Write to both
        if (phase === 'dual-write') {
          // Write to localStorage
          saveToLocalStorage(userId, data, sessionId, bookingId);

          // Write to Supabase
          const { error: supabaseError } = await supabase
            .from('draft_bookings')
            .upsert({
              user_id: userId,
              booking_id: bookingId || null,
              session_id: sessionId,
              draft_data: data as unknown as Record<string, unknown>,
              last_saved: new Date().toISOString(),
              expires_at: expiresAt.toISOString(),
            });

          if (supabaseError) {
            throw new MigrationError(
              'Failed to save draft to Supabase',
              phase,
              'save_draft',
              supabaseError
            );
          }

          setDraft(data);
          setLastSaved(new Date());
        }

        // Phase 3: Write to Supabase only
        if (phase === 'supabase-only') {
          const { error: supabaseError } = await supabase
            .from('draft_bookings')
            .upsert({
              user_id: userId,
              booking_id: bookingId || null,
              session_id: sessionId,
              draft_data: data as unknown as Record<string, unknown>,
              last_saved: new Date().toISOString(),
              expires_at: expiresAt.toISOString(),
            });

          if (supabaseError) {
            throw new MigrationError(
              'Failed to save draft to Supabase',
              phase,
              'save_draft',
              supabaseError
            );
          }

          setDraft(data);
          setLastSaved(new Date());
        }
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : 'Unknown error';
        setError(new Error(`Failed to save draft: ${errorMessage}`));
        throw err;
      } finally {
        setIsSaving(false);
      }
    },
    [userId, bookingId, sessionId, phase]
  );

  /**
   * Clear draft
   */
  const clearDraft = useCallback(async (): Promise<void> => {
    if (!userId) {
      throw new Error('User ID is required to clear draft');
    }

    setError(null);

    try {
      // Phase 1: Clear from localStorage only
      if (phase === 'fallback') {
        clearFromLocalStorage(userId, bookingId);
        setDraft(null);
        setLastSaved(null);
      }

      // Phase 2: Clear from both
      if (phase === 'dual-write') {
        // Clear from localStorage
        clearFromLocalStorage(userId, bookingId);

        // Clear from Supabase
        const query = supabase
          .from('draft_bookings')
          .delete()
          .eq('user_id', userId);

        if (bookingId) {
          query.eq('booking_id', bookingId);
        } else {
          query.is('booking_id', null);
        }

        const { error: supabaseError } = await query;

        if (supabaseError) {
          throw new MigrationError(
            'Failed to clear draft from Supabase',
            phase,
            'clear_draft',
            supabaseError
          );
        }

        setDraft(null);
        setLastSaved(null);
      }

      // Phase 3: Clear from Supabase only
      if (phase === 'supabase-only') {
        const query = supabase
          .from('draft_bookings')
          .delete()
          .eq('user_id', userId);

        if (bookingId) {
          query.eq('booking_id', bookingId);
        } else {
          query.is('booking_id', null);
        }

        const { error: supabaseError } = await query;

        if (supabaseError) {
          throw new MigrationError(
            'Failed to clear draft from Supabase',
            phase,
            'clear_draft',
            supabaseError
          );
        }

        setDraft(null);
        setLastSaved(null);
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Unknown error';
      setError(new Error(`Failed to clear draft: ${errorMessage}`));
      throw err;
    }
  }, [userId, bookingId, phase]);

  /**
   * Auto-save handler with debounce
   */
  useEffect(() => {
    if (!autoSave || !pendingDraftRef.current) {
      return;
    }

    // Clear existing timer
    if (autoSaveTimerRef.current) {
      clearTimeout(autoSaveTimerRef.current);
    }

    // Set new timer
    autoSaveTimerRef.current = setTimeout(() => {
      if (pendingDraftRef.current) {
        saveDraft(pendingDraftRef.current);
        pendingDraftRef.current = null;
      }
    }, autoSaveDelay);

    // Cleanup
    return () => {
      if (autoSaveTimerRef.current) {
        clearTimeout(autoSaveTimerRef.current);
      }
    };
  }, [draft, autoSave, autoSaveDelay, saveDraft]);

  /**
   * Update pending draft for auto-save
   */
  useEffect(() => {
    if (draft && autoSave) {
      pendingDraftRef.current = draft;
    }
  }, [draft, autoSave]);

  /**
   * Fetch draft on mount
   */
  useEffect(() => {
    if (userId) {
      fetchDraft();
    }
  }, [userId, bookingId, fetchDraft]);

  /**
   * Cleanup on unmount
   */
  useEffect(() => {
    return () => {
      if (autoSaveTimerRef.current) {
        clearTimeout(autoSaveTimerRef.current);
      }
    };
  }, []);

  return {
    draft,
    isLoading,
    isSaving,
    error,
    hasDraft: draft !== null,
    lastSaved,
    saveDraft,
    clearDraft,
    refetch: fetchDraft,
  };
};

/**
 * Export type for external use
 */
export type { UseDraftBookingReturn };

import { useState, useCallback } from 'react';
import { useTranslation } from 'react-i18next';

/**
 * Validation rule types
 */
export interface ValidationRule {
  readonly type: 'required' | 'email' | 'phone' | 'minLength' | 'maxLength' | 'minValue' | 'maxValue' | 'pattern' | 'custom';
  readonly value?: number | string | RegExp;
  readonly message?: string;
  readonly validate?: (value: unknown) => boolean;
}

export interface ValidationRules {
  readonly [key: string]: readonly ValidationRule[];
}

export interface ValidationErrors {
  readonly [key: string]: string;
}

/**
 * Form validation hook
 *
 * Provides reusable validation logic with i18n support
 * Following Single Responsibility Principle - only handles validation
 *
 * @param rules - Validation rules for form fields
 * @returns Validation state and methods
 */
export const useFormValidation = (rules: ValidationRules) => {
  const { t } = useTranslation('validation');
  const [errors, setErrors] = useState<ValidationErrors>({});

  /**
   * Validate a single field
   */
  const validateField = useCallback((name: string, value: unknown): string | null => {
    const fieldRules = rules[name];
    if (!fieldRules) return null;

    for (const rule of fieldRules) {
      switch (rule.type) {
        case 'required':
          if (!value || (typeof value === 'string' && !value.trim())) {
            return rule.message || t('required');
          }
          break;

        case 'email':
          if (value && typeof value === 'string') {
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!emailRegex.test(value)) {
              return rule.message || t('invalid_email');
            }
          }
          break;

        case 'phone':
          if (value && typeof value === 'string') {
            const phoneRegex = /^[+]?[(]?[0-9]{3}[)]?[-\s.]?[0-9]{3}[-\s.]?[0-9]{4,6}$/;
            if (!phoneRegex.test(value)) {
              return rule.message || t('invalid_phone');
            }
          }
          break;

        case 'minLength':
          if (value && typeof value === 'string' && rule.value) {
            if (value.length < Number(rule.value)) {
              return rule.message || t('min_length', { count: rule.value });
            }
          }
          break;

        case 'maxLength':
          if (value && typeof value === 'string' && rule.value) {
            if (value.length > Number(rule.value)) {
              return rule.message || t('max_length', { count: rule.value });
            }
          }
          break;

        case 'minValue':
          if (value !== null && value !== undefined && rule.value) {
            if (Number(value) < Number(rule.value)) {
              return rule.message || t('min_value', { value: rule.value });
            }
          }
          break;

        case 'maxValue':
          if (value !== null && value !== undefined && rule.value) {
            if (Number(value) > Number(rule.value)) {
              return rule.message || t('max_value', { value: rule.value });
            }
          }
          break;

        case 'pattern':
          if (value && typeof value === 'string' && rule.value instanceof RegExp) {
            if (!rule.value.test(value)) {
              return rule.message || t('invalid_format');
            }
          }
          break;

        case 'custom':
          if (rule.validate && !rule.validate(value)) {
            return rule.message || t('validation_failed');
          }
          break;
      }
    }

    return null;
  }, [rules, t]);

  /**
   * Validate all fields
   */
  const validateAll = useCallback((data: Record<string, unknown>): boolean => {
    const newErrors: ValidationErrors = {};
    let isValid = true;

    Object.keys(rules).forEach(fieldName => {
      const error = validateField(fieldName, data[fieldName]);
      if (error) {
        newErrors[fieldName] = error;
        isValid = false;
      }
    });

    setErrors(newErrors);
    return isValid;
  }, [rules, validateField]);

  /**
   * Clear errors for a specific field
   */
  const clearError = useCallback((name: string): void => {
    setErrors(prev => {
      const { [name]: _, ...rest } = prev;
      return rest;
    });
  }, []);

  /**
   * Clear all errors
   */
  const clearAllErrors = useCallback((): void => {
    setErrors({});
  }, []);

  /**
   * Set error for a field manually
   */
  const setError = useCallback((name: string, message: string): void => {
    setErrors(prev => ({ ...prev, [name]: message }));
  }, []);

  return {
    errors,
    validateField,
    validateAll,
    clearError,
    clearAllErrors,
    setError,
  };
};

