              </div>

              {/* Date Range Presets */}
              {showFilters && (
                <div className="space-y-4">
                  <div>
                    <p className="text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                      Quick Date Ranges:
                    </p>
                    <div className="flex flex-wrap gap-2">
                      {dateRangePresets.map((preset) => (
                        <Button
                          key={preset.label}
                          variant="outline"
                          size="sm"
                          onClick={preset.onClick}
                          className="h-10"
                        >
                          {preset.label}
                        </Button>
                      ))}
                    </div>
                  </div>

                  {/* Action Filters */}
                  {uniqueActions.length > 0 && (
                    <div>
                      <p className="text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                        Actions:
                      </p>
                      <div className="flex flex-wrap gap-2">
                        {uniqueActions.slice(0, 10).map((action) => (
                          <Button
                            key={action}
                            variant={filters.actions.includes(action) ? "default" : "outline"}
                            size="sm"
                            onClick={() => toggleActionFilter(action)}
                            className="h-10"
                          >
                            {action.replace(/_/g, ' ')}
                          </Button>
                        ))}
                      </div>
                    </div>
                  )}

                  {/* Entity Filters */}
                  {uniqueEntities.length > 0 && (
                    <div>
                      <p className="text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                        Entities:
                      </p>
                      <div className="flex flex-wrap gap-2">
                        {uniqueEntities.map((entity) => (
                          <Button
                            key={entity}
                            variant={filters.entities.includes(entity) ? "default" : "outline"}
                            size="sm"
                            onClick={() => toggleEntityFilter(entity)}
                            className="h-10"
                          >
                            {entity}
                          </Button>
                        ))}
                      </div>
                    </div>
                  )}

                  {/* Severity Filters */}
                  <div>
                    <p className="text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                      Severity:
                    </p>
                    <div className="flex flex-wrap gap-2">
                      {['info', 'warning', 'critical'].map((severity) => (
                        <Button
                          key={severity}
                          variant={filters.severityFilter.includes(severity) ? "default" : "outline"}
                          size="sm"
                          onClick={() => toggleSeverityFilter(severity)}
                          className="h-10"
                        >
                          {severity.charAt(0).toUpperCase() + severity.slice(1)}
                        </Button>
                      ))}
                    </div>
                  </div>
                </div>
              )}
            </div>
          </CardContent>
        </Card>

        {/* View Selector and Results */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center justify-between">
              <span className="flex items-center gap-2">
                <FileText className="h-5 w-5" />
                Audit Trail ({totalItems.toLocaleString('nb-NO')} events)
              </span>
              <div className="flex items-center gap-2">
                {viewModes.map((mode) => {
                  const Icon = mode.icon;
                  return (
                    <Button
                      key={mode.value}
                      variant={view === mode.value ? "default" : "outline"}
                      size="sm"
                      onClick={() => setView(mode.value)}
                      aria-label={`Switch to ${mode.label} view`}
                    >
                      <Icon className="h-4 w-4" />
                    </Button>
                  );
                })}
              </div>
            </CardTitle>
          </CardHeader>
          <CardContent>
            {view === 'timeline' && renderTimelineView()}
            {view === 'list' && renderListView()}
            {view === 'table' && renderTableView()}

            {/* Pagination */}
            {view !== 'timeline' && totalPages > 1 && (
              <div className="flex items-center justify-between mt-6 pt-6 border-t border-gray-200 dark:border-gray-700">
                <div className="flex items-center gap-2">
                  <span className="text-sm text-gray-600 dark:text-gray-400">
                    Showing {((currentPage - 1) * itemsPerPage) + 1} to {Math.min(currentPage * itemsPerPage, totalItems)} of {totalItems}
                  </span>
                </div>
                <div className="flex items-center gap-2">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={goToFirstPage}
                    disabled={!hasPreviousPage}
                  >
                    First
                  </Button>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={previousPage}
                    disabled={!hasPreviousPage}
                  >
                    <ChevronLeft className="h-4 w-4" />
                  </Button>
                  <span className="text-sm font-medium text-gray-900 dark:text-white px-2">
                    Page {currentPage} of {totalPages}
                  </span>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={nextPage}
                    disabled={!hasNextPage}
                  >
                    <ChevronRight className="h-4 w-4" />
                  </Button>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={goToLastPage}
                    disabled={!hasNextPage}
                  >
                    Last
                  </Button>
                </div>
              </div>
            )}
          </CardContent>
        </Card>
      </SystemPageLayout>
    </RequireRole>
  );
};

