/**
 * Audit Business Logic Service
 *
 * Contains all business logic related to audit log operations.
 * NO UI logic, NO component dependencies.
 * Pure business rules and data transformations for security audit trails.
 */

import type { Database } from "@/types/database";

type AuditEvent = Database['public']['Tables']['audit_events']['Row'];
type Json = Database['public']['Json'];

/**
 * Audit filter configuration
 */
export interface IAuditFilters {
  readonly searchTerm?: string;
  readonly userIds?: readonly string[];
  readonly actions?: readonly string[];
  readonly entities?: readonly string[];
  readonly dateRange?: {
    readonly startDate: Date;
    readonly endDate: Date;
  };
}

/**
 * Audit sort configuration
 */
export interface IAuditSortConfig {
  readonly sortBy: 'created_at' | 'action' | 'entity' | 'actor_id';
  readonly sortOrder: 'asc' | 'desc';
}

/**
 * Formatted audit entry for display
 */
export interface IFormattedAuditEntry {
  readonly id: string;
  readonly timestamp: Date;
  readonly formattedTimestamp: string;
  readonly relativeTime: string;
  readonly action: string;
  readonly actionLabel: string;
  readonly actionIcon: string;
  readonly actionColor: string;
  readonly entity: string;
  readonly entityLabel: string;
  readonly entityId: string;
  readonly actorId: string | null;
  readonly actorName: string;
  readonly details: Record<string, unknown> | null;
  readonly formattedDetails: string;
  readonly severity: 'info' | 'warning' | 'critical';
}

/**
 * Grouped audit entries by date
 */
export interface IGroupedAuditEntries {
  readonly date: string;
  readonly formattedDate: string;
  readonly entries: readonly IFormattedAuditEntry[];
  readonly count: number;
}

/**
 * Audit statistics
 */
export interface IAuditStats {
  readonly totalEvents: number;
  readonly uniqueUsers: number;
  readonly actionBreakdown: Record<string, number>;
  readonly entityBreakdown: Record<string, number>;
  readonly eventsToday: number;
  readonly eventsThisWeek: number;
  readonly eventsThisMonth: number;
  readonly criticalEvents: number;
  readonly mostActiveUser: string | null;
  readonly mostCommonAction: string | null;
}

/**
 * CSV export data for audit logs
 */
export interface IAuditExportData {
  readonly headers: readonly string[];
  readonly rows: readonly (readonly string[])[];
  readonly filename: string;
}

/**
 * Filter audit logs based on criteria
 *
 * @param auditLogs - Array of audit events to filter
 * @param filters - Filter configuration
 * @returns Filtered audit logs
 */
export const filterAuditLogs = (
  auditLogs: readonly AuditEvent[],
  filters: IAuditFilters
): readonly AuditEvent[] => {
  let filtered = [...auditLogs];

  // Search term filter (searches in action, entity, and details)
  if (filters.searchTerm && filters.searchTerm.trim() !== '') {
    const searchLower = filters.searchTerm.toLowerCase().trim();
    filtered = filtered.filter((log) => {
      const matchesAction = log.action.toLowerCase().includes(searchLower);
      const matchesEntity = log.entity.toLowerCase().includes(searchLower);
      const matchesEntityId = log.entity_id.toLowerCase().includes(searchLower);
      const matchesDetails = log.details
        ? JSON.stringify(log.details).toLowerCase().includes(searchLower)
        : false;

      return matchesAction || matchesEntity || matchesEntityId || matchesDetails;
    });
  }

  // User filter
  if (filters.userIds && filters.userIds.length > 0) {
    filtered = filtered.filter((log) =>
      log.actor_id && filters.userIds?.includes(log.actor_id)
    );
  }

  // Action filter
  if (filters.actions && filters.actions.length > 0) {
    filtered = filtered.filter((log) =>
      filters.actions?.includes(log.action)
    );
  }

  // Entity filter
  if (filters.entities && filters.entities.length > 0) {
    filtered = filtered.filter((log) =>
      filters.entities?.includes(log.entity)
    );
  }

  // Date range filter
  if (filters.dateRange) {
    const { startDate, endDate } = filters.dateRange;
    filtered = filtered.filter((log) => {
      const logDate = new Date(log.created_at);
      return logDate >= startDate && logDate <= endDate;
    });
  }

  return filtered;
};

/**
 * Sort audit logs based on configuration
 *
 * @param auditLogs - Array of audit events to sort
 * @param sortConfig - Sort configuration
 * @returns Sorted audit logs
 */
export const sortAuditLogs = (
  auditLogs: readonly AuditEvent[],
  sortConfig: IAuditSortConfig
): readonly AuditEvent[] => {
  const sorted = [...auditLogs];

  sorted.sort((a, b) => {
    let comparison = 0;

    switch (sortConfig.sortBy) {
      case 'created_at':
        comparison = new Date(a.created_at).getTime() - new Date(b.created_at).getTime();
        break;
      case 'action':
        comparison = a.action.localeCompare(b.action);
        break;
      case 'entity':
        comparison = a.entity.localeCompare(b.entity);
        break;
      case 'actor_id':
        comparison = (a.actor_id || '').localeCompare(b.actor_id || '');
        break;
      default:
        comparison = 0;
    }

    return sortConfig.sortOrder === 'asc' ? comparison : -comparison;
  });

  return sorted;
};

/**
 * Format audit entry for display with rich metadata
 *
 * @param auditLog - Raw audit event from database
 * @returns Formatted audit entry with display-ready fields
 */
export const formatAuditEntry = (auditLog: AuditEvent): IFormattedAuditEntry => {
  const timestamp = new Date(auditLog.created_at);
  const actionMeta = getActionMetadata(auditLog.action);
  const entityMeta = getEntityMetadata(auditLog.entity);
  const severity = calculateSeverity(auditLog.action, auditLog.entity);

  return {
    id: auditLog.id,
    timestamp,
    formattedTimestamp: formatTimestamp(timestamp),
    relativeTime: formatRelativeTime(timestamp),
    action: auditLog.action,
    actionLabel: actionMeta.label,
    actionIcon: actionMeta.icon,
    actionColor: actionMeta.color,
    entity: auditLog.entity,
    entityLabel: entityMeta.label,
    entityId: auditLog.entity_id,
    actorId: auditLog.actor_id,
    actorName: auditLog.actor_id ? `User ${auditLog.actor_id.slice(0, 8)}` : 'System',
    details: auditLog.details as Record<string, unknown> | null,
    formattedDetails: formatDetails(auditLog.details),
    severity,
  };
};

/**
 * Group audit entries by date
 *
 * @param auditLogs - Array of formatted audit entries
 * @returns Grouped audit entries by date
 */
export const groupAuditLogsByDate = (
  auditLogs: readonly IFormattedAuditEntry[]
): readonly IGroupedAuditEntries[] => {
  const groups = new Map<string, IFormattedAuditEntry[]>();

  auditLogs.forEach((log) => {
    const dateKey = log.timestamp.toISOString().split('T')[0]; // YYYY-MM-DD
    const existing = groups.get(dateKey) || [];
    groups.set(dateKey, [...existing, log]);
  });

  const result: IGroupedAuditEntries[] = [];
  groups.forEach((entries, date) => {
    result.push({
      date,
      formattedDate: formatDateGrouping(new Date(date)),
      entries,
      count: entries.length,
    });
  });

  // Sort by date descending (newest first)
  result.sort((a, b) => b.date.localeCompare(a.date));

  return result;
};

/**
 * Get unique action types from audit logs
 *
 * @param auditLogs - Array of audit events
 * @returns Array of unique action types
 */
export const getUniqueActions = (
  auditLogs: readonly AuditEvent[]
): readonly string[] => {
  const actions = new Set<string>();
  auditLogs.forEach((log) => actions.add(log.action));
  return Array.from(actions).sort();
};

/**
 * Get unique entity types from audit logs
 *
 * @param auditLogs - Array of audit events
 * @returns Array of unique entity types
 */
export const getUniqueEntities = (
  auditLogs: readonly AuditEvent[]
): readonly string[] => {
  const entities = new Set<string>();
  auditLogs.forEach((log) => entities.add(log.entity));
  return Array.from(entities).sort();
};

/**
 * Get unique user IDs from audit logs
 *
 * @param auditLogs - Array of audit events
 * @returns Array of unique user IDs
 */
export const getUniqueUsers = (
  auditLogs: readonly AuditEvent[]
): readonly string[] => {
  const users = new Set<string>();
  auditLogs.forEach((log) => {
    if (log.actor_id) {
      users.add(log.actor_id);
    }
  });
  return Array.from(users).sort();
};

/**
 * Calculate audit statistics
 *
 * @param auditLogs - Array of audit events
 * @returns Comprehensive audit statistics
 */
export const calculateAuditStats = (
  auditLogs: readonly AuditEvent[]
): IAuditStats => {
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const weekAgo = new Date(today.getTime() - 7 * 24 * 60 * 60 * 1000);
  const monthAgo = new Date(today.getFullYear(), today.getMonth() - 1, today.getDate());

  // Action breakdown
  const actionBreakdown: Record<string, number> = {};
  auditLogs.forEach((log) => {
    actionBreakdown[log.action] = (actionBreakdown[log.action] || 0) + 1;
  });

  // Entity breakdown
  const entityBreakdown: Record<string, number> = {};
  auditLogs.forEach((log) => {
    entityBreakdown[log.entity] = (entityBreakdown[log.entity] || 0) + 1;
  });

  // User activity
  const userActivity: Record<string, number> = {};
  auditLogs.forEach((log) => {
    if (log.actor_id) {
      userActivity[log.actor_id] = (userActivity[log.actor_id] || 0) + 1;
    }
  });

  const mostActiveUser = Object.entries(userActivity).sort((a, b) => b[1] - a[1])[0]?.[0] || null;
  const mostCommonAction = Object.entries(actionBreakdown).sort((a, b) => b[1] - a[1])[0]?.[0] || null;

  // Time-based counts
  const eventsToday = auditLogs.filter((log) =>
    new Date(log.created_at) >= today
  ).length;

  const eventsThisWeek = auditLogs.filter((log) =>
    new Date(log.created_at) >= weekAgo
  ).length;

  const eventsThisMonth = auditLogs.filter((log) =>
    new Date(log.created_at) >= monthAgo
  ).length;

  // Critical events (deletion, security-related actions)
  const criticalActions = ['delete', 'revoke', 'suspend', 'ban', 'security_alert'];
  const criticalEvents = auditLogs.filter((log) =>
    criticalActions.some((action) => log.action.toLowerCase().includes(action))
  ).length;

  return {
    totalEvents: auditLogs.length,
    uniqueUsers: getUniqueUsers(auditLogs).length,
    actionBreakdown,
    entityBreakdown,
    eventsToday,
    eventsThisWeek,
    eventsThisMonth,
    criticalEvents,
    mostActiveUser,
    mostCommonAction,
  };
};

/**
 * Export audit logs to CSV format
 *
 * @param auditLogs - Array of formatted audit entries
 * @returns CSV export data structure
 */
export const exportAuditLogsToCSV = (
  auditLogs: readonly IFormattedAuditEntry[]
): IAuditExportData => {
  const headers = [
    'Timestamp',
    'Action',
    'Entity',
    'Entity ID',
    'Actor',
    'Severity',
    'Details',
  ];

  const rows = auditLogs.map((log) => [
    log.formattedTimestamp,
    log.actionLabel,
    log.entityLabel,
    log.entityId,
    log.actorName,
    log.severity,
    log.formattedDetails,
  ]);

  return {
    headers,
    rows,
    filename: `audit-logs-${formatDateForFilename(new Date())}`,
  };
};

/**
 * Generate CSV content from export data
 *
 * @param exportData - CSV export data structure
 * @returns CSV content as string
 */
export const generateAuditCSVContent = (exportData: IAuditExportData): string => {
  const csvLines: string[] = [];

  // Add headers
  csvLines.push(exportData.headers.map((h) => `"${h}"`).join(','));

  // Add rows
  exportData.rows.forEach((row) => {
    csvLines.push(row.map((cell) => `"${String(cell).replace(/"/g, '""')}"`).join(','));
  });

  return csvLines.join('\n');
};

/**
 * Get action metadata (label, icon, color)
 *
 * @param action - Action string from audit log
 * @returns Action metadata for display
 */
const getActionMetadata = (
  action: string
): { label: string; icon: string; color: string } => {
  const actionLower = action.toLowerCase();

  // Create
  if (actionLower.includes('create') || actionLower.includes('add')) {
    return {
      label: formatActionLabel(action),
      icon: 'Plus',
      color: 'text-green-600 dark:text-green-400',
    };
  }

  // Update
  if (actionLower.includes('update') || actionLower.includes('edit') || actionLower.includes('modify')) {
    return {
      label: formatActionLabel(action),
      icon: 'Edit',
      color: 'text-blue-600 dark:text-blue-400',
    };
  }

  // Delete
  if (actionLower.includes('delete') || actionLower.includes('remove')) {
    return {
      label: formatActionLabel(action),
      icon: 'Trash',
      color: 'text-red-600 dark:text-red-400',
    };
  }

  // Login/Logout
  if (actionLower.includes('login') || actionLower.includes('signin')) {
    return {
      label: formatActionLabel(action),
      icon: 'LogIn',
      color: 'text-green-600 dark:text-green-400',
    };
  }

  if (actionLower.includes('logout') || actionLower.includes('signout')) {
    return {
      label: formatActionLabel(action),
      icon: 'LogOut',
      color: 'text-gray-600 dark:text-gray-400',
    };
  }

  // Security
  if (actionLower.includes('revoke') || actionLower.includes('suspend') || actionLower.includes('ban')) {
    return {
      label: formatActionLabel(action),
      icon: 'Shield',
      color: 'text-orange-600 dark:text-orange-400',
    };
  }

  // Default
  return {
    label: formatActionLabel(action),
    icon: 'Activity',
    color: 'text-gray-600 dark:text-gray-400',
  };
};

/**
 * Get entity metadata (label)
 *
 * @param entity - Entity string from audit log
 * @returns Entity metadata for display
 */
const getEntityMetadata = (entity: string): { label: string } => {
  const entityMap: Record<string, string> = {
    'booking': 'Booking',
    'bookings': 'Booking',
    'facility': 'Facility',
    'facilities': 'Facility',
    'user': 'User',
    'users': 'User',
    'organization': 'Organization',
    'organizations': 'Organization',
    'role': 'Role',
    'roles': 'Role',
    'permission': 'Permission',
    'permissions': 'Permission',
    'service': 'Service',
    'services': 'Service',
    'zone': 'Zone',
    'zones': 'Zone',
  };

  return {
    label: entityMap[entity.toLowerCase()] || formatEntityLabel(entity),
  };
};

/**
 * Calculate severity level based on action and entity
 *
 * @param action - Action string
 * @param entity - Entity string
 * @returns Severity level
 */
const calculateSeverity = (
  action: string,
  entity: string
): 'info' | 'warning' | 'critical' => {
  const actionLower = action.toLowerCase();
  const entityLower = entity.toLowerCase();

  // Critical actions
  const criticalActions = ['delete', 'remove', 'revoke', 'suspend', 'ban'];
  if (criticalActions.some((a) => actionLower.includes(a))) {
    return 'critical';
  }

  // Warning actions
  const warningActions = ['update', 'edit', 'modify'];
  const sensitiveEntities = ['user', 'role', 'permission', 'organization'];

  if (
    warningActions.some((a) => actionLower.includes(a)) &&
    sensitiveEntities.some((e) => entityLower.includes(e))
  ) {
    return 'warning';
  }

  // Default to info
  return 'info';
};

/**
 * Format timestamp for display
 *
 * @param date - Date to format
 * @returns Formatted timestamp string
 */
const formatTimestamp = (date: Date): string => {
  return date.toLocaleString('nb-NO', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
  });
};

/**
 * Format relative time (e.g., "2 hours ago")
 *
 * @param date - Date to format
 * @returns Relative time string
 */
const formatRelativeTime = (date: Date): string => {
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffSeconds = Math.floor(diffMs / 1000);
  const diffMinutes = Math.floor(diffSeconds / 60);
  const diffHours = Math.floor(diffMinutes / 60);
  const diffDays = Math.floor(diffHours / 24);

  if (diffSeconds < 60) {
    return 'Just now';
  } else if (diffMinutes < 60) {
    return `${diffMinutes} minute${diffMinutes !== 1 ? 's' : ''} ago`;
  } else if (diffHours < 24) {
    return `${diffHours} hour${diffHours !== 1 ? 's' : ''} ago`;
  } else if (diffDays < 7) {
    return `${diffDays} day${diffDays !== 1 ? 's' : ''} ago`;
  } else {
    return formatTimestamp(date);
  }
};

/**
 * Format date for grouping (e.g., "Today", "Yesterday", "Dec 15, 2024")
 *
 * @param date - Date to format
 * @returns Formatted date string
 */
const formatDateGrouping = (date: Date): string => {
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const yesterday = new Date(today.getTime() - 24 * 60 * 60 * 1000);
  const inputDate = new Date(date.getFullYear(), date.getMonth(), date.getDate());

  if (inputDate.getTime() === today.getTime()) {
    return 'Today';
  } else if (inputDate.getTime() === yesterday.getTime()) {
    return 'Yesterday';
  } else {
    return date.toLocaleDateString('nb-NO', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    });
  }
};

/**
 * Format action label (convert snake_case to Title Case)
 *
 * @param action - Action string
 * @returns Formatted action label
 */
const formatActionLabel = (action: string): string => {
  return action
    .split('_')
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
    .join(' ');
};

/**
 * Format entity label (convert snake_case to Title Case)
 *
 * @param entity - Entity string
 * @returns Formatted entity label
 */
const formatEntityLabel = (entity: string): string => {
  return entity
    .split('_')
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
    .join(' ');
};

/**
 * Format details JSON for display
 *
 * @param details - Details JSON object
 * @returns Formatted details string
 */
const formatDetails = (details: Json | null): string => {
  if (!details) {
    return 'No additional details';
  }

  try {
    const detailsObj = details as Record<string, unknown>;
    const entries = Object.entries(detailsObj);

    if (entries.length === 0) {
      return 'No additional details';
    }

    return entries
      .map(([key, value]) => {
        const formattedKey = formatActionLabel(key);
        const formattedValue = typeof value === 'object'
          ? JSON.stringify(value)
          : String(value);
        return `${formattedKey}: ${formattedValue}`;
      })
      .join(', ');
  } catch (error) {
    return 'Unable to parse details';
  }
};

/**
 * Format date for filename (YYYY-MM-DD)
 *
 * @param date - Date to format
 * @returns Formatted date string for filename
 */
const formatDateForFilename = (date: Date): string => {
  return date.toISOString().split('T')[0];
};

/**
 * Auth Business Logic Service
 *
 * Contains all business logic related to authentication and authorization.
 * NO UI logic, NO component dependencies, NO API calls, NO localStorage access.
 * Pure business rules and data transformations.
 *
 * @module services/business/auth
 */

import type { OrgRole, PlatformRole, SystemRole } from '@/constants/roles';
import { ROLE_PRIORITY, ORG_ROLES, PLATFORM_ROLES } from '@/constants/roles';

// ============================================================================
// Types
// ============================================================================

export interface ValidationResult {
  readonly isValid: boolean;
  readonly errors: readonly string[];
  readonly errorsNo: readonly string[];
}

export interface PasswordRequirements {
  readonly minLength: number;
  readonly requireUppercase: boolean;
  readonly requireLowercase: boolean;
  readonly requireNumber: boolean;
  readonly requireSpecialChar: boolean;
}

export interface PasswordStrengthResult extends ValidationResult {
  readonly strength: 'weak' | 'medium' | 'strong';
  readonly score: number;
}

export interface RouteAccessResult {
  readonly canAccess: boolean;
  readonly reason?: string;
  readonly reasonNo?: string;
  readonly redirectTo?: string;
}

export interface SessionInfo {
  readonly expiresAt: string;
  readonly issuedAt: string;
}

export interface SanitizedInput {
  readonly email: string;
  readonly password?: string;
  readonly [key: string]: string | undefined;
}

// ============================================================================
// Constants
// ============================================================================

const EMAIL_REGEX = /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$/;

const PASSWORD_REQUIREMENTS: PasswordRequirements = {
  minLength: 8,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecialChar: false,
} as const;

const SESSION_DURATION_MS = 24 * 60 * 60 * 1000; // 24 hours

const ADMIN_ROLES: readonly SystemRole[] = [
  PLATFORM_ROLES.PLATFORM_ADMIN,
  ORG_ROLES.OWNER,
  ORG_ROLES.ADMIN,
] as const;

const USER_ROLES: readonly SystemRole[] = [
  ORG_ROLES.CASE_HANDLER,
  ORG_ROLES.EDITOR,
  ORG_ROLES.READ_ONLY,
  ORG_ROLES.CUSTOMER,
] as const;

// ============================================================================
// Email Validation
// ============================================================================

/**
 * Validate email format with comprehensive regex
 *
 * Checks for:
 * - Valid email structure
 * - Proper domain format
 * - No invalid characters
 *
 * @param email - Email address to validate
 * @returns Validation result with errors in English and Norwegian
 *
 * @example
 * ```typescript
 * const result = validateEmailFormat('user@example.com');
 * if (result.isValid) {
 *   console.log('Email is valid');
 * } else {
 *   console.log(result.errors); // English errors
 *   console.log(result.errorsNo); // Norwegian errors
 * }
 * ```
 */
export const validateEmailFormat = (email: string): ValidationResult => {
  const errors: string[] = [];
  const errorsNo: string[] = [];

  if (!email) {
    errors.push('Email is required');
    errorsNo.push('E-post er påkrevd');
    return { isValid: false, errors, errorsNo };
  }

  const trimmedEmail = email.trim();

  if (trimmedEmail.length === 0) {
    errors.push('Email cannot be empty');
    errorsNo.push('E-post kan ikke være tom');
    return { isValid: false, errors, errorsNo };
  }

  if (trimmedEmail.length > 254) {
    errors.push('Email is too long (max 254 characters)');
    errorsNo.push('E-post er for lang (maks 254 tegn)');
    return { isValid: false, errors, errorsNo };
  }

  if (!EMAIL_REGEX.test(trimmedEmail)) {
    errors.push('Please provide a valid email address');
    errorsNo.push('Vennligst oppgi en gyldig e-postadresse');
    return { isValid: false, errors, errorsNo };
  }

  // Check for common typos
  const commonTypos = ['.con', '.cmo', '.col', '@gmial', '@yahooo'];
  const hasTypo = commonTypos.some(typo => trimmedEmail.toLowerCase().includes(typo));
  if (hasTypo) {
    errors.push('Email address contains a common typo');
    errorsNo.push('E-postadressen inneholder en vanlig skrivefeil');
    return { isValid: false, errors, errorsNo };
  }

  return { isValid: true, errors: [], errorsNo: [] };
};

// ============================================================================
// Password Validation
// ============================================================================

/**
 * Check password requirements and strength
 *
 * Validates:
 * - Minimum length (8 characters)
 * - Contains uppercase letter
 * - Contains lowercase letter
 * - Contains number
 * - Calculates strength score
 *
 * @param password - Password to validate
 * @returns Password strength result with errors and score
 *
 * @example
 * ```typescript
 * const result = validatePasswordStrength('MyPass123!');
 * console.log(result.strength); // 'strong'
 * console.log(result.score); // 4
 * console.log(result.isValid); // true
 * ```
 */
export const validatePasswordStrength = (password: string): PasswordStrengthResult => {
  const errors: string[] = [];
  const errorsNo: string[] = [];
  let score = 0;

  if (!password) {
    errors.push('Password is required');
    errorsNo.push('Passord er påkrevd');
    return {
      isValid: false,
      errors,
      errorsNo,
      strength: 'weak',
      score: 0,
    };
  }

  // Check minimum length
  if (password.length < PASSWORD_REQUIREMENTS.minLength) {
    errors.push(`Password must be at least ${PASSWORD_REQUIREMENTS.minLength} characters long`);
    errorsNo.push(`Passord må være minst ${PASSWORD_REQUIREMENTS.minLength} tegn langt`);
  } else {
    score++;
    if (password.length >= 12) score++; // Extra point for longer passwords
  }

  // Check for uppercase letter
  const hasUpperCase = /[A-Z]/.test(password);
  if (PASSWORD_REQUIREMENTS.requireUppercase && !hasUpperCase) {
    errors.push('Password must contain at least one uppercase letter');
    errorsNo.push('Passord må inneholde minst én stor bokstav');
  } else if (hasUpperCase) {
    score++;
  }

  // Check for lowercase letter
  const hasLowerCase = /[a-z]/.test(password);
  if (PASSWORD_REQUIREMENTS.requireLowercase && !hasLowerCase) {
    errors.push('Password must contain at least one lowercase letter');
    errorsNo.push('Passord må inneholde minst én liten bokstav');
  } else if (hasLowerCase) {
    score++;
  }

  // Check for number
  const hasNumber = /[0-9]/.test(password);
  if (PASSWORD_REQUIREMENTS.requireNumber && !hasNumber) {
    errors.push('Password must contain at least one number');
    errorsNo.push('Passord må inneholde minst ett tall');
  } else if (hasNumber) {
    score++;
  }

  // Check for special character (optional but adds to strength)
  const hasSpecialChar = /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(password);
  if (hasSpecialChar) {
    score++;
  }

  // Check for common weak passwords
  const commonPasswords = [
    'password',
    '12345678',
    'qwerty',
    'abc123',
    'password123',
    'admin123',
  ];
  if (commonPasswords.includes(password.toLowerCase())) {
    errors.push('Password is too common. Please choose a stronger password');
    errorsNo.push('Passordet er for vanlig. Vennligst velg et sterkere passord');
    score = 0;
  }

  // Determine strength
  let strength: 'weak' | 'medium' | 'strong' = 'weak';
  if (score >= 5) {
    strength = 'strong';
  } else if (score >= 3) {
    strength = 'medium';
  }

  return {
    isValid: errors.length === 0,
    errors,
    errorsNo,
    strength,
    score,
  };
};

/**
 * Confirm password matches confirmation
 *
 * @param password - Original password
 * @param confirmPassword - Password confirmation
 * @returns Validation result
 *
 * @example
 * ```typescript
 * const result = validatePasswordMatch('MyPass123', 'MyPass123');
 * console.log(result.isValid); // true
 * ```
 */
export const validatePasswordMatch = (
  password: string,
  confirmPassword: string
): ValidationResult => {
  const errors: string[] = [];
  const errorsNo: string[] = [];

  if (!password || !confirmPassword) {
    errors.push('Both password fields are required');
    errorsNo.push('Begge passordfeltene er påkrevd');
    return { isValid: false, errors, errorsNo };
  }

  if (password !== confirmPassword) {
    errors.push('Passwords do not match');
    errorsNo.push('Passordene stemmer ikke overens');
    return { isValid: false, errors, errorsNo };
  }

  return { isValid: true, errors: [], errorsNo: [] };
};

// ============================================================================
// Route Access Control
// ============================================================================

/**
 * Check if user role can access admin routes
 *
 * Admin routes are accessible by:
 * - platform_admin
 * - owner
 * - admin
 *
 * @param role - User's role
 * @param isPlatformAdmin - Whether user is a platform admin
 * @returns Access result with reason if denied
 *
 * @example
 * ```typescript
 * const result = canAccessAdminRoute('admin', false);
 * console.log(result.canAccess); // true
 *
 * const result2 = canAccessAdminRoute('customer', false);
 * console.log(result2.canAccess); // false
 * console.log(result2.reason); // 'Insufficient permissions...'
 * ```
 */
export const canAccessAdminRoute = (
  role: SystemRole | null,
  isPlatformAdmin: boolean
): RouteAccessResult => {
  if (isPlatformAdmin) {
    return { canAccess: true };
  }

  if (!role) {
    return {
      canAccess: false,
      reason: 'Authentication required. Please sign in to continue.',
      reasonNo: 'Autentisering påkrevd. Vennligst logg inn for å fortsette.',
      redirectTo: '/login',
    };
  }

  if (ADMIN_ROLES.includes(role)) {
    return { canAccess: true };
  }

  return {
    canAccess: false,
    reason: 'Insufficient permissions. Admin access required.',
    reasonNo: 'Utilstrekkelige tillatelser. Administratortilgang kreves.',
    redirectTo: '/dashboard',
  };
};

/**
 * Check if user role can access user routes
 *
 * User routes are accessible by all authenticated users including:
 * - All admin roles
 * - case_handler
 * - editor
 * - read_only
 * - customer
 *
 * @param role - User's role
 * @param isPlatformAdmin - Whether user is a platform admin
 * @returns Access result with reason if denied
 *
 * @example
 * ```typescript
 * const result = canAccessUserRoute('customer', false);
 * console.log(result.canAccess); // true
 *
 * const result2 = canAccessUserRoute(null, false);
 * console.log(result2.canAccess); // false
 * ```
 */
export const canAccessUserRoute = (
  role: SystemRole | null,
  isPlatformAdmin: boolean
): RouteAccessResult => {
  if (isPlatformAdmin) {
    return { canAccess: true };
  }

  if (!role) {
    return {
      canAccess: false,
      reason: 'Authentication required. Please sign in to continue.',
      reasonNo: 'Autentisering påkrevd. Vennligst logg inn for å fortsette.',
      redirectTo: '/login',
    };
  }

  // All authenticated users with valid roles can access user routes
  if ([...ADMIN_ROLES, ...USER_ROLES].includes(role)) {
    return { canAccess: true };
  }

  return {
    canAccess: false,
    reason: 'Invalid user role. Please contact support.',
    reasonNo: 'Ugyldig brukerrolle. Vennligst kontakt support.',
    redirectTo: '/login',
  };
};

// ============================================================================
// Session Management
// ============================================================================

/**
 * Check if session timestamp is expired
 *
 * @param expiresAt - Session expiration timestamp (ISO 8601)
 * @param currentTime - Current time (defaults to now)
 * @returns True if session is expired
 *
 * @example
 * ```typescript
 * const expiresAt = '2025-10-30T12:00:00Z';
 * const isExpired = isSessionExpired(expiresAt);
 * console.log(isExpired); // true or false based on current time
 * ```
 */
export const isSessionExpired = (
  expiresAt: string,
  currentTime: Date = new Date()
): boolean => {
  try {
    const expirationDate = new Date(expiresAt);
    return currentTime.getTime() >= expirationDate.getTime();
  } catch (error) {
    // Invalid date format, consider as expired
    return true;
  }
};

/**
 * Calculate session expiration time
 *
 * @param issuedAt - Session issued timestamp (ISO 8601)
 * @param durationMs - Session duration in milliseconds (defaults to 24 hours)
 * @returns Session expiration timestamp
 *
 * @example
 * ```typescript
 * const issuedAt = '2025-10-29T12:00:00Z';
 * const expiresAt = calculateSessionExpiration(issuedAt);
 * console.log(expiresAt); // ISO 8601 timestamp 24 hours later
 * ```
 */
export const calculateSessionExpiration = (
  issuedAt: string,
  durationMs: number = SESSION_DURATION_MS
): string => {
  try {
    const issuedDate = new Date(issuedAt);
    const expirationDate = new Date(issuedDate.getTime() + durationMs);
    return expirationDate.toISOString();
  } catch (error) {
    // Invalid date, return current time + duration
    const now = new Date();
    const expirationDate = new Date(now.getTime() + durationMs);
    return expirationDate.toISOString();
  }
};

/**
 * Get remaining session time in minutes
 *
 * @param expiresAt - Session expiration timestamp (ISO 8601)
 * @param currentTime - Current time (defaults to now)
 * @returns Remaining time in minutes (0 if expired)
 *
 * @example
 * ```typescript
 * const expiresAt = '2025-10-29T13:00:00Z';
 * const remaining = getRemainingSessionTime(expiresAt);
 * console.log(remaining); // Number of minutes remaining
 * ```
 */
export const getRemainingSessionTime = (
  expiresAt: string,
  currentTime: Date = new Date()
): number => {
  try {
    const expirationDate = new Date(expiresAt);
    const remainingMs = expirationDate.getTime() - currentTime.getTime();
    if (remainingMs <= 0) return 0;
    return Math.floor(remainingMs / (60 * 1000)); // Convert to minutes
  } catch (error) {
    return 0;
  }
};

// ============================================================================
// Input Sanitization
// ============================================================================

/**
 * Sanitize user input for login/registration
 *
 * Trims whitespace and removes potentially harmful characters.
 * Does NOT modify passwords (they should remain as-is for validation).
 *
 * @param input - Raw user input
 * @returns Sanitized input
 *
 * @example
 * ```typescript
 * const sanitized = sanitizeUserInput({
 *   email: '  user@example.com  ',
 *   password: 'MyPass123',
 * });
 * console.log(sanitized.email); // 'user@example.com'
 * console.log(sanitized.password); // 'MyPass123' (unchanged)
 * ```
 */
export const sanitizeUserInput = (input: {
  readonly email: string;
  readonly password?: string;
  readonly [key: string]: string | undefined;
}): SanitizedInput => {
  const sanitized: { [key: string]: string | undefined } = {};

  // Sanitize email (trim and lowercase)
  if (input.email) {
    sanitized.email = input.email.trim().toLowerCase();
  } else {
    sanitized.email = '';
  }

  // Keep password as-is (no trimming or modification)
  if (input.password !== undefined) {
    sanitized.password = input.password;
  }

  // Sanitize other string fields (trim only)
  Object.keys(input).forEach(key => {
    if (key !== 'email' && key !== 'password' && input[key]) {
      const value = input[key];
      if (typeof value === 'string') {
        sanitized[key] = value.trim();
      }
    }
  });

  return sanitized as SanitizedInput;
};

// ============================================================================
// Password Requirements
// ============================================================================

/**
 * Generate password requirement messages
 *
 * Returns human-readable password requirements in English and Norwegian.
 *
 * @returns Password requirement messages
 *
 * @example
 * ```typescript
 * const requirements = generatePasswordRequirements();
 * console.log(requirements.en); // English requirements
 * console.log(requirements.no); // Norwegian requirements
 * ```
 */
export const generatePasswordRequirements = (): {
  readonly en: readonly string[];
  readonly no: readonly string[];
} => {
  const en: string[] = [];
  const no: string[] = [];

  en.push(`At least ${PASSWORD_REQUIREMENTS.minLength} characters long`);
  no.push(`Minst ${PASSWORD_REQUIREMENTS.minLength} tegn langt`);

  if (PASSWORD_REQUIREMENTS.requireUppercase) {
    en.push('Contains at least one uppercase letter (A-Z)');
    no.push('Inneholder minst én stor bokstav (A-Å)');
  }

  if (PASSWORD_REQUIREMENTS.requireLowercase) {
    en.push('Contains at least one lowercase letter (a-z)');
    no.push('Inneholder minst én liten bokstav (a-å)');
  }

  if (PASSWORD_REQUIREMENTS.requireNumber) {
    en.push('Contains at least one number (0-9)');
    no.push('Inneholder minst ett tall (0-9)');
  }

  if (PASSWORD_REQUIREMENTS.requireSpecialChar) {
    en.push('Contains at least one special character (!@#$%^&*)');
    no.push('Inneholder minst ett spesialtegn (!@#$%^&*)');
  }

  return { en, no };
};

// ============================================================================
// Role Comparison
// ============================================================================

/**
 * Check if a role has sufficient priority for an action
 *
 * @param userRole - User's current role
 * @param requiredRole - Required role for the action
 * @param isPlatformAdmin - Whether user is a platform admin
 * @returns True if user has sufficient priority
 *
 * @example
 * ```typescript
 * const canEdit = hasRolePriority('admin', 'editor', false);
 * console.log(canEdit); // true (admin > editor)
 *
 * const canDelete = hasRolePriority('editor', 'admin', false);
 * console.log(canDelete); // false (editor < admin)
 * ```
 */
export const hasRolePriority = (
  userRole: OrgRole | null,
  requiredRole: OrgRole,
  isPlatformAdmin: boolean
): boolean => {
  // Platform admin has highest priority
  if (isPlatformAdmin) return true;

  // No role means no access
  if (!userRole) return false;

  // Get priorities (default to 0 if role not found)
  const userPriority = ROLE_PRIORITY[userRole] ?? 0;
  const requiredPriority = ROLE_PRIORITY[requiredRole] ?? 0;

  return userPriority >= requiredPriority;
};

/**
 * Get role priority level
 *
 * @param role - Role to check
 * @returns Priority level (0-100)
 *
 * @example
 * ```typescript
 * const priority = getRolePriority('admin');
 * console.log(priority); // 80
 * ```
 */
export const getRolePriority = (role: OrgRole): number => {
  return ROLE_PRIORITY[role] ?? 0;
};

