/**
 * Booking Business Logic Service
 *
 * Contains all business logic related to booking operations.
 * NO UI logic, NO component dependencies.
 * Pure business rules and data transformations.
 */

import type { Database } from "@/types/database";

type Booking = Database['public']['Tables']['bookings']['Row'];
type BookingStatus = Database['public']['Enums']['booking_status'];
type Facility = Database['public']['Tables']['facilities']['Row'];

/**
 * Actor type for pricing calculations
 */
export type ActorType =
  | 'private-person'
  | 'lag-foreninger'
  | 'paraply'
  | 'private-firma'
  | 'kommunale-enheter';

/**
 * Extended booking with facility information for display and filtering
 */
export interface BookingWithFacility extends Booking {
  readonly facilities?: Pick<Facility, 'name' | 'facility_type' | 'address'>;
}

/**
 * Booking filter configuration
 */
export interface IBookingFilters {
  readonly searchTerm?: string;
  readonly statusFilter?: readonly BookingStatus[];
  readonly facilityIds?: readonly string[];
  readonly dateRange?: {
    readonly startDate: Date;
    readonly endDate: Date;
  };
  readonly userIds?: readonly string[];
  readonly isRecurring?: boolean;
}

/**
 * Booking sort configuration
 */
export interface IBookingSortConfig {
  readonly sortBy: 'starts_at' | 'ends_at' | 'created_at' | 'status' | 'total_cents' | 'facility_name';
  readonly sortOrder: 'asc' | 'desc';
}

/**
 * Booking validation result
 */
export interface BookingValidationResult {
  readonly isValid: boolean;
  readonly errors: readonly string[];
}

/**
 * Price breakdown structure
 */
export interface PriceBreakdown {
  readonly basePrice: number;
  readonly actorDiscount: number;
  readonly actorMultiplier: number;
  readonly subtotal: number;
  readonly vat: number;
  readonly vatRate: number;
  readonly total: number;
  readonly currency: string;
}

/**
 * Booking conflict detection result
 */
export interface BookingConflict {
  readonly bookingId: string;
  readonly startsAt: string;
  readonly endsAt: string;
  readonly facilityId: string;
  readonly zoneId?: string | null;
}

/**
 * Booking statistics
 */
export interface BookingStats {
  readonly totalBookings: number;
  readonly pendingBookings: number;
  readonly confirmedBookings: number;
  readonly cancelledBookings: number;
  readonly completedBookings: number;
  readonly totalRevenue: number;
  readonly averageBookingValue: number;
  readonly utilizationRate: number;
  readonly currency: string;
}

/**
 * Cancellation eligibility result
 */
export interface CancellationEligibility {
  readonly canCancel: boolean;
  readonly reason?: string;
  readonly hoursUntilStart?: number;
}

/**
 * Modification eligibility result
 */
export interface ModificationEligibility {
  readonly canModify: boolean;
  readonly reason?: string;
  readonly hoursUntilStart?: number;
}

/**
 * Filter bookings based on search and filter criteria
 *
 * @param bookings - Array of bookings to filter
 * @param filters - Filter configuration
 * @returns Filtered array of bookings
 */
export const filterBookings = (
  bookings: readonly BookingWithFacility[],
  filters: IBookingFilters
): readonly BookingWithFacility[] => {
  return bookings.filter(booking => {
    // Search filter - searches in facility name, notes, and facility address
    if (filters.searchTerm) {
      const searchLower = filters.searchTerm.toLowerCase();
      const facilityName = booking.facilities?.name?.toLowerCase() || '';
      const notes = booking.notes?.toLowerCase() || '';
      const address = booking.facilities?.address?.toLowerCase() || '';

      const matchesSearch =
        facilityName.includes(searchLower) ||
        notes.includes(searchLower) ||
        address.includes(searchLower) ||
        booking.id.toLowerCase().includes(searchLower);

      if (!matchesSearch) return false;
    }

    // Status filter
    if (filters.statusFilter && filters.statusFilter.length > 0) {
      if (!filters.statusFilter.includes(booking.status)) return false;
    }

    // Facility filter
    if (filters.facilityIds && filters.facilityIds.length > 0) {
      if (!filters.facilityIds.includes(booking.facility_id)) return false;
    }

    // Date range filter
    if (filters.dateRange) {
      const bookingStart = new Date(booking.starts_at);
      const bookingEnd = new Date(booking.ends_at);
      const { startDate, endDate } = filters.dateRange;

      // Check if booking overlaps with the filter date range
      const overlaps = bookingStart <= endDate && bookingEnd >= startDate;
      if (!overlaps) return false;
    }

    // User filter
    if (filters.userIds && filters.userIds.length > 0) {
      if (!filters.userIds.includes(booking.user_id)) return false;
    }

    // Recurring filter
    if (filters.isRecurring !== undefined) {
      if (booking.is_recurring !== filters.isRecurring) return false;
    }

    return true;
  });
};

/**
 * Sort bookings based on sort configuration
 *
 * @param bookings - Array of bookings to sort
 * @param sortConfig - Sort configuration
 * @returns Sorted array of bookings
 */
export const sortBookings = (
  bookings: readonly BookingWithFacility[],
  sortConfig: IBookingSortConfig
): readonly BookingWithFacility[] => {
  const sorted = [...bookings].sort((a, b) => {
    let comparison = 0;

    switch (sortConfig.sortBy) {
      case 'starts_at':
        comparison = new Date(a.starts_at).getTime() - new Date(b.starts_at).getTime();
        break;
      case 'ends_at':
        comparison = new Date(a.ends_at).getTime() - new Date(b.ends_at).getTime();
        break;
      case 'created_at':
        comparison = new Date(a.created_at).getTime() - new Date(b.created_at).getTime();
        break;
      case 'status':
        comparison = a.status.localeCompare(b.status);
        break;
      case 'total_cents':
        comparison = a.total_cents - b.total_cents;
        break;
      case 'facility_name':
        const nameA = a.facilities?.name || '';
        const nameB = b.facilities?.name || '';
        comparison = nameA.localeCompare(nameB);
        break;
    }

    return sortConfig.sortOrder === 'asc' ? comparison : -comparison;
  });

  return sorted;
};

/**
 * Validate booking form data
 *
 * @param bookingData - Partial booking data to validate
 * @returns Validation result with errors
 */
export const validateBookingData = (
  bookingData: Partial<Booking>
): BookingValidationResult => {
  const errors: string[] = [];

  // Required fields
  if (!bookingData.facility_id) {
    errors.push('Facility is required');
  }

  if (!bookingData.starts_at) {
    errors.push('Start date and time is required');
  }

  if (!bookingData.ends_at) {
    errors.push('End date and time is required');
  }

  if (!bookingData.user_id) {
    errors.push('User is required');
  }

  if (!bookingData.org_id) {
    errors.push('Organization is required');
  }

  // Date logic validation
  if (bookingData.starts_at && bookingData.ends_at) {
    const startDate = new Date(bookingData.starts_at);
    const endDate = new Date(bookingData.ends_at);
    const now = new Date();

    // Start date must be in the future (allow some grace period of 5 minutes for clock differences)
    const gracePeriod = 5 * 60 * 1000; // 5 minutes in milliseconds
    if (startDate.getTime() < now.getTime() - gracePeriod) {
      errors.push('Start date must be in the future');
    }

    // End date must be after start date
    if (endDate <= startDate) {
      errors.push('End date must be after start date');
    }

    // Booking duration validation (minimum 30 minutes, maximum 24 hours for single booking)
    const durationMs = endDate.getTime() - startDate.getTime();
    const durationHours = durationMs / (1000 * 60 * 60);

    if (durationHours < 0.5) {
      errors.push('Booking duration must be at least 30 minutes');
    }

    if (durationHours > 24 && !bookingData.is_recurring) {
      errors.push('Single booking duration cannot exceed 24 hours');
    }
  }

  // Price validation
  if (bookingData.total_cents !== undefined && bookingData.total_cents < 0) {
    errors.push('Total price cannot be negative');
  }

  // Currency validation
  if (bookingData.currency && !['NOK', 'USD', 'EUR'].includes(bookingData.currency)) {
    errors.push('Invalid currency code');
  }

  return {
    isValid: errors.length === 0,
    errors,
  };
};

/**
 * Get actor pricing multiplier based on actor type
 *
 * @param actorType - Type of actor making the booking
 * @returns Price multiplier for the actor type
 */
export const getActorMultiplier = (actorType: ActorType): number => {
  switch (actorType) {
    case 'paraply':
      return 0.9; // 10% discount
    case 'private-firma':
      return 1.2; // 20% surcharge
    case 'kommunale-enheter':
      return 0.8; // 20% discount
    case 'lag-foreninger':
      return 0.85; // 15% discount
    case 'private-person':
    default:
      return 1.0; // No adjustment
  }
};

/**
 * Calculate booking price with VAT and discounts
 *
 * @param basePrice - Base price in cents before adjustments
 * @param actorType - Type of actor for pricing adjustments
 * @param currency - Currency code (default: NOK)
 * @returns Complete price breakdown
 */
export const calculateBookingPrice = (
  basePrice: number,
  actorType: ActorType,
  currency: string = 'NOK'
): PriceBreakdown => {
  const actorMultiplier = getActorMultiplier(actorType);
  const actorDiscount = basePrice * (1 - actorMultiplier);
  const subtotal = basePrice * actorMultiplier;

  // VAT rate is 25% in Norway
  const vatRate = 0.25;
  const vat = subtotal * vatRate;
  const total = subtotal + vat;

  return {
    basePrice,
    actorDiscount,
    actorMultiplier,
    subtotal,
    vat,
    vatRate,
    total,
    currency,
  };
};

/**
 * Check if a booking can be cancelled based on business rules
 *
 * Business rules:
 * - Cannot cancel completed, cancelled, expired, or refunded bookings
 * - Must be at least 24 hours before start time
 * - Paid bookings require special handling (refund process)
 *
 * @param booking - Booking to check
 * @returns Cancellation eligibility result
 */
export const canCancelBooking = (booking: Booking): CancellationEligibility => {
  const now = new Date();
  const startTime = new Date(booking.starts_at);
  const hoursUntilStart = (startTime.getTime() - now.getTime()) / (1000 * 60 * 60);

  // Check booking status
  const nonCancellableStatuses: BookingStatus[] = ['completed', 'cancelled', 'expired', 'refunded'];
  if (nonCancellableStatuses.includes(booking.status)) {
    return {
      canCancel: false,
      reason: `Cannot cancel ${booking.status} bookings`,
      hoursUntilStart,
    };
  }

  // Check if booking has already started or passed
  if (hoursUntilStart <= 0) {
    return {
      canCancel: false,
      reason: 'Cannot cancel bookings that have already started or passed',
      hoursUntilStart,
    };
  }

  // Check minimum cancellation notice period (24 hours)
  const minimumNoticeHours = 24;
  if (hoursUntilStart < minimumNoticeHours) {
    return {
      canCancel: false,
      reason: `Cancellation requires at least ${minimumNoticeHours} hours notice`,
      hoursUntilStart,
    };
  }

  // All checks passed
  return {
    canCancel: true,
    hoursUntilStart,
  };
};

/**
 * Check if a booking can be modified based on business rules
 *
 * Business rules:
 * - Cannot modify completed, cancelled, expired, or refunded bookings
 * - Must be at least 12 hours before start time
 * - Paid bookings can be modified but may require payment adjustment
 *
 * @param booking - Booking to check
 * @returns Modification eligibility result
 */
export const canModifyBooking = (booking: Booking): ModificationEligibility => {
  const now = new Date();
  const startTime = new Date(booking.starts_at);
  const hoursUntilStart = (startTime.getTime() - now.getTime()) / (1000 * 60 * 60);

  // Check booking status
  const nonModifiableStatuses: BookingStatus[] = ['completed', 'cancelled', 'expired', 'refunded'];
  if (nonModifiableStatuses.includes(booking.status)) {
    return {
      canModify: false,
      reason: `Cannot modify ${booking.status} bookings`,
      hoursUntilStart,
    };
  }

  // Check if booking has already started or passed
  if (hoursUntilStart <= 0) {
    return {
      canModify: false,
      reason: 'Cannot modify bookings that have already started or passed',
      hoursUntilStart,
    };
  }

  // Check minimum modification notice period (12 hours)
  const minimumNoticeHours = 12;
  if (hoursUntilStart < minimumNoticeHours) {
    return {
      canModify: false,
      reason: `Modification requires at least ${minimumNoticeHours} hours notice`,
      hoursUntilStart,
    };
  }

  // All checks passed
  return {
    canModify: true,
    hoursUntilStart,
  };
};

/**
 * Detect booking conflicts for a given time slot and facility/zone
 *
 * @param existingBookings - Array of existing bookings to check against
 * @param newStartTime - Start time of new booking (ISO string)
 * @param newEndTime - End time of new booking (ISO string)
 * @param facilityId - Facility ID
 * @param zoneId - Optional zone ID for zone-specific conflicts
 * @param excludeBookingId - Optional booking ID to exclude (for updates)
 * @returns Array of conflicting bookings
 */
export const detectBookingConflicts = (
  existingBookings: readonly Booking[],
  newStartTime: string,
  newEndTime: string,
  facilityId: string,
  zoneId?: string | null,
  excludeBookingId?: string
): readonly BookingConflict[] => {
  const newStart = new Date(newStartTime);
  const newEnd = new Date(newEndTime);

  const conflicts: BookingConflict[] = [];

  for (const booking of existingBookings) {
    // Skip excluded booking (for updates)
    if (excludeBookingId && booking.id === excludeBookingId) {
      continue;
    }

    // Skip cancelled, expired, or refunded bookings
    if (['cancelled', 'expired', 'refunded'].includes(booking.status)) {
      continue;
    }

    // Check facility match
    if (booking.facility_id !== facilityId) {
      continue;
    }

    // Check zone match if zone is specified
    if (zoneId && booking.zone_id !== zoneId) {
      continue;
    }

    // Check time overlap
    const existingStart = new Date(booking.starts_at);
    const existingEnd = new Date(booking.ends_at);

    const hasOverlap = newStart < existingEnd && newEnd > existingStart;

    if (hasOverlap) {
      conflicts.push({
        bookingId: booking.id,
        startsAt: booking.starts_at,
        endsAt: booking.ends_at,
        facilityId: booking.facility_id,
        zoneId: booking.zone_id,
      });
    }
  }

  return conflicts;
};

/**
 * Calculate booking statistics from a set of bookings
 *
 * @param bookings - Array of bookings to analyze
 * @param facilityCapacity - Optional total facility capacity for utilization calculation
 * @returns Booking statistics
 */
export const calculateBookingStats = (
  bookings: readonly Booking[],
  facilityCapacity?: number
): BookingStats => {
  const totalBookings = bookings.length;

  // Count by status
  const pendingBookings = bookings.filter(b => b.status === 'pending').length;
  const confirmedBookings = bookings.filter(b =>
    ['awaiting_payment', 'paid'].includes(b.status)
  ).length;
  const cancelledBookings = bookings.filter(b => b.status === 'cancelled').length;
  const completedBookings = bookings.filter(b => b.status === 'completed').length;

  // Calculate revenue (only from paid and completed bookings)
  const revenueBookings = bookings.filter(b =>
    ['paid', 'completed'].includes(b.status)
  );
  const totalRevenue = revenueBookings.reduce((sum, b) => sum + b.total_cents, 0);

  // Calculate average booking value
  const averageBookingValue = totalBookings > 0
    ? totalRevenue / revenueBookings.length
    : 0;

  // Calculate utilization rate (if capacity provided)
  let utilizationRate = 0;
  if (facilityCapacity && facilityCapacity > 0) {
    // Calculate total booked hours
    const totalBookedHours = bookings.reduce((sum, booking) => {
      const start = new Date(booking.starts_at);
      const end = new Date(booking.ends_at);
      const hours = (end.getTime() - start.getTime()) / (1000 * 60 * 60);
      return sum + hours;
    }, 0);

    // Assuming capacity is per hour, calculate utilization
    // This is a simplified calculation - real utilization would need time period
    utilizationRate = totalBookedHours > 0 ? totalBookedHours / facilityCapacity : 0;
  }

  // Get currency from first booking or default to NOK
  const currency = bookings[0]?.currency || 'NOK';

  return {
    totalBookings,
    pendingBookings,
    confirmedBookings,
    cancelledBookings,
    completedBookings,
    totalRevenue,
    averageBookingValue,
    utilizationRate,
    currency,
  };
};

/**
 * Get unique booking statuses from a list of bookings
 *
 * @param bookings - Array of bookings
 * @returns Array of unique status values
 */
export const getUniqueBookingStatuses = (
  bookings: readonly Booking[]
): readonly BookingStatus[] => {
  return Array.from(new Set(bookings.map(b => b.status)));
};

/**
 * Get all possible booking statuses
 *
 * @returns Array of all possible booking status values
 */
export const getAllBookingStatuses = (): readonly BookingStatus[] => {
  return [
    'pending',
    'awaiting_payment',
    'paid',
    'cancelled',
    'expired',
    'completed',
    'refunded',
  ];
};

/**
 * Format booking for display
 *
 * @param booking - Booking to format
 * @returns Booking with formatted display fields
 */
export const formatBookingForDisplay = (booking: BookingWithFacility) => {
  const startDate = new Date(booking.starts_at);
  const endDate = new Date(booking.ends_at);
  const createdDate = new Date(booking.created_at);

  // Calculate duration
  const durationMs = endDate.getTime() - startDate.getTime();
  const durationHours = durationMs / (1000 * 60 * 60);

  return {
    ...booking,
    formattedStartDate: startDate.toLocaleDateString('no-NO'),
    formattedStartTime: startDate.toLocaleTimeString('no-NO', {
      hour: '2-digit',
      minute: '2-digit'
    }),
    formattedEndDate: endDate.toLocaleDateString('no-NO'),
    formattedEndTime: endDate.toLocaleTimeString('no-NO', {
      hour: '2-digit',
      minute: '2-digit'
    }),
    formattedCreatedAt: createdDate.toLocaleDateString('no-NO'),
    durationHours: Math.round(durationHours * 10) / 10, // Round to 1 decimal
    formattedPrice: `${(booking.total_cents / 100).toFixed(2)} ${booking.currency}`,
    facilityName: booking.facilities?.name || 'Unknown Facility',
    hasNotes: Boolean(booking.notes),
  };
};

/**
 * Check if booking is upcoming (starts in the future)
 *
 * @param booking - Booking to check
 * @returns True if booking starts in the future
 */
export const isUpcomingBooking = (booking: Booking): boolean => {
  const now = new Date();
  const startTime = new Date(booking.starts_at);
  return startTime > now;
};

/**
 * Check if booking is currently active (ongoing)
 *
 * @param booking - Booking to check
 * @returns True if booking is currently active
 */
export const isActiveBooking = (booking: Booking): boolean => {
  const now = new Date();
  const startTime = new Date(booking.starts_at);
  const endTime = new Date(booking.ends_at);
  return startTime <= now && endTime >= now;
};

/**
 * Check if booking is past (ended)
 *
 * @param booking - Booking to check
 * @returns True if booking has ended
 */
export const isPastBooking = (booking: Booking): boolean => {
  const now = new Date();
  const endTime = new Date(booking.ends_at);
  return endTime < now;
};

/**
 * Calendar Business Logic Service
 *
 * Contains all business logic related to calendar operations and time slot management.
 * NO UI logic, NO component dependencies, NO API calls.
 * Pure business rules and data transformations using date-fns for date manipulation.
 *
 * Pure Functions:
 * - No side effects
 * - No external state mutations
 * - Deterministic outputs for given inputs
 * - No React or UI dependencies
 */

import {
  endOfMonth,
  eachDayOfInterval,
  startOfWeek,
  endOfWeek,
  format,
  parse,
  isWithinInterval,
  differenceInMinutes,
  differenceInHours,
  isSameDay,
  getDay,
  getWeek,
  addDays,
  isBefore,
  isAfter,
  isSameHourAndMinute,
  addMinutes,
  setHours,
  setMinutes,
  setSeconds,
  setMilliseconds,
} from 'date-fns';
import { nb } from 'date-fns/locale';

/**
 * Business hours configuration
 */
export interface BusinessHours {
  readonly startTime: string; // HH:MM format
  readonly endTime: string;   // HH:MM format
  readonly isOpenOnDay: boolean;
}

/**
 * Weekly business hours (one entry per day of week)
 */
export interface WeeklyBusinessHours {
  readonly monday: BusinessHours;
  readonly tuesday: BusinessHours;
  readonly wednesday: BusinessHours;
  readonly thursday: BusinessHours;
  readonly friday: BusinessHours;
  readonly saturday: BusinessHours;
  readonly sunday: BusinessHours;
}

/**
 * Calendar day structure for month view
 */
export interface CalendarDay {
  readonly date: Date;
  readonly dayOfMonth: number;
  readonly dayOfWeek: number; // 0-6
  readonly isCurrentMonth: boolean;
  readonly isToday: boolean;
  readonly isWeekend: boolean;
  readonly weekNumber: number;
}

/**
 * Calendar week structure
 */
export interface CalendarWeek {
  readonly weekNumber: number;
  readonly startDate: Date;
  readonly endDate: Date;
  readonly days: readonly CalendarDay[];
}

/**
 * Calendar month structure with grid layout
 */
export interface CalendarMonth {
  readonly year: number;
  readonly month: number; // 1-12
  readonly monthName: string;
  readonly weeks: readonly CalendarWeek[];
  readonly allDays: readonly CalendarDay[];
  readonly firstDay: Date;
  readonly lastDay: Date;
}

/**
 * Time slot for availability
 */
export interface TimeSlot {
  readonly startTime: string; // HH:MM format
  readonly endTime: string;   // HH:MM format
  readonly isAvailable: boolean;
  readonly durationMinutes: number;
  readonly durationHours: number;
}

/**
 * Available slots result
 */
export interface AvailableSlotsResult {
  readonly date: Date;
  readonly slots: readonly TimeSlot[];
  readonly totalSlotsAvailable: number;
  readonly totalSlotsDuration: number; // in hours
}

/**
 * Booking time slot structure
 */
export interface BookingSlot {
  readonly startTime: string; // ISO string
  readonly endTime: string;   // ISO string
  readonly facilityId: string;
}

/**
 * Slot overlap detection result
 */
export interface SlotOverlapResult {
  readonly hasOverlap: boolean;
  readonly overlappingSlot?: {
    readonly startTime: string;
    readonly endTime: string;
  };
  readonly overlapDurationMinutes?: number;
}

/**
 * Grouped bookings by date
 */
export interface BookingsByDate {
  readonly date: Date;
  readonly dateString: string; // YYYY-MM-DD format
  readonly bookings: readonly {
    readonly id: string;
    readonly title: string;
    readonly startTime: string;
    readonly endTime: string;
    readonly status: string;
    readonly durationMinutes: number;
  }[];
  readonly totalBookingsCount: number;
  readonly totalDurationHours: number;
}

/**
 * Generate a complete calendar structure for a given month
 *
 * Creates a full calendar grid with proper week organization.
 * Includes days from previous/next months needed to fill the grid.
 *
 * @param year - Year (YYYY)
 * @param month - Month (1-12)
 * @returns Complete calendar month structure with weeks and days
 *
 * @example
 * const calendar = generateMonthCalendar(2024, 10);
 * console.log(calendar.weeks.length); // 5 or 6 weeks depending on layout
 */
export const generateMonthCalendar = (
  year: number,
  month: number
): CalendarMonth => {
  // Validate inputs
  if (month < 1 || month > 12) {
    throw new Error('Month must be between 1 and 12');
  }

  const startDate = new Date(year, month - 1, 1);
  const endDate = endOfMonth(startDate);
  const firstDay = startOfWeek(startDate, { weekStartsOn: 1 }); // Monday = 1
  const lastDay = endOfWeek(endDate, { weekStartsOn: 1 });

  const allDates = eachDayOfInterval({
    start: firstDay,
    end: lastDay,
  });

  // Create calendar day objects
  const calendarDays: CalendarDay[] = allDates.map(date => {
    const today = new Date();
    const isToday =
      date.getFullYear() === today.getFullYear() &&
      date.getMonth() === today.getMonth() &&
      date.getDate() === today.getDate();

    return {
      date,
      dayOfMonth: date.getDate(),
      dayOfWeek: getDay(date), // 0-6, Sunday = 0
      isCurrentMonth: date.getMonth() === startDate.getMonth(),
      isToday,
      isWeekend: getDay(date) === 0 || getDay(date) === 6,
      weekNumber: getWeek(date, { weekStartsOn: 1 }),
    };
  });

  // Group days into weeks
  const weekMap = new Map<number, CalendarDay[]>();
  calendarDays.forEach(day => {
    const weekNum = day.weekNumber;
    if (!weekMap.has(weekNum)) {
      weekMap.set(weekNum, []);
    }
    weekMap.get(weekNum)!.push(day);
  });

  const weeks: CalendarWeek[] = Array.from(weekMap.entries()).map(
    ([weekNumber, days]) => {
      const sortedDays = days.sort((a, b) => a.date.getTime() - b.date.getTime());
      return {
        weekNumber,
        startDate: sortedDays[0].date,
        endDate: sortedDays[sortedDays.length - 1].date,
        days: sortedDays,
      };
    }
  );

  // Sort weeks by start date
  weeks.sort((a, b) => a.startDate.getTime() - b.startDate.getTime());

  return {
    year,
    month,
    monthName: format(startDate, 'MMMM', { locale: nb }),
    weeks,
    allDays: calendarDays,
    firstDay: startDate,
    lastDay: endDate,
  };
};

/**
 * Generate a calendar structure for a specific week
 *
 * Creates a week view with all 7 days clearly structured.
 *
 * @param date - Any date within the target week
 * @returns Calendar week structure with all 7 days
 *
 * @example
 * const week = generateWeekCalendar(new Date(2024, 9, 15));
 * console.log(week.days.length); // 7
 */
export const generateWeekCalendar = (date: Date): CalendarWeek => {
  const weekStart = startOfWeek(date, { weekStartsOn: 1 }); // Monday
  const weekEnd = endOfWeek(date, { weekStartsOn: 1 });

  const allDates = eachDayOfInterval({
    start: weekStart,
    end: weekEnd,
  });

  const today = new Date();
  const calendarDays: CalendarDay[] = allDates.map(dayDate => {
    const isToday =
      dayDate.getFullYear() === today.getFullYear() &&
      dayDate.getMonth() === today.getMonth() &&
      dayDate.getDate() === today.getDate();

    return {
      date: dayDate,
      dayOfMonth: dayDate.getDate(),
      dayOfWeek: getDay(dayDate),
      isCurrentMonth: true,
      isToday,
      isWeekend: getDay(dayDate) === 0 || getDay(dayDate) === 6,
      weekNumber: getWeek(dayDate, { weekStartsOn: 1 }),
    };
  });

  return {
    weekNumber: getWeek(date, { weekStartsOn: 1 }),
    startDate: weekStart,
    endDate: weekEnd,
    days: calendarDays,
  };
};

/**
 * Find available time slots within a date range
 *
 * Finds all available slots in 30-minute or custom interval increments,
 * excluding existing bookings and outside business hours.
 *
 * @param date - Target date for slot availability
 * @param existingBookings - Array of existing bookings to exclude
 * @param businessHours - Business hours for the day
 * @param slotDurationMinutes - Duration of each slot in minutes (default: 60)
 * @returns Available slots result with all open time windows
 *
 * @example
 * const slots = findAvailableSlots(
 *   new Date(2024, 9, 15),
 *   existingBookings,
 *   { startTime: '09:00', endTime: '17:00', isOpenOnDay: true },
 *   60
 * );
 */
export const findAvailableSlots = (
  date: Date,
  existingBookings: readonly BookingSlot[],
  businessHours: BusinessHours,
  slotDurationMinutes: number = 60
): AvailableSlotsResult => {
  const slots: TimeSlot[] = [];

  // Check if business is open on this day
  if (!businessHours.isOpenOnDay) {
    return {
      date,
      slots,
      totalSlotsAvailable: 0,
      totalSlotsDuration: 0,
    };
  }

  // Parse business hours
  const [startHour, startMinute] = businessHours.startTime.split(':').map(Number);
  const [endHour, endMinute] = businessHours.endTime.split(':').map(Number);

  const dayStart = setMilliseconds(setSeconds(setMinutes(setHours(date, startHour), startMinute), 0), 0);
  const dayEnd = setMilliseconds(setSeconds(setMinutes(setHours(date, endHour), endMinute), 0), 0);

  // Generate all potential slots
  let currentSlotStart = new Date(dayStart);

  while (currentSlotStart.getTime() < dayEnd.getTime()) {
    const currentSlotEnd = addMinutes(currentSlotStart, slotDurationMinutes);

    // Ensure slot doesn't exceed business hours
    if (currentSlotEnd.getTime() > dayEnd.getTime()) {
      break;
    }

    // Check for overlaps with existing bookings
    const hasOverlap = existingBookings.some(booking => {
      const bookingStart = new Date(booking.startTime);
      const bookingEnd = new Date(booking.endTime);

      return (
        currentSlotStart.getTime() < bookingEnd.getTime() &&
        currentSlotEnd.getTime() > bookingStart.getTime()
      );
    });

    if (!hasOverlap) {
      slots.push({
        startTime: format(currentSlotStart, 'HH:mm'),
        endTime: format(currentSlotEnd, 'HH:mm'),
        isAvailable: true,
        durationMinutes: slotDurationMinutes,
        durationHours: slotDurationMinutes / 60,
      });
    }

    currentSlotStart = currentSlotEnd;
  }

  // Calculate total duration
  const totalDuration = slots.reduce((sum, slot) => sum + slot.durationHours, 0);

  return {
    date,
    slots,
    totalSlotsAvailable: slots.length,
    totalSlotsDuration: totalDuration,
  };
};

/**
 * Detect overlapping time slots
 *
 * Checks if a new booking slot overlaps with any existing bookings.
 *
 * @param newSlot - New booking slot to check
 * @param existingBookings - Array of existing booking slots
 * @returns Overlap detection result with details
 *
 * @example
 * const overlap = detectSlotOverlaps(newSlot, existingBookings);
 * if (overlap.hasOverlap) {
 *   console.log('Overlapping slot:', overlap.overlappingSlot);
 * }
 */
export const detectSlotOverlaps = (
  newSlot: BookingSlot,
  existingBookings: readonly BookingSlot[]
): SlotOverlapResult => {
  const newStart = new Date(newSlot.startTime);
  const newEnd = new Date(newSlot.endTime);

  for (const booking of existingBookings) {
    const existingStart = new Date(booking.startTime);
    const existingEnd = new Date(booking.endTime);

    // Check for overlap: new slot starts before existing ends AND new slot ends after existing starts
    const hasOverlap = newStart.getTime() < existingEnd.getTime() && newEnd.getTime() > existingStart.getTime();

    if (hasOverlap) {
      // Calculate overlap duration
      const overlapStart = new Date(Math.max(newStart.getTime(), existingStart.getTime()));
      const overlapEnd = new Date(Math.min(newEnd.getTime(), existingEnd.getTime()));
      const overlapDurationMinutes = differenceInMinutes(overlapEnd, overlapStart);

      return {
        hasOverlap: true,
        overlappingSlot: {
          startTime: booking.startTime,
          endTime: booking.endTime,
        },
        overlapDurationMinutes,
      };
    }
  }

  return {
    hasOverlap: false,
  };
};

/**
 * Calculate duration between two time points
 *
 * Returns both minute and hour representations of the duration.
 *
 * @param startTime - Start time (ISO string or Date)
 * @param endTime - End time (ISO string or Date)
 * @param unit - Unit for return value ('minutes' or 'hours')
 * @returns Duration in specified unit
 *
 * @example
 * const minutes = calculateSlotDuration('2024-10-15T09:00:00Z', '2024-10-15T10:30:00Z', 'minutes');
 * const hours = calculateSlotDuration('2024-10-15T09:00:00Z', '2024-10-15T10:30:00Z', 'hours');
 */
export const calculateSlotDuration = (
  startTime: string | Date,
  endTime: string | Date,
  unit: 'minutes' | 'hours' = 'minutes'
): number => {
  const start = typeof startTime === 'string' ? new Date(startTime) : startTime;
  const end = typeof endTime === 'string' ? new Date(endTime) : endTime;

  if (unit === 'hours') {
    return differenceInHours(end, start);
  }

  return differenceInMinutes(end, start);
};

/**
 * Check if a time falls within business hours
 *
 * Determines if a given time is within the configured business hours.
 *
 * @param time - Time to check (HH:MM format)
 * @param businessHours - Business hours configuration
 * @returns True if time is within business hours
 *
 * @example
 * const isValid = isBusinessHours('14:30', { startTime: '09:00', endTime: '17:00', isOpenOnDay: true });
 */
export const isBusinessHours = (
  time: string,
  businessHours: BusinessHours
): boolean => {
  if (!businessHours.isOpenOnDay) {
    return false;
  }

  // Parse time strings
  const [timeHour, timeMinute] = time.split(':').map(Number);
  const [startHour, startMinute] = businessHours.startTime.split(':').map(Number);
  const [endHour, endMinute] = businessHours.endTime.split(':').map(Number);

  // Convert to minutes since midnight for comparison
  const timeInMinutes = timeHour * 60 + timeMinute;
  const startInMinutes = startHour * 60 + startMinute;
  const endInMinutes = endHour * 60 + endMinute;

  return timeInMinutes >= startInMinutes && timeInMinutes < endInMinutes;
};

/**
 * Format a time slot for display in Norwegian locale
 *
 * Formats a time slot as a human-readable string in Norwegian format.
 *
 * @param startTime - Start time (HH:MM format or Date)
 * @param endTime - End time (HH:MM format or Date)
 * @param includeDate - Whether to include the date (default: false)
 * @param date - Date object if including date in format
 * @returns Formatted time slot string (e.g., "09:00 - 10:30")
 *
 * @example
 * const formatted = formatTimeSlot('09:00', '10:30');
 * console.log(formatted); // "09:00 - 10:30"
 *
 * const withDate = formatTimeSlot('09:00', '10:30', true, new Date(2024, 9, 15));
 * console.log(withDate); // "15.10.2024 - 09:00 - 10:30"
 */
export const formatTimeSlot = (
  startTime: string | Date,
  endTime: string | Date,
  includeDate: boolean = false,
  date?: Date
): string => {
  // Handle Date objects
  let startStr: string;
  let endStr: string;

  if (typeof startTime === 'string') {
    startStr = startTime;
  } else {
    startStr = format(startTime, 'HH:mm');
  }

  if (typeof endTime === 'string') {
    endStr = endTime;
  } else {
    endStr = format(endTime, 'HH:mm');
  }

  const timeSlot = `${startStr} - ${endStr}`;

  if (!includeDate || !date) {
    return timeSlot;
  }

  const dateStr = format(date, 'dd.MM.yyyy', { locale: nb });
  return `${dateStr} - ${timeSlot}`;
};

/**
 * Group bookings by date for calendar display
 *
 * Organizes bookings into groups by date for easier calendar rendering.
 * Includes calculated statistics per date.
 *
 * @param bookings - Array of bookings to group
 * @returns Array of grouped bookings with statistics
 *
 * @example
 * const grouped = groupBookingsByDate(bookings);
 * grouped.forEach(group => {
 *   console.log(`${group.dateString}: ${group.totalBookingsCount} bookings`);
 * });
 */
export const groupBookingsByDate = (
  bookings: readonly {
    readonly id: string;
    readonly title: string;
    readonly starts_at?: string;
    readonly start?: string;
    readonly ends_at?: string;
    readonly end?: string;
    readonly status: string;
  }[]
): readonly BookingsByDate[] => {
  const dateMap = new Map<string, BookingsByDate>();

  bookings.forEach(booking => {
    // Handle both starts_at/ends_at and start/end field names
    const startTimeStr = booking.starts_at || booking.start;
    const endTimeStr = booking.ends_at || booking.end;

    if (!startTimeStr || !endTimeStr) {
      return;
    }

    const startDate = new Date(startTimeStr);
    const endDate = new Date(endTimeStr);
    const dateString = format(startDate, 'yyyy-MM-dd');

    const durationMinutes = differenceInMinutes(endDate, startDate);

    if (!dateMap.has(dateString)) {
      dateMap.set(dateString, {
        date: startDate,
        dateString,
        bookings: [],
        totalBookingsCount: 0,
        totalDurationHours: 0,
      });
    }

    const group = dateMap.get(dateString)!;
    (group.bookings as typeof group.bookings & { push: Function }).push({
      id: booking.id,
      title: booking.title,
      startTime: format(startDate, 'HH:mm'),
      endTime: format(endDate, 'HH:mm'),
      status: booking.status,
      durationMinutes,
    });

    group.totalBookingsCount += 1;
    group.totalDurationHours += durationMinutes / 60;
  });

  // Convert map to array and sort by date
  const result = Array.from(dateMap.values()).sort((a, b) => a.date.getTime() - b.date.getTime());

  return result;
};

/**
 * Check if a booking slot is entirely within business hours
 *
 * Validates that both start and end times of a slot are within business hours.
 *
 * @param startTime - Start time (HH:MM format)
 * @param endTime - End time (HH:MM format)
 * @param businessHours - Business hours configuration
 * @returns True if entire slot is within business hours
 *
 * @example
 * const isValid = isSlotWithinBusinessHours('09:00', '10:30', businessHours);
 */
export const isSlotWithinBusinessHours = (
  startTime: string,
  endTime: string,
  businessHours: BusinessHours
): boolean => {
  return (
    isBusinessHours(startTime, businessHours) &&
    isBusinessHours(endTime, businessHours)
  );
};

/**
 * Calculate available hours per day for a facility
 *
 * Returns the total number of business hours available per day.
 *
 * @param businessHours - Business hours configuration
 * @returns Total available hours for the day
 *
 * @example
 * const hours = calculateDailyAvailableHours({ startTime: '09:00', endTime: '17:00', isOpenOnDay: true });
 * console.log(hours); // 8
 */
export const calculateDailyAvailableHours = (
  businessHours: BusinessHours
): number => {
  if (!businessHours.isOpenOnDay) {
    return 0;
  }

  const [startHour, startMinute] = businessHours.startTime.split(':').map(Number);
  const [endHour, endMinute] = businessHours.endTime.split(':').map(Number);

  const startInMinutes = startHour * 60 + startMinute;
  const endInMinutes = endHour * 60 + endMinute;

  return (endInMinutes - startInMinutes) / 60;
};

/**
 * Get day name in Norwegian locale
 *
 * Returns the full or abbreviated day name in Norwegian.
 *
 * @param date - Date to get day name for
 * @param abbreviated - Whether to return abbreviated name (default: false)
 * @returns Day name in Norwegian
 *
 * @example
 * const dayName = getDayNameNorwegian(new Date(2024, 9, 14)); // Monday
 * console.log(dayName); // "Mandag"
 */
export const getDayNameNorwegian = (
  date: Date,
  abbreviated: boolean = false
): string => {
  const formatStr = abbreviated ? 'EEE' : 'EEEE';
  return format(date, formatStr, { locale: nb });
};

/**
 * Get month name in Norwegian locale
 *
 * Returns the full month name in Norwegian.
 *
 * @param monthNumber - Month number (1-12)
 * @returns Month name in Norwegian
 *
 * @example
 * const monthName = getMonthNameNorwegian(10);
 * console.log(monthName); // "Oktober"
 */
export const getMonthNameNorwegian = (monthNumber: number): string => {
  const date = new Date(2024, monthNumber - 1, 1);
  return format(date, 'MMMM', { locale: nb });
};

/**
 * Check if a date is a weekend
 *
 * Determines if a date falls on a Saturday or Sunday.
 *
 * @param date - Date to check
 * @returns True if date is Saturday or Sunday
 *
 * @example
 * const isWeekend = isWeekendDay(new Date(2024, 9, 12)); // Saturday
 * console.log(isWeekend); // true
 */
export const isWeekendDay = (date: Date): boolean => {
  const day = getDay(date);
  return day === 0 || day === 6; // Sunday or Saturday
};

/**
 * Get default weekly business hours (9 AM to 5 PM, closed Sundays)
 *
 * Returns a standard business hours configuration for a week.
 *
 * @returns Default weekly business hours
 *
 * @example
 * const hours = getDefaultWeeklyBusinessHours();
 * console.log(hours.monday.startTime); // "09:00"
 */
export const getDefaultWeeklyBusinessHours = (): WeeklyBusinessHours => {
  const workdayHours: BusinessHours = {
    startTime: '09:00',
    endTime: '17:00',
    isOpenOnDay: true,
  };

  const saturdayHours: BusinessHours = {
    startTime: '10:00',
    endTime: '16:00',
    isOpenOnDay: true,
  };

  const closedHours: BusinessHours = {
    startTime: '00:00',
    endTime: '00:00',
    isOpenOnDay: false,
  };

  return {
    monday: workdayHours,
    tuesday: workdayHours,
    wednesday: workdayHours,
    thursday: workdayHours,
    friday: workdayHours,
    saturday: saturdayHours,
    sunday: closedHours,
  };
};

/**
 * Get business hours for a specific day of week
 *
 * Retrieves the business hours configuration for a given day.
 *
 * @param date - Date to get business hours for
 * @param weeklyHours - Weekly business hours configuration
 * @returns Business hours for that day
 *
 * @example
 * const hours = getBusinessHoursForDay(new Date(2024, 9, 14), weeklyHours);
 */
export const getBusinessHoursForDay = (
  date: Date,
  weeklyHours: WeeklyBusinessHours
): BusinessHours => {
  const dayOfWeek = getDay(date);

  const dayMap: Record<number, keyof WeeklyBusinessHours> = {
    0: 'sunday',
    1: 'monday',
    2: 'tuesday',
    3: 'wednesday',
    4: 'thursday',
    5: 'friday',
    6: 'saturday',
  };

  const dayKey = dayMap[dayOfWeek];
  return weeklyHours[dayKey];
};

/**
 * Facility Business Logic Service
 *
 * Contains all business logic related to facility operations.
 * NO UI logic, NO component dependencies.
 * Pure business rules and data transformations.
 */

import type { Database } from "@/types/database";

type Facility = Database['public']['Tables']['facilities']['Row'];

export interface IFacilityFilters {
  readonly searchTerm?: string;
  readonly statusFilter?: readonly string[];
  readonly typeFilter?: readonly string[];
  readonly capacityRange?: { readonly min: number; readonly max: number };
}

export interface IFacilitySortConfig {
  readonly sortBy: 'name' | 'capacity' | 'updated_at' | 'created_at';
  readonly sortOrder: 'asc' | 'desc';
}

/**
 * Filter facilities based on search and filter criteria
 */
export const filterFacilities = (
  facilities: readonly Facility[],
  filters: IFacilityFilters
): readonly Facility[] => {
  return facilities.filter(facility => {
    // Search filter
    if (filters.searchTerm) {
      const searchLower = filters.searchTerm.toLowerCase();
      const matchesSearch =
        facility.name.toLowerCase().includes(searchLower) ||
        facility.facility_type.toLowerCase().includes(searchLower) ||
        (facility.address || '').toLowerCase().includes(searchLower);

      if (!matchesSearch) return false;
    }

    // Status filter
    if (filters.statusFilter && filters.statusFilter.length > 0) {
      if (!filters.statusFilter.includes(facility.status)) return false;
    }

    // Type filter
    if (filters.typeFilter && filters.typeFilter.length > 0) {
      if (!filters.typeFilter.includes(facility.facility_type)) return false;
    }

    // Capacity range filter
    if (filters.capacityRange) {
      const { min, max } = filters.capacityRange;
      if (facility.capacity < min || facility.capacity > max) return false;
    }

    return true;
  });
};

/**
 * Sort facilities based on sort configuration
 */
export const sortFacilities = (
  facilities: readonly Facility[],
  sortConfig: IFacilitySortConfig
): readonly Facility[] => {
  const sorted = [...facilities].sort((a, b) => {
    let comparison = 0;

    switch (sortConfig.sortBy) {
      case 'name':
        comparison = a.name.localeCompare(b.name);
        break;
      case 'capacity':
        comparison = a.capacity - b.capacity;
        break;
      case 'updated_at':
        comparison = new Date(a.updated_at).getTime() - new Date(b.updated_at).getTime();
        break;
      case 'created_at':
        comparison = new Date(a.created_at).getTime() - new Date(b.created_at).getTime();
        break;
    }

    return sortConfig.sortOrder === 'asc' ? comparison : -comparison;
  });

  return sorted;
};

/**
 * Get unique facility types from a list of facilities
 */
export const getUniqueFacilityTypes = (facilities: readonly Facility[]): readonly string[] => {
  return Array.from(new Set(facilities.map(f => f.facility_type)));
};

/**
 * Get unique facility statuses
 */
export const getUniqueFacilityStatuses = (): readonly string[] => {
  return ["published", "draft", "archived"];
};

/**
 * Validate if a facility can be deleted
 */
export const canDeleteFacility = (facility: Facility): { canDelete: boolean; reason?: string } => {
  // Business rule: Can't delete published facilities with active bookings (to be implemented)
  // For now, allow all deletions
  return { canDelete: true };
};

/**
 * Validate if facilities can be batch deleted
 */
export const canBatchDeleteFacilities = (
  facilities: readonly Facility[]
): { canDelete: boolean; reason?: string } => {
  // Business rule: Check if any facility has active bookings
  // For now, allow all batch deletions
  return { canDelete: true };
};

/**
 * Calculate facility statistics
 */
export const calculateFacilityStats = (facilities: readonly Facility[]) => {
  const total = facilities.length;
  const published = facilities.filter(f => f.status === 'published').length;
  const draft = facilities.filter(f => f.status === 'draft').length;
  const archived = facilities.filter(f => f.status === 'archived').length;

  return {
    total,
    published,
    draft,
    archived,
    publishedPercentage: total > 0 ? Math.round((published / total) * 100) : 0,
  };
};

/**
 * Format facility for display
 */
export const formatFacilityForDisplay = (facility: Facility) => {
  return {
    ...facility,
    formattedCreatedAt: new Date(facility.created_at).toLocaleDateString('no-NO'),
    formattedUpdatedAt: new Date(facility.updated_at).toLocaleDateString('no-NO'),
    hasAddress: Boolean(facility.address),
    hasImages: Boolean(facility.images && Array.isArray(facility.images) && facility.images.length > 0),
  };
};

/**
 * Validate facility data
 */
export const validateFacilityData = (facility: Partial<Facility>): { isValid: boolean; errors: string[] } => {
  const errors: string[] = [];

  if (!facility.name || facility.name.trim().length < 3) {
    errors.push('Name must be at least 3 characters');
  }

  if (!facility.facility_type) {
    errors.push('Facility type is required');
  }

  if (!facility.capacity || facility.capacity < 1) {
    errors.push('Capacity must be at least 1');
  }

  if (!facility.address) {
    errors.push('Address is required');
  }

  return {
    isValid: errors.length === 0,
    errors,
  };
};

/**
 * Message Business Logic Service
 *
 * Contains all business logic related to message operations.
 * NO UI logic, NO component dependencies.
 * Pure business rules and data transformations.
 */

import type { Message, MessageThread } from "@/types/message";

export interface IMessageFilters {
  readonly searchTerm?: string;
  readonly senderId?: string;
  readonly recipientId?: string;
  readonly status?: readonly Message['status'][];
  readonly hasAttachments?: boolean;
  readonly dateRange?: { readonly from: Date; readonly to: Date };
}

export interface IMessageSortConfig {
  readonly sortBy: 'created_at' | 'sender' | 'status';
  readonly sortOrder: 'asc' | 'desc';
}

export interface IThreadGrouping {
  readonly [threadId: string]: readonly Message[];
}

/**
 * Filter messages based on search and filter criteria
 */
export const filterMessages = (
  messages: readonly Message[],
  filters: IMessageFilters
): readonly Message[] => {
  return messages.filter(message => {
    // Search filter
    if (filters.searchTerm) {
      const searchLower = filters.searchTerm.toLowerCase();
      const matchesSearch =
        message.content.toLowerCase().includes(searchLower) ||
        message.senderName.toLowerCase().includes(searchLower);

      if (!matchesSearch) return false;
    }

    // Sender filter
    if (filters.senderId) {
      if (message.senderId !== filters.senderId) return false;
    }

    // Recipient filter
    if (filters.recipientId) {
      if (message.recipientId !== filters.recipientId) return false;
    }

    // Status filter
    if (filters.status && filters.status.length > 0) {
      if (!filters.status.includes(message.status)) return false;
    }

    // Attachments filter
    if (filters.hasAttachments !== undefined) {
      const hasAttachments = Boolean(message.attachments && message.attachments.length > 0);
      if (filters.hasAttachments !== hasAttachments) return false;
    }

    // Date range filter
    if (filters.dateRange) {
      const messageDate = new Date(message.createdAt);
      if (messageDate < filters.dateRange.from || messageDate > filters.dateRange.to) {
        return false;
      }
    }

    return true;
  });
};

/**
 * Sort messages based on sort configuration
 */
export const sortMessages = (
  messages: readonly Message[],
  sortConfig: IMessageSortConfig
): readonly Message[] => {
  const sorted = [...messages].sort((a, b) => {
    let comparison = 0;

    switch (sortConfig.sortBy) {
      case 'created_at':
        comparison = new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime();
        break;
      case 'sender':
        comparison = a.senderName.localeCompare(b.senderName);
        break;
      case 'status':
        comparison = a.status.localeCompare(b.status);
        break;
    }

    return sortConfig.sortOrder === 'asc' ? comparison : -comparison;
  });

  return sorted;
};

/**
 * Group messages by thread
 */
export const groupMessagesByThread = (
  messages: readonly Message[]
): IThreadGrouping => {
  return messages.reduce((grouped, message) => {
    const threadId = message.threadId;
    const existing = grouped[threadId] || [];

    return {
      ...grouped,
      [threadId]: [...existing, message],
    };
  }, {} as IThreadGrouping);
};

/**
 * Mark messages as read for a specific user
 */
export const markAsRead = (
  messages: readonly Message[],
  userId: string,
  threadId?: string
): readonly Message[] => {
  const now = new Date().toISOString();

  return messages.map(message => {
    // Only mark messages where the user is the recipient
    const isRecipient = message.recipientId === userId;
    const isInThread = !threadId || message.threadId === threadId;
    const isUnread = message.status !== 'read';

    if (isRecipient && isInThread && isUnread) {
      return {
        ...message,
        status: 'read' as const,
        readAt: now,
      };
    }

    return message;
  });
};

/**
 * Validate message data
 */
export const validateMessageData = (message: Partial<Message>): { isValid: boolean; errors: string[] } => {
  const errors: string[] = [];

  if (!message.content || message.content.trim().length === 0) {
    errors.push('Message content cannot be empty');
  }

  if (message.content && message.content.length > 10000) {
    errors.push('Message content exceeds maximum length of 10,000 characters');
  }

  if (!message.senderId) {
    errors.push('Sender ID is required');
  }

  if (!message.recipientId) {
    errors.push('Recipient ID is required');
  }

  if (!message.threadId) {
    errors.push('Thread ID is required');
  }

  // Validate attachments
  if (message.attachments && message.attachments.length > 0) {
    const totalSize = message.attachments.reduce((sum, att) => sum + att.size, 0);
    const maxSize = 25 * 1024 * 1024; // 25MB total

    if (totalSize > maxSize) {
      errors.push('Total attachment size exceeds 25MB limit');
    }

    if (message.attachments.length > 10) {
      errors.push('Cannot attach more than 10 files per message');
    }
  }

  return {
    isValid: errors.length === 0,
    errors,
  };
};

/**
 * Validate if a message can be deleted
 */
export const canDeleteMessage = (
  message: Message,
  userId: string,
  userRole?: 'tenant' | 'landlord' | 'admin'
): { canDelete: boolean; reason?: string } => {
  // Business rule: Users can delete their own messages
  if (message.senderId === userId) {
    return { canDelete: true };
  }

  // Business rule: Admins can delete any message
  if (userRole === 'admin') {
    return { canDelete: true };
  }

  return {
    canDelete: false,
    reason: 'You can only delete your own messages.'
  };
};

/**
 * Validate if a message can be edited
 */
export const canEditMessage = (
  message: Message,
  userId: string,
  timeWindowMinutes: number = 15
): { canEdit: boolean; reason?: string } => {
  // Business rule: Users can only edit their own messages
  if (message.senderId !== userId) {
    return {
      canEdit: false,
      reason: 'You can only edit your own messages.'
    };
  }

  // Business rule: Cannot edit read messages
  if (message.status === 'read') {
    return {
      canEdit: false,
      reason: 'Cannot edit messages that have been read.'
    };
  }

  // Business rule: Can only edit within time window
  const messageTime = new Date(message.createdAt).getTime();
  const now = Date.now();
  const timeWindowMs = timeWindowMinutes * 60 * 1000;

  if (now - messageTime > timeWindowMs) {
    return {
      canEdit: false,
      reason: `Messages can only be edited within ${timeWindowMinutes} minutes of sending.`
    };
  }

  return { canEdit: true };
};

/**
 * Calculate unread count for a user
 */
export const calculateUnreadCount = (
  messages: readonly Message[],
  userId: string
): number => {
  return messages.filter(
    message => message.recipientId === userId && message.status !== 'read'
  ).length;
};

/**
 * Calculate unread count per thread
 */
export const calculateUnreadCountPerThread = (
  messages: readonly Message[],
  userId: string
): ReadonlyMap<string, number> => {
  const unreadByThread = new Map<string, number>();

  messages.forEach(message => {
    if (message.recipientId === userId && message.status !== 'read') {
      const currentCount = unreadByThread.get(message.threadId) || 0;
      unreadByThread.set(message.threadId, currentCount + 1);
    }
  });

  return unreadByThread;
};

/**
 * Get most recent message per thread
 */
export const getMostRecentMessagePerThread = (
  messages: readonly Message[]
): ReadonlyMap<string, Message> => {
  const mostRecentByThread = new Map<string, Message>();

  messages.forEach(message => {
    const existing = mostRecentByThread.get(message.threadId);

    if (!existing || new Date(message.createdAt) > new Date(existing.createdAt)) {
      mostRecentByThread.set(message.threadId, message);
    }
  });

  return mostRecentByThread;
};

/**
 * Calculate message statistics for a thread
 */
export const calculateThreadStats = (
  messages: readonly Message[],
  threadId: string
) => {
  const threadMessages = messages.filter(m => m.threadId === threadId);

  const totalMessages = threadMessages.length;
  const unreadMessages = threadMessages.filter(m => m.status !== 'read').length;
  const messagesWithAttachments = threadMessages.filter(
    m => m.attachments && m.attachments.length > 0
  ).length;

  const senders = new Set(threadMessages.map(m => m.senderId));
  const participantCount = senders.size;

  return {
    totalMessages,
    unreadMessages,
    messagesWithAttachments,
    participantCount,
  };
};

/**
 * Format message for display
 */
export const formatMessageForDisplay = (message: Message) => {
  return {
    ...message,
    formattedCreatedAt: new Date(message.createdAt).toLocaleString('no-NO'),
    formattedReadAt: message.readAt ? new Date(message.readAt).toLocaleString('no-NO') : undefined,
    isUnread: message.status !== 'read',
    hasAttachments: Boolean(message.attachments && message.attachments.length > 0),
    attachmentCount: message.attachments?.length || 0,
    contentPreview: message.content.length > 100
      ? message.content.substring(0, 100) + '...'
      : message.content,
  };
};

