/**
 * User Business Logic Service
 *
 * Contains all business logic related to user operations.
 * NO UI logic, NO component dependencies.
 * Pure business rules and data transformations.
 *
 * @module services/business/user.business.service
 */

import type { Database } from "@/types/database";
import type { OrgRole } from "@/constants/roles";
import {
  ROLE_PRIORITY,
  normalizeRole,
  hasMinimumRole,
  ORG_ROLES,
} from "@/constants/roles";

type Profile = Database['public']['Tables']['profiles']['Row'];
type Membership = Database['public']['Tables']['memberships']['Row'];

/**
 * Extended user profile with role information
 */
export interface IUserWithRole extends Profile {
  readonly role?: OrgRole;
  readonly membership?: Membership;
  readonly lastLogin?: string;
}

/**
 * User filter configuration
 */
export interface IUserFilters {
  readonly searchTerm?: string;
  readonly roleFilter?: readonly OrgRole[];
  readonly statusFilter?: readonly ('active' | 'inactive' | 'suspended')[];
  readonly organizationFilter?: string;
}

/**
 * User sort configuration
 */
export interface IUserSortConfig {
  readonly sortBy: 'display_name' | 'email' | 'role' | 'last_login' | 'created_at';
  readonly sortOrder: 'asc' | 'desc';
}

/**
 * User validation result
 */
export interface IUserValidationResult {
  readonly isValid: boolean;
  readonly errors: readonly string[];
}

/**
 * Role change validation result
 */
export interface IRoleChangeValidationResult {
  readonly canChange: boolean;
  readonly reason?: string;
}

/**
 * User deletion validation result
 */
export interface IUserDeletionValidationResult {
  readonly canDelete: boolean;
  readonly reason?: string;
  readonly warnings?: readonly string[];
}

/**
 * User statistics
 */
export interface IUserStatistics {
  readonly total: number;
  readonly byRole: Readonly<Record<OrgRole, number>>;
  readonly active: number;
  readonly inactive: number;
  readonly suspended: number;
  readonly activePercentage: number;
}

/**
 * User permissions based on role
 */
export interface IUserPermissions {
  readonly canManageUsers: boolean;
  readonly canManageFacilities: boolean;
  readonly canManageBookings: boolean;
  readonly canViewReports: boolean;
  readonly canExportData: boolean;
  readonly canManageOrganization: boolean;
  readonly canManageRoles: boolean;
  readonly canManageBilling: boolean;
  readonly canViewAuditLogs: boolean;
  readonly isReadOnly: boolean;
}

/**
 * Filter users based on search and filter criteria
 *
 * @param users - Array of users to filter
 * @param filters - Filter configuration
 * @returns Filtered array of users
 *
 * @example
 * ```typescript
 * const activeAdmins = filterUsers(users, {
 *   roleFilter: ['admin'],
 *   statusFilter: ['active']
 * });
 * ```
 */
export const filterUsers = (
  users: readonly IUserWithRole[],
  filters: IUserFilters
): readonly IUserWithRole[] => {
  return users.filter(user => {
    // Search filter - search by name, email, or phone
    if (filters.searchTerm) {
      const searchLower = filters.searchTerm.toLowerCase();
      const matchesSearch =
        (user.display_name || '').toLowerCase().includes(searchLower) ||
        (user.email || '').toLowerCase().includes(searchLower) ||
        (user.phone || '').toLowerCase().includes(searchLower);

      if (!matchesSearch) return false;
    }

    // Role filter
    if (filters.roleFilter && filters.roleFilter.length > 0 && user.role) {
      const normalizedUserRole = normalizeRole(user.role);
      if (!filters.roleFilter.includes(normalizedUserRole)) return false;
    }

    // Status filter (based on profile status or membership)
    if (filters.statusFilter && filters.statusFilter.length > 0) {
      // Determine user status
      // For now, consider all users as 'active' unless we have explicit status field
      const userStatus: 'active' | 'inactive' | 'suspended' = 'active';
      if (!filters.statusFilter.includes(userStatus)) return false;
    }

    // Organization filter
    if (filters.organizationFilter && user.membership) {
      if (user.membership.org_id !== filters.organizationFilter) return false;
    }

    return true;
  });
};

/**
 * Sort users based on sort configuration
 *
 * @param users - Array of users to sort
 * @param sortConfig - Sort configuration
 * @returns Sorted array of users
 *
 * @example
 * ```typescript
 * const sortedUsers = sortUsers(users, {
 *   sortBy: 'display_name',
 *   sortOrder: 'asc'
 * });
 * ```
 */
export const sortUsers = (
  users: readonly IUserWithRole[],
  sortConfig: IUserSortConfig
): readonly IUserWithRole[] => {
  const sorted = [...users].sort((a, b) => {
    let comparison = 0;

    switch (sortConfig.sortBy) {
      case 'display_name':
        comparison = (a.display_name || '').localeCompare(b.display_name || '');
        break;
      case 'email':
        comparison = (a.email || '').localeCompare(b.email || '');
        break;
      case 'role':
        // Sort by role priority
        const aPriority = a.role ? ROLE_PRIORITY[normalizeRole(a.role)] : 0;
        const bPriority = b.role ? ROLE_PRIORITY[normalizeRole(b.role)] : 0;
        comparison = bPriority - aPriority; // Higher priority first
        break;
      case 'last_login':
        const aLogin = a.lastLogin || a.updated_at || a.created_at;
        const bLogin = b.lastLogin || b.updated_at || b.created_at;
        comparison = new Date(aLogin).getTime() - new Date(bLogin).getTime();
        break;
      case 'created_at':
        comparison = new Date(a.created_at).getTime() - new Date(b.created_at).getTime();
        break;
    }

    return sortConfig.sortOrder === 'asc' ? comparison : -comparison;
  });

  return sorted;
};

/**
 * Validate user data for creation or update
 *
 * @param userData - Partial user data to validate
 * @returns Validation result with errors
 *
 * @example
 * ```typescript
 * const result = validateUserData({
 *   email: 'user@example.com',
 *   display_name: 'John Doe'
 * });
 * if (!result.isValid) {
 *   console.error(result.errors);
 * }
 * ```
 */
export const validateUserData = (
  userData: Partial<Profile> & { readonly password?: string }
): IUserValidationResult => {
  const errors: string[] = [];

  // Email validation
  if (userData.email !== undefined) {
    if (!userData.email || userData.email.trim().length === 0) {
      errors.push('Email is required');
    } else {
      // Basic email format validation
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(userData.email)) {
        errors.push('Invalid email format');
      }
    }
  }

  // Display name validation
  if (userData.display_name !== undefined) {
    if (userData.display_name && userData.display_name.trim().length < 2) {
      errors.push('Display name must be at least 2 characters');
    }
    if (userData.display_name && userData.display_name.trim().length > 100) {
      errors.push('Display name must not exceed 100 characters');
    }
  }

  // Phone validation (if provided)
  if (userData.phone && userData.phone.trim().length > 0) {
    // Basic phone format validation (international format)
    const phoneRegex = /^\+?[\d\s\-()]{8,}$/;
    if (!phoneRegex.test(userData.phone)) {
      errors.push('Invalid phone number format');
    }
  }

  // Password validation (if provided for new users)
  if (userData.password !== undefined) {
    if (userData.password.length < 8) {
      errors.push('Password must be at least 8 characters');
    }
    if (!/[A-Z]/.test(userData.password)) {
      errors.push('Password must contain at least one uppercase letter');
    }
    if (!/[a-z]/.test(userData.password)) {
      errors.push('Password must contain at least one lowercase letter');
    }
    if (!/\d/.test(userData.password)) {
      errors.push('Password must contain at least one number');
    }
  }

  return {
    isValid: errors.length === 0,
    errors,
  };
};

/**
 * Validate if a role change is allowed
 *
 * Business rules:
 * - Only owners and admins can change roles
 * - Cannot change your own role
 * - Cannot promote users to a role higher than your own
 * - Owner role requires special approval
 *
 * @param currentUserRole - Role of the user making the change
 * @param targetUserId - ID of user whose role is being changed
 * @param currentUserId - ID of user making the change
 * @param newRole - New role to assign
 * @returns Validation result
 *
 * @example
 * ```typescript
 * const result = validateRoleChange('admin', 'user123', 'admin456', 'case_handler');
 * if (!result.canChange) {
 *   console.error(result.reason);
 * }
 * ```
 */
export const validateRoleChange = (
  currentUserRole: OrgRole,
  targetUserId: string,
  currentUserId: string,
  newRole: OrgRole
): IRoleChangeValidationResult => {
  // Normalize roles
  const normalizedCurrentRole = normalizeRole(currentUserRole);
  const normalizedNewRole = normalizeRole(newRole);

  // Only owners and admins can change roles
  if (!hasMinimumRole(normalizedCurrentRole, ORG_ROLES.ADMIN as OrgRole)) {
    return {
      canChange: false,
      reason: 'Only owners and administrators can change user roles',
    };
  }

  // Cannot change your own role
  if (targetUserId === currentUserId) {
    return {
      canChange: false,
      reason: 'You cannot change your own role. Contact another administrator.',
    };
  }

  // Cannot promote users to a role higher than your own
  const currentRolePriority = ROLE_PRIORITY[normalizedCurrentRole];
  const newRolePriority = ROLE_PRIORITY[normalizedNewRole];

  if (newRolePriority > currentRolePriority) {
    return {
      canChange: false,
      reason: 'You cannot assign a role with higher privileges than your own',
    };
  }

  // Only owners can assign the owner role
  if (normalizedNewRole === ORG_ROLES.OWNER && normalizedCurrentRole !== ORG_ROLES.OWNER) {
    return {
      canChange: false,
      reason: 'Only organization owners can assign the owner role',
    };
  }

  return {
    canChange: true,
  };
};

/**
 * Validate if a user can be deleted
 *
 * Business rules:
 * - Cannot delete yourself
 * - Cannot delete the last owner of an organization
 * - Warn if user has active bookings
 * - Warn if user owns facilities
 *
 * @param targetUserId - ID of user to delete
 * @param currentUserId - ID of user requesting deletion
 * @param targetUserRole - Role of user to be deleted
 * @param isLastOwner - Whether user is the last owner of the organization
 * @param hasActiveBookings - Whether user has active bookings
 * @param ownsFacilities - Whether user owns facilities
 * @returns Validation result with warnings
 *
 * @example
 * ```typescript
 * const result = canDeleteUser('user123', 'admin456', 'customer', false, true, false);
 * if (!result.canDelete) {
 *   console.error(result.reason);
 * }
 * ```
 */
export const canDeleteUser = (
  targetUserId: string,
  currentUserId: string,
  targetUserRole: OrgRole,
  isLastOwner: boolean = false,
  hasActiveBookings: boolean = false,
  ownsFacilities: boolean = false
): IUserDeletionValidationResult => {
  const warnings: string[] = [];

  // Cannot delete yourself
  if (targetUserId === currentUserId) {
    return {
      canDelete: false,
      reason: 'You cannot delete your own account. Contact another administrator.',
    };
  }

  // Cannot delete the last owner
  if (isLastOwner && targetUserRole === ORG_ROLES.OWNER) {
    return {
      canDelete: false,
      reason: 'Cannot delete the last owner of the organization. Assign another owner first.',
    };
  }

  // Warning for active bookings
  if (hasActiveBookings) {
    warnings.push('User has active bookings. These will need to be reassigned or cancelled.');
  }

  // Warning for owned facilities
  if (ownsFacilities) {
    warnings.push('User owns facilities. These will need to be reassigned to another user.');
  }

  return {
    canDelete: true,
    warnings: warnings.length > 0 ? warnings : undefined,
  };
};

/**
 * Validate if a user can be suspended
 *
 * Business rules:
 * - Cannot suspend yourself
 * - Cannot suspend the last owner
 * - Only admins and owners can suspend users
 *
 * @param targetUserId - ID of user to suspend
 * @param currentUserId - ID of user requesting suspension
 * @param targetUserRole - Role of user to be suspended
 * @param isLastOwner - Whether user is the last owner
 * @returns Validation result
 *
 * @example
 * ```typescript
 * const result = canSuspendUser('user123', 'admin456', 'customer', false);
 * if (!result.canChange) {
 *   console.error(result.reason);
 * }
 * ```
 */
export const canSuspendUser = (
  targetUserId: string,
  currentUserId: string,
  targetUserRole: OrgRole,
  isLastOwner: boolean = false
): IRoleChangeValidationResult => {
  // Cannot suspend yourself
  if (targetUserId === currentUserId) {
    return {
      canChange: false,
      reason: 'You cannot suspend your own account.',
    };
  }

  // Cannot suspend the last owner
  if (isLastOwner && targetUserRole === ORG_ROLES.OWNER) {
    return {
      canChange: false,
      reason: 'Cannot suspend the last owner of the organization.',
    };
  }

  return {
    canChange: true,
  };
};

/**
 * Calculate user statistics
 *
 * @param users - Array of users with role information
 * @returns Statistics object
 *
 * @example
 * ```typescript
 * const stats = calculateUserStats(users);
 * console.log(`Total users: ${stats.total}, Active: ${stats.activePercentage}%`);
 * ```
 */
export const calculateUserStats = (
  users: readonly IUserWithRole[]
): IUserStatistics => {
  const total = users.length;

  // Count by role
  const byRole: Record<OrgRole, number> = {
    owner: 0,
    admin: 0,
    case_handler: 0,
    editor: 0,
    read_only: 0,
    customer: 0,
    staff: 0,
  };

  users.forEach(user => {
    if (user.role) {
      const normalizedRole = normalizeRole(user.role);
      byRole[normalizedRole] = (byRole[normalizedRole] || 0) + 1;
    }
  });

  // For now, consider all users as active
  // In the future, this should check actual status field
  const active = total;
  const inactive = 0;
  const suspended = 0;

  return {
    total,
    byRole,
    active,
    inactive,
    suspended,
    activePercentage: total > 0 ? Math.round((active / total) * 100) : 0,
  };
};

/**
 * Get user permissions based on role
 *
 * @param role - User's organization role
 * @returns Permissions object
 *
 * @example
 * ```typescript
 * const permissions = getUserPermissions('admin');
 * if (permissions.canManageUsers) {
 *   // Show user management UI
 * }
 * ```
 */
export const getUserPermissions = (
  role: OrgRole | null | undefined
): IUserPermissions => {
  if (!role) {
    return {
      canManageUsers: false,
      canManageFacilities: false,
      canManageBookings: false,
      canViewReports: false,
      canExportData: false,
      canManageOrganization: false,
      canManageRoles: false,
      canManageBilling: false,
      canViewAuditLogs: false,
      isReadOnly: true,
    };
  }

  const normalizedRole = normalizeRole(role);

  // Owner has all permissions
  if (normalizedRole === ORG_ROLES.OWNER) {
    return {
      canManageUsers: true,
      canManageFacilities: true,
      canManageBookings: true,
      canViewReports: true,
      canExportData: true,
      canManageOrganization: true,
      canManageRoles: true,
      canManageBilling: true,
      canViewAuditLogs: true,
      isReadOnly: false,
    };
  }

  // Admin has most permissions except billing
  if (normalizedRole === ORG_ROLES.ADMIN) {
    return {
      canManageUsers: true,
      canManageFacilities: true,
      canManageBookings: true,
      canViewReports: true,
      canExportData: true,
      canManageOrganization: true,
      canManageRoles: true,
      canManageBilling: false,
      canViewAuditLogs: true,
      isReadOnly: false,
    };
  }

  // Case handler can manage bookings and view reports
  if (normalizedRole === ORG_ROLES.CASE_HANDLER) {
    return {
      canManageUsers: false,
      canManageFacilities: false,
      canManageBookings: true,
      canViewReports: true,
      canExportData: true,
      canManageOrganization: false,
      canManageRoles: false,
      canManageBilling: false,
      canViewAuditLogs: false,
      isReadOnly: false,
    };
  }

  // Editor can manage facilities and content
  if (normalizedRole === ORG_ROLES.EDITOR) {
    return {
      canManageUsers: false,
      canManageFacilities: true,
      canManageBookings: false,
      canViewReports: true,
      canExportData: false,
      canManageOrganization: false,
      canManageRoles: false,
      canManageBilling: false,
      canViewAuditLogs: false,
      isReadOnly: false,
    };
  }

  // Read-only can only view
  if (normalizedRole === ORG_ROLES.READ_ONLY) {
    return {
      canManageUsers: false,
      canManageFacilities: false,
      canManageBookings: false,
      canViewReports: true,
      canExportData: true,
      canManageOrganization: false,
      canManageRoles: false,
      canManageBilling: false,
      canViewAuditLogs: false,
      isReadOnly: true,
    };
  }

  // Customer (default) - minimal permissions
  return {
    canManageUsers: false,
    canManageFacilities: false,
    canManageBookings: false,
    canViewReports: false,
    canExportData: false,
    canManageOrganization: false,
    canManageRoles: false,
    canManageBilling: false,
    canViewAuditLogs: false,
    isReadOnly: true,
  };
};

/**
 * Get unique user roles from a list of users
 *
 * @param users - Array of users
 * @returns Array of unique roles
 *
 * @example
 * ```typescript
 * const roles = getUniqueUserRoles(users);
 * // ['owner', 'admin', 'customer']
 * ```
 */
export const getUniqueUserRoles = (
  users: readonly IUserWithRole[]
): readonly OrgRole[] => {
  const roles = users
    .map(u => u.role)
    .filter((role): role is OrgRole => role !== undefined && role !== null)
    .map(role => normalizeRole(role));

  return Array.from(new Set(roles));
};

/**
 * Format user for display purposes
 *
 * @param user - User profile
 * @returns Formatted user object with display properties
 *
 * @example
 * ```typescript
 * const displayUser = formatUserForDisplay(user);
 * console.log(displayUser.formattedCreatedAt); // "29.10.2025"
 * ```
 */
export const formatUserForDisplay = (user: IUserWithRole) => {
  return {
    ...user,
    formattedCreatedAt: new Date(user.created_at).toLocaleDateString('no-NO'),
    formattedUpdatedAt: user.updated_at
      ? new Date(user.updated_at).toLocaleDateString('no-NO')
      : null,
    hasPhone: Boolean(user.phone),
    hasAvatar: Boolean(user.avatar_url),
    displayRole: user.role || 'customer',
  };
};

/**
 * Check if user email is from a trusted domain
 *
 * @param email - Email address to check
 * @param trustedDomains - Array of trusted domains
 * @returns True if email domain is trusted
 *
 * @example
 * ```typescript
 * const isTrusted = isEmailFromTrustedDomain('user@company.com', ['company.com']);
 * // true
 * ```
 */
export const isEmailFromTrustedDomain = (
  email: string,
  trustedDomains: readonly string[]
): boolean => {
  const emailDomain = email.split('@')[1]?.toLowerCase();
  if (!emailDomain) return false;

  return trustedDomains.some(domain =>
    emailDomain === domain.toLowerCase()
  );
};

/**
 * Generate user initials from display name or email
 *
 * @param user - User profile
 * @returns User initials (up to 2 characters)
 *
 * @example
 * ```typescript
 * const initials = getUserInitials({ display_name: 'John Doe', email: 'j@example.com' });
 * // "JD"
 * ```
 */
export const getUserInitials = (user: Pick<Profile, 'display_name' | 'email'>): string => {
  if (user.display_name) {
    const parts = user.display_name.trim().split(/\s+/);
    if (parts.length >= 2) {
      return (parts[0][0] + parts[1][0]).toUpperCase();
    }
    return user.display_name.substring(0, 2).toUpperCase();
  }

  if (user.email) {
    return user.email.substring(0, 2).toUpperCase();
  }

  return 'U';
};

/**
 * Zone Business Logic Service
 *
 * Contains all business logic related to zone operations.
 * NO UI logic, NO component dependencies.
 * Pure business rules and data transformations.
 */

import type { Zone } from '@/types/booking';

export interface IZoneFilters {
  readonly searchTerm?: string;
  readonly facilityId?: string;
  readonly capacityRange?: { readonly min: number; readonly max: number };
  readonly priceRange?: { readonly min: number; readonly max: number };
}

export interface IZoneSortConfig {
  readonly sortBy: 'name' | 'capacity' | 'pricePerHour';
  readonly sortOrder: 'asc' | 'desc';
}

export interface ZoneValidationResult {
  readonly isValid: boolean;
  readonly errors: readonly string[];
}

export interface ZoneDeleteCheckResult {
  readonly canDelete: boolean;
  readonly reason?: string;
}

export interface ZoneUtilizationStats {
  readonly zoneId: string;
  readonly name: string;
  readonly totalCapacity: number;
  readonly utilizationPercentage: number;
  readonly averageOccupancy: number;
}

export interface ZonesByFacility {
  readonly facilityId: string;
  readonly zones: readonly Zone[];
  readonly totalCapacity: number;
  readonly zoneCount: number;
}

export interface AvailableZone {
  readonly zone: Zone;
  readonly availableCapacity: number;
  readonly isFullyAvailable: boolean;
}

/**
 * Filter zones based on search and filter criteria
 *
 * @param zones - Array of zones to filter
 * @param filters - Filter configuration
 * @returns Filtered array of zones
 */
export const filterZones = (
  zones: readonly Zone[],
  filters: IZoneFilters
): readonly Zone[] => {
  return zones.filter(zone => {
    // Search filter - searches in name, description, and amenities
    if (filters.searchTerm) {
      const searchLower = filters.searchTerm.toLowerCase();
      const matchesSearch =
        zone.name.toLowerCase().includes(searchLower) ||
        (zone.description || '').toLowerCase().includes(searchLower) ||
        zone.amenities.some(amenity =>
          amenity.toLowerCase().includes(searchLower)
        );

      if (!matchesSearch) return false;
    }

    // Facility filter
    if (filters.facilityId) {
      if (zone.facilityId !== filters.facilityId) return false;
    }

    // Capacity range filter
    if (filters.capacityRange) {
      const { min, max } = filters.capacityRange;
      if (zone.capacity < min || zone.capacity > max) return false;
    }

    // Price range filter
    if (filters.priceRange) {
      const { min, max } = filters.priceRange;
      if (zone.pricePerHour < min || zone.pricePerHour > max) return false;
    }

    return true;
  });
};

/**
 * Sort zones based on sort configuration
 *
 * @param zones - Array of zones to sort
 * @param sortConfig - Sort configuration
 * @returns Sorted array of zones
 */
export const sortZones = (
  zones: readonly Zone[],
  sortConfig: IZoneSortConfig
): readonly Zone[] => {
  const sorted = [...zones].sort((a, b) => {
    let comparison = 0;

    switch (sortConfig.sortBy) {
      case 'name':
        comparison = a.name.localeCompare(b.name);
        break;
      case 'capacity':
        comparison = a.capacity - b.capacity;
        break;
      case 'pricePerHour':
        comparison = a.pricePerHour - b.pricePerHour;
        break;
    }

    return sortConfig.sortOrder === 'asc' ? comparison : -comparison;
  });

  return sorted;
};

/**
 * Validate zone form data
 *
 * @param zone - Partial zone data to validate
 * @returns Validation result with errors
 */
export const validateZoneData = (zone: Partial<Zone>): ZoneValidationResult => {
  const errors: string[] = [];

  // Validate name
  if (!zone.name || zone.name.trim().length < 2) {
    errors.push('Zone name must be at least 2 characters');
  }

  if (zone.name && zone.name.length > 100) {
    errors.push('Zone name must not exceed 100 characters');
  }

  // Validate facility ID
  if (!zone.facilityId) {
    errors.push('Facility ID is required');
  }

  // Validate capacity
  if (!zone.capacity || zone.capacity < 1) {
    errors.push('Capacity must be at least 1 person');
  }

  if (zone.capacity && zone.capacity > 10000) {
    errors.push('Capacity cannot exceed 10000 people');
  }

  // Validate price per hour
  if (zone.pricePerHour === undefined || zone.pricePerHour < 0) {
    errors.push('Price per hour must be a non-negative number');
  }

  if (zone.pricePerHour && zone.pricePerHour > 999999) {
    errors.push('Price per hour is too high');
  }

  // Validate area if provided
  if (zone.area !== undefined && zone.area !== null) {
    if (zone.area < 0) {
      errors.push('Area cannot be negative');
    }

    if (zone.area > 999999) {
      errors.push('Area value is too high');
    }
  }

  // Validate description if provided
  if (zone.description && zone.description.length > 1000) {
    errors.push('Description must not exceed 1000 characters');
  }

  // Validate amenities if provided
  if (zone.amenities && !Array.isArray(zone.amenities)) {
    errors.push('Amenities must be an array');
  }

  if (zone.amenities && zone.amenities.length > 50) {
    errors.push('Cannot have more than 50 amenities');
  }

  // Validate availability if provided
  if (zone.availability) {
    const daysOfWeek = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'] as const;

    for (const day of daysOfWeek) {
      const dayAvailability = zone.availability[day];
      if (dayAvailability) {
        if (!isValidTimeFormat(dayAvailability.start)) {
          errors.push(`Invalid start time for ${day}`);
        }

        if (!isValidTimeFormat(dayAvailability.end)) {
          errors.push(`Invalid end time for ${day}`);
        }

        // Check if start time is before end time
        if (
          isValidTimeFormat(dayAvailability.start) &&
          isValidTimeFormat(dayAvailability.end)
        ) {
          const startMinutes = timeToMinutes(dayAvailability.start);
          const endMinutes = timeToMinutes(dayAvailability.end);

          if (startMinutes >= endMinutes) {
            errors.push(`Start time must be before end time for ${day}`);
          }
        }
      }
    }
  }

  return {
    isValid: errors.length === 0,
    errors: errors as readonly string[],
  };
};

/**
 * Check if a zone can be deleted based on business rules
 *
 * @param zone - Zone to check for deletion
 * @param activeBookingCount - Number of active bookings for this zone
 * @returns Deletion check result with reason if cannot delete
 */
export const canDeleteZone = (
  zone: Zone,
  activeBookingCount: number
): ZoneDeleteCheckResult => {
  // Business rule: Cannot delete zones with active bookings
  if (activeBookingCount > 0) {
    return {
      canDelete: false,
      reason: `Cannot delete zone with ${activeBookingCount} active booking(s). Please cancel all bookings before deletion.`,
    };
  }

  return { canDelete: true };
};

/**
 * Calculate zone utilization percentage
 *
 * @param zone - Zone to calculate utilization for
 * @param currentOccupancy - Current number of occupants
 * @returns Utilization percentage (0-100)
 */
export const calculateZoneUtilization = (
  zone: Zone,
  currentOccupancy: number
): number => {
  if (zone.capacity === 0) {
    return 0;
  }

  const utilization = (currentOccupancy / zone.capacity) * 100;
  // Clamp between 0 and 100
  return Math.max(0, Math.min(100, Math.round(utilization)));
};

/**
 * Find zones available for a specific time slot
 *
 * @param zones - All zones to search
 * @param dayOfWeek - Day of the week (0-6, where 0 is Sunday)
 * @param timeSlot - Time slot to check (HH:mm format)
 * @param facilityId - Optional: filter by facility
 * @param minimumCapacity - Optional: minimum required capacity
 * @returns Array of available zones for the time slot
 */
export const findAvailableZones = (
  zones: readonly Zone[],
  dayOfWeek: number,
  timeSlot: string,
  facilityId?: string,
  minimumCapacity?: number
): readonly Zone[] => {
  const daysMap = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'] as const;
  const dayName = daysMap[dayOfWeek % 7];

  return zones.filter(zone => {
    // Filter by facility if specified
    if (facilityId && zone.facilityId !== facilityId) {
      return false;
    }

    // Filter by minimum capacity if specified
    if (minimumCapacity && zone.capacity < minimumCapacity) {
      return false;
    }

    // Check availability for the day
    const dayAvailability = zone.availability[dayName];
    if (!dayAvailability) {
      return false;
    }

    // Check if time slot falls within available hours
    const slotMinutes = timeToMinutes(timeSlot);
    const startMinutes = timeToMinutes(dayAvailability.start);
    const endMinutes = timeToMinutes(dayAvailability.end);

    return slotMinutes >= startMinutes && slotMinutes < endMinutes;
  });
};

/**
 * Group zones by facility for display
 *
 * @param zones - All zones to group
 * @returns Array of zones grouped by facility with metadata
 */
export const groupZonesByFacility = (
  zones: readonly Zone[]
): readonly ZonesByFacility[] => {
  const grouped = new Map<string, Zone[]>();

  // Group zones by facility ID
  for (const zone of zones) {
    if (!grouped.has(zone.facilityId)) {
      grouped.set(zone.facilityId, []);
    }
    grouped.get(zone.facilityId)!.push(zone);
  }

  // Convert to array with metadata
  return Array.from(grouped.entries()).map(([facilityId, facilityZones]) => ({
    facilityId,
    zones: facilityZones as readonly Zone[],
    totalCapacity: facilityZones.reduce((sum, zone) => sum + zone.capacity, 0),
    zoneCount: facilityZones.length,
  }));
};

/**
 * Get average price per hour across zones
 *
 * @param zones - Array of zones
 * @returns Average price per hour, or 0 if no zones
 */
export const getAveragePricePerHour = (zones: readonly Zone[]): number => {
  if (zones.length === 0) {
    return 0;
  }

  const totalPrice = zones.reduce((sum, zone) => sum + zone.pricePerHour, 0);
  return Math.round((totalPrice / zones.length) * 100) / 100;
};

/**
 * Get zones with minimum and maximum capacities
 *
 * @param zones - Array of zones
 * @returns Object with min and max capacity zones
 */
export const getZoneCapacityBounds = (zones: readonly Zone[]) => {
  if (zones.length === 0) {
    return { minCapacity: 0, maxCapacity: 0, minZone: null, maxZone: null };
  }

  const sorted = [...zones].sort((a, b) => a.capacity - b.capacity);

  return {
    minCapacity: sorted[0].capacity,
    maxCapacity: sorted[sorted.length - 1].capacity,
    minZone: sorted[0],
    maxZone: sorted[sorted.length - 1],
  };
};

/**
 * Get unique amenities across all zones
 *
 * @param zones - Array of zones
 * @returns Array of unique amenities
 */
export const getUniqueAmenities = (zones: readonly Zone[]): readonly string[] => {
  const amenitiesSet = new Set<string>();

  for (const zone of zones) {
    for (const amenity of zone.amenities) {
      amenitiesSet.add(amenity);
    }
  }

  return Array.from(amenitiesSet).sort();
};

/**
 * Calculate total capacity across multiple zones
 *
 * @param zones - Array of zones
 * @returns Total capacity sum
 */
export const calculateTotalCapacity = (zones: readonly Zone[]): number => {
  return zones.reduce((sum, zone) => sum + zone.capacity, 0);
};

/**
 * Find zones that match specific criteria
 *
 * @param zones - Array of zones to search
 * @param predicateFn - Function to test each zone
 * @returns Matching zones
 */
export const findZonesByCriteria = (
  zones: readonly Zone[],
  predicateFn: (zone: Zone) => boolean
): readonly Zone[] => {
  return zones.filter(predicateFn);
};

/**
 * Check if zone has specific amenity
 *
 * @param zone - Zone to check
 * @param amenity - Amenity to search for
 * @returns True if zone has the amenity
 */
export const hasAmenity = (zone: Zone, amenity: string): boolean => {
  return zone.amenities.some(
    a => a.toLowerCase() === amenity.toLowerCase()
  );
};

/**
 * Check if zone has all specified amenities
 *
 * @param zone - Zone to check
 * @param amenities - Amenities to search for
 * @returns True if zone has all amenities
 */
export const hasAllAmenities = (
  zone: Zone,
  amenities: readonly string[]
): boolean => {
  return amenities.every(amenity => hasAmenity(zone, amenity));
};

/**
 * Calculate cost for booking a zone
 *
 * @param zone - Zone to book
 * @param hours - Number of hours to book
 * @returns Total cost
 */
export const calculateBookingCost = (zone: Zone, hours: number): number => {
  return Math.round(zone.pricePerHour * hours * 100) / 100;
};

/**
 * Get zones available on a specific date and time range
 *
 * @param zones - All zones to search
 * @param date - Date to check
 * @param startTime - Start time (HH:mm format)
 * @param endTime - End time (HH:mm format)
 * @param facilityId - Optional: filter by facility
 * @returns Available zones for the date and time range
 */
export const getZonesAvailableForDateTimeRange = (
  zones: readonly Zone[],
  date: Date,
  startTime: string,
  endTime: string,
  facilityId?: string
): readonly Zone[] => {
  const dayOfWeek = date.getDay();

  const availableZones = findAvailableZones(
    zones,
    dayOfWeek,
    startTime,
    facilityId
  );

  // Further filter by end time
  const startMinutes = timeToMinutes(startTime);
  const endMinutes = timeToMinutes(endTime);

  const daysMap = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'] as const;
  const dayName = daysMap[dayOfWeek % 7];

  return availableZones.filter(zone => {
    const dayAvailability = zone.availability[dayName];
    if (!dayAvailability) return false;

    const zoneEndMinutes = timeToMinutes(dayAvailability.end);

    // End time must not exceed zone's available end time
    return endMinutes <= zoneEndMinutes;
  });
};

/**
 * Helper function to validate time format (HH:mm)
 *
 * @param time - Time string to validate
 * @returns True if time is in valid HH:mm format
 */
const isValidTimeFormat = (time: string): boolean => {
  const timeRegex = /^([0-1]?[0-9]|2[0-3]):[0-5][0-9]$/;
  return timeRegex.test(time);
};

/**
 * Helper function to convert time string (HH:mm) to minutes
 *
 * @param time - Time string in HH:mm format
 * @returns Total minutes since midnight
 */
const timeToMinutes = (time: string): number => {
  const [hours, minutes] = time.split(':').map(Number);
  return hours * 60 + minutes;
};

import type { IBookingEvent, ICalendarQuery } from "@/types/calendar";

// Convert booking data to calendar events
const convertBookingToEvent = (booking: {
  readonly id: string;
  readonly facilityName: string;
  readonly time: string;
  readonly duration?: number;
  readonly timeSlots?: readonly { readonly date: string; readonly timeSlot: string }[];
  readonly status: string;
  readonly purpose?: string;
  readonly facility?: string;
  readonly facilityId?: string;
  readonly price?: string | number;
  readonly description?: string;
}): IBookingEvent => {
  try {
    // Parse date - handle different formats (prioritize date over startDate)
    let bookingDate: Date;
    if (booking.date) {
      // Handle date string more carefully to avoid timezone issues
      if (typeof booking.date === 'string') {
        // If it's a date string in YYYY-MM-DD format, parse it as local date
        if (booking.date.match(/^\d{4}-\d{2}-\d{2}$/)) {
          const [year, month, day] = booking.date.split('-').map(Number);
          bookingDate = new Date(year, month - 1, day); // month is 0-indexed
        } else {
          bookingDate = new Date(booking.date);
        }
      } else {
        bookingDate = new Date(booking.date);
      }
    } else if (booking.startDate) {
      bookingDate = new Date(booking.startDate);
    } else {
      bookingDate = new Date();
    }

    // Validate date
    if (isNaN(bookingDate.getTime())) {
      bookingDate = new Date();
    }

  // Parse time - handle different formats (prioritize time over startTime/endTime)
  let startTime: string, endTime: string;
  if (booking.time && booking.time.includes('-')) {
    [startTime, endTime] = booking.time.split('-').map(t => t.trim());
  } else if (booking.time) {
    // Handle single time format
    startTime = booking.time;
    endTime = booking.time;
  } else if (booking.startTime && booking.endTime) {
    startTime = booking.startTime;
    endTime = booking.endTime;
  } else {
    startTime = '12:00';
    endTime = '13:00';
  }

  // Ensure times are in HH:MM format
  if (!startTime.includes(':')) {
    startTime = '12:00';
  }
  if (!endTime.includes(':')) {
    endTime = '13:00';
  }

  // Create start and end datetime
  const [startHour, startMinute] = startTime.split(':').map(Number);
  const [endHour, endMinute] = endTime.split(':').map(Number);

  const startDateTime = new Date(bookingDate);
  startDateTime.setHours(startHour, startMinute, 0, 0);

  const endDateTime = new Date(bookingDate);
  endDateTime.setHours(endHour, endMinute, 0, 0);

  // Extract price as number - handle both string and number types
  let price = 0;
  if (typeof booking.price === 'string') {
    price = parseInt(booking.price.replace(/\D/g, '') || '0');
  } else if (typeof booking.price === 'number') {
    price = booking.price;
  } else {
    price = 0;
  }

    const event = {
      id: booking.id,
      facilityId: booking.facilityId || booking.id,
      facilityName: booking.facility || booking.facilityName || 'Ukjent lokale',
      title: booking.description || booking.purpose || 'Booking',
      start: startDateTime.toISOString(),
      end: endDateTime.toISOString(),
      status: booking.status === 'confirmed' || booking.status === 'approved' ? 'confirmed' :
              booking.status === 'pending' ? 'pending' :
              booking.status === 'rejected' || booking.status === 'cancelled' ? 'cancelled' : 'cancelled',
      price: price,
      tags: [booking.facility?.toLowerCase() || 'booking']
    };

    return event;
  } catch (error) {
    // Return a fallback event
    return {
      id: booking.id || 'unknown',
      facilityId: booking.facilityId || booking.id || 'unknown',
      facilityName: booking.facility || booking.facilityName || 'Ukjent lokale',
      title: booking.description || booking.purpose || 'Booking',
      start: new Date().toISOString(),
      end: new Date().toISOString(),
      status: 'cancelled' as const,
      price: 0,
      tags: ['error']
    };
  }
};

/**
 * Recurring occurrence data structure
 */
interface RecurringOccurrence {
  readonly id: string;
  readonly facilityId: string;
  readonly date: string;
  readonly timeSlot: string;
}

/**
 * Parent booking data for recurring occurrences
 */
interface ParentBookingData {
  readonly facility?: string;
  readonly facilityName?: string;
  readonly description?: string;
  readonly purpose?: string;
  readonly status?: string;
  readonly pricePerHour?: number;
}

// Convert recurring occurrence to calendar event
const convertRecurringOccurrenceToEvent = (occurrence: RecurringOccurrence, parentBooking: ParentBookingData): IBookingEvent => {
  try {
    const startTime = occurrence.timeSlot.split('-')[0];
    const endTime = occurrence.timeSlot.split('-')[1];

    const [startHour, startMinute] = startTime.split(':').map(Number);
    const [endHour, endMinute] = endTime.split(':').map(Number);

    const startDateTime = new Date(occurrence.date);
    startDateTime.setHours(startHour, startMinute, 0, 0);

    const endDateTime = new Date(occurrence.date);
    endDateTime.setHours(endHour, endMinute, 0, 0);

    return {
      id: occurrence.id,
      facilityId: occurrence.facilityId,
      facilityName: parentBooking.facility || parentBooking.facilityName || 'Ukjent lokale',
      title: parentBooking.description || parentBooking.purpose || 'Gjentakende booking',
      start: startDateTime.toISOString(),
      end: endDateTime.toISOString(),
      status: parentBooking.status === 'confirmed' || parentBooking.status === 'approved' ? 'confirmed' :
              parentBooking.status === 'pending' ? 'pending' :
              parentBooking.status === 'rejected' || parentBooking.status === 'cancelled' ? 'cancelled' : 'cancelled',
      price: parentBooking.pricePerHour || 0,
      tags: ['recurring', parentBooking.facility?.toLowerCase() || 'booking']
    };
  } catch (error) {
    console.error('Error converting recurring occurrence to event:', error);
    return {
      id: occurrence.id || 'unknown',
      facilityId: occurrence.facilityId || 'unknown',
      facilityName: parentBooking.facility || parentBooking.facilityName || 'Ukjent lokale',
      title: parentBooking.description || parentBooking.purpose || 'Gjentakende booking',
      start: new Date().toISOString(),
      end: new Date().toISOString(),
      status: 'cancelled' as const,
      price: 0,
      tags: ['error']
    };
  }
};

export const calendarService = {
  async list(params: ICalendarQuery): Promise<readonly IBookingEvent[]> {
    // Get bookings from localStorage
    const pendingBookings = JSON.parse(localStorage.getItem('pendingBookings') || '[]');
    const processedBookings = JSON.parse(localStorage.getItem('processedBookings') || '[]');

    // Combine all bookings
    const allBookings = [...pendingBookings, ...processedBookings];


    // Convert bookings to calendar events
    const events: IBookingEvent[] = [];

    for (const booking of allBookings) {
      // Convert booking to calendar event (all bookings are now stored as individual occurrences)
      const event = convertBookingToEvent(booking);
      events.push(event);
    }

    // Simulate API delay
    await new Promise(resolve => setTimeout(resolve, 100));

    // Filter based on query parameters
    let filtered = events;

    if (params.facilityIds && params.facilityIds.length > 0) {
      filtered = filtered.filter(event => params.facilityIds!.includes(event.facilityId));
    }

    if (params.statuses && params.statuses.length > 0) {
      filtered = filtered.filter(event => params.statuses!.includes(event.status));
    }

    if (params.text) {
      const searchText = params.text.toLowerCase();
      filtered = filtered.filter(event => 
        event.title.toLowerCase().includes(searchText) ||
        event.facilityName.toLowerCase().includes(searchText)
      );
    }

    // Filter by date range
    if (params.from && params.to) {
      const fromDate = new Date(params.from);
      const toDate = new Date(params.to);

      filtered = filtered.filter(event => {
        const eventDate = new Date(event.start);
        return eventDate >= fromDate && eventDate <= toDate;
      });
    }

    return filtered;
  },
} as const;

/**
 * Authentication Service
 *
 * Handles all authentication operations including:
 * - Email/password authentication
 * - Social authentication (Google, etc.)
 * - Session management
 * - Password reset
 * - Email verification
 *
 * @module services/supabase/auth
 */

import { supabase } from './client';
import {
  handleSupabaseError,
  UnauthorizedError,
  ValidationError,
  ServiceError,
} from './errors';
import type { User, Session, AuthError } from '@supabase/supabase-js';

// ============================================================================
// Types
// ============================================================================

export interface SignUpParams {
  readonly email: string;
  readonly password: string;
  readonly fullName?: string;
  readonly metadata?: Record<string, unknown>;
}

export interface SignInParams {
  readonly email: string;
  readonly password: string;
}

export interface ResetPasswordParams {
  readonly email: string;
  readonly redirectTo?: string;
}

export interface UpdatePasswordParams {
  readonly newPassword: string;
}

export interface UpdateProfileParams {
  readonly fullName?: string;
  readonly avatarUrl?: string;
  readonly metadata?: Record<string, unknown>;
}

export interface AuthResponse {
  readonly user: User | null;
  readonly session: Session | null;
}

// ============================================================================
// Authentication Service
// ============================================================================

export class AuthService {
  /**
   * Sign up a new user with email and password
   *
   * @param params - Sign up parameters
   * @returns User and session
   * @throws {ValidationError} If email/password invalid
   */
  async signUp(params: SignUpParams): Promise<AuthResponse> {
    try {
      this.validateEmail(params.email);
      this.validatePassword(params.password);

      const { data, error } = await supabase.auth.signUp({
        email: params.email,
        password: params.password,
        options: {
          data: {
            full_name: params.fullName,
            ...params.metadata,
          },
        },
      });

      if (error) {
        throw this.handleAuthError(error);
      }

      return {
        user: data.user,
        session: data.session,
      };
    } catch (error) {
      throw handleSupabaseError(error, 'signUp');
    }
  }

  /**
   * Sign in with email and password
   *
   * @param params - Sign in parameters
   * @returns User and session
   * @throws {UnauthorizedError} If credentials invalid
   */
  async signIn(params: SignInParams): Promise<AuthResponse> {
    try {
      this.validateEmail(params.email);
      this.validatePassword(params.password);

      const { data, error } = await supabase.auth.signInWithPassword({
        email: params.email,
        password: params.password,
      });

      if (error) {
        throw this.handleAuthError(error);
      }

      return {
        user: data.user,
        session: data.session,
      };
    } catch (error) {
      throw handleSupabaseError(error, 'signIn');
    }
  }

  /**
   * Sign in with Google OAuth
   *
   * @param redirectTo - URL to redirect after authentication
   */
  async signInWithGoogle(redirectTo?: string): Promise<void> {
    try {
      const { error } = await supabase.auth.signInWithOAuth({
        provider: 'google',
        options: {
          redirectTo: redirectTo ?? window.location.origin,
        },
      });

      if (error) {
        throw this.handleAuthError(error);
      }
    } catch (error) {
      throw handleSupabaseError(error, 'signInWithGoogle');
    }
  }

  /**
   * Sign out the current user
   */
  async signOut(): Promise<void> {
    try {
      const { error } = await supabase.auth.signOut();

      if (error) {
        throw this.handleAuthError(error);
      }
    } catch (error) {
      throw handleSupabaseError(error, 'signOut');
    }
  }

  /**
   * Get the current user
   *
   * @returns Current user or null
   */
  async getCurrentUser(): Promise<User | null> {
    try {
      const { data: { user }, error } = await supabase.auth.getUser();

      if (error) {
        throw this.handleAuthError(error);
      }

      return user;
    } catch (error) {
      throw handleSupabaseError(error, 'getCurrentUser');
    }
  }

  /**
   * Get the current session
   *
   * @returns Current session or null
   */
  async getCurrentSession(): Promise<Session | null> {
    try {
      const { data: { session }, error } = await supabase.auth.getSession();

      if (error) {
        throw this.handleAuthError(error);
      }

      return session;
    } catch (error) {
      throw handleSupabaseError(error, 'getCurrentSession');
    }
  }

  /**
   * Check if user is authenticated
   *
   * @returns True if user is authenticated
   */
  async isAuthenticated(): Promise<boolean> {
    try {
      const session = await this.getCurrentSession();
      return session !== null;
    } catch (error) {
      return false;
    }
  }

  /**
   * Send password reset email
   *
   * @param params - Reset password parameters
   */
  async resetPassword(params: ResetPasswordParams): Promise<void> {
    try {
      this.validateEmail(params.email);

      const { error } = await supabase.auth.resetPasswordForEmail(params.email, {
        redirectTo: params.redirectTo ?? `${window.location.origin}/reset-password`,
      });

      if (error) {
        throw this.handleAuthError(error);
      }
    } catch (error) {
      throw handleSupabaseError(error, 'resetPassword');
    }
  }

  /**
   * Update user password
   *
   * @param params - Update password parameters
   * @throws {UnauthorizedError} If user not authenticated
   */
  async updatePassword(params: UpdatePasswordParams): Promise<void> {
    try {
      this.validatePassword(params.newPassword);

      const { error } = await supabase.auth.updateUser({
        password: params.newPassword,
      });

      if (error) {
        throw this.handleAuthError(error);
      }
    } catch (error) {
      throw handleSupabaseError(error, 'updatePassword');
    }
  }

  /**
   * Update user profile
   *
   * @param params - Update profile parameters
   * @returns Updated user
   */
  async updateProfile(params: UpdateProfileParams): Promise<User> {
    try {
      const { data, error } = await supabase.auth.updateUser({
        data: {
          full_name: params.fullName,
          avatar_url: params.avatarUrl,
          ...params.metadata,
        },
      });

      if (error) {
        throw this.handleAuthError(error);
      }

      if (!data.user) {
        throw new UnauthorizedError('User not authenticated');
      }

      return data.user;
    } catch (error) {
      throw handleSupabaseError(error, 'updateProfile');
    }
  }

  /**
   * Refresh the current session
   *
   * @returns Refreshed session
   */
  async refreshSession(): Promise<Session> {
    try {
      const { data, error } = await supabase.auth.refreshSession();

      if (error) {
        throw this.handleAuthError(error);
      }

      if (!data.session) {
        throw new UnauthorizedError('Failed to refresh session');
      }

      return data.session;
    } catch (error) {
      throw handleSupabaseError(error, 'refreshSession');
    }
  }

  /**
   * Resend verification email
   *
   * @param email - User email
   */
  async resendVerificationEmail(email: string): Promise<void> {
    try {
      this.validateEmail(email);

      const { error } = await supabase.auth.resend({
        type: 'signup',
        email,
      });

      if (error) {
        throw this.handleAuthError(error);
      }
    } catch (error) {
      throw handleSupabaseError(error, 'resendVerificationEmail');
    }
  }

  /**
   * Listen to authentication state changes
   *
   * @param callback - Callback function
   * @returns Unsubscribe function
   */
  onAuthStateChange(
    callback: (event: string, session: Session | null) => void
  ): () => void {
    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      (event, session) => {
        callback(event, session);
      }
    );

    return () => {
      subscription.unsubscribe();
    };
  }

  // ==========================================================================
  // Private Helpers
  // ==========================================================================

  /**
   * Validate email format
   */
  private validateEmail(email: string): void {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    if (!email || !emailRegex.test(email)) {
      throw new ValidationError('Invalid email format', {
        email: ['Please provide a valid email address'],
      });
    }
  }

  /**
   * Validate password strength
   */
  private validatePassword(password: string): void {
    if (!password || password.length < 8) {
      throw new ValidationError('Invalid password', {
        password: ['Password must be at least 8 characters long'],
      });
    }

    // Additional password strength checks
    const hasUpperCase = /[A-Z]/.test(password);
    const hasLowerCase = /[a-z]/.test(password);
    const hasNumber = /[0-9]/.test(password);

    if (!hasUpperCase || !hasLowerCase || !hasNumber) {
      throw new ValidationError('Weak password', {
        password: [
          'Password must contain at least one uppercase letter, one lowercase letter, and one number',
        ],
      });
    }
  }

  /**
   * Handle authentication errors
   */
  private handleAuthError(error: AuthError): ServiceError {
    switch (error.message) {
      case 'Invalid login credentials':
      case 'Email not confirmed':
        return new UnauthorizedError(error.message);
      case 'User already registered':
        return new ValidationError('Email already in use', {
          email: ['This email is already registered'],
        });
      default:
        return handleSupabaseError(error, 'auth');
    }
  }
}

/**
 * Singleton instance of AuthService
 */
export const authService = new AuthService();

/**
 * Avatar Service
 *
 * Manages user avatar uploads and storage.
 *
 * Features:
 * - Avatar upload to Supabase Storage with localStorage fallback
 * - Avatar URL management
 * - Avatar deletion
 *
 * @module services/supabase/avatar
 */

import { supabase } from './client';
import { handleSupabaseError } from './errors';
import type { Database } from '@/types/database';

// ============================================================================
// Extended Types
// ============================================================================

export interface AvatarUploadResult {
  readonly url: string;
  readonly path: string;
}

// ============================================================================
// Avatar Service
// ============================================================================

export class AvatarService {
  /**
   * Convert file to data URL (for localStorage storage)
   *
   * @param file - Avatar file to convert
   * @returns Data URL string
   */
  async fileToDataUrl(file: File): Promise<string> {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  }

  /**
   * Upload user avatar to Supabase Storage with localStorage fallback
   *
   * @param userId - User ID
   * @param file - Avatar file to upload
   * @returns Avatar URL and storage path
   */
  async uploadAvatar(userId: string, file: File): Promise<AvatarUploadResult> {
    try {
      // First, try to upload to Supabase Storage
      const fileExtension = file.name.split('.').pop() || 'jpg';
      const fileName = `avatars/${userId}.${fileExtension}`;

      const { data, error: uploadError } = await supabase.storage
        .from('avatars')
        .upload(fileName, file, {
          cacheControl: '3600',
          upsert: true // Allow overwriting existing avatar
        });

      if (!uploadError && data) {
        // Successfully uploaded to Supabase Storage
        const { data: { publicUrl } } = supabase.storage
          .from('avatars')
          .getPublicUrl(fileName);

        return {
          url: publicUrl,
          path: fileName
        };
      }
    } catch (error) {
      console.warn('Failed to upload to Supabase Storage, falling back to localStorage:', error);
    }

    // Fallback to localStorage
    try {
      const dataUrl = await this.fileToDataUrl(file);
      const storageKey = `avatar_${userId}`;
      localStorage.setItem(storageKey, dataUrl);

      return {
        url: dataUrl,
        path: storageKey, // Use localStorage key as path
      };
    } catch (error) {
      console.error('Error processing avatar file:', error);
      throw new Error('Failed to process avatar file');
    }
  }

  /**
   * Delete user avatar
   *
   * @param filePath - Path to the avatar file in storage
   * @returns True if deleted successfully
   */
  async deleteAvatar(filePath: string): Promise<boolean> {
    try {
      // Try to delete from Supabase Storage first
      const { error } = await supabase.storage
        .from('avatars')
        .remove([filePath]);

      if (!error) {
        return true;
      }
    } catch (error) {
      console.warn('Failed to delete from Supabase Storage:', error);
    }

    // Fallback to localStorage
    try {
      localStorage.removeItem(filePath);
      return true;
    } catch (error) {
      console.error('Error deleting avatar:', error);
      return false;
    }
  }

  /**
   * Get avatar URL for user
   *
   * @param userId - User ID
   * @returns Avatar URL or null if not found
   */
  async getAvatarUrl(userId: string): Promise<string | null> {
    try {
      // Try to get from Supabase Storage first
      const { data, error } = await supabase.storage
        .from('avatars')
        .list('avatars', {
          search: userId
        });

      if (!error && data && data.length > 0) {
        const fileName = data[0].name;
        const { data: { publicUrl } } = supabase.storage
          .from('avatars')
          .getPublicUrl(fileName);

        return publicUrl;
      }
    } catch (error) {
      console.warn('Failed to get avatar from Supabase Storage:', error);
    }

    // Fallback to localStorage
    try {
      const storageKey = `avatar_${userId}`;
      return localStorage.getItem(storageKey);
    } catch (error) {
      console.error('Error getting avatar URL:', error);
      return null;
    }
  }
}

