/**
 * Base Service Abstract Class
 *
 * Provides common CRUD operations for all domain services.
 * Implements SOLID principles with template method pattern.
 *
 * Features:
 * - Generic CRUD operations
 * - Consistent error handling
 * - Type-safe query building
 * - Pagination support
 * - Soft delete support
 * - Audit logging hooks
 *
 * @module services/supabase/base
 */

import { supabase } from './client';
import {
  handleSupabaseError,
  NotFoundError,
  ValidationError,
  type ServiceError,
} from './errors';
import type { PaginatedResponse, PaginationParams } from './types';

/**
 * Base configuration for services
 */
export interface BaseServiceConfig {
  readonly tableName: string;
  readonly idColumn?: string;
  readonly softDelete?: boolean;
  readonly deletedAtColumn?: string;
}

/**
 * Abstract base service class
 * All domain services should extend this class
 *
 * @template TRow - The database table row type
 * @template TInsert - The database table insert type
 * @template TUpdate - The database table update type
 */
export abstract class BaseService<TRow, TInsert, TUpdate> {
  protected abstract readonly config: BaseServiceConfig;

  /**
   * Get table name for this service
   */
  protected get tableName(): string {
    return this.config.tableName;
  }

  /**
   * Get ID column name (defaults to 'id')
   */
  protected get idColumn(): string {
    return this.config.idColumn ?? 'id';
  }

  /**
   * Check if soft delete is enabled
   */
  protected get softDeleteEnabled(): boolean {
    return this.config.softDelete ?? false;
  }

  /**
   * Get deleted_at column name
   */
  protected get deletedAtColumn(): string {
    return this.config.deletedAtColumn ?? 'deleted_at';
  }

  // ==========================================================================
  // CRUD Operations
  // ==========================================================================

  /**
   * Fetch all records
   * Excludes soft-deleted records if soft delete is enabled
   *
   * @param select - Columns to select (defaults to '*')
   * @returns Array of records
   */
  async getAll(select = '*'): Promise<TRow[]> {
    try {
      let query = supabase.from(this.tableName).select(select);

      // Exclude soft-deleted records
      if (this.softDeleteEnabled) {
        query = query.is(this.deletedAtColumn, null);
      }

      const { data, error } = await query;

      if (error) {
        throw handleSupabaseError(error, `getAll ${this.tableName}`);
      }

      return (data ?? []) as TRow[];
    } catch (error) {
      throw handleSupabaseError(error, `getAll ${this.tableName}`);
    }
  }

  /**
   * Fetch paginated records
   *
   * @param params - Pagination parameters
   * @param select - Columns to select
   * @returns Paginated response
   */
  async getPaginated(
    params: PaginationParams = {},
    select = '*'
  ): Promise<PaginatedResponse<TRow>> {
    try {
      const page = params.page ?? 1;
      const pageSize = params.pageSize ?? 10;
      const from = (page - 1) * pageSize;
      const to = from + pageSize - 1;

      let query = supabase
        .from(this.tableName)
        .select(select, { count: 'exact' });

      // Exclude soft-deleted records
      if (this.softDeleteEnabled) {
        query = query.is(this.deletedAtColumn, null);
      }

      const { data, error, count } = await query.range(from, to);

      if (error) {
        throw handleSupabaseError(error, `getPaginated ${this.tableName}`);
      }

      const totalCount = count ?? 0;
      const hasMore = to < totalCount - 1;

      return {
        data: (data ?? []) as TRow[],
        count: totalCount,
        page,
        pageSize,
        hasMore,
      };
    } catch (error) {
      throw handleSupabaseError(error, `getPaginated ${this.tableName}`);
    }
  }

  /**
   * Fetch a single record by ID
   *
   * @param id - Record ID
   * @param select - Columns to select
   * @returns Single record
   * @throws {NotFoundError} If record not found
   */
  async getById(id: string, select = '*'): Promise<TRow> {
    try {
      let query = supabase
        .from(this.tableName)
        .select(select)
        .eq(this.idColumn, id);

      // Exclude soft-deleted records
      if (this.softDeleteEnabled) {
        query = query.is(this.deletedAtColumn, null);
      }

      const { data, error } = await query.single();

      if (error) {
        throw handleSupabaseError(error, `getById ${this.tableName}`);
      }

      if (!data) {
        throw new NotFoundError(this.tableName, id);
      }

      return data as TRow;
    } catch (error) {
      if (error instanceof NotFoundError) {
        throw error;
      }
      throw handleSupabaseError(error, `getById ${this.tableName}`);
    }
  }

  /**
   * Create a new record
   *
   * @param data - Record data to insert
   * @returns Created record
   */
  async create(data: TInsert): Promise<TRow> {
    try {
      // Validate data before insert
      await this.validateInsert(data);

      // Call before hook
      const processedData = await this.beforeCreate(data);

      const { data: created, error } = await supabase
        .from(this.tableName)
        .insert(processedData)
        .select()
        .single();

      if (error) {
        throw handleSupabaseError(error, `create ${this.tableName}`);
      }

      if (!created) {
        throw new ValidationError(`Failed to create ${this.tableName}`);
      }

      // Call after hook
      await this.afterCreate(created as TRow);

      return created as TRow;
    } catch (error) {
      throw handleSupabaseError(error, `create ${this.tableName}`);
    }
  }

  /**
   * Update an existing record
   *
   * @param id - Record ID
   * @param data - Data to update
   * @returns Updated record
   * @throws {NotFoundError} If record not found
   */
  async update(id: string, data: TUpdate): Promise<TRow> {
    try {
      // Validate data before update
      await this.validateUpdate(id, data);

      // Call before hook
      const processedData = await this.beforeUpdate(id, data);

      let query = supabase
        .from(this.tableName)
        .update(processedData)
        .eq(this.idColumn, id);

      // Exclude soft-deleted records
      if (this.softDeleteEnabled) {
        query = query.is(this.deletedAtColumn, null);
      }

      const { data: updated, error } = await query.select().single();

      if (error) {
        throw handleSupabaseError(error, `update ${this.tableName}`);
      }

      if (!updated) {
        throw new NotFoundError(this.tableName, id);
      }

      // Call after hook
      await this.afterUpdate(updated as TRow);

      return updated as TRow;
    } catch (error) {
      throw handleSupabaseError(error, `update ${this.tableName}`);
    }
  }

  /**
   * Delete a record (hard or soft delete)
   *
   * @param id - Record ID
   * @throws {NotFoundError} If record not found
   */
  async delete(id: string): Promise<void> {
    try {
      // Call before hook
      await this.beforeDelete(id);

      if (this.softDeleteEnabled) {
        // Soft delete - set deleted_at timestamp
        const { error } = await supabase
          .from(this.tableName)
          .update({ [this.deletedAtColumn]: new Date().toISOString() } as unknown as TUpdate)
          .eq(this.idColumn, id)
          .is(this.deletedAtColumn, null);

        if (error) {
          throw handleSupabaseError(error, `delete ${this.tableName}`);
        }
      } else {
        // Hard delete
        const { error } = await supabase
          .from(this.tableName)
          .delete()
          .eq(this.idColumn, id);

        if (error) {
          throw handleSupabaseError(error, `delete ${this.tableName}`);
        }
      }

      // Call after hook
      await this.afterDelete(id);
    } catch (error) {
      throw handleSupabaseError(error, `delete ${this.tableName}`);
    }
  }

  /**
   * Restore a soft-deleted record
   * Only works if soft delete is enabled
   *
   * @param id - Record ID
   * @throws {ValidationError} If soft delete not enabled
   */
  async restore(id: string): Promise<TRow> {
    if (!this.softDeleteEnabled) {
      throw new ValidationError('Restore operation requires soft delete to be enabled');
    }

    try {
      const { data, error } = await supabase
        .from(this.tableName)
        .update({ [this.deletedAtColumn]: null } as unknown as TUpdate)
        .eq(this.idColumn, id)
        .select()
        .single();

      if (error) {
        throw handleSupabaseError(error, `restore ${this.tableName}`);
      }

      if (!data) {
        throw new NotFoundError(this.tableName, id);
      }

      return data as TRow;
    } catch (error) {
      throw handleSupabaseError(error, `restore ${this.tableName}`);
    }
  }

  /**
   * Check if a record exists
   *
   * @param id - Record ID
   * @returns True if record exists
   */
  async exists(id: string): Promise<boolean> {
    try {
      let query = supabase
        .from(this.tableName)
        .select(this.idColumn, { count: 'exact', head: true })
        .eq(this.idColumn, id);

      // Exclude soft-deleted records
      if (this.softDeleteEnabled) {
        query = query.is(this.deletedAtColumn, null);
      }

      const { count, error } = await query;

      if (error) {
        throw handleSupabaseError(error, `exists ${this.tableName}`);
      }

      return (count ?? 0) > 0;
    } catch (error) {
      throw handleSupabaseError(error, `exists ${this.tableName}`);
    }
  }

  /**
   * Count total records
   *
   * @returns Total record count
   */
  async count(): Promise<number> {
    try {
      let query = supabase
        .from(this.tableName)
        .select('*', { count: 'exact', head: true });

      // Exclude soft-deleted records
      if (this.softDeleteEnabled) {
        query = query.is(this.deletedAtColumn, null);
      }

      const { count, error } = await query;

      if (error) {
        throw handleSupabaseError(error, `count ${this.tableName}`);
      }

      return count ?? 0;
    } catch (error) {
      throw handleSupabaseError(error, `count ${this.tableName}`);
    }
  }

  // ==========================================================================
  // Lifecycle Hooks (Override in subclasses)
  // ==========================================================================

  /**
   * Validate data before insert
   * Override in subclass for custom validation
   */
  protected async validateInsert(data: TInsert): Promise<void> {
    // Default: no validation
    // Subclasses should override this method
  }

  /**
   * Validate data before update
   * Override in subclass for custom validation
   */
  protected async validateUpdate(id: string, data: TUpdate): Promise<void> {
    // Default: no validation
    // Subclasses should override this method
  }

  /**
   * Hook called before creating a record
   * Override in subclass for custom preprocessing
   */
  protected async beforeCreate(data: TInsert): Promise<TInsert> {
    return data;
  }

  /**
   * Hook called after creating a record
   * Override in subclass for side effects
   */
  protected async afterCreate(data: TRow): Promise<void> {
    // Default: no action
  }

  /**
   * Hook called before updating a record
   * Override in subclass for custom preprocessing
   */
  protected async beforeUpdate(id: string, data: TUpdate): Promise<TUpdate> {
    return data;
  }

  /**
   * Hook called after updating a record
   * Override in subclass for side effects
   */
  protected async afterUpdate(data: TRow): Promise<void> {
    // Default: no action
  }

  /**
   * Hook called before deleting a record
   * Override in subclass for validation
   */
  protected async beforeDelete(id: string): Promise<void> {
    // Default: no action
  }

  /**
   * Hook called after deleting a record
   * Override in subclass for cleanup
   */
  protected async afterDelete(id: string): Promise<void> {
    // Default: no action
  }
}

/**
 * Bookings Service
 *
 * Handles all booking-related operations with Supabase backend.
 * Provides CRUD operations and React Query hooks for bookings.
 *
 * Features:
 * - Type-safe booking operations
 * - React Query integration with caching
 * - Support for zones and facilities
 * - Availability checking
 * - Booking lifecycle management
 * - Organization and user-scoped queries
 */

import { supabase } from '@/lib/clients/supabase';
import type { Database } from '@/types/database';
import { useQuery, useMutation, useQueryClient, type UseQueryResult, type UseMutationResult } from '@tanstack/react-query';

// Type aliases
type Booking = Database['public']['Tables']['bookings']['Row'];
type BookingInsert = Database['public']['Tables']['bookings']['Insert'];
type BookingUpdate = Database['public']['Tables']['bookings']['Update'];
type Facility = Database['public']['Tables']['facilities']['Row'];
type Zone = Database['public']['Tables']['zones']['Row'];
type UserProfile = Database['public']['Tables']['profiles']['Row'];

/**
 * Booking with related data
 */
export interface BookingWithDetails extends Booking {
  readonly facility?: Facility;
  readonly zone?: Zone | null;
  readonly user_profile?: UserProfile | null;
}

/**
 * Availability check parameters
 */
export interface AvailabilityParams {
  readonly facilityId: string;
  readonly zoneId?: string | null;
  readonly startTime: string;
  readonly endTime: string;
}

/**
 * Query keys for React Query
 */
export const bookingKeys = {
  all: ['bookings'] as const,
  lists: () => [...bookingKeys.all, 'list'] as const,
  list: (filters: Record<string, unknown>) => [...bookingKeys.lists(), filters] as const,
  userBookings: (userId: string) => [...bookingKeys.lists(), 'user', userId] as const,
  orgBookings: (orgId: string) => [...bookingKeys.lists(), 'org', orgId] as const,
  facilityBookings: (facilityId: string) => [...bookingKeys.lists(), 'facility', facilityId] as const,
  details: () => [...bookingKeys.all, 'detail'] as const,
  detail: (id: string) => [...bookingKeys.details(), id] as const,
};

// ============================================================================
// Service Functions
// ============================================================================

export const bookingsService = {
  /**
   * Fetch bookings for a specific user
   */
  async getUserBookings(userId: string): Promise<BookingWithDetails[]> {
    const { data, error } = await supabase
      .from('bookings')
      .select(`
        *,
        facility:facilities (*),
        zone:zones (*)
      `)
      .eq('user_id', userId)
      .order('starts_at', { ascending: true });

    if (error) {
      console.error('❌ Error fetching bookings:', error);
      throw error;
    }

    return data as BookingWithDetails[];
  },

  /**
   * Fetch bookings for an organization
   */
  async getOrgBookings(orgId: string): Promise<BookingWithDetails[]> {
    // First get the bookings with facility information
    const { data: bookings, error: bookingsError } = await supabase
      .from('bookings')
      .select(`
        *,
        facility:facilities!inner (*)
      `)
      .eq('facility.org_id', orgId)
      .order('starts_at', { ascending: false });

    if (bookingsError) throw bookingsError;

    // If no bookings, return early
    if (!bookings || bookings.length === 0) {
      return [];
    }

    // Get unique user IDs from the bookings
    const userIds = [...new Set(bookings.map(booking => booking.user_id))];

    // Get user profiles for these users
    const { data: profiles, error: profilesError } = await supabase
      .from('profiles')
      .select('*')
      .in('user_id', userIds);

    if (profilesError) throw profilesError;

    // Create a map of user profiles for quick lookup
    const profileMap = new Map(profiles.map(profile => [profile.user_id, profile]));

    // Combine bookings with their user profiles
    const bookingsWithProfiles = bookings.map(booking => ({
      ...booking,
      user_profile: profileMap.get(booking.user_id) || null
    }));

    return bookingsWithProfiles as BookingWithDetails[];
  },

  /**
   * Fetch bookings for a specific facility
   */
  async getFacilityBookings(
    facilityId: string,
    startDate?: string,
    endDate?: string
  ): Promise<Booking[]> {
    let query = supabase
      .from('bookings')
      .select('*')
      .eq('facility_id', facilityId)
      .in('status', ['pending', 'awaiting_payment', 'paid', 'completed']);

    if (startDate) {
      query = query.gte('starts_at', startDate);
    }
    if (endDate) {
      query = query.lte('ends_at', endDate);
    }

    const { data, error } = await query.order('starts_at', { ascending: true });

    if (error) throw error;
    return data;
  },

  /**
   * Fetch a single booking by ID
   */
  async getById(id: string): Promise<BookingWithDetails> {
    const { data, error } = await supabase
      .from('bookings')
      .select(`
        *,
        facility:facilities (*),
        zone:zones (*)
      `)
      .eq('id', id)
      .single();

    if (error) throw error;
    return data as BookingWithDetails;
  },

  /**
   * Create a new booking
   */
  async create(booking: BookingInsert): Promise<Booking> {
    console.log('Supabase client available:', !!supabase);
    console.log('Attempting to create booking:', booking);

    // Validate that no fields contain invalid UUIDs
    for (const [key, value] of Object.entries(booking)) {
      if (typeof value === 'string' && value.length > 0) {
        // Check if this might be a UUID field with an invalid value
        if (key.includes('id') && value.length > 10 && !value.includes('-')) {
          console.warn(`Potential invalid UUID in field ${key}:`, value);
        }
      }
    }

    try {
      console.log('Executing Supabase insert...');
      const { data, error } = await supabase
        .from('bookings')
        .insert(booking)
        .select()
        .single();

      console.log('Supabase insert result:', { data, error });

      if (error) {
        console.error('Supabase insert error:', error);
        throw error;
      }

      console.log('Booking created successfully:', data);
      return data;
    } catch (error) {
      console.error('Exception in bookingsService.create:', error);
      throw error;
    }
  },

  /**
   * Update an existing booking
   */
  async update(id: string, updates: BookingUpdate): Promise<Booking> {
    const { data, error } = await supabase
      .from('bookings')
      .update(updates)
      .eq('id', id)
      .select()
      .single();

    if (error) throw error;
    return data;
  },

  /**
   * Cancel a booking
   */
  async cancel(id: string, reason?: string): Promise<Booking> {
    const updates: BookingUpdate = {
      status: 'cancelled',
      updated_at: new Date().toISOString(),
    };

    return this.update(id, updates);
  },

  /**
   * Delete a booking
   */
  async delete(id: string): Promise<void> {
    // First verify the booking exists and belongs to the current user
    const { data: booking, error: fetchError } = await supabase
      .from('bookings')
      .select('id, user_id, status')
      .eq('id', id)
      .single();

    if (fetchError) {
      throw new Error(`Failed to fetch booking: ${fetchError.message}`);
    }

    // Check if booking belongs to current user
    const { data: { user } } = await supabase.auth.getUser();
    if (!user || booking.user_id !== user.id) {
      throw new Error('Not authorized to delete this booking');
    }

    // For cancelled bookings, use the specific RPC function to avoid trigger issues
    if (booking.status === 'cancelled') {
      const { error: rpcError } = await supabase.rpc('delete_cancelled_booking' as any, { p_booking: id });
      if (rpcError) {
        throw new Error(`Failed to delete cancelled booking: ${rpcError.message}`);
      }
      return;
    }

    // For other bookings, use the standard delete
    const { error: deleteError } = await supabase
      .from('bookings')
      .delete()
      .eq('id', id);

    if (deleteError) {
      throw new Error(`Failed to delete booking: ${deleteError.message}`);
    }
  },

  /**
   * Get upcoming bookings for a user
   */
  async getUpcoming(userId: string, limit = 10): Promise<BookingWithDetails[]> {
    const { data, error } = await supabase
      .from('bookings')
      .select(`
        *,
        facility:facilities (*),
        zone:zones (*)
      `)
      .eq('user_id', userId)
      .gte('starts_at', new Date().toISOString())
      .order('starts_at', { ascending: true })
      .limit(limit);

    if (error) throw error;
    return data as BookingWithDetails[];
  },

  /**
   * Get past bookings for a user
   */
  async getPast(userId: string, limit = 20): Promise<BookingWithDetails[]> {
    const { data, error } = await supabase
      .from('bookings')
      .select(`
        *,
        facility:facilities (*),
        zone:zones (*)
      `)
      .eq('user_id', userId)
      .lt('starts_at', new Date().toISOString())
      .order('starts_at', { ascending: false })
      .limit(limit);

    if (error) throw error;
    return data as BookingWithDetails[];
  },

  /**
   * Check availability for a time slot
   * Uses RPC function from backend
   */
  async checkAvailability(params: AvailabilityParams): Promise<boolean> {
    // Using has_overlap function with negation to check availability
    const { data, error } = await supabase.rpc('has_overlap', {
      p_facility: params.facilityId,
      p_starts: params.startTime,
      p_ends: params.endTime,
    });

    if (error) {
      console.error('Availability check error:', error);
      throw error;
    }

    // has_overlap returns true if there's an overlap, so we negate it
    return !data;
  },
};

// ============================================================================
// React Query Hooks
// ============================================================================

/**
 * Hook to fetch user's bookings
 *
 * @example
 * ```tsx
 * function MyBookings() {
 *   const { user } = useAuth();
 *   const { data: bookings, isLoading } = useUserBookings(user?.id!);
 *
 *   if (isLoading) return <LoadingSpinner />;
 *
 *   return (
 *     <div>
 *       {bookings?.map(booking => (
 *         <BookingCard key={booking.id} booking={booking} />
 *       ))}
 *     </div>
 *   );
 * }
 * ```
 */
export const useUserBookings = (
  userId: string,
  enabled = true
): UseQueryResult<BookingWithDetails[], Error> => {
  return useQuery({
    queryKey: bookingKeys.userBookings(userId),
    queryFn: () => bookingsService.getUserBookings(userId),
    enabled: !!userId && enabled,
    staleTime: 2 * 60 * 1000, // 2 minutes
