/**
 * Hook to add a favorite
 *
 * Uses optimistic updates for instant UI feedback
 */
export const useAddFavorite = (): UseMutationResult<
  Favorite,
  Error,
  { userId: string; facilityId: string }
> => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ userId, facilityId }) => favoritesService.add(userId, facilityId),
    onMutate: async ({ userId, facilityId }) => {
      // Cancel outgoing queries
      await queryClient.cancelQueries({ queryKey: favoriteKeys.user(userId) });

      // Optimistically update cache
      queryClient.setQueryData(
        favoriteKeys.isFavorite(userId, facilityId),
        true
      );
    },
    onSuccess: (_, { userId }) => {
      // Invalidate favorites list to refetch with facility data
      queryClient.invalidateQueries({ queryKey: favoriteKeys.user(userId) });
    },
    onError: (_, { userId, facilityId }) => {
      // Revert optimistic update on error
      queryClient.setQueryData(
        favoriteKeys.isFavorite(userId, facilityId),
        false
      );
    },
  });
};

/**
 * Hook to remove a favorite
 *
 * Uses optimistic updates for instant UI feedback
 */
export const useRemoveFavorite = (): UseMutationResult<
  void,
  Error,
  { userId: string; facilityId: string }
> => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ userId, facilityId }) => favoritesService.remove(userId, facilityId),
    onMutate: async ({ userId, facilityId }) => {
      // Cancel outgoing queries
      await queryClient.cancelQueries({ queryKey: favoriteKeys.user(userId) });

      // Optimistically update cache
      queryClient.setQueryData(
        favoriteKeys.isFavorite(userId, facilityId),
        false
      );
    },
    onSuccess: (_, { userId }) => {
      // Invalidate favorites list
      queryClient.invalidateQueries({ queryKey: favoriteKeys.user(userId) });
    },
    onError: (_, { userId, facilityId }) => {
      // Revert optimistic update on error
      queryClient.setQueryData(
        favoriteKeys.isFavorite(userId, facilityId),
        true
      );
    },
  });
};

/**
 * Hook to toggle favorite status
 *
 * Convenience hook that combines add and remove with optimistic updates
 *
 * @example
 * ```tsx
 * function FavoriteButton({ facilityId }: { facilityId: string }) {
 *   const { user } = useAuth();
 *   const { data: isFavorite } = useIsFavorite(user?.id!, facilityId);
 *   const toggleFavorite = useToggleFavorite();
 *
 *   const handleClick = () => {
 *     toggleFavorite.mutate({
 *       userId: user!.id,
 *       facilityId,
 *     });
 *   };
 *
 *   return (
 *     <button
 *       onClick={handleClick}
 *       disabled={toggleFavorite.isPending}
 *       className={isFavorite ? 'text-red-500' : 'text-gray-400'}
 *     >
 *       {isFavorite ? '❤️' : '🤍'}
 *     </button>
 *   );
 * }
 * ```
 */
export const useToggleFavorite = (): UseMutationResult<
  boolean,
  Error,
  { userId: string; facilityId: string }
> => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ userId, facilityId }) => favoritesService.toggle(userId, facilityId),
    onMutate: async ({ userId, facilityId }) => {
      // Cancel outgoing queries
      await queryClient.cancelQueries({ queryKey: favoriteKeys.user(userId) });

      // Get current state
      const currentState = queryClient.getQueryData<boolean>(
        favoriteKeys.isFavorite(userId, facilityId)
      ) ?? false;

      // Optimistically toggle
      queryClient.setQueryData(
        favoriteKeys.isFavorite(userId, facilityId),
        !currentState
      );

      return { previousState: currentState };
    },
    onSuccess: (_, { userId }) => {
      // Invalidate favorites list
      queryClient.invalidateQueries({ queryKey: favoriteKeys.user(userId) });
    },
    onError: (_, { userId, facilityId }, context) => {
      // Revert optimistic update on error
      if (context?.previousState !== undefined) {
        queryClient.setQueryData(
          favoriteKeys.isFavorite(userId, facilityId),
          context.previousState
        );
      }
    },
  });
};

/**
 * Notifications Service
 *
 * Handles notification management with React Query hooks.
 * Provides CRUD operations, read status tracking, and notification preferences.
 *
 * @example
 * ```tsx
 * function NotificationCenter() {
 *   const { user } = useAuth();
 *   const { data: notifications, isLoading } = useNotifications(user?.id!);
 *
 *   // Enable real-time
 *   useRealtimeNotifications(user?.id!);
 *
 *   return <NotificationList notifications={notifications} />;
 * }
 * ```
 */

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/lib/clients/supabase';
import type { Database } from '@/types/database';

type Notification = Database['public']['Tables']['notifications']['Row'];
type NotificationInsert = Database['public']['Tables']['notifications']['Insert'];
type NotificationUpdate = Database['public']['Tables']['notifications']['Update'];
type NotificationPreferences = Database['public']['Tables']['notification_preferences']['Row'];
type NotificationPreferencesUpdate = Database['public']['Tables']['notification_preferences']['Update'];

/**
 * Query keys for notifications
 */
export const notificationKeys = {
  all: ['notifications'] as const,
  lists: () => [...notificationKeys.all, 'list'] as const,
  user: (userId: string) => [...notificationKeys.all, 'user', userId] as const,
  unread: (userId: string) => [...notificationKeys.all, 'unread', userId] as const,
  unreadCount: (userId: string) => [...notificationKeys.all, 'unread-count', userId] as const,
  byType: (userId: string, type: string) => [...notificationKeys.all, 'type', userId, type] as const,
  urgent: (userId: string) => [...notificationKeys.all, 'urgent', userId] as const,
  preferences: (userId: string) => [...notificationKeys.all, 'preferences', userId] as const,
};

/**
 * Notifications service
 */
export const notificationsService = {
  /**
   * Get all notifications for user
   */
  getAll: async (userId: string): Promise<Notification[]> => {
    const { data, error } = await supabase
      .from('notifications')
      .select('*')
      .eq('user_id', userId)
      .order('created_at', { ascending: false });

    if (error) throw error;
    return data || [];
  },

  /**
   * Get unread notifications
   */
  getUnread: async (userId: string): Promise<Notification[]> => {
    const { data, error } = await supabase
      .from('notifications')
      .select('*')
      .eq('user_id', userId)
      .eq('read', false)
      .order('created_at', { ascending: false });

    if (error) throw error;
    return data || [];
  },

  /**
   * Get unread count
   */
  getUnreadCount: async (userId: string): Promise<number> => {
    const { count, error } = await supabase
      .from('notifications')
      .select('*', { count: 'exact', head: true })
      .eq('user_id', userId)
      .eq('read', false);

    if (error) throw error;
    return count || 0;
  },

  /**
   * Get notifications by type
   */
  getByType: async (userId: string, type: string): Promise<Notification[]> => {
    const { data, error } = await supabase
      .from('notifications')
      .select('*')
      .eq('user_id', userId)
      .eq('type', type)
      .order('created_at', { ascending: false });

    if (error) throw error;
    return data || [];
  },

  /**
   * Get urgent notifications
   */
  getUrgent: async (userId: string): Promise<Notification[]> => {
    const { data, error } = await supabase
      .from('notifications')
      .select('*')
      .eq('user_id', userId)
      .eq('priority', 'urgent')
      .eq('read', false)
      .order('created_at', { ascending: false });

    if (error) throw error;
    return data || [];
  },

  /**
   * Create notification
   */
  create: async (notification: NotificationInsert): Promise<Notification> => {
    const { data, error } = await supabase
      .from('notifications')
      .insert(notification)
      .select()
      .single();

    if (error) throw error;
    return data;
  },

  /**
   * Mark notification as read
   */
  markAsRead: async (id: string): Promise<Notification> => {
    const { data, error } = await supabase
      .from('notifications')
      .update({ read: true, read_at: new Date().toISOString() })
      .eq('id', id)
      .select()
      .single();

    if (error) throw error;
    return data;
  },

  /**
   * Mark all as read
   */
  markAllAsRead: async (userId: string): Promise<void> => {
    const { error } = await supabase
      .from('notifications')
      .update({ read: true, read_at: new Date().toISOString() })
      .eq('user_id', userId)
      .eq('read', false);

    if (error) throw error;
  },

  /**
   * Delete notification
   */
  delete: async (id: string): Promise<void> => {
    const { error } = await supabase
      .from('notifications')
      .delete()
      .eq('id', id);

    if (error) throw error;
  },

  /**
   * Delete all read notifications
   */
  deleteAllRead: async (userId: string): Promise<void> => {
    const { error } = await supabase
      .from('notifications')
      .delete()
      .eq('user_id', userId)
      .eq('read', true);

    if (error) throw error;
  },

  /**
   * Get notification preferences
   */
  getPreferences: async (userId: string): Promise<NotificationPreferences | null> => {
    const { data, error } = await supabase
      .from('notification_preferences')
      .select('*')
      .eq('user_id', userId)
      .single();

    if (error) {
      // If no preferences exist, return default
      if (error.code === 'PGRST116') {
        return null;
      }
      throw error;
    }

    return data;
  },

  /**
   * Update notification preferences
   */
  updatePreferences: async (
    userId: string,
    preferences: NotificationPreferencesUpdate
  ): Promise<NotificationPreferences> => {
    // Try to update first
    const { data: existing } = await supabase
      .from('notification_preferences')
      .select('*')
      .eq('user_id', userId)
      .single();

    if (existing) {
      // Update existing
      const { data, error } = await supabase
        .from('notification_preferences')
        .update(preferences)
        .eq('user_id', userId)
        .select()
        .single();

      if (error) throw error;
      return data;
    } else {
      // Create new
      const { data, error } = await supabase
        .from('notification_preferences')
        .insert({ user_id: userId, ...preferences })
        .select()
        .single();

      if (error) throw error;
      return data;
    }
  },
};

