/**
 * Hook to fetch user's recurring bookings
 *
 * @example
 * ```tsx
 * function MyRecurringBookings() {
 *   const { user } = useAuth();
 *   const { data: recurring, isLoading } = useUserRecurring(user?.id!);
 *
 *   if (isLoading) return <LoadingSpinner />;
 *
 *   return (
 *     <div>
 *       {recurring?.map(r => (
 *         <RecurringBookingCard key={r.id} recurring={r} />
 *       ))}
 *     </div>
 *   );
 * }
 * ```
 */
export const useUserRecurring = (
  userId: string,
  enabled = true
): UseQueryResult<RecurringBookingWithOccurrences[], Error> => {
  return useQuery({
    queryKey: recurringKeys.userRecurring(userId),
    queryFn: () => recurringService.getUserRecurring(userId),
    enabled: !!userId && enabled,
    staleTime: 3 * 60 * 1000, // 3 minutes
  });
};

/**
 * Hook to fetch a single recurring booking with occurrences
 */
export const useRecurringBooking = (
  id: string,
  enabled = true
): UseQueryResult<RecurringBookingWithOccurrences, Error> => {
  return useQuery({
    queryKey: recurringKeys.withOccurrences(id),
    queryFn: () => recurringService.getById(id),
    enabled: !!id && enabled,
  });
};

/**
 * Hook to fetch occurrences for a recurring booking
 */
export const useRecurringOccurrences = (
  recurringId: string,
  enabled = true
): UseQueryResult<RecurringOccurrence[], Error> => {
  return useQuery({
    queryKey: recurringKeys.occurrences(recurringId),
    queryFn: () => recurringService.getOccurrences(recurringId),
    enabled: !!recurringId && enabled,
    staleTime: 1 * 60 * 1000, // 1 minute
  });
};

/**
 * Hook to fetch pending occurrences
 */
export const usePendingOccurrences = (
  recurringId: string,
  enabled = true
): UseQueryResult<RecurringOccurrence[], Error> => {
  return useQuery({
    queryKey: [...recurringKeys.occurrences(recurringId), 'pending'],
    queryFn: () => recurringService.getPendingOccurrences(recurringId),
    enabled: !!recurringId && enabled,
    staleTime: 30 * 1000, // 30 seconds
  });
};

/**
 * Hook to create a recurring booking
 *
 * @example
 * ```tsx
 * function CreateRecurringForm() {
 *   const createRecurring = useCreateRecurring();
 *
 *   const handleSubmit = (data: RecurringBookingInsert) => {
 *     createRecurring.mutate(data, {
 *       onSuccess: (recurring) => {
 *         toast.success('Recurring booking created!');
 *         navigate(`/recurring/${recurring.id}`);
 *       }
 *     });
 *   };
 *
 *   return <form onSubmit={handleSubmit}>...</form>;
 * }
 * ```
 */
export const useCreateRecurring = (): UseMutationResult<
  RecurringBooking,
  Error,
  RecurringBookingInsert
> => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: recurringService.create,
    onSuccess: (newRecurring) => {
      // Invalidate user's recurring bookings
      queryClient.invalidateQueries({
        queryKey: recurringKeys.userRecurring(newRecurring.user_id),
      });
    },
  });
};

/**
 * Hook to update a recurring booking
 */
export const useUpdateRecurring = (): UseMutationResult<
  RecurringBooking,
  Error,
  { id: string; updates: RecurringBookingUpdate }
> => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ id, updates }) => recurringService.update(id, updates),
    onSuccess: (updatedRecurring, { id }) => {
      // Invalidate queries
      queryClient.invalidateQueries({ queryKey: recurringKeys.all });
      queryClient.setQueryData(recurringKeys.detail(id), updatedRecurring);
    },
  });
};

/**
 * Hook to pause a recurring booking
 */
export const usePauseRecurring = (): UseMutationResult<RecurringBooking, Error, string> => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: recurringService.pause,
    onSuccess: (_, id) => {
      queryClient.invalidateQueries({ queryKey: recurringKeys.all });
    },
  });
};

/**
 * Hook to resume a recurring booking
 */
export const useResumeRecurring = (): UseMutationResult<RecurringBooking, Error, string> => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: recurringService.resume,
    onSuccess: (_, id) => {
      queryClient.invalidateQueries({ queryKey: recurringKeys.all });
    },
  });
};

/**
